import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Codex Minigame Pilot",
	internalName = "codex-minigame-pilot",
	legacyDataDirectory = "codex-minigame-pilot",
	description = "One clear next step for Motherlode Mine, Blast Furnace and Mahogany Homes: what to click, the path there, and why",
	tags = {"motherlode", "mlm", "blast furnace", "mahogany homes", "construction", "mining", "smithing", "guide", "codex"}
)
public class CodexMinigamePilotPlugin extends Plugin
{
	private static final String CONTRACT_KEY = "contract";
	private static final String PACE_KEY = "pace.";
	private static final String VERSION = "1.1";
	/** Where Codex Navigator saves its goal board for companion plugins. */
	static final String NAVIGATOR_GROUP = "codexnavigator";
	static final String NAVIGATOR_BOARD_KEY = "goalBoard";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	@Inject
	private CodexMinigamePilotConfig config;

	@Inject
	private Gson gson;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	private final StepPlaque plaque = new StepPlaque();
	private volatile Flight flight;
	private Pilots pilots;
	private PilotPanel panel;
	private NavigationButton navButton;
	private SceneGuide sceneGuide;
	private MinimapGuide minimapGuide;
	private ItemGuide itemGuide;
	private String shown;
	private WorldPoint arrow;
	private WorldMapPoint mapPoint;
	private FieldNotes notes;
	private final Map<Integer, Integer> lastInventory = new HashMap<>();
	/** Whether lastInventory holds this login's inventory yet; the first one seen is only a base. */
	private boolean inventoryKnown;
	/**
	 * The ticks after logging in or hopping before reading the minigames: the inventory, skills
	 * and varbits arrive over the first ticks, and a pack read as empty then full would look like
	 * a haul.
	 */
	private final LoginSettle settle = new LoginSettle();
	private GoalWatch goals;
	private String navigatorJson;
	private NavigatorGoals.Board navigatorBoard;
	/** Where the Pilot keeps its own look at the bank's supplies. */
	static final String STOCK_KEY = "stock.bank";
	/** The supplies in the bank as the Pilot last saw them, or null. */
	private BankStock ownStock;
	private String stewardJson;
	private BankStock stewardStock;

	@Provides
	CodexMinigamePilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexMinigamePilotConfig.class);
	}

	@Override
	protected void startUp()
	{
		notes = new FieldNotes(this::getPluginDirectory, gson);
		if (config.fieldNotes())
		{
			notes.open(VERSION);
		}
		pilots = new Pilots(client, loadContract(), this::saveContract, notes, this::loadBests, this::saveBests,
			id -> (int) Math.min(Integer.MAX_VALUE, itemManager.getItemPrice(id)),
			key -> configManager.getRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, key),
			(key, value) -> configManager.setRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, key, value),
			this::bankStock);
		// Turned on while logged in, no profile change arrives for this account: note it now, or a
		// later login to another account would not be told apart from it.
		pilots.profile(configManager.getRSProfileKey());
		goals = new GoalWatch(key -> configManager.getRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, key),
			(key, value) -> configManager.setRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, key, value),
			this::navigatorBoard);
		panel = new PilotPanel();
		panel.icons(itemManager::getImage);
		// The panel is only rebuilt while it is open, so bring it up to date as it opens.
		panel.onOpen(() -> clientThread.invokeLater(() ->
		{
			shown = null;
			publish();
		}));
		navButton = NavigationButton.builder()
			.tooltip("Codex Minigame Pilot")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		sceneGuide = new SceneGuide(client, () -> flight,
			() -> new SceneGuide.Settings(config.route(), config.labels(), config.others()));
		minimapGuide = new MinimapGuide(client, () -> flight, config::minimap);
		itemGuide = new ItemGuide(() -> flight);
		overlayManager.add(sceneGuide);
		overlayManager.add(minimapGuide);
		overlayManager.add(itemGuide);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				// Started while logged in: no inventory from the game by now means an empty one.
				seedInventory(client.getItemContainer(InventoryID.INV), true);
				pilots.rescan();
				goals.reload();
				pilots.loadContract(loadContract());
				loadStock();
			}
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneGuide);
		overlayManager.remove(minimapGuide);
		overlayManager.remove(itemGuide);
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			clearArrow();
			clearMapPoint();
		});
		flight = null;
		pilots = null;
		goals = null;
		panel = null;
		shown = null;
		notes.shutdown();
		notes = null;
		lastInventory.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexMinigamePilotConfig.GROUP.equals(event.getGroup()) || !"fieldNotes".equals(event.getKey()) || notes == null)
		{
			return;
		}
		if (config.fieldNotes())
		{
			notes.open(VERSION);
		}
		else
		{
			notes.close();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (pilots != null)
		{
			pilots.varbit(event.getVarbitId(), event.getValue());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			if (goals != null)
			{
				goals.bank(event.getItemContainer());
			}
			seeBank(event.getItemContainer());
			return;
		}
		if (event.getContainerId() != InventoryID.INV || pilots == null)
		{
			return;
		}
		if (!inventoryKnown)
		{
			// The inventory as it arrives after logging in: a base, not a change.
			seedInventory(event.getItemContainer(), false);
			return;
		}
		Map<Integer, Integer> now = new HashMap<>();
		for (Item item : event.getItemContainer().getItems())
		{
			if (item.getId() > 0)
			{
				now.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		Map<Integer, Integer> changes = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : now.entrySet())
		{
			int d = e.getValue() - lastInventory.getOrDefault(e.getKey(), 0);
			if (d != 0)
			{
				changes.put(e.getKey(), d);
			}
		}
		for (Map.Entry<Integer, Integer> e : lastInventory.entrySet())
		{
			if (!now.containsKey(e.getKey()))
			{
				changes.put(e.getKey(), -e.getValue());
			}
		}
		lastInventory.clear();
		lastInventory.putAll(now);
		pilots.inventory(changes);
	}

	/**
	 * Takes an inventory as the base later changes are measured from.
	 *
	 * @param nullIsEmpty whether a missing inventory is an empty one, rather than one still to come
	 */
	private void seedInventory(ItemContainer container, boolean nullIsEmpty)
	{
		lastInventory.clear();
		if (container == null)
		{
			inventoryKnown = nullIsEmpty;
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				lastInventory.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		inventoryKnown = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOADING:
				pilots.clearScene();
				break;
			case LOGIN_SCREEN:
			case HOPPING:
				// What was seen before is no base for what comes after: the next login may be
				// another account, and this one may have played elsewhere in between.
				pilots.relogged(System.currentTimeMillis());
				if (goals != null)
				{
					goals.relog();
				}
				lastInventory.clear();
				inventoryKnown = false;
				settle.relog();
				// Take the Pilot's arrow down (only if it is still ours) and set it again once
				// back, so none is left pointing at a house the next login has no business with.
				clearArrow();
				flight = null;
				plaque.show(null);
				publish();
				break;
			case LOGGING_IN:
				settle.relog();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		pilots.profile(event.getNewProfile());
		pilots.loadContract(loadContract());
		if (goals != null)
		{
			goals.reload();
		}
		loadStock();
	}

	/** This account's saved look at the bank, after logging in or switching account. */
	private void loadStock()
	{
		ownStock = BankStock.decode(configManager.getRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, STOCK_KEY));
		stewardJson = null;
		stewardStock = null;
	}

	/** The bank changed while open: keep its supplies, saved only when they change. */
	private void seeBank(ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		Map<Integer, Long> counts = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0 && BankStock.isSupply(item.getId()))
			{
				counts.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		BankStock seen = BankStock.seen(counts, System.currentTimeMillis());
		if (!seen.sameItems(ownStock))
		{
			configManager.setRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, STOCK_KEY, seen.encode());
		}
		ownStock = seen;
	}

	/**
	 * The supplies in the bank: the Pilot's own look or Codex Bank Steward's shared snapshot,
	 * whichever is newer, or null when neither has seen the bank. Bank Steward's is parsed again
	 * only when it changes.
	 */
	private BankStock bankStock()
	{
		String json = configManager.getRSProfileConfiguration(BankStock.STEWARD_GROUP, BankStock.STEWARD_KEY);
		if (json == null || json.isEmpty())
		{
			stewardJson = null;
			stewardStock = null;
		}
		else if (!json.equals(stewardJson))
		{
			stewardJson = json;
			stewardStock = BankStock.steward(gson, json);
		}
		return BankStock.newest(ownStock, stewardStock, System.currentTimeMillis());
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		pilots.scene().add(e.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned e)
	{
		pilots.scene().remove(e.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned e)
	{
		pilots.scene().add(e.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned e)
	{
		pilots.scene().remove(e.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned e)
	{
		pilots.scene().add(e.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned e)
	{
		pilots.scene().remove(e.getDecorativeObject());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM || type == ChatMessageType.MESBOX)
		{
			pilots.chat(type.name(), Text.removeTags(event.getMessage()));
			if (goals != null)
			{
				goals.chat(Text.removeTags(event.getMessage()));
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		pilots.click(Text.removeTags(event.getMenuOption()), Text.removeTags(event.getMenuTarget()), event.getId(),
			event.getMenuAction() == null ? null : event.getMenuAction().name(), event.getItemId());
		int id = event.getItemId();
		if (id == ItemIds.COAL_BAG || id == ItemIds.COAL_BAG_OPEN)
		{
			ItemContainer inv = client.getItemContainer(InventoryID.INV);
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			boolean bankOpen = FurnacePilot.bankOpen(client);
			pilots.coalBagOption(Text.removeTags(event.getMenuOption()),
				inv == null ? 0 : inv.count(Bar.COAL), bankOpen && bank != null ? bank.count(Bar.COAL) : -1);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN || pilots == null)
		{
			return;
		}
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (settle.tick(inv != null))
		{
			return;
		}
		if (!inventoryKnown)
		{
			// Settled with no inventory from the game: take what there is (nothing) as the base,
			// so the first real change is noted as one rather than taken as the base.
			seedInventory(inv, true);
		}
		Bar bar = config.bar() == CodexMinigamePilotConfig.BarChoice.AUTO ? null : Bar.valueOf(config.bar().name());
		Flight f = pilots.fly(config.motherlode(), config.furnace(), config.homes(), bar, config.cofferLow(), System.currentTimeMillis());
		if (config.showGoals() && goals != null)
		{
			goals.tick(client, f.view, new GoalWatch.Choices(
				config.motherlode() ? config.motherlodeGoal().choice() : Goals.Choice.OFF,
				config.homes() ? config.homesGoal().choice() : Goals.Choice.OFF,
				config.furnace() ? config.furnaceGoal() : -1, config.rewardRoad() && panelOpen()),
				f.activity == View.Activity.HOMES || f.activity == View.Activity.NONE ? loadContract() : null);
		}
		flight = f;
		String note = pilots.takeNote();
		if (note != null && config.visitChat())
		{
			chat(note);
		}
		plaque.show(config.plaque() && f.step != null ? f.step : null);
		updateArrow(f);
		updateMapPoint(f);
		publish();
	}

	private void updateArrow(Flight f)
	{
		WorldPoint want = config.hintArrow() && f.activity == View.Activity.HOMES ? f.destination : null;
		if (want != null && !want.equals(arrow))
		{
			client.setHintArrow(want);
			arrow = want;
		}
		else if (want == null)
		{
			clearArrow();
		}
	}

	/** Clears the hint arrow only if it is still the one the Pilot set. */
	private void clearArrow()
	{
		if (arrow != null && client.hasHintArrow() && arrow.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		arrow = null;
	}

	private void updateMapPoint(Flight f)
	{
		WorldPoint want = config.worldMap() && f.activity == View.Activity.HOMES ? f.destination : null;
		if (want == null)
		{
			clearMapPoint();
			return;
		}
		if (mapPoint != null && want.equals(mapPoint.getWorldPoint()))
		{
			return;
		}
		clearMapPoint();
		BufferedImage icon = Sigil.icon(20);
		mapPoint = WorldMapPoint.builder()
			.worldPoint(want)
			.image(icon)
			.name("Mahogany Homes client")
			.tooltip("Mahogany Homes client")
			.jumpOnClick(true)
			.snapToEdge(true)
			.build();
		worldMapPointManager.add(mapPoint);
	}

	private void clearMapPoint()
	{
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
		}
	}

	/** True while the panel is open; the reward road is only worked out for it then. */
	private boolean panelOpen()
	{
		PilotPanel p = panel;
		return p != null && p.isOpen();
	}

	/** Hands the panel a new view when anything on it has changed, and only while it is open. */
	private void publish()
	{
		PilotPanel p = panel;
		if (p == null || !p.isOpen())
		{
			// Closed: nothing to redraw. Opening it forgets what was shown, so it is drawn afresh.
			shown = null;
			return;
		}
		Flight f = flight;
		View view;
		if (client.getGameState() != GameState.LOGGED_IN || pilots == null)
		{
			view = View.loggedOut();
		}
		else if (f == null)
		{
			view = pilots.idleView();
		}
		else
		{
			view = f.view;
		}
		String signature = view.signature();
		if (signature.equals(shown))
		{
			return;
		}
		shown = signature;
		SwingUtilities.invokeLater(() -> p.update(view));
	}

	private void chat(String text)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Codex Pilot: ")
				.append(ChatColorType.NORMAL).append(text)
				.build())
			.build());
	}

	private String loadBests(View.Activity activity)
	{
		return configManager.getRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, PACE_KEY + activity.name());
	}

	private void saveBests(View.Activity activity, String bests)
	{
		configManager.setRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, PACE_KEY + activity.name(), bests);
	}

	/**
	 * Codex Navigator's goal board for this account, read from where Navigator saves it for
	 * companion plugins, or null when Navigator is not installed or has nothing pinned. It is
	 * parsed again only when it changes.
	 */
	private NavigatorGoals.Board navigatorBoard()
	{
		String json = configManager.getRSProfileConfiguration(NAVIGATOR_GROUP, NAVIGATOR_BOARD_KEY);
		if (json == null || json.isEmpty())
		{
			navigatorJson = null;
			navigatorBoard = null;
			return null;
		}
		if (!json.equals(navigatorJson))
		{
			navigatorJson = json;
			navigatorBoard = NavigatorGoals.read(gson, json);
		}
		return navigatorBoard;
	}

	private Contract loadContract()
	{
		return Contract.decode(configManager.getRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, CONTRACT_KEY));
	}

	private void saveContract(Contract contract)
	{
		if (contract == null)
		{
			configManager.unsetRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, CONTRACT_KEY);
			return;
		}
		String value = contract.getHome().getName() + (contract.getTier() == null ? "" : ":" + contract.getTier().getName());
		configManager.setRSProfileConfiguration(CodexMinigamePilotConfig.GROUP, CONTRACT_KEY, value);
	}
}

package com.codex.minigamepilot.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;

/**
 * The supplies the minigames burn (ore, coal, planks, steel bars) as your bank last held them,
 * and when it was seen. The Pilot keeps its own copy from every look at the bank, and also reads
 * Codex Bank Steward's shared snapshot, so a fresh install knows your stock before you open the
 * bank. The newer of the two is used.
 *
 * <p>Bank Steward saves {@code codexbanksteward/bankV1} in the RuneLite profile, read here and
 * never written:
 * {@code {"version":1,"savedAt":1760000000000,"items":{"995":1234567,"2434":30},"truncated":false}}.</p>
 */
public final class BankStock
{
	public static final String STEWARD_GROUP = "codexbanksteward";
	public static final String STEWARD_KEY = "bankV1";

	/** Where a stock came from. */
	public enum Source
	{
		/** The Pilot's own look at the bank. */
		PILOT,
		/** Codex Bank Steward's shared snapshot. */
		BANK_STEWARD
	}

	/** Every item the minigames burn: each bar's ore, coal, the four planks and steel bars. */
	private static final int[] SUPPLIES = supplies();

	private final Map<Integer, Long> items;
	private final long savedAt;
	private final Source source;

	BankStock(Map<Integer, Long> items, long savedAt, Source source)
	{
		// No stack in the bank passes 2,147,483,647: a bigger saved figure is damage, held there.
		items.replaceAll((id, n) -> Math.min(n, Integer.MAX_VALUE));
		this.items = Collections.unmodifiableMap(items);
		this.savedAt = Math.max(0, savedAt);
		this.source = source;
	}

	private static int[] supplies()
	{
		java.util.Set<Integer> ids = new java.util.TreeSet<>();
		for (Bar b : Bar.values())
		{
			ids.add(b.getOre());
		}
		ids.add(Bar.COAL);
		for (Contract.Tier t : Contract.Tier.values())
		{
			ids.add(t.getPlank());
		}
		ids.add(Contract.STEEL_BAR);
		int[] out = new int[ids.size()];
		int i = 0;
		for (int id : ids)
		{
			out[i++] = id;
		}
		return out;
	}

	public static boolean isSupply(int id)
	{
		for (int s : SUPPLIES)
		{
			if (s == id)
			{
				return true;
			}
		}
		return false;
	}

	/** The Pilot's own look at the bank: the supplies among what it holds. */
	public static BankStock seen(Map<Integer, Long> bank, long savedAt)
	{
		Map<Integer, Long> keep = new TreeMap<>();
		for (Map.Entry<Integer, Long> e : bank.entrySet())
		{
			if (e.getKey() != null && isSupply(e.getKey()) && e.getValue() != null && e.getValue() > 0)
			{
				keep.merge(e.getKey(), e.getValue(), Long::sum);
			}
		}
		return new BankStock(keep, savedAt, Source.PILOT);
	}

	/** Bank Steward's snapshot, or null when there is none or it cannot be read. */
	public static BankStock steward(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		JsonObject root;
		try
		{
			JsonElement e = gson.fromJson(json, JsonElement.class);
			root = e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
		}
		catch (JsonParseException | IllegalStateException | NumberFormatException e)
		{
			return null;
		}
		JsonElement list = root == null ? null : root.get("items");
		if (list == null || !list.isJsonObject())
		{
			return null;
		}
		Map<Integer, Long> keep = new TreeMap<>();
		for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
		{
			Integer id = integer(e.getKey());
			Long qty = number(e.getValue());
			if (id != null && isSupply(id) && qty != null && qty > 0)
			{
				keep.put(id, qty);
			}
		}
		Long savedAt = number(root.get("savedAt"));
		return new BankStock(keep, savedAt == null ? 0 : savedAt, Source.BANK_STEWARD);
	}

	/** The newer of two stocks, either of which may be null. The Pilot's own wins a tie. */
	public static BankStock newest(BankStock own, BankStock steward)
	{
		return newest(own, steward, Long.MAX_VALUE);
	}

	/**
	 * The newer of two stocks as of {@code now}. A time more than a day past now (a clock set
	 * wrong when it was saved) counts as unknown, so that stock does not win for ever.
	 */
	public static BankStock newest(BankStock own, BankStock steward, long now)
	{
		if (own == null)
		{
			return steward;
		}
		if (steward == null)
		{
			return own;
		}
		return seenBy(steward.savedAt, now) > seenBy(own.savedAt, now) ? steward : own;
	}

	/** A saved time, or 0 when it is more than a day past now. */
	private static long seenBy(long savedAt, long now)
	{
		return now != Long.MAX_VALUE && savedAt > now + 86_400_000L ? 0 : savedAt;
	}

	public long count(int id)
	{
		return items.getOrDefault(id, 0L);
	}

	/** When the bank was seen, in epoch milliseconds; 0 when not known. */
	public long getSavedAt()
	{
		return savedAt;
	}

	public Source getSource()
	{
		return source;
	}

	/** Saved as "savedAt|id=n;id=n". */
	public String encode()
	{
		StringBuilder b = new StringBuilder().append(savedAt).append('|');
		boolean first = true;
		for (Map.Entry<Integer, Long> e : new TreeMap<>(items).entrySet())
		{
			if (!first)
			{
				b.append(';');
			}
			first = false;
			b.append(e.getKey()).append('=').append(e.getValue());
		}
		return b.toString();
	}

	/** The Pilot's saved copy, or null when there is none; damaged entries are dropped. */
	public static BankStock decode(String saved)
	{
		if (saved == null || saved.isEmpty())
		{
			return null;
		}
		int bar = saved.indexOf('|');
		if (bar <= 0)
		{
			return null;
		}
		Long savedAt = parse(saved.substring(0, bar));
		if (savedAt == null || savedAt < 0)
		{
			return null;
		}
		Map<Integer, Long> keep = new TreeMap<>();
		String rest = saved.substring(bar + 1);
		for (String part : rest.isEmpty() ? new String[0] : rest.split(";"))
		{
			int eq = part.indexOf('=');
			Integer id = eq <= 0 ? null : integer(part.substring(0, eq));
			Long qty = eq <= 0 ? null : parse(part.substring(eq + 1));
			if (id != null && isSupply(id) && qty != null && qty > 0)
			{
				keep.put(id, qty);
			}
		}
		return new BankStock(keep, savedAt, Source.PILOT);
	}

	/** Whether two stocks hold the same supplies, whenever they were seen. */
	public boolean sameItems(BankStock other)
	{
		return other != null && items.equals(other.items);
	}

	private static Long number(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		try
		{
			// Past what a long holds reads as the most it holds, not wrapped round.
			java.math.BigDecimal d = e.getAsBigDecimal();
			if (d.compareTo(java.math.BigDecimal.valueOf(Long.MAX_VALUE)) > 0)
			{
				return Long.MAX_VALUE;
			}
			if (d.compareTo(java.math.BigDecimal.valueOf(Long.MIN_VALUE)) < 0)
			{
				return Long.MIN_VALUE;
			}
			return d.longValue();
		}
		catch (NumberFormatException | ArithmeticException ex)
		{
			return null;
		}
	}

	private static Integer integer(String s)
	{
		try
		{
			return Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Long parse(String s)
	{
		try
		{
			return Long.parseLong(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.codex.minigamepilot.core;

/**
 * The bars the Blast Furnace makes, with the ore and coal each needs. Coal is per bar at the
 * Blast Furnace, which is half what an ordinary furnace takes.
 */
public enum Bar
{
	IRON("Iron", 440, 0, 2351, 951, 942),
	STEEL("Steel", 440, 1, 2353, 951, 943),
	MITHRIL("Mithril", 447, 2, 2359, 952, 944),
	ADAMANTITE("Adamantite", 449, 3, 2361, 953, 945),
	RUNITE("Runite", 451, 4, 2363, 954, 946),
	GOLD("Gold", 444, 0, 2357, 955, 947),
	SILVER("Silver", 442, 0, 2355, 956, 948);

	public static final int COAL = 453;
	/** The furnace's coal count, a varbit. */
	public static final int COAL_VARBIT = 949;

	private final String name;
	private final int ore;
	private final int coal;
	private final int bar;
	private final int oreVarbit;
	private final int barVarbit;

	Bar(String name, int ore, int coal, int bar, int oreVarbit, int barVarbit)
	{
		this.name = name;
		this.ore = ore;
		this.coal = coal;
		this.bar = bar;
		this.oreVarbit = oreVarbit;
		this.barVarbit = barVarbit;
	}

	public String getName()
	{
		return name;
	}

	/** The ore item. */
	public int getOre()
	{
		return ore;
	}

	/** Coal needed per bar. */
	public int getCoal()
	{
		return coal;
	}

	/** The bar item. */
	public int getBar()
	{
		return bar;
	}

	/** The varbit holding this ore waiting in the furnace. */
	public int getOreVarbit()
	{
		return oreVarbit;
	}

	/** The varbit holding finished bars in the dispenser. */
	public int getBarVarbit()
	{
		return barVarbit;
	}

	/** "mithril ore", "coal" and so on, for sentences. */
	public String oreName()
	{
		return name.toLowerCase() + " ore";
	}

	public String barName(int count)
	{
		return name.toLowerCase() + (count == 1 ? " bar" : " bars");
	}

	public static boolean isBar(int itemId)
	{
		for (Bar b : values())
		{
			if (b.bar == itemId)
			{
				return true;
			}
		}
		return false;
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.List;
import java.util.function.IntUnaryOperator;

/**
 * Which bar pays best at the Blast Furnace right now. Each bar is priced at the Grand Exchange:
 * what a bar sells for less its ore and the coal it burns. Then the trips are counted: a load of
 * ore takes one trip, and bars that burn more coal than the coal bag carries along need coal trips
 * too, so runite makes far fewer bars an hour than steel. At your own trip time that gives coins
 * and experience an hour, less the coffer (and the foreman under level 60).
 */
public final class BarPick
{
	/** Coins the coffer burns an hour. */
	public static final int COFFER_PER_HOUR = 72_000;
	/** The foreman's fee an hour below level 60 Smithing: 2,500 coins every ten minutes. */
	public static final int FOREMAN_PER_HOUR = 15_000;
	public static final int FOREMAN_FREE_LEVEL = 60;

	/** A bar's Smithing level and experience at the Blast Furnace. */
	enum Facts
	{
		IRON(Bar.IRON, 15, 12.5),
		SILVER(Bar.SILVER, 20, 13.7),
		STEEL(Bar.STEEL, 30, 17.5),
		GOLD(Bar.GOLD, 40, 22.5),
		MITHRIL(Bar.MITHRIL, 50, 30),
		ADAMANTITE(Bar.ADAMANTITE, 70, 37.5),
		RUNITE(Bar.RUNITE, 85, 50);

		final Bar bar;
		final int level;
		final double xp;

		Facts(Bar bar, int level, double xp)
		{
			this.bar = bar;
			this.level = level;
			this.xp = xp;
		}
	}

	/** Gold with goldsmith gauntlets on gives this much experience a bar instead. */
	static final double GOLD_GAUNTLETS_XP = 56.2;

	/** One bar, priced. */
	public static final class Row
	{
		private final Bar bar;
		private final int level;
		private final boolean unlocked;
		private final long perBar;
		private final double perTrip;
		private final double coalTrips;
		private final double barsPerHour;
		private final long perHour;
		private final double xpPerHour;

		Row(Bar bar, int level, boolean unlocked, long perBar, double perTrip, double coalTrips, double barsPerHour, long perHour, double xpPerHour)
		{
			this.bar = bar;
			this.level = level;
			this.unlocked = unlocked;
			this.perBar = perBar;
			this.perTrip = perTrip;
			this.coalTrips = coalTrips;
			this.barsPerHour = barsPerHour;
			this.perHour = perHour;
			this.xpPerHour = xpPerHour;
		}

		public Bar getBar()
		{
			return bar;
		}

		public int getLevel()
		{
			return level;
		}

		public boolean isUnlocked()
		{
			return unlocked;
		}

		/** Coins a bar makes after its ore and coal. */
		public long getPerBar()
		{
			return perBar;
		}

		/** Coins each trip makes, coal trips counted in, before the coffer. */
		public double getPerTrip()
		{
			return perTrip;
		}

		/** Coal trips each load of ore needs. */
		public double getCoalTrips()
		{
			return coalTrips;
		}

		/** Bars an hour at the trip time given, or 0 when no trip time is known. */
		public double getBarsPerHour()
		{
			return barsPerHour;
		}

		/** Coins an hour after the coffer, or Long.MIN_VALUE when no trip time is known. */
		public long getPerHour()
		{
			return perHour;
		}

		public double getXpPerHour()
		{
			return xpPerHour;
		}
	}

	/** What the ranking is worked out for. */
	public static final class Setup
	{
		/** Your Smithing level. */
		public int level = 1;
		public boolean coalBag;
		public int bagCapacity = 27;
		/** Ore one trip carries: free slots once the coal bag and the like are in. */
		public int oreSlots = 27;
		/** Seconds a trip takes you, bank to bank, or 0 when not known. */
		public double tripSeconds;
		public boolean goldsmith;
	}

	private BarPick()
	{
	}

	/**
	 * Every bar the furnace makes, priced, best first: those you can make by coins a trip (which
	 * at one trip time is the same order as coins an hour), then those your level does not reach.
	 *
	 * @param price an item's Grand Exchange price, 0 when unknown
	 * @return the bars, or an empty list when prices are not loaded
	 */
	public static List<Row> rank(IntUnaryOperator price, Setup s)
	{
		List<Row> rows = new ArrayList<>();
		int coal = price.applyAsInt(Bar.COAL);
		int slots = Math.max(1, s.oreSlots);
		int bag = s.coalBag ? Math.max(0, s.bagCapacity) : 0;
		long fixed = COFFER_PER_HOUR + (s.level < FOREMAN_FREE_LEVEL ? FOREMAN_PER_HOUR : 0);
		for (Facts f : Facts.values())
		{
			int barPrice = price.applyAsInt(f.bar.getBar());
			int ore = price.applyAsInt(f.bar.getOre());
			if (barPrice <= 0 || ore <= 0 || f.bar.getCoal() > 0 && coal <= 0)
			{
				// A price not loaded yet would rank the bar wrongly; leave it out until it is.
				continue;
			}
			long perBar = barPrice - ore - (long) f.bar.getCoal() * coal;
			double coalTrips = coalTrips(f.bar.getCoal(), slots, bag);
			double tripsPerLoad = 1 + coalTrips;
			double perTrip = perBar * slots / tripsPerLoad;
			double barsPerHour = 0;
			long perHour = Long.MIN_VALUE;
			double xpPerHour = 0;
			if (s.tripSeconds > 0)
			{
				barsPerHour = slots * 3600 / (s.tripSeconds * tripsPerLoad);
				perHour = Math.round(barsPerHour * perBar) - fixed;
				double xp = f.bar == Bar.GOLD && s.goldsmith ? GOLD_GAUNTLETS_XP : f.xp;
				xpPerHour = barsPerHour * xp;
			}
			rows.add(new Row(f.bar, f.level, s.level >= f.level, perBar, perTrip, coalTrips, barsPerHour, perHour, xpPerHour));
		}
		rows.sort((a, b) ->
		{
			if (a.unlocked != b.unlocked)
			{
				return a.unlocked ? -1 : 1;
			}
			return Double.compare(b.perTrip, a.perTrip);
		});
		return rows;
	}

	/**
	 * Coal trips each load of ore needs, on average: a load burns slots times the bar's coal,
	 * the coal bag brings some of it along with the ore, and each coal trip brings a full pack
	 * and a full bag.
	 */
	static double coalTrips(int coalPerBar, int slots, int bag)
	{
		double need = (double) coalPerBar * slots - bag;
		return need <= 0 ? 0 : need / (slots + bag);
	}
}

package com.codex.minigamepilot.core;

/**
 * Your fastest visit to a minigame: the most pay-dirt or bars an hour over a stretch of at least
 * {@link #MIN_MS}, with its experience an hour. Kept per account beside the last visit's summary,
 * shown on the minigame's card away from it, and said in the chat when a visit beats it. Saved as
 * {@code startedAt|endedAt|minutes|perHour|xpPerHour}.
 *
 * <p>A visit is measured each time it is summed up (walking out, logging out, hopping). Its
 * session carries on when you step back in, so a later reading of the same session replaces an
 * earlier one only when it is faster, and only beating a different session's record is news.
 */
public final class BestVisit
{
	/** Shorter stretches swing too much on one good sack or one quick trip to stand as a record. */
	public static final long MIN_MS = 15 * 60_000L;

	private final long startedAt;
	private final long endedAt;
	private final long minutes;
	private final long perHour;
	private final long xpPerHour;

	BestVisit(long startedAt, long endedAt, long minutes, long perHour, long xpPerHour)
	{
		this.startedAt = startedAt;
		this.endedAt = endedAt;
		this.minutes = minutes;
		this.perHour = perHour;
		this.xpPerHour = xpPerHour;
	}

	/**
	 * A visit's pace, or null when it ran under {@link #MIN_MS} or made nothing.
	 *
	 * @param startedAt when its session began, to tell one session's readings from another's
	 * @param activeMs how long it ran
	 * @param units pay-dirt deposited or bars taken
	 * @param xp experience gained in the minigame's skill
	 */
	public static BestVisit of(long startedAt, long endedAt, long activeMs, long units, long xp)
	{
		if (startedAt <= 0 || activeMs < MIN_MS || units <= 0)
		{
			return null;
		}
		return new BestVisit(startedAt, endedAt, activeMs / 60_000L,
			Math.round(units * 3_600_000d / activeMs), Math.round(Math.max(0, xp) * 3_600_000d / activeMs));
	}

	/** What a new reading does to the record held. */
	public enum Outcome
	{
		/** Not faster, or not a reading at all: the record stands. */
		KEPT,
		/** The first record, or the same session going faster: saved without a word. */
		QUIET,
		/** A faster visit than a different session's record: worth saying. */
		BEATEN
	}

	/** @param held the record so far, or null */
	public static Outcome judge(BestVisit held, BestVisit reading)
	{
		if (reading == null)
		{
			return Outcome.KEPT;
		}
		if (held == null)
		{
			return Outcome.QUIET;
		}
		if (reading.perHour <= held.perHour)
		{
			return Outcome.KEPT;
		}
		return held.startedAt == reading.startedAt ? Outcome.QUIET : Outcome.BEATEN;
	}

	/** Whether two readings are of the same session. */
	public boolean sameSession(BestVisit other)
	{
		return other != null && other.startedAt == startedAt;
	}

	public long getPerHour()
	{
		return perHour;
	}

	public long getXpPerHour()
	{
		return xpPerHour;
	}

	public long getEndedAt()
	{
		return endedAt;
	}

	/** "1,620 pay-dirt an hour" */
	public String pace(String unit)
	{
		return Figures.count(perHour) + " " + unit + " an hour";
	}

	/** For the chat: "A new best: 1,620 pay-dirt an hour, up from 1,512." */
	public String beat(BestVisit held, String unit)
	{
		return "A new best: " + pace(unit) + (held == null ? "." : ", up from " + Figures.count(held.perHour) + ".");
	}

	/**
	 * For the card: "Best visit 3 days ago: 1,620 pay-dirt and 81K Mining xp an hour over 1h 12m."
	 * When the last visit was the best, the card already says when and how long, so it reads
	 * "Your best visit yet, at 1,620 pay-dirt and 81K Mining xp an hour."
	 *
	 * @param last the summary of your last visit, or null
	 */
	public String status(String unit, String skill, Visit last, long now)
	{
		String rate = Figures.count(perHour) + " " + unit + (xpPerHour > 0 ? " and " + Figures.count(xpPerHour) + " " + skill + " xp" : "") + " an hour";
		if (last != null && last.getEndedAt() == endedAt)
		{
			return "Your best visit yet, at " + rate + ".";
		}
		long m = minutes;
		String over = m < 60 ? m + "m" : (m / 60) + "h " + (m % 60) + "m";
		return "Best visit " + Visit.ago(endedAt, now) + ": " + rate + " over " + over + ".";
	}

	public String encode()
	{
		return startedAt + "|" + endedAt + "|" + minutes + "|" + perHour + "|" + xpPerHour;
	}

	/** A saved record, or null when there is none or it cannot be read. */
	public static BestVisit decode(String saved)
	{
		if (saved == null || saved.isEmpty())
		{
			return null;
		}
		String[] f = saved.split("\\|");
		if (f.length != 5)
		{
			return null;
		}
		try
		{
			long started = Long.parseLong(f[0].trim());
			long ended = Long.parseLong(f[1].trim());
			long minutes = Long.parseLong(f[2].trim());
			long perHour = Long.parseLong(f[3].trim());
			long xpPerHour = Long.parseLong(f[4].trim());
			if (started <= 0 || ended < started || minutes < MIN_MS / 60_000L || perHour <= 0 || xpPerHour < 0)
			{
				return null;
			}
			return new BestVisit(started, ended, minutes, perHour, xpPerHour);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.List;

/**
 * A Mahogany Homes contract and what is left of it: which client, what tier, the state of each
 * hotspot, and so what to fetch, where to go and what to fix next.
 *
 * <p>Hotspot varbit values, as the game uses them: 0 not part of this job, 1 needs mending,
 * 2 mended, 3 needs taking out, 4 ready to build, 5 to 8 built at tiers one to four.
 */
public final class Contract
{
	public static final int STEEL_BAR = 2353;

	/** Contract tiers, the plank each uses and the Construction level that unlocks it. */
	public enum Tier
	{
		BEGINNER("Beginner", 1, 960, "plank"),
		NOVICE("Novice", 20, 8778, "oak plank"),
		ADEPT("Adept", 50, 8780, "teak plank"),
		EXPERT("Expert", 70, 8782, "mahogany plank");

		private final String name;
		private final int level;
		private final int plank;
		private final String plankName;

		Tier(String name, int level, int plank, String plankName)
		{
			this.name = name;
			this.level = level;
			this.plank = plank;
			this.plankName = plankName;
		}

		public String getName()
		{
			return name;
		}

		public int getLevel()
		{
			return level;
		}

		public int getPlank()
		{
			return plank;
		}

		public String planks(int count)
		{
			return count + " " + plankName + (count == 1 ? "" : "s");
		}

		/** Points a finished contract of this tier is worth. */
		public int points()
		{
			return ordinal() + 2;
		}

		/** The best tier a Construction level can take. */
		public static Tier forLevel(int level)
		{
			Tier best = BEGINNER;
			for (Tier t : values())
			{
				if (level >= t.level)
				{
					best = t;
				}
			}
			return best;
		}

		public static Tier byName(String name)
		{
			for (Tier t : values())
			{
				if (t.name.equalsIgnoreCase(name))
				{
					return t;
				}
			}
			return null;
		}
	}

	/** What the game shows this tick. */
	public static final class Snapshot
	{
		/** The eight hotspot varbits. */
		public int[] values = new int[Home.HOTSPOTS];
		/** Planks of this contract's kind carried, plank sack included. */
		public int planks;
		public int steelBars;
		/** Whether the player is inside the client's house, on any floor. */
		public boolean atHome;
		public int constructionLevel = 1;
	}

	private final Home home;
	private final Tier tier;

	public Contract(Home home, Tier tier)
	{
		this.home = home;
		this.tier = tier;
	}

	public Home getHome()
	{
		return home;
	}

	/** The tier, or null when it has not been seen yet. */
	public Tier getTier()
	{
		return tier;
	}

	/**
	 * The contract saved as "home:tier" (the tier left off while not known), or null when there
	 * is none or it names no home.
	 */
	public static Contract decode(String saved)
	{
		if (saved == null || saved.isEmpty())
		{
			return null;
		}
		String[] parts = saved.split(":");
		// ":" alone splits to nothing at all.
		Home home = parts.length == 0 ? null : Home.byName(parts[0]);
		if (home == null)
		{
			return null;
		}
		Tier tier = parts.length > 1 ? Tier.byName(parts[1]) : null;
		return new Contract(home, tier);
	}

	/** Whether a hotspot value still needs work. */
	public static boolean needsWork(int value)
	{
		return value == 1 || value == 3 || value == 4;
	}

	/** The word for what a hotspot needs: Repair, Remove or Build. */
	public static String verb(int value)
	{
		switch (value)
		{
			case 1:
				return "Repair";
			case 3:
				return "Remove";
			case 4:
				return "Build";
			default:
				return "Done";
		}
	}

	/** The tier the hotspots show once furniture is built, or null. Values 5 to 8 are tiers one to four. */
	public static Tier tierFromValues(int[] values)
	{
		int best = 0;
		for (int v : values)
		{
			best = Math.max(best, v);
		}
		return best >= 5 && best <= 8 ? Tier.values()[best - 5] : null;
	}

	/** Whether the hotspot varbits say anything about this job yet. */
	public static boolean known(int[] values)
	{
		for (int v : values)
		{
			if (v != 0)
			{
				return true;
			}
		}
		return false;
	}

	/** Hotspots still to do, by index. */
	public List<Integer> remaining(int[] values)
	{
		List<Integer> left = new ArrayList<>();
		for (int i = 0; i < home.hotspotCount() && i < values.length; i++)
		{
			if (needsWork(values[i]))
			{
				left.add(i);
			}
		}
		return left;
	}

	/** Planks the rest of the job takes. Taking furniture out costs nothing; building it does. */
	public int planksNeeded(int[] values)
	{
		int n = 0;
		for (int i : remaining(values))
		{
			Home.Kind kind = home.hotspot(i).getKind();
			if (!kind.isSteel())
			{
				n += kind.getAmount();
			}
		}
		return n;
	}

	public int steelNeeded(int[] values)
	{
		int n = 0;
		for (int i : remaining(values))
		{
			if (home.hotspot(i).getKind().isSteel())
			{
				n++;
			}
		}
		return n;
	}

	/** The next step for this contract, or for getting one when there is none. */
	public static Step next(Contract contract, Snapshot s)
	{
		if (contract == null)
		{
			Tier best = Tier.forLevel(s.constructionLevel);
			return Step.of("Contract", "Get a Mahogany Homes contract",
				"Ask Amy in Falador, Marlo in Varrock, Ellie in East Ardougne or Angelo in Hosidius for "
					+ (best == Tier.EXPERT || best == Tier.ADEPT ? "an " : "a ") + best.getName().toLowerCase() + " contract",
				Step.Target.CONTRACTOR);
		}
		return contract.next(s);
	}

	private Step next(Snapshot s)
	{
		Home h = home;
		boolean known = known(s.values);
		List<Integer> left = remaining(s.values);
		if (known && left.isEmpty())
		{
			return Step.of("Talk", "Tell " + h.getName() + " the work is done",
				"Worth " + (tier == null ? "your" : tier.points()) + " points" + (h.isClientUpstairs() ? ". " + h.getName() + " is upstairs" : ""),
				Step.Target.CLIENT);
		}

		if (tier != null && known)
		{
			int planks = planksNeeded(s.values);
			int steel = steelNeeded(s.values);
			int shortPlanks = Math.max(0, planks - s.planks);
			int shortSteel = Math.max(0, steel - s.steelBars);
			if (shortPlanks > 0 || shortSteel > 0)
			{
				String what = shortPlanks > 0 ? tier.planks(shortPlanks) : "";
				if (shortSteel > 0)
				{
					what += (what.isEmpty() ? "" : " and ") + shortSteel + (shortSteel == 1 ? " steel bar" : " steel bars");
				}
				int[] items = shortSteel > 0 && shortPlanks > 0 ? new int[]{tier.getPlank(), STEEL_BAR}
					: shortSteel > 0 ? new int[]{STEEL_BAR} : new int[]{tier.getPlank()};
				return Step.items("Fetch", "Bring " + what,
					"The job needs " + tier.planks(planks) + (steel > 0 ? " and " + steel + " steel" : "") + "; you have " + s.planks
						+ (steel > 0 ? " and " + s.steelBars : ""), items);
			}
		}

		if (!s.atHome)
		{
			return Step.of("Travel", "Go to " + h.getName() + "'s house",
				h.getCity().getName() + ", " + h.getWhere(), Step.Target.HOME);
		}
		if (!known)
		{
			return Step.of("Look", "Look over " + h.getName() + "'s furniture",
				"The pieces that need work light up as you get close", Step.Target.HOTSPOT);
		}
		int planks = planksNeeded(s.values);
		String rest = left.size() == 1 ? "Last piece" : left.size() + " pieces left";
		if (planks > 0 && tier != null)
		{
			rest += ", " + tier.planks(planks);
		}
		return Step.of("Fix", "Fix up the furniture", rest, Step.Target.HOTSPOT);
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * What your Mahogany Homes contracts really cost, learned one finished contract at a time: the
 * Construction experience each one gave you, the planks and steel bars it took, and how long the
 * whole loop took, kept per tier. Priced at today's Grand Exchange prices, that answers the
 * question every Construction trainer asks: how many coins each experience point costs at each
 * tier, and how fast it comes.
 *
 * <p>Nothing is assumed about experience per plank: a tier is only ranked once you have finished
 * a contract of it, so carpenter's outfit bonuses and the like are counted as you earn them.</p>
 */
public final class ContractBook
{
	/** A loop longer than this (a break, a bank trip elsewhere) is not timed. */
	public static final int MAX_LOOP_SECONDS = 20 * 60;
	/** Experience one contract cannot plausibly give; anything above means other training mixed in. */
	static final int MAX_XP = 20_000;

	/** One tier's contracts so far. */
	public static final class Tally
	{
		int contracts;
		long xp;
		long planks;
		long steel;
		/** Contracts whose whole loop was timed, and the seconds they took. */
		int timed;
		long seconds;

		public int getContracts()
		{
			return contracts;
		}

		public double xpEach()
		{
			return contracts == 0 ? 0 : xp / (double) contracts;
		}

		public double planksEach()
		{
			return contracts == 0 ? 0 : planks / (double) contracts;
		}

		public double steelEach()
		{
			return contracts == 0 ? 0 : steel / (double) contracts;
		}

		/** Seconds a contract takes you, the trip for it included, or 0 when none was timed. */
		public double secondsEach()
		{
			return timed == 0 ? 0 : seconds / (double) timed;
		}
	}

	/** A tier priced at today's prices. */
	public static final class Row
	{
		private final Contract.Tier tier;
		private final Tally tally;
		private final double coinsEach;
		private final double perXp;
		private final double xpPerHour;
		private final boolean unlocked;

		Row(Contract.Tier tier, Tally tally, double coinsEach, double perXp, double xpPerHour, boolean unlocked)
		{
			this.tier = tier;
			this.tally = tally;
			this.coinsEach = coinsEach;
			this.perXp = perXp;
			this.xpPerHour = xpPerHour;
			this.unlocked = unlocked;
		}

		public Contract.Tier getTier()
		{
			return tier;
		}

		/** This tier's contracts, or null when you have finished none. */
		public Tally getTally()
		{
			return tally;
		}

		/** Coins one contract's planks and steel cost. */
		public double getCoinsEach()
		{
			return coinsEach;
		}

		/** Coins each experience point costs; 0 when not known. */
		public double getPerXp()
		{
			return perXp;
		}

		/** Experience an hour at your own loop time, or 0 when not timed. */
		public double getXpPerHour()
		{
			return xpPerHour;
		}

		public boolean isUnlocked()
		{
			return unlocked;
		}

		public boolean isKnown()
		{
			return tally != null && tally.contracts > 0;
		}
	}

	private final Map<Contract.Tier, Tally> tallies = new EnumMap<>(Contract.Tier.class);

	/**
	 * A finished contract.
	 *
	 * @param xp Construction experience from taking the job to handing it in
	 * @param planks planks the whole job took
	 * @param steel steel bars it took
	 * @param seconds the whole loop, from the contract before it was handed in, or 0 when not timed
	 * @return true when it was kept; experience no contract gives is left out
	 */
	public boolean record(Contract.Tier tier, long xp, int planks, int steel, long seconds)
	{
		if (tier == null || xp <= 0 || xp > MAX_XP || planks < 0 || steel < 0)
		{
			return false;
		}
		Tally t = tallies.computeIfAbsent(tier, k -> new Tally());
		t.contracts++;
		t.xp += xp;
		t.planks += planks;
		t.steel += steel;
		if (seconds > 0 && seconds <= MAX_LOOP_SECONDS)
		{
			t.timed++;
			t.seconds += seconds;
		}
		return true;
	}

	/** A tier's contracts, or null when none is recorded. */
	public Tally tally(Contract.Tier tier)
	{
		return tallies.get(tier);
	}

	public boolean isEmpty()
	{
		return tallies.isEmpty();
	}

	/**
	 * Every tier, cheapest experience first among those you have done, then those you can take but
	 * have not, then those your level does not reach.
	 *
	 * @param price an item's Grand Exchange price, 0 when unknown
	 * @return the tiers, or an empty list while steel bar or a done tier's plank has no price yet
	 */
	public List<Row> rank(IntUnaryOperator price, int constructionLevel)
	{
		List<Row> rows = new ArrayList<>();
		int steelPrice = price.applyAsInt(Contract.STEEL_BAR);
		for (Contract.Tier tier : Contract.Tier.values())
		{
			Tally t = tallies.get(tier);
			boolean unlocked = constructionLevel >= tier.getLevel();
			if (t == null || t.contracts == 0)
			{
				rows.add(new Row(tier, null, 0, 0, 0, unlocked));
				continue;
			}
			int plankPrice = price.applyAsInt(tier.getPlank());
			if (plankPrice <= 0 || t.steel > 0 && steelPrice <= 0)
			{
				// An unpriced plank would make the tier look free.
				return new ArrayList<>();
			}
			double coins = t.planksEach() * plankPrice + t.steelEach() * steelPrice;
			double perXp = coins / t.xpEach();
			double xpPerHour = t.secondsEach() > 0 ? t.xpEach() * 3600 / t.secondsEach() : 0;
			rows.add(new Row(tier, t, coins, perXp, xpPerHour, unlocked));
		}
		rows.sort((a, b) ->
		{
			int ga = group(a);
			int gb = group(b);
			if (ga != gb)
			{
				return Integer.compare(ga, gb);
			}
			if (ga == 0)
			{
				return Double.compare(a.perXp, b.perXp);
			}
			return Integer.compare(b.tier.ordinal(), a.tier.ordinal());
		});
		return rows;
	}

	private static int group(Row r)
	{
		return r.isKnown() ? 0 : r.unlocked ? 1 : 2;
	}

	/** Saved as "tier=contracts,xp,planks,steel,timed,seconds;..." with tiers by name. */
	public String encode()
	{
		StringBuilder b = new StringBuilder();
		for (Map.Entry<Contract.Tier, Tally> e : tallies.entrySet())
		{
			Tally t = e.getValue();
			if (b.length() > 0)
			{
				b.append(';');
			}
			b.append(e.getKey().name()).append('=').append(t.contracts).append(',').append(t.xp).append(',').append(t.planks)
				.append(',').append(t.steel).append(',').append(t.timed).append(',').append(t.seconds);
		}
		return b.toString();
	}

	/** Reads a saved book; damaged entries are dropped and the rest kept. */
	public static ContractBook decode(String saved)
	{
		ContractBook book = new ContractBook();
		if (saved == null || saved.isEmpty())
		{
			return book;
		}
		for (String part : saved.split(";"))
		{
			int eq = part.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			Contract.Tier tier;
			try
			{
				tier = Contract.Tier.valueOf(part.substring(0, eq).toUpperCase(Locale.ENGLISH));
			}
			catch (IllegalArgumentException e)
			{
				continue;
			}
			String[] f = part.substring(eq + 1).split(",");
			if (f.length != 6)
			{
				continue;
			}
			try
			{
				Tally t = new Tally();
				t.contracts = Integer.parseInt(f[0]);
				t.xp = Long.parseLong(f[1]);
				t.planks = Long.parseLong(f[2]);
				t.steel = Long.parseLong(f[3]);
				t.timed = Integer.parseInt(f[4]);
				t.seconds = Long.parseLong(f[5]);
				if (t.contracts > 0 && t.xp > 0 && t.planks >= 0 && t.steel >= 0 && t.timed >= 0 && t.timed <= t.contracts && t.seconds >= 0)
				{
					book.tallies.put(tier, t);
				}
			}
			catch (NumberFormatException e)
			{
				// A damaged entry is dropped; the rest still count.
			}
		}
		return book;
	}
}

package com.codex.minigamepilot.core;

import java.util.Locale;

/**
 * Every count the Pilot shows, written the one way the whole Codex suite writes them: in full
 * with commas below 10,000 ("9,870"), whole lowercase thousands below a million ("142k"),
 * millions with one decimal ("3.1M") and billions with two ("1.23B"). A figure is rounded, never
 * cut, and one that rounds up to the next unit moves to it, so 999,960 is "1.0M", not "1000k".
 */
public final class Figures
{
	/** Where a count stops writing every digit, as everywhere in the suite. */
	static final long BRIEF_EXACT = 10_000;

	private Figures()
	{
	}

	/** "9,870", "68k", "142k", "3.1M". */
	public static String count(long n)
	{
		return scaled(n, BRIEF_EXACT);
	}

	/** The same as {@link #count}: "9,870", "41k", "3.1M". */
	public static String brief(long n)
	{
		return scaled(n, BRIEF_EXACT);
	}

	/** A brief figure with its sign: "+71k", "-104k", "+9,870", "+0". */
	public static String signed(long n)
	{
		return (n < 0 ? "-" : "+") + brief(n == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(n));
	}

	/**
	 * Two brief figures written in the larger one's unit, so a gauge never reads "41,000 / 993k":
	 * "41k / 993k", "612 / 1,800", "1.2M / 13.0M". A part too small to show in that unit keeps
	 * its own rather than reading as nothing: "300 / 41k", "12k / 13.0M". A part short of the
	 * whole is never written as all of it: where rounding would make the two read the same, the
	 * part is rounded down instead, "9k / 10k" for 9,600 of 10,000, not "10k / 10k", and when
	 * even that reads the same (13,000,577 of 13,034,431) it reads one step below the whole,
	 * "12.9M / 13.0M": still true of what you have, and the gauge's fill shows the rest.
	 */
	public static String pair(long have, long need)
	{
		long top = Math.max(Math.abs(have), Math.abs(need));
		if (top < BRIEF_EXACT)
		{
			return exact(have) + " / " + exact(need);
		}
		int unit = unit(top);
		String part = in(have, unit);
		String whole = in(need, unit);
		if (have >= 0 && have < need && part.equals(whole))
		{
			part = down(have, unit);
			if (part.equals(whole))
			{
				long step = unit == 1 ? 1_000 : unit == 2 ? 100_000 : 10_000_000;
				part = down(Math.max(0, Math.round((double) need / step) - 1) * step, unit);
			}
		}
		return part + " / " + whole;
	}

	/** {@link #in} for a figure that is not below zero, rounded down rather than to the nearest. */
	private static String down(long n, int unit)
	{
		switch (unit)
		{
			case 1:
				return n < 1000 ? exact(n) : n / 1000 + "k";
			case 2:
				return String.format(Locale.ENGLISH, "%d.%dM", n / 1_000_000, n / 100_000 % 10);
			default:
				return String.format(Locale.ENGLISH, "%d.%02dB", n / 1_000_000_000, n / 10_000_000 % 100);
		}
	}

	private static String scaled(long n, long exactBelow)
	{
		long a = Math.abs(n);
		if (a < exactBelow)
		{
			return exact(n);
		}
		return in(n, unit(a));
	}

	/** 1 for thousands, 2 for millions, 3 for billions, after rounding. */
	private static int unit(long a)
	{
		if (a < 999_500)
		{
			return 1;
		}
		if (a < 999_950_000)
		{
			return 2;
		}
		return 3;
	}

	private static String in(long n, int unit)
	{
		long a = Math.abs(n);
		String sign = n < 0 ? "-" : "";
		switch (unit)
		{
			case 1:
				return a < 1000 ? exact(n) : sign + Math.round(a / 1000.0) + "k";
			case 2:
				return a < 50_000 ? brief(n) : sign + String.format(Locale.ENGLISH, "%.1fM", a / 1_000_000.0);
			default:
				return a < 5_000_000 ? brief(n) : sign + String.format(Locale.ENGLISH, "%.2fB", a / 1_000_000_000.0);
		}
	}

	private static String exact(long n)
	{
		return String.format(Locale.ENGLISH, "%,d", n);
	}
}

package com.codex.minigamepilot.core;

/**
 * The Blast Furnace loop: bank, load the conveyor belt, collect bars, bank again.
 *
 * <p>What makes it work is choosing the trip at the bank. A bar needs coal already in the
 * furnace, so the cycle compares the coal waiting there (plus a full coal bag) with what a load
 * of ore will burn, and calls a coal trip only when the ore would otherwise sit unsmelted. For
 * steel with a coal bag that is never; for runite it is three coal trips to each ore trip.
 */
public final class FurnaceCycle
{
	/** Bars the dispenser holds before more ore just waits in the furnace. */
	static final int DISPENSER_FULL = 27;
	/** Ticks with ore or coal on the belt and nothing reaching the furnace before the count is dropped. */
	static final int BELT_TIMEOUT = 20;

	/** What the game shows this tick. */
	public static final class Snapshot
	{
		public Bar bar = Bar.STEEL;
		/** Coal and this bar's ore waiting in the furnace. */
		public int furnaceCoal;
		public int furnaceOre;
		/** Finished bars of this kind in the dispenser. */
		public int dispenserBars;
		/** The dispenser varbit: 0 empty, 1 still smelting, 2 hot (ice gloves to take), 3 cooled. */
		public int dispenserState;
		public int ore;
		public int coal;
		/** Bars of any kind carried. */
		public int bars;
		public int free;
		/** Inventory slots not taken by ore, coal or bars: a coal bag, gloves, a stamina potion. */
		public int fixed;
		public boolean coalBag;
		/** Coal in the bag, or -1 when it has not been seen. */
		public int bagCoal;
		public int bagCapacity = 27;
		public boolean bankOpen;
		public boolean iceGlovesWorn;
		public boolean iceGlovesCarried;
		public boolean goldsmithWorn;
		public boolean goldsmithCarried;
		/** Coins in the coffer. */
		public int coffer;
		/** Below this the coffer should be topped up. */
		public int cofferLow = 2500;
		/** Whether the coffer matters: under level 60 Smithing the foreman is paid instead. */
		public boolean usesCoffer = true;
		/** This bar's ore and coal in the bank, or -1 when the bank has not been seen. */
		public int bankOre = -1;
		public int bankCoal = -1;
	}

	private int onBelt;
	private int lastCarried = -1;
	private int lastFurnace = -1;
	private int idle;

	/**
	 * Follows ore and coal from the inventory onto the belt and into the furnace.
	 *
	 * @param carried ore and coal carried
	 * @param inFurnace ore and coal in the furnace
	 * @param atBelt whether the player is at the conveyor belt
	 */
	public void observe(int carried, int inFurnace, boolean atBelt)
	{
		if (lastCarried >= 0 && carried < lastCarried && atBelt)
		{
			onBelt += lastCarried - carried;
			idle = 0;
		}
		if (lastFurnace >= 0 && inFurnace > lastFurnace)
		{
			onBelt = Math.max(0, onBelt - (inFurnace - lastFurnace));
			idle = 0;
		}
		if (onBelt > 0 && ++idle > BELT_TIMEOUT)
		{
			onBelt = 0;
		}
		lastCarried = carried;
		lastFurnace = inFurnace;
	}

	/**
	 * After logging in or hopping: the last readings are no base for change, but ore already on
	 * the belt is still on its way.
	 */
	public void relog()
	{
		lastCarried = -1;
		lastFurnace = -1;
	}

	public void reset()
	{
		onBelt = 0;
		lastCarried = -1;
		lastFurnace = -1;
		idle = 0;
	}

	/** Ore and coal on the belt that has not reached the furnace yet. */
	public int getOnBelt()
	{
		return onBelt;
	}

	/** Ore one trip carries: every slot not taken by the coal bag, gloves and the like. */
	public static int load(Snapshot s)
	{
		return Math.max(1, 28 - s.fixed);
	}

	/** Coal one trip brings: a full inventory plus a full bag. */
	public static int coalTrip(Snapshot s)
	{
		return load(s) + (s.coalBag ? s.bagCapacity : 0);
	}

	/** Whether the next trip from the bank should carry coal rather than ore. */
	public static boolean coalRunNext(Snapshot s)
	{
		if (s.bar.getCoal() == 0)
		{
			return false;
		}
		int bag = s.coalBag ? s.bagCapacity : 0;
		return s.furnaceCoal + bag < s.bar.getCoal() * load(s);
	}

	private boolean dispenserReady(Snapshot s)
	{
		return s.dispenserBars > 0 && (s.dispenserState == 3 || (s.dispenserState == 2 && s.iceGlovesWorn));
	}

	public Step next(Snapshot s)
	{
		Bar bar = s.bar;
		boolean needsCoal = bar.getCoal() > 0;
		int bag = Math.max(0, s.bagCoal);

		if (s.usesCoffer && s.coffer < s.cofferLow && !s.bankOpen)
		{
			int minutes = s.coffer / 1200;
			return Step.of("Pay", "Top up the coffer", s.coffer == 0
				? "The furnace stops without coins in it"
				: "About " + (minutes <= 1 ? "a minute" : minutes + " minutes") + " left", Step.Target.COFFER);
		}

		if (s.bankOpen)
		{
			return atBank(s, needsCoal, bag);
		}

		// Bars waiting come out before anything else, so the dispenser never backs up.
		boolean carryingLoad = s.ore > 0 || s.coal > 0;
		if (s.dispenserBars > 0 && !carryingLoad && s.bars == 0)
		{
			if (s.dispenserState == 2 && !s.iceGlovesWorn)
			{
				if (s.iceGlovesCarried)
				{
					return Step.items("Equip", "Put on your ice gloves", "The bars are too hot to touch without them", ItemIds.ICE_GLOVES);
				}
				return Step.waiting("Wait for the bars to cool", "Ice gloves let you take them hot", Step.Target.DISPENSER);
			}
			if (dispenserReady(s))
			{
				return Step.of("Take", "Take the bars from the dispenser",
					s.dispenserBars + " " + bar.barName(s.dispenserBars), Step.Target.DISPENSER);
			}
		}

		if (carryingLoad)
		{
			if (s.dispenserBars >= DISPENSER_FULL && s.bars == 0 && s.free > 0 && dispenserReady(s))
			{
				return Step.of("Take", "Take the bars first", "The dispenser is full", Step.Target.DISPENSER);
			}
			if (bar == Bar.GOLD && s.ore > 0 && s.goldsmithCarried && !s.goldsmithWorn)
			{
				return Step.items("Equip", "Put on your goldsmith gauntlets",
					"They more than double the experience from gold bars", ItemIds.GOLDSMITH_GAUNTLETS);
			}
			String what = s.ore > 0 && s.coal > 0 ? "ore and coal" : s.ore > 0 ? bar.oreName() : "coal";
			return Step.of("Load", "Put the " + what + " on the conveyor belt",
				(s.ore + s.coal) + " to load", Step.Target.BELT);
		}

		if (needsCoal && s.coalBag && bag > 0 && s.free > 0)
		{
			return Step.items("Empty", "Empty the coal bag", bag + " coal, then load the belt again", ItemIds.COAL_BAG, ItemIds.COAL_BAG_OPEN);
		}

		if (s.bars > 0)
		{
			return Step.of("Bank", "Bank your bars", "Then the next load", Step.Target.BANK);
		}

		boolean smelting = s.furnaceOre > 0 || onBelt > 0 || s.dispenserBars > 0;
		if (smelting && (s.furnaceOre == 0 || s.furnaceCoal >= bar.getCoal()))
		{
			if (s.iceGlovesCarried && !s.iceGlovesWorn)
			{
				return Step.items("Equip", "Put on your ice gloves while the bars smelt", "Then take them from the dispenser", ItemIds.ICE_GLOVES);
			}
			return Step.waiting("Wait at the bar dispenser", "The " + bar.barName(2) + " are smelting", Step.Target.DISPENSER);
		}

		return Step.of("Bank", "Open the bank", coalRunNext(s) ? "Next: a coal trip" : "Next: " + bar.oreName(), Step.Target.BANK);
	}

	private Step atBank(Snapshot s, boolean needsCoal, int bag)
	{
		Bar bar = s.bar;
		if (s.bars > 0)
		{
			return Step.items("Deposit", "Deposit your bars", s.bars + (s.bars == 1 ? " bar" : " bars"), barIds());
		}
		if (bar == Bar.GOLD && s.goldsmithCarried && !s.goldsmithWorn)
		{
			return Step.items("Equip", "Put on your goldsmith gauntlets", "Before the gold goes on the belt", ItemIds.GOLDSMITH_GAUNTLETS);
		}
		boolean coalRun = coalRunNext(s);
		if (needsCoal && s.coalBag && (s.bagCoal < 0 || bag < s.bagCapacity) && s.bankCoal != 0)
		{
			return Step.items("Fill", "Fill the coal bag", s.bagCoal < 0 ? "From the bank's coal" : bag + " of " + s.bagCapacity + " coal now",
				ItemIds.COAL_BAG, ItemIds.COAL_BAG_OPEN);
		}
		if (coalRun)
		{
			if (s.coal == 0 && s.free > 0)
			{
				int need = Math.max(1, bar.getCoal() * load(s) - s.furnaceCoal - (s.coalBag ? s.bagCapacity : 0));
				String detail = s.bankCoal == 0 ? "You are out of coal"
					: "A coal trip: the furnace needs " + need + " more before the next ore";
				return Step.items("Withdraw", "Withdraw coal", detail, Bar.COAL);
			}
		}
		else if (s.ore == 0 && s.free > 0)
		{
			if (s.bankOre == 0)
			{
				return Step.items("Withdraw", "Withdraw " + bar.oreName(), "You are out of " + bar.oreName(), bar.getOre());
			}
			String detail = needsCoal ? s.furnaceCoal + " coal waiting in the furnace" : load(s) + " ore makes " + load(s) + " bars";
			return Step.items("Withdraw", "Withdraw " + bar.oreName(), detail, bar.getOre());
		}
		return Step.of("Load", "Close the bank and load the belt", (s.ore + s.coal) + " to load", Step.Target.BELT);
	}

	private static int[] barIds()
	{
		Bar[] bars = Bar.values();
		int[] ids = new int[bars.length];
		for (int i = 0; i < bars.length; i++)
		{
			ids[i] = bars[i].getBar();
		}
		return ids;
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.function.IntPredicate;

/**
 * What you are working toward in a minigame and how far off it is. A reward goal adds up the
 * pieces you do not own yet (a prospector piece in the bank counts as owned), takes off what you
 * already hold in the minigame's currency, and turns the rest into rounds and time at your own
 * pace. A level goal does the same with experience.
 */
public final class Goal
{
	/** A reward from a minigame's shop. */
	public enum Reward
	{
		PROSPECTOR_HELMET("Prospector helmet", 40, Currency.NUGGETS, 12013, 25549),
		PROSPECTOR_JACKET("Prospector jacket", 60, Currency.NUGGETS, 12014, 25551),
		PROSPECTOR_LEGS("Prospector legs", 50, Currency.NUGGETS, 12015, 25553),
		PROSPECTOR_BOOTS("Prospector boots", 30, Currency.NUGGETS, 12016, 25555),
		COAL_BAG("Coal bag", 100, Currency.NUGGETS, 12019, 24480),
		GEM_BAG("Gem bag", 100, Currency.NUGGETS, 12020, 24481),
		/** Owned when the sack's upgrade varbit is set, not by an item. */
		BIGGER_SACK("Bigger sack", 200, Currency.NUGGETS),
		CARPENTERS_HELMET("Carpenter's helmet", 400, Currency.POINTS, 24872),
		CARPENTERS_SHIRT("Carpenter's shirt", 800, Currency.POINTS, 24874),
		CARPENTERS_TROUSERS("Carpenter's trousers", 600, Currency.POINTS, 24876),
		CARPENTERS_BOOTS("Carpenter's boots", 200, Currency.POINTS, 24878),
		PLANK_SACK("Plank sack", 350, Currency.POINTS, 24882),
		/** The saw, or the same saw made into an off-hand. */
		AMYS_SAW("Amy's saw", 500, Currency.POINTS, 24880, 29774),
		HOSIDIUS_BLUEPRINTS("Hosidius blueprints", 2000, Currency.POINTS, 24885);

		private final String name;
		private final int cost;
		private final Currency currency;
		private final int[] items;

		Reward(String name, int cost, Currency currency, int... items)
		{
			this.name = name;
			this.cost = cost;
			this.currency = currency;
			this.items = items;
		}

		public String getName()
		{
			return name;
		}

		public int getCost()
		{
			return cost;
		}

		public Currency getCurrency()
		{
			return currency;
		}

		/** The items that mean you own it, any one of them. */
		public int[] getItems()
		{
			return items.clone();
		}

		/** Whether any of its items is among what you have. */
		public boolean ownedBy(IntPredicate have)
		{
			for (int id : items)
			{
				if (have.test(id))
				{
					return true;
				}
			}
			return false;
		}
	}

	/** What a minigame's shop takes. */
	public enum Currency
	{
		NUGGETS("nugget", "nuggets"),
		POINTS("point", "points");

		private final String one;
		private final String many;

		Currency(String one, String many)
		{
			this.one = one;
			this.many = many;
		}

		public String of(long n)
		{
			return n == 1 ? one : many;
		}
	}

	/** One piece of a reward goal. */
	public static final class Piece
	{
		private final Reward reward;
		private final boolean owned;

		public Piece(Reward reward, boolean owned)
		{
			this.reward = reward;
			this.owned = owned;
		}

		public Reward getReward()
		{
			return reward;
		}

		public boolean isOwned()
		{
			return owned;
		}
	}

	private final String title;
	private final long have;
	private final long need;
	private final String unit;
	private final List<Piece> pieces;
	private final double perHour;
	private final double perRound;
	private final String roundName;

	private Goal(String title, long have, long need, String unit, List<Piece> pieces, double perHour, double perRound, String roundName)
	{
		this.title = title;
		this.have = Math.max(0, have);
		this.need = Math.max(0, need);
		this.unit = unit;
		this.pieces = Collections.unmodifiableList(pieces);
		this.perHour = perHour;
		this.perRound = perRound;
		this.roundName = roundName;
	}

	/**
	 * @param title "Prospector kit"
	 * @param pieces every reward in the goal, with whether you own it
	 * @param balance what you hold of the currency now
	 * @param perHour currency you earn an hour at your pace, or 0 when not known yet
	 * @param perRound currency a round earns, or 0 when not known
	 * @param roundName "contract", for "4 contracts to go"
	 */
	public static Goal rewards(String title, Currency currency, List<Piece> pieces, long balance, double perHour, double perRound, String roundName)
	{
		long cost = 0;
		for (Piece p : pieces)
		{
			if (!p.owned)
			{
				cost += p.reward.cost;
			}
		}
		return new Goal(title, Math.min(balance, cost), cost, currency.many, new ArrayList<>(pieces), perHour, perRound, roundName);
	}

	/**
	 * @param skill "Mining"
	 * @param xp your experience now
	 * @param level the level to reach
	 * @param fromXp the experience the climb is measured from, such as the start of the current level
	 * @param toXp the experience the level takes
	 * @param perHour experience an hour at your pace, or 0
	 * @param perRound experience a round earns, or 0
	 */
	public static Goal level(String skill, int level, long fromXp, long xp, long toXp, double perHour, double perRound, String roundName)
	{
		long span = Math.max(1, toXp - fromXp);
		long done = Math.max(0, Math.min(span, xp - fromXp));
		return new Goal(skill + " level " + level, done, span, "xp", Collections.emptyList(), perHour, perRound, roundName);
	}

	/** The first reward in the list you do not own yet, or null when you have them all. */
	public static Reward firstMissing(List<Reward> rewards, IntPredicate have, java.util.Set<Reward> ownedOtherwise)
	{
		for (Reward r : rewards)
		{
			if (!ownedOtherwise.contains(r) && !r.ownedBy(have))
			{
				return r;
			}
		}
		return null;
	}

	public String getTitle()
	{
		return title;
	}

	/** How much of the goal you have, capped at what it needs. */
	public long getHave()
	{
		return have;
	}

	/** What the goal still takes in all, before what you hold. */
	public long getNeed()
	{
		return need;
	}

	public String getUnit()
	{
		return unit;
	}

	public List<Piece> getPieces()
	{
		return pieces;
	}

	public long toGo()
	{
		return Math.max(0, need - have);
	}

	public boolean done()
	{
		return toGo() == 0;
	}

	public double progress()
	{
		return need == 0 ? 1 : have / (double) need;
	}

	/** Rounds left at what a round earns, or -1 when not known. */
	public long roundsLeft()
	{
		if (perRound <= 0)
		{
			return -1;
		}
		return (long) Math.ceil(toGo() / perRound - 1e-9);
	}

	/** Minutes left at your pace, or -1 when your pace is not known yet. */
	public long minutesLeft()
	{
		if (perHour <= 0)
		{
			return -1;
		}
		return (long) Math.ceil(toGo() * 60 / perHour - 1e-9);
	}

	/** "143 nuggets to go · 36 contracts · about 2h 10m" */
	public String describe()
	{
		if (need == 0 && !pieces.isEmpty())
		{
			return "All owned. Pick another goal in the settings";
		}
		if (done())
		{
			return pieces.isEmpty() ? "Reached" : "You have enough: off to the shop";
		}
		StringBuilder b = new StringBuilder(group(toGo()) + " " + unit + " to go");
		long rounds = roundsLeft();
		if (rounds > 0 && roundName != null)
		{
			b.append(" · ").append(rounds).append(' ').append(rounds == 1 ? roundName : roundName + "s");
		}
		long minutes = minutesLeft();
		if (minutes >= 0)
		{
			b.append(" · about ").append(duration(minutes));
		}
		return b.toString();
	}

	/** 130 minutes as "2h 10m". */
	public static String duration(long minutes)
	{
		if (minutes < 60)
		{
			return Math.max(1, minutes) + "m";
		}
		long h = minutes / 60;
		long m = minutes % 60;
		if (h >= 100)
		{
			return h + "h";
		}
		return m == 0 ? h + "h" : h + "h " + m + "m";
	}

	static String group(long n)
	{
		return Figures.count(n);
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntPredicate;

/**
 * Turns a goal chosen in the settings into a {@link Goal}: which rewards it covers, what you
 * already own, what you hold, and your pace. "Next reward" walks the usual order of buys and
 * picks the first set you have not finished; once every reward is owned it becomes the next
 * level.
 */
public final class Goals
{
	/** The goals each minigame offers, as the settings name them. */
	public enum Choice
	{
		NEXT_REWARD("Next reward"),
		PROSPECTOR_KIT("Prospector kit"),
		COAL_BAG("Coal bag"),
		GEM_BAG("Gem bag"),
		BIGGER_SACK("Bigger sack"),
		CARPENTERS_OUTFIT("Carpenter's outfit"),
		PLANK_SACK("Plank sack"),
		AMYS_SAW("Amy's saw"),
		HOSIDIUS_BLUEPRINTS("Hosidius blueprints"),
		EVERY_REWARD("Every reward"),
		NEXT_LEVEL("Next level"),
		OFF("Off");

		private final String label;

		Choice(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Reward sets in the order players usually buy them. */
	static final List<List<Goal.Reward>> MOTHERLODE_ORDER = Arrays.asList(
		Arrays.asList(Goal.Reward.PROSPECTOR_HELMET, Goal.Reward.PROSPECTOR_JACKET, Goal.Reward.PROSPECTOR_LEGS, Goal.Reward.PROSPECTOR_BOOTS),
		Collections.singletonList(Goal.Reward.COAL_BAG),
		Collections.singletonList(Goal.Reward.GEM_BAG),
		Collections.singletonList(Goal.Reward.BIGGER_SACK));
	static final List<List<Goal.Reward>> HOMES_ORDER = Arrays.asList(
		Collections.singletonList(Goal.Reward.PLANK_SACK),
		Arrays.asList(Goal.Reward.CARPENTERS_HELMET, Goal.Reward.CARPENTERS_SHIRT, Goal.Reward.CARPENTERS_TROUSERS, Goal.Reward.CARPENTERS_BOOTS),
		Collections.singletonList(Goal.Reward.AMYS_SAW),
		Collections.singletonList(Goal.Reward.HOSIDIUS_BLUEPRINTS));

	/** What a goal is worked out from. */
	public static final class Input
	{
		/** Whether you have an item anywhere the Pilot can see: carried, worn or banked. */
		public IntPredicate have = id -> false;
		/** Rewards owned some other way, such as the bigger sack. */
		public Set<Goal.Reward> ownedOtherwise = EnumSet.noneOf(Goal.Reward.class);
		/** The currency you hold, or -1 when not known yet. */
		public long balance = -1;
		public double currencyPerHour;
		public double currencyPerRound;
		public String roundName;
		public String skill;
		public long xp;
		public double xpPerHour;
		public double xpPerRound;
		/** The level to reach for a level goal, 0 for the next one. */
		public int targetLevel;
	}

	private Goals()
	{
	}

	public static Goal motherlode(Choice choice, Input in)
	{
		return plan(choice, in, MOTHERLODE_ORDER, Goal.Currency.NUGGETS);
	}

	public static Goal homes(Choice choice, Input in)
	{
		return plan(choice, in, HOMES_ORDER, Goal.Currency.POINTS);
	}

	/** The Blast Furnace has no shop: its goal is always a level. */
	public static Goal furnace(Input in)
	{
		return level(in);
	}

	static Goal plan(Choice choice, Input in, List<List<Goal.Reward>> order, Goal.Currency currency)
	{
		if (choice == null || choice == Choice.OFF)
		{
			return null;
		}
		if (choice == Choice.NEXT_LEVEL)
		{
			return level(in);
		}
		List<Goal.Reward> set;
		String title;
		if (choice == Choice.NEXT_REWARD)
		{
			set = null;
			title = null;
			for (List<Goal.Reward> s : order)
			{
				if (!allOwned(s, in))
				{
					set = s;
					title = titleOf(s);
					break;
				}
			}
			if (set == null)
			{
				return level(in);
			}
		}
		else if (choice == Choice.EVERY_REWARD)
		{
			set = new ArrayList<>();
			for (List<Goal.Reward> s : order)
			{
				set.addAll(s);
			}
			title = "Every reward";
		}
		else
		{
			set = setFor(choice, order);
			if (set == null)
			{
				// A goal from the other minigame's shop: fall back to the next reward here.
				return plan(Choice.NEXT_REWARD, in, order, currency);
			}
			title = titleOf(set);
		}
		List<Goal.Piece> pieces = new ArrayList<>();
		for (Goal.Reward r : set)
		{
			pieces.add(new Goal.Piece(r, owned(r, in)));
		}
		return Goal.rewards(title, currency, pieces, Math.max(0, in.balance), in.currencyPerHour, in.currencyPerRound, in.roundName);
	}

	private static List<Goal.Reward> setFor(Choice choice, List<List<Goal.Reward>> order)
	{
		Goal.Reward key;
		switch (choice)
		{
			case PROSPECTOR_KIT:
				key = Goal.Reward.PROSPECTOR_HELMET;
				break;
			case COAL_BAG:
				key = Goal.Reward.COAL_BAG;
				break;
			case GEM_BAG:
				key = Goal.Reward.GEM_BAG;
				break;
			case BIGGER_SACK:
				key = Goal.Reward.BIGGER_SACK;
				break;
			case CARPENTERS_OUTFIT:
				key = Goal.Reward.CARPENTERS_HELMET;
				break;
			case PLANK_SACK:
				key = Goal.Reward.PLANK_SACK;
				break;
			case AMYS_SAW:
				key = Goal.Reward.AMYS_SAW;
				break;
			case HOSIDIUS_BLUEPRINTS:
				key = Goal.Reward.HOSIDIUS_BLUEPRINTS;
				break;
			default:
				return null;
		}
		for (List<Goal.Reward> s : order)
		{
			if (s.contains(key))
			{
				return s;
			}
		}
		return null;
	}

	static String titleOf(List<Goal.Reward> set)
	{
		if (set.contains(Goal.Reward.PROSPECTOR_HELMET))
		{
			return "Prospector kit";
		}
		if (set.contains(Goal.Reward.CARPENTERS_HELMET))
		{
			return "Carpenter's outfit";
		}
		return set.get(0).getName();
	}

	static boolean owned(Goal.Reward r, Input in)
	{
		return in.ownedOtherwise.contains(r) || r.ownedBy(in.have);
	}

	private static boolean allOwned(List<Goal.Reward> set, Input in)
	{
		for (Goal.Reward r : set)
		{
			if (!owned(r, in))
			{
				return false;
			}
		}
		return true;
	}

	static Goal level(Input in)
	{
		int now = levelFor(in.xp);
		if (now >= 99 && in.targetLevel <= 99)
		{
			return null;
		}
		int target = in.targetLevel > now ? Math.min(99, in.targetLevel) : Math.min(99, now + 1);
		// The bar measures from the start of the level you are on.
		long from = xpFor(now);
		return Goal.level(in.skill == null ? "Skill" : in.skill, target, from, in.xp, xpFor(target), in.xpPerHour, in.xpPerRound, in.roundName);
	}

	/** The experience a level takes, by the game's own table. */
	public static long xpFor(int level)
	{
		if (XP != null && level >= 1 && level < XP.length)
		{
			return XP[level];
		}
		return worked(level);
	}

	/** Experience at each level 1 to 99, worked out once: a level is looked up every tick. */
	private static final long[] XP = table();

	private static long[] table()
	{
		long[] t = new long[100];
		for (int level = 1; level < t.length; level++)
		{
			t[level] = worked(level);
		}
		return t;
	}

	/** The game's experience formula for a level. */
	private static long worked(int level)
	{
		long points = 0;
		for (int i = 1; i < level; i++)
		{
			points += (long) Math.floor(i + 300 * Math.pow(2, i / 7.0));
		}
		return points / 4;
	}

	/** The level some experience gives, up to 99. */
	public static int levelFor(long xp)
	{
		int level = 1;
		while (level < 99 && xpFor(level + 1) <= xp)
		{
			level++;
		}
		return level;
	}
}

