		this.city = city;
		this.where = where;
		this.npcId = npcId;
		this.x = x;
		this.y = y;
		this.width = width;
		this.height = height;
		this.doorX = doorX;
		this.doorY = doorY;
		this.clientUpstairs = clientUpstairs;
