package com.codex.minigamepilot.core;

/**
 * The Motherlode Mine loop: mine pay-dirt, wash it through the hopper until the sack is full,
 * then empty the sack into the bank and go again.
 *
 * <p>The cycle sizes each load so the sack fills exactly: when the sack has room for 19 more,
 * it says to mine 19, not a full inventory that the hopper would turn away. Pay-dirt still
 * washing through the wheel is counted as in flight, so the sack is never overfilled by a load
 * that has not reached it yet. It remembers whether it is filling or emptying the sack, since
 * the same inventory means different things on the way in and on the way out.
 */
public final class MotherlodeCycle
{
	/** Ticks with pay-dirt in flight and nothing reaching the sack before the count is dropped. */
	static final int FLIGHT_TIMEOUT = 60;

	/** What the game shows this tick. */
	public static final class Snapshot
	{
		/** Pay-dirt carried. */
		public int payDirt;
		/** Empty inventory slots. */
		public int free;
		/** Ore and uncut gems carried, which go to the bank. */
		public int loot;
		/** Pay-dirt waiting in the sack. */
		public int sack;
		/** 108, or 189 with the bigger sack. */
		public int capacity = 108;
		/** Struts that are broken; with both down the wheel stops. */
		public int brokenStruts;
		public boolean hammer;
	}

	private boolean emptying;
	private int inFlight;
	private int lastPayDirt = -1;
	private int lastSack = -1;
	private int idle;
	private int deposited;

	/**
	 * Follows pay-dirt from the inventory into the hopper and out into the sack.
	 *
	 * @param nearHopper whether the player is at the hopper, so pay-dirt leaving the inventory went into it
	 * @param wheelStopped whether both struts are broken, which holds pay-dirt in the water
	 */
	public void observe(int payDirt, int sack, boolean nearHopper, boolean wheelStopped)
	{
		if (lastPayDirt >= 0 && payDirt < lastPayDirt && nearHopper)
		{
			int went = lastPayDirt - payDirt;
			inFlight += went;
			deposited += went;
			idle = 0;
		}
		if (lastSack >= 0 && sack > lastSack)
		{
			inFlight = Math.max(0, inFlight - (sack - lastSack));
			idle = 0;
		}
		if (inFlight > 0 && !wheelStopped && ++idle > FLIGHT_TIMEOUT)
		{
			inFlight = 0;
		}
		lastPayDirt = payDirt;
		lastSack = sack;
	}

	/**
	 * After logging in or hopping: the last readings are no base for change, but pay-dirt already
	 * in the hopper is still on its way to the sack.
	 */
	public void relog()
	{
		lastPayDirt = -1;
		lastSack = -1;
	}

	/** Forgets what was in flight, such as after leaving the mine. */
	public void reset()
	{
		inFlight = 0;
		lastPayDirt = -1;
		lastSack = -1;
		idle = 0;
	}

	public int getInFlight()
	{
		return inFlight;
	}

	/** Pay-dirt put in the hopper since the cycle began. */
	public int getDeposited()
	{
		return deposited;
	}

	public boolean isEmptying()
	{
		return emptying;
	}

	/** Room left in the sack once everything in flight has landed. */
	public int room(Snapshot s)
	{
		return Math.max(0, s.capacity - s.sack - inFlight);
	}

	/** How much pay-dirt this load should hold: what fits in the bag, capped by what the sack can still take. */
	public int loadSize(Snapshot s)
	{
		return Math.min(s.free + s.payDirt, room(s));
	}

	public Step next(Snapshot s)
	{
		int room = room(s);
		boolean wheelStopped = s.brokenStruts >= 2;

		if (!emptying && s.payDirt == 0 && room == 0)
		{
			emptying = true;
		}
		if (emptying && s.sack == 0 && inFlight == 0 && s.loot == 0)
		{
			emptying = false;
		}

		if (emptying)
		{
			return emptyingStep(s, room, wheelStopped);
		}

		int load = loadSize(s);
		if (s.payDirt > 0 && (s.payDirt >= load || s.free == 0))
		{
			if (room == 0)
			{
				// Mined more than the sack can take; it must be emptied, which needs room in the bag.
				return Step.of("Bank", "Bank the pay-dirt you are carrying",
					"The sack is full, and emptying it needs free space", Step.Target.BANK);
			}
			int after = s.sack + inFlight + Math.min(s.payDirt, room);
			return Step.of("Deposit", "Deposit your pay-dirt in the hopper",
				s.payDirt + " pay-dirt in, sack " + after + " of " + s.capacity + " once it lands", Step.Target.HOPPER);
		}
		if (wheelStopped && inFlight > 0)
		{
			return repair(s);
		}
		if (s.free == 0)
		{
			return Step.of("Bank", "Bank your ore and gems", "Your inventory is full", Step.Target.BANK);
		}
		int more = load - s.payDirt;
		String detail = more == 1 ? "1 more fills this load" : more + " more fills this load";
		if (room < s.free + s.payDirt)
		{
			detail += ", which fills the sack";
		}
		return Step.of("Mine", "Mine pay-dirt", detail, Step.Target.VEIN);
	}

	private Step emptyingStep(Snapshot s, int room, boolean wheelStopped)
	{
		if (s.payDirt > 0 && room > 0)
		{
			return Step.of("Deposit", "Deposit your pay-dirt in the hopper", "The sack still has room for " + room, Step.Target.HOPPER);
		}
		if (s.free == 0 || s.payDirt > 0)
		{
			String left = s.sack > 0 ? s.sack + " pay-dirt still in the sack" : "Then mine the next sackful";
			return Step.of("Bank", s.payDirt > 0 ? "Bank your inventory" : "Bank your ore and gems", left, Step.Target.BANK);
		}
		if (s.sack > 0)
		{
			int take = Math.min(s.free, s.sack);
			String detail = take == s.sack ? "Takes the last " + take : "Takes " + take + " of " + s.sack + ", then bank";
			return Step.of("Collect", "Search the sack", detail, Step.Target.SACK);
		}
		if (inFlight > 0)
		{
			if (wheelStopped)
			{
				return repair(s);
			}
			return Step.waiting("Wait by the sack", inFlight + " pay-dirt is still washing through", Step.Target.SACK);
		}
		return Step.of("Bank", "Bank your ore and gems", "The sack is empty: then mine the next sackful", Step.Target.BANK);
	}

	private static Step repair(Snapshot s)
	{
		String detail = s.hammer ? "Both struts are broken, so the wheel has stopped"
			: "Both struts are broken: take a hammer from the crate first";
		return Step.of("Repair", "Hammer a broken strut", detail, Step.Target.STRUT);
	}
}

package com.codex.minigamepilot.core;

import com.google.gson.Gson;
import java.util.List;
import java.util.Map;

/**
 * The levels Codex Navigator's pinned goals still need, so a minigame can say what its training
 * is for. Navigator saves its goal board for companion plugins to read (fields only ever added);
 * this keeps just what the Pilot uses: each unfinished goal's title, how long it has left and
 * the levels it needs. With Navigator not installed there is no board and nothing changes.
 */
public final class NavigatorGoals
{
	/** One of Navigator's pinned goals, as saved. Field names are Navigator's. */
	public static final class Entry
	{
		public String key;
		public String title;
		public boolean complete;
		public double hoursLeft;
		public Map<String, Integer> skills;
	}

	/** Navigator's saved board, as far as the Pilot reads it. */
	public static final class Board
	{
		public int version;
		public String focus;
		public List<Entry> goals;
	}

	/** A level a goal needs. */
	public static final class Target
	{
		private final int level;
		private final String goal;
		private final boolean focus;

		Target(int level, String goal, boolean focus)
		{
			this.level = level;
			this.goal = goal;
			this.focus = focus;
		}

		public int getLevel()
		{
			return level;
		}

		/** The goal's title, such as "Dragon Slayer II". */
		public String getGoal()
		{
			return goal;
		}

		/** True when it is the goal Navigator has in focus. */
		public boolean isFocus()
		{
			return focus;
		}
	}

	private NavigatorGoals()
	{
	}

	/** Navigator's saved board, or null when there is none or this version cannot read it. */
	public static Board read(Gson gson, String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, Board.class);
		}
		catch (RuntimeException e)
		{
			// Gson lets a NumberFormatException through unwrapped for "x" in a number field.
			// A board this version cannot read is left alone: goals work as without Navigator.
			return null;
		}
	}

	/**
	 * The level to train a skill to next for your goals: the focus goal's, when it needs this
	 * skill above where you are; otherwise the nearest level above yours any unfinished goal needs.
	 *
	 * @return the target, or null when no goal needs the skill above your level
	 */
	public static Target target(Board board, String skill, int level)
	{
		if (board == null || board.goals == null || skill == null)
		{
			return null;
		}
		Target nearest = null;
		for (Entry e : board.goals)
		{
			if (e == null || e.complete || e.skills == null)
			{
				continue;
			}
			Integer need = need(e.skills, skill);
			if (need == null || need <= level || need > 99)
			{
				continue;
			}
			String title = e.title == null || e.title.isEmpty() ? "a Navigator goal" : e.title;
			boolean focus = e.key != null && e.key.equals(board.focus);
			if (focus)
			{
				return new Target(need, title, true);
			}
			if (nearest == null || need < nearest.level)
			{
				nearest = new Target(need, title, false);
			}
		}
		return nearest;
	}

	/** The level a goal needs in a skill, matching the name however it is capitalised. */
	private static Integer need(Map<String, Integer> skills, String skill)
	{
		for (Map.Entry<String, Integer> s : skills.entrySet())
		{
			if (s.getKey() != null && s.getKey().equalsIgnoreCase(skill) && s.getValue() != null)
			{
				return s.getValue();
			}
		}
		return null;
	}
}

package com.codex.minigamepilot.core;

import java.util.function.IntUnaryOperator;

/**
 * The ore the Motherlode Mine's sack has paid out this session, and what it is worth. Ore is only
 * counted on a tick the sack goes down, when what turns up in your pack can only have come out
 * of it: ore taken from the bank or picked up elsewhere is left out.
 *
 * <p>With an open coal bag, the sack's coal goes straight into the bag and never shows in the
 * pack. The sack says how many pieces it gave, so whatever of that did not land in the pack
 * (ore or nuggets) went into the bag as coal.</p>
 */
public final class OreHaul
{
	/** What the sack pays out: coal and the four ores, in that order. */
	public static final int[] ORES = {453, 444, 447, 449, 451};

	private final long[] haul = new long[ORES.length];
	private final int[] last = new int[ORES.length];
	private boolean seen;
	/** Ticks left in which a pack that grows is the sack paying out. */
	private int window;
	/** Pieces the sack gave in the payout being watched, and how many of them landed in the pack. */
	private int paid;
	private int landed;
	private int lastNuggets;
	/** Whether an open coal bag was carried when the sack paid out. */
	private boolean bagOpen;

	/**
	 * One tick, without a coal bag.
	 *
	 * @param carried how many of each of {@link #ORES} you carry now, in that order
	 * @param sackPaidOut whether the sack went down since the last tick
	 */
	public void observe(int[] carried, boolean sackPaidOut)
	{
		observe(carried, 0, sackPaidOut ? 1 : 0, false);
	}

	/**
	 * One tick.
	 *
	 * @param carried how many of each of {@link #ORES} you carry now, in that order
	 * @param nuggets golden nuggets carried now
	 * @param sackDrop how many pieces the sack went down by since the last tick
	 * @param openCoalBag whether an open coal bag is carried, which takes the sack's coal
	 */
	public void observe(int[] carried, int nuggets, int sackDrop, boolean openCoalBag)
	{
		if (sackDrop > 0)
		{
			if (window == 0)
			{
				paid = 0;
				landed = 0;
				bagOpen = false;
			}
			window = 2;
			// Only a payout seen from a known pack can say what went into the bag.
			paid += seen ? sackDrop : 0;
			bagOpen |= openCoalBag;
		}
		for (int i = 0; i < ORES.length; i++)
		{
			int now = i < carried.length ? Math.max(0, carried[i]) : 0;
			if (seen && window > 0 && now > last[i])
			{
				haul[i] += now - last[i];
				landed += now - last[i];
			}
			last[i] = now;
		}
		int n = Math.max(0, nuggets);
		if (seen && window > 0 && n > lastNuggets)
		{
			landed += n - lastNuggets;
		}
		lastNuggets = n;
		if (window > 0 && --window == 0)
		{
			if (bagOpen && paid > landed)
			{
				// What the sack gave but the pack never showed went into the coal bag.
				haul[0] += paid - landed;
			}
			paid = 0;
			landed = 0;
			bagOpen = false;
		}
		seen = true;
	}

	/** After leaving the mine: what you carry then is no guide to what comes next. */
	public void forget()
	{
		seen = false;
		window = 0;
		paid = 0;
		landed = 0;
		bagOpen = false;
	}

	/** A new session: the haul starts again from nothing. */
	public void clear()
	{
		java.util.Arrays.fill(haul, 0);
	}

	public long count()
	{
		long n = 0;
		for (long h : haul)
		{
			n += h;
		}
		return n;
	}

	/** The haul at today's Grand Exchange prices; ore without a price yet counts nothing. */
	public long worth(IntUnaryOperator price)
	{
		long coins = 0;
		for (int i = 0; i < ORES.length; i++)
		{
			coins += haul[i] * Math.max(0, price.applyAsInt(ORES[i]));
		}
		return coins;
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The shop rewards you have been seen to own, remembered per account. A carpenter's outfit or a
 * prospector kit put away in your house's costume room drops out of sight of the inventory, worn
 * items and the bank, but you still own it, so once a reward has been seen carried, worn or in
 * your bank it stays owned. A reward that turned up in your pack while group storage was open
 * might be a group mate's, so it is not remembered for that session.
 */
public final class Owned
{
	private final EnumSet<Goal.Reward> owned = EnumSet.noneOf(Goal.Reward.class);
	private final EnumSet<Goal.Reward> borrowed = EnumSet.noneOf(Goal.Reward.class);
	/**
	 * Saved names this version does not know (a reward a newer version added), kept as they were
	 * so saving again does not forget that you own it.
	 */
	private final List<String> unknown = new ArrayList<>();
	/** What a reward's saved name looks like; anything else is damage, and dropped. */
	private static final Pattern NAME = Pattern.compile("[A-Z][A-Z0-9_]{0,47}");
	/** At most this many unknown names are kept, so damage cannot make the saved value grow. */
	private static final int KEEP_UNKNOWN = 16;

	/**
	 * One tick.
	 *
	 * @param seen rewards carried, worn or in the bank as last seen
	 * @param appeared rewards in your pack now that were not carried or worn a tick ago
	 * @param groupStorage whether group storage was open on this tick or the last
	 * @return true when a reward was remembered for the first time, so the memory wants saving
	 */
	public boolean see(Set<Goal.Reward> seen, Set<Goal.Reward> appeared, boolean groupStorage)
	{
		if (groupStorage)
		{
			for (Goal.Reward r : appeared)
			{
				if (!owned.contains(r))
				{
					borrowed.add(r);
				}
			}
		}
		boolean grew = false;
		for (Goal.Reward r : seen)
		{
			if (!borrowed.contains(r) && r.getItems().length > 0)
			{
				grew |= owned.add(r);
			}
		}
		return grew;
	}

	public boolean has(Goal.Reward r)
	{
		return owned.contains(r);
	}

	/** Whether an item is one of a reward you are remembered to own. */
	public boolean hasItem(int id)
	{
		for (Goal.Reward r : owned)
		{
			for (int item : r.getItems())
			{
				if (item == id)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Saved as reward names joined by commas. */
	public String encode()
	{
		StringBuilder b = new StringBuilder();
		for (Goal.Reward r : owned)
		{
			if (b.length() > 0)
			{
				b.append(',');
			}
			b.append(r.name());
		}
		for (String name : unknown)
		{
			if (b.length() > 0)
			{
				b.append(',');
			}
			b.append(name);
		}
		return b.toString();
	}

	/**
	 * Reads a saved memory. A name this version does not know is kept to be saved again, unless it
	 * is not a name at all. Group storage sightings start afresh.
	 */
	public static Owned decode(String saved)
	{
		Owned o = new Owned();
		if (saved == null || saved.isEmpty())
		{
			return o;
		}
		for (String part : saved.split(","))
		{
			try
			{
				Goal.Reward r = Goal.Reward.valueOf(part.trim().toUpperCase(Locale.ENGLISH));
				if (r.getItems().length > 0)
				{
					o.owned.add(r);
				}
			}
			catch (IllegalArgumentException e)
			{
				// A reward this version does not know counts for nothing here, but is kept for
				// the version that wrote it.
				String name = part.trim();
				if (NAME.matcher(name).matches() && !o.unknown.contains(name) && o.unknown.size() < KEEP_UNKNOWN)
				{
					o.unknown.add(name);
				}
			}
		}
		return o;
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The pace coach. Fed one sample a game tick, it cuts the minigame into rounds (each time the
 * loop comes back to its first stage), and for each round counts where time went: ticks spent
 * standing still while there was something to do, and tiles walked beyond the shortest way.
 * Each round is compared with your best of the same kind, such as a full load of pay-dirt or an
 * ore trip of steel, and the biggest loss becomes one line of advice.
 */
public final class Pace
{
	/** Standing still for a tick after the step changes is just the time it takes to click. */
	static final int GRACE = 1;
	/** Walking a tile or two over the shortest way is not worth mentioning. */
	public static final int TOLERANCE = 2;
	/** A round this many times the usual length had a break in it, and is not a fair comparison. */
	static final int BREAK_FACTOR = 3;
	private static final int KEEP = 50;
	/** Stages a loop can have; the step's stage number indexes the splits. */
	public static final int STAGES = 31;
	/** Marks a saved best as one stage of a kind of round: "kind#stage=ticks". */
	private static final char STAGE_MARK = '#';

	/** One finished round. */
	public static final class Round
	{
		public final String kind;
		public final int ticks;
		public final int units;
		public final int idle;
		/** Where the most standing still happened, such as "the bank", or null. */
		public final String idlePlace;
		public final int idlePlaceTicks;
		public final int extraTiles;
		/** The walk that went furthest out of its way, or null. */
		public final String extraPlace;
		public final int extraPlaceTiles;
		/** Your best for this kind of round before this one, or 0 when this is the first. */
		public final int bestBefore;
		public final boolean hadBreak;
		/*
		 * Stage splits. Transient so the field notes' record of a round keeps exactly the shape it
		 * had before splits existed.
		 */
		/** Ticks spent in each stage of the loop this round, by stage. */
		private final transient int[] stageTicks;
		/** Your best for each stage in this kind of round before this one, 0 where there was none. */
		private final transient int[] stageBests;

		Round(String kind, int ticks, int units, int idle, String idlePlace, int idlePlaceTicks,
			int extraTiles, String extraPlace, int extraPlaceTiles, int bestBefore, boolean hadBreak)
		{
			this(kind, ticks, units, idle, idlePlace, idlePlaceTicks, extraTiles, extraPlace, extraPlaceTiles, bestBefore, hadBreak,
				new int[STAGES], new int[STAGES]);
		}

		Round(String kind, int ticks, int units, int idle, String idlePlace, int idlePlaceTicks,
			int extraTiles, String extraPlace, int extraPlaceTiles, int bestBefore, boolean hadBreak, int[] stageTicks, int[] stageBests)
		{
			this.stageTicks = stageTicks.clone();
			this.stageBests = stageBests.clone();
			this.kind = kind;
			this.ticks = ticks;
			this.units = units;
			this.idle = idle;
			this.idlePlace = idlePlace;
			this.idlePlaceTicks = idlePlaceTicks;
			this.extraTiles = extraTiles;
			this.extraPlace = extraPlace;
			this.extraPlaceTiles = extraPlaceTiles;
			this.bestBefore = bestBefore;
			this.hadBreak = hadBreak;
		}

		/** Ticks spent in a stage of the loop this round. */
		public int stageTicks(int stage)
		{
			return stage >= 0 && stage < STAGES ? stageTicks[stage] : 0;
		}

		/** Your best for a stage in this kind of round before this one, or 0. */
		public int stageBest(int stage)
		{
			return stage >= 0 && stage < STAGES ? stageBests[stage] : 0;
		}

		/**
		 * The stage that lost the most time against your best for it, or -1 when every stage was
		 * within a tick or two of its best (or there were no bests to compare with).
		 */
		public int slowestStage()
		{
			if (hadBreak)
			{
				return -1;
			}
			int worst = -1;
			int by = TOLERANCE;
			for (int s = 0; s < STAGES; s++)
			{
				if (stageTicks[s] > 0 && stageBests[s] > 0 && stageTicks[s] - stageBests[s] > by)
				{
					by = stageTicks[s] - stageBests[s];
					worst = s;
				}
			}
			return worst;
		}

		public boolean isBest()
		{
			return !hadBreak && (bestBefore == 0 || ticks < bestBefore);
		}

		/** Whether the round lost time worth mentioning. */
		public boolean costly()
		{
			return !hadBreak && (idlePlaceTicks >= 3 && idlePlace != null || extraPlaceTiles > TOLERANCE && extraPlace != null);
		}

		/** The one thing that would have made this round quicker, in a sentence. */
		public String advice()
		{
			if (hadBreak)
			{
				return "Long round, so it is left out of your bests";
			}
			boolean idleMatters = idlePlaceTicks >= 3 && idlePlace != null;
			boolean walkMatters = extraPlaceTiles > TOLERANCE && extraPlace != null;
			// A tile walked costs about half a tick when running, so compare like with like.
			if (idleMatters && (!walkMatters || idlePlaceTicks * 2 >= extraPlaceTiles))
			{
				return "Stood still " + idlePlaceTicks + " ticks at " + idlePlace;
			}
			if (walkMatters)
			{
				return "Walked " + extraPlaceTiles + " tiles more than needed to " + extraPlace;
			}
			if (isBest() && bestBefore > 0)
			{
				return "Your best round of this kind";
			}
			return "A clean round: no standing still, no detours";
		}
	}

	private final Map<String, Integer> bests = new HashMap<>();
	private final Map<String, int[]> stageBests = new HashMap<>();
	private final int[] stageTicks = new int[STAGES];
	private final List<Round> rounds = new ArrayList<>();

	private boolean started;
	private boolean leftStart;
	private int ticks;
	private int mask;
	private int unitsAtStart = -1;
	private int units;
	private int idle;
	private final Map<String, Integer> idleAt = new HashMap<>();
	private final Map<String, Integer> extraAt = new HashMap<>();
	private int extraTotal;
	private int stillRun;
	private String leg;
	private String legPlace;
	private int legPlanned;
	private int legWalked;
	private int idleTotal;
	private String roundHint;

	/**
	 * One game tick.
	 *
	 * @param stage where in the loop the step sits, 0 being the start of a round
	 * @param leg a key for the current step and its target, so a new walk is told from an old one
	 * @param place where the step is, said as "the bank"
	 * @param still whether you stood still this tick (not moving, not animating, nothing open)
	 * @param waiting whether the step is to wait, so standing still is right
	 * @param moved tiles moved since the last tick
	 * @param routeLength the shortest walk to the target from here, or -1 when it is not known
	 * @param unitCount a running count of what a round produces, such as pay-dirt deposited or bars taken
	 * @param kindHint what makes rounds comparable beyond their shape, such as the contract, or null;
	 *                 the last one seen during a round is the one it is filed under
	 * @return the round that just finished, or null
	 */
	public Round tick(int stage, String leg, String place, boolean still, boolean waiting, int moved,
		int routeLength, int unitCount, String kindHint)
	{
		Round finished = null;
		if (!started)
		{
			if (stage != 0)
			{
				// Rounds are only timed from the start of the loop, so the first part-round is skipped.
				return null;
			}
			begin(unitCount);
		}
		else if (stage == 0 && leftStart)
		{
			endLeg();
			units = unitCount;
			finished = finish(roundHint);
			begin(unitCount);
		}
		if (kindHint != null)
		{
			roundHint = kindHint.replaceAll("[;=/#]", " ");
		}
		if (stage != 0)
		{
			leftStart = true;
		}
		if (stage >= 0 && stage < STAGES)
		{
			mask |= 1 << stage;
			stageTicks[stage]++;
		}
		units = unitCount;
		ticks++;

		if (leg == null || !leg.equals(this.leg))
		{
			endLeg();
			this.leg = leg;
			legPlace = place;
			legPlanned = routeLength;
			legWalked = 0;
			stillRun = 0;
		}
		legWalked += Math.max(0, moved);

		if (still && !waiting)
		{
			stillRun++;
			if (stillRun > GRACE)
			{
				idle++;
				idleTotal++;
				if (place != null)
				{
					idleAt.merge(place, 1, Integer::sum);
				}
			}
		}
		else
		{
			stillRun = 0;
		}
		return finished;
	}

	/** Leaving the minigame: the round in progress is dropped, as it was not finished. */
	public void reset()
	{
		started = false;
		leg = null;
	}

	public List<Round> rounds()
	{
		return Collections.unmodifiableList(rounds);
	}

	public Round last()
	{
		return rounds.isEmpty() ? null : rounds.get(rounds.size() - 1);
	}

	/** Your best for each stage of a kind of round, by stage; zeros where there is none. */
	public int[] stageBests(String kind)
	{
		int[] b = stageBests.get(kind);
		return b == null ? new int[STAGES] : b.clone();
	}

	public int best(String kind)
	{
		Integer b = bests.get(kind);
		return b == null ? 0 : b;
	}

	/** Ticks spent standing still with something to do, across every round so far. */
	public int idleTotal()
	{
		return idleTotal;
	}

	/** The usual round of this kind this session, the median, or 0 before there are any. */
	public int typical(String kind)
	{
		List<Integer> t = new ArrayList<>();
		for (Round r : rounds)
		{
			if (r.kind.equals(kind) && !r.hadBreak)
			{
				t.add(r.ticks);
			}
		}
		if (t.isEmpty())
		{
			return 0;
		}
		Collections.sort(t);
		return t.get(t.size() / 2);
	}

	/** Bests carried over from earlier sessions, as "kind=ticks;kind=ticks". */
	public void loadBests(String saved)
	{
		bests.clear();
		stageBests.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String part : saved.split(";"))
		{
			int eq = part.lastIndexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			try
			{
				int t = Integer.parseInt(part.substring(eq + 1));
				String key = part.substring(0, eq);
				int mark = key.lastIndexOf(STAGE_MARK);
				if (t <= 0)
				{
					continue;
				}
				if (mark > 0)
				{
					int stage = Integer.parseInt(key.substring(mark + 1));
					if (stage >= 0 && stage < STAGES)
					{
						stageBests.computeIfAbsent(key.substring(0, mark), k -> new int[STAGES])[stage] = t;
					}
				}
				else
				{
					bests.put(key, t);
				}
			}
			catch (NumberFormatException ignored)
			{
				// A damaged entry is dropped; the rest still count.
			}
		}
	}

	public String saveBests()
	{
		StringBuilder b = new StringBuilder();
		java.util.TreeMap<String, Integer> all = new java.util.TreeMap<>(bests);
		for (Map.Entry<String, int[]> e : stageBests.entrySet())
		{
			for (int s = 0; s < STAGES; s++)
			{
				if (e.getValue()[s] > 0)
				{
					all.put(e.getKey() + STAGE_MARK + s, e.getValue()[s]);
				}
			}
		}
		all.forEach((k, v) ->
		{
			if (b.length() > 0)
			{
				b.append(';');
			}
			b.append(k).append('=').append(v);
		});
		return b.toString();
	}

	private void begin(int unitCount)
	{
		started = true;
		leftStart = false;
		ticks = 0;
		mask = 0;
		unitsAtStart = unitCount;
		units = unitCount;
		idle = 0;
		idleAt.clear();
		extraAt.clear();
		extraTotal = 0;
		roundHint = null;
		java.util.Arrays.fill(stageTicks, 0);
	}

	private void endLeg()
	{
		if (leg != null && legPlanned > 0 && legPlace != null)
		{
			int extra = legWalked - legPlanned;
			if (extra > TOLERANCE)
			{
				extraTotal += extra;
				extraAt.merge(legPlace, extra, Integer::sum);
			}
		}
		leg = null;
	}

	private Round finish(String kindHint)
	{
		int made = Math.max(0, units - unitsAtStart);
		String kind = Integer.toString(mask) + "/" + made + (kindHint == null ? "" : "/" + kindHint);
		int typical = typical(kind);
		boolean hadBreak = typical > 0 && ticks > typical * BREAK_FACTOR;
		int bestBefore = best(kind);
		Map.Entry<String, Integer> worstIdle = worst(idleAt);
		Map.Entry<String, Integer> worstWalk = worst(extraAt);
		int[] stagesBefore = stageBests(kind);
		Round r = new Round(kind, ticks, made, idle,
			worstIdle == null ? null : worstIdle.getKey(), worstIdle == null ? 0 : worstIdle.getValue(),
			extraTotal, worstWalk == null ? null : worstWalk.getKey(), worstWalk == null ? 0 : worstWalk.getValue(),
			bestBefore, hadBreak, stageTicks, stagesBefore);
		if (r.isBest())
		{
			bests.put(kind, ticks);
		}
		if (!hadBreak)
		{
			// Each stage keeps its own best, so a round can be slow overall yet set a best bank trip.
			int[] sb = stageBests.computeIfAbsent(kind, k -> new int[STAGES]);
			for (int s = 0; s < STAGES; s++)
			{
				if (stageTicks[s] > 0 && (sb[s] == 0 || stageTicks[s] < sb[s]))
				{
					sb[s] = stageTicks[s];
				}
			}
		}
		rounds.add(r);
		if (rounds.size() > KEEP)
		{
			rounds.remove(0);
		}
		return r;
	}

	private static Map.Entry<String, Integer> worst(Map<String, Integer> m)
	{
		Map.Entry<String, Integer> w = null;
		for (Map.Entry<String, Integer> e : m.entrySet())
		{
			if (w == null || e.getValue() > w.getValue())
			{
				w = e;
			}
		}
		return w == null ? null : new java.util.AbstractMap.SimpleImmutableEntry<>(w);
	}

	/** Ticks as m:ss. */
	public static String clock(int ticks)
	{
		long ms = ticks * 600L;
		long s = Math.round(ms / 1000d);
		return (s / 60) + ":" + String.format("%02d", s % 60);
	}
}

package com.codex.minigamepilot.core;

/**
 * Your Mahogany Homes points, from the line after each contract: "You have completed 120
 * contracts with a total of 470 points." Nobody has yet confirmed whether that total is what you
 * can spend or everything you have ever earned, so the book works it out as you play instead of
 * guessing:
 *
 * <ul>
 * <li>A total that goes down can only be a balance.</li>
 * <li>A total smaller than what the rewards you own cost can only be a balance, since every
 * reward is bought with points.</li>
 * <li>Buy a reward between two contracts and the next total tells: a balance drops by its cost,
 * a lifetime total just carries on climbing by a contract's few points.</li>
 * </ul>
 *
 * Until one of those settles it, what you can spend is taken as the lower of the two readings,
 * so the goal card never lights a reward you cannot afford.
 */
public final class Points
{
	/** What the total in the message means. */
	public enum Meaning
	{
		UNKNOWN,
		BALANCE,
		LIFETIME
	}

	/** The fewest and most points one contract pays, across every tier. */
	static final int MIN_PER_CONTRACT = 1;
	static final int MAX_PER_CONTRACT = 10;

	private long total = -1;
	private long contracts = -1;
	private Meaning meaning = Meaning.UNKNOWN;
	/** Points spent on rewards bought since the last message. */
	private long spentSince;

	/** True once a message has been read. */
	public boolean known()
	{
		return total >= 0;
	}

	public Meaning getMeaning()
	{
		return meaning;
	}

	/** The total from the last message, or -1. */
	public long getTotal()
	{
		return total;
	}

	/**
	 * The line after a contract.
	 *
	 * @param count the contracts it says you have completed
	 * @param newTotal the points total it gives
	 * @param ownedCost what every points reward you own cost, all bought with points
	 * @return points earned since the last message, or 0 when that cannot be told
	 */
	public long message(long count, long newTotal, long ownedCost)
	{
		if (total >= 0 && contracts >= 0 && count <= contracts)
		{
			// The same line again, or an older one: nothing new to learn from it.
			return 0;
		}
		long earned = 0;
		if (total >= 0 && contracts >= 0)
		{
			long k = count - contracts;
			long delta = newTotal - total;
			boolean lifetimeFits = fits(delta, k);
			boolean balanceFits = fits(delta + spentSince, k);
			if (delta < 0)
			{
				meaning = Meaning.BALANCE;
			}
			else if (spentSince > 0 && lifetimeFits != balanceFits)
			{
				meaning = lifetimeFits ? Meaning.LIFETIME : Meaning.BALANCE;
			}
			// Either way the contracts in between paid what the totals climbed, plus anything spent
			// from a balance; take the reading that fits a contract's pay.
			if (meaning == Meaning.BALANCE)
			{
				earned = delta + spentSince;
			}
			else if (meaning == Meaning.LIFETIME || lifetimeFits)
			{
				earned = Math.max(0, delta);
			}
			else
			{
				earned = balanceFits ? delta + spentSince : Math.max(0, delta);
			}
		}
		if (newTotal < ownedCost)
		{
			meaning = Meaning.BALANCE;
		}
		total = newTotal;
		contracts = count;
		spentSince = 0;
		// A drop with no purchase seen (one bought out of sight) leaves this contract's pay unknown.
		return Math.max(0, earned);
	}

	private static boolean fits(long delta, long contracts)
	{
		return delta >= MIN_PER_CONTRACT * contracts && delta <= MAX_PER_CONTRACT * contracts;
	}

	/** A points reward just bought (it turned up in your pack from nowhere you had it). */
	public void bought(long cost)
	{
		if (cost > 0)
		{
			spentSince += cost;
		}
	}

	/**
	 * What you can spend now, or -1 before the first message.
	 *
	 * @param ownedCost what every points reward you own cost
	 */
	public long balance(long ownedCost)
	{
		if (total < 0)
		{
			return -1;
		}
		long asBalance = total - spentSince;
		long asLifetime = total - ownedCost;
		switch (meaning)
		{
			case BALANCE:
				return Math.max(0, asBalance);
			case LIFETIME:
				return Math.max(0, asLifetime);
			default:
				return Math.max(0, Math.min(asBalance, asLifetime));
		}
	}

	/** "470:120:UNKNOWN:350", to save. */
	public String encode()
	{
		return total + ":" + contracts + ":" + meaning.name() + ":" + spentSince;
	}

	/**
	 * Reads a saved book. A bare number, as older versions saved, is taken as a total with
	 * nothing known about what it means.
	 */
	public static Points decode(String saved)
	{
		Points p = new Points();
		if (saved == null || saved.trim().isEmpty())
		{
			return p;
		}
		String[] parts = saved.trim().split(":");
		try
		{
			p.total = Long.parseLong(parts[0]);
			if (parts.length >= 4)
			{
				p.contracts = Long.parseLong(parts[1]);
				p.meaning = Meaning.valueOf(parts[2]);
				p.spentSince = Math.max(0, Long.parseLong(parts[3]));
			}
		}
		catch (IllegalArgumentException e)
		{
			return new Points();
		}
		return p;
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A minigame's whole shop as one road, in the order players usually buy: each reward set a stop,
 * ticked when you own it, lit when what you hold already pays for it and every unowned stop
 * before it, and otherwise how far off it is in time or rounds at your own pace, counting the
 * stops before it first. A level a Codex Navigator goal needs can close the road as its last
 * stop. The goal card says how far off the next thing is; the road says how far off everything is.
 */
public final class RewardRoad
{
	/** One stop on the road. */
	public static final class Stop
	{
		private final String name;
		private final int icon;
		private final int level;
		private final long cost;
		private final long left;
		private final boolean owned;
		private final boolean affordable;
		private final long minutesAway;
		private final long roundsAway;
		private final String reason;
		private final Goal.Currency currency;
		private final String roundName;
		private final boolean known;
		private final String skill;

		Stop(String name, int icon, int level, long cost, long left, boolean owned, boolean affordable, long minutesAway, long roundsAway, String reason,
			Goal.Currency currency, String roundName, boolean known)
		{
			this(name, icon, level, cost, left, owned, affordable, minutesAway, roundsAway, reason, currency, roundName, known, null);
		}

		Stop(String name, int icon, int level, long cost, long left, boolean owned, boolean affordable, long minutesAway, long roundsAway, String reason,
			Goal.Currency currency, String roundName, boolean known, String skill)
		{
			this.skill = skill;
			this.known = known;
			this.currency = currency;
			this.roundName = roundName;
			this.name = name;
			this.icon = icon;
			this.level = level;
			this.cost = cost;
			this.left = left;
			this.owned = owned;
			this.affordable = affordable;
			this.minutesAway = minutesAway;
			this.roundsAway = roundsAway;
			this.reason = reason;
		}

		public String getName()
		{
			return name;
		}

		/** An item that shows the reward, or 0 when it has none (the bigger sack, a level). */
		public int getIcon()
		{
			return icon;
		}

		/** The level, for a level stop; 0 for a reward. */
		public int getLevel()
		{
			return level;
		}

		/** What the stop's unowned pieces cost, in the shop's currency (or experience for a level). */
		public long getCost()
		{
			return cost;
		}

		/** What is still to earn before this stop is yours, the stops before it first; 0 when it is. */
		public long getLeft()
		{
			return left;
		}

		public boolean isOwned()
		{
			return owned;
		}

		/** True when what you hold already pays for it and every unowned stop before it. */
		public boolean isAffordable()
		{
			return affordable;
		}

		/** Minutes at your pace until it is yours, or -1 with no pace yet. */
		public long getMinutesAway()
		{
			return minutesAway;
		}

		/** Rounds (contracts) until it is yours, or -1 when rounds do not apply. */
		public long getRoundsAway()
		{
			return roundsAway;
		}

		/** False when what you hold is not known yet, so only what the stop costs can be said. */
		public boolean isKnown()
		{
			return known;
		}

		/** The shop's currency, or null for a level, which is counted in experience. */
		public Goal.Currency getCurrency()
		{
			return currency;
		}

		/** What a round is called, such as "adept contract", or null. */
		public String getRoundName()
		{
			return roundName;
		}

		/** For a level stop, the skill and level, such as "Smithing 70", whatever the stop is called; otherwise its name. */
		public String getLevelName()
		{
			return level > 0 && skill != null ? skill + " " + level : name;
		}

		/** For a level stop, whose goal needs it, such as "Dragon Slayer II"; otherwise null. */
		public String getReason()
		{
			return reason;
		}
	}

	private RewardRoad()
	{
	}

	public static List<Stop> motherlode(Goals.Input in)
	{
		return of(Goals.MOTHERLODE_ORDER, in);
	}

	public static List<Stop> homes(Goals.Input in)
	{
		return of(Goals.HOMES_ORDER, in);
	}

	/**
	 * The Blast Furnace has no shop, so its road is the Smithing levels that open its bars (and
	 * the level that ends the foreman's fee), from the last one you have reached onward, timed
	 * at your experience an hour.
	 */
	public static List<Stop> furnace(Goals.Input in)
	{
		if (in == null)
		{
			return Collections.emptyList();
		}
		int now = Goals.levelFor(in.xp);
		List<Stop> all = new ArrayList<>();
		boolean foreman = false;
		for (BarPick.Facts f : BarPick.Facts.values())
		{
			if (!foreman && f.level > BarPick.FOREMAN_FREE_LEVEL)
			{
				all.add(level("No foreman fee", 0, "Smithing", BarPick.FOREMAN_FREE_LEVEL, null, in));
				foreman = true;
			}
			all.add(level(f.bar.getName() + " bars", f.bar.getBar(), "Smithing", f.level, null, in));
		}
		// Only the last level reached, then everything ahead of it.
		int from = 0;
		for (int i = 0; i < all.size(); i++)
		{
			if (all.get(i).getLevel() <= now)
			{
				from = i;
			}
		}
		return new ArrayList<>(all.subList(from, all.size()));
	}

	private static Stop level(String name, int icon, String skill, int level, String reason, Goals.Input in)
	{
		boolean reached = Goals.levelFor(in.xp) >= level;
		long left = reached ? 0 : Math.max(0, Goals.xpFor(level) - in.xp);
		return new Stop(name, icon, level, left, left, reached, false, reached ? 0 : minutes(left, in.xpPerHour),
			reached ? 0 : rounds(left, in.xpPerRound), reason, null, in.roundName, true, skill);
	}

	/**
	 * @param in what you own and hold, and your pace; a balance below 0 means it is not known,
	 *     and then nothing is lit or timed, only what each stop costs
	 */
	static List<Stop> of(List<List<Goal.Reward>> order, Goals.Input in)
	{
		if (in == null)
		{
			return Collections.emptyList();
		}
		List<Stop> road = new ArrayList<>();
		boolean known = in.balance >= 0;
		long spent = 0;
		for (List<Goal.Reward> set : order)
		{
			long cost = 0;
			boolean owned = true;
			int icon = 0;
			for (Goal.Reward r : set)
			{
				int[] items = r.getItems();
				if (icon == 0 && items.length > 0)
				{
					icon = items[0];
				}
				if (!Goals.owned(r, in))
				{
					owned = false;
					cost += r.getCost();
				}
			}
			String name = set.size() > 1 ? Goals.titleOf(set) : set.get(0).getName();
			if (owned)
			{
				road.add(new Stop(name, icon, 0, 0, 0, true, false, 0, -1, null, set.get(0).getCurrency(), in.roundName, known));
				continue;
			}
			spent += cost;
			long left = known ? Math.max(0, spent - in.balance) : spent;
			road.add(new Stop(name, icon, 0, cost, left, false, known && left == 0,
				known ? minutes(left, in.currencyPerHour) : -1, known ? rounds(left, in.currencyPerRound) : -1, null, set.get(0).getCurrency(), in.roundName, known));
		}
		return road;
	}

	/**
	 * Adds a level a Navigator goal needs as the road's last stop, timed at your experience an
	 * hour; nothing when that level is already reached.
	 *
	 * @param goal the goal that needs it, such as "Dragon Slayer II"
	 */
	public static List<Stop> withLevel(List<Stop> road, String skill, int level, String goal, Goals.Input in)
	{
		if (skill == null || level <= 1 || level > 99 || in == null || Goals.levelFor(in.xp) >= level)
		{
			return road;
		}
		List<Stop> out = new ArrayList<>(road);
		// A road of levels keeps its order, and a level already on it just gains the goal's name;
		// reward stops have no level, so on a shop's road the level comes last.
		for (int i = 0; i < out.size(); i++)
		{
			Stop s = out.get(i);
			if (s.getLevel() == level)
			{
				out.set(i, new Stop(s.name, s.icon, s.level, s.cost, s.left, s.owned, s.affordable, s.minutesAway, s.roundsAway, goal,
					s.currency, s.roundName, s.known, s.skill));
				return out;
			}
			if (s.getLevel() > level)
			{
				out.add(i, level(skill + " " + level, 0, skill, level, goal, in));
				return out;
			}
		}
		out.add(level(skill + " " + level, 0, skill, level, goal, in));
		return out;
	}

	/** Whether anything on the road is still to come. */
	public static boolean open(List<Stop> road)
	{
		for (Stop s : road)
		{
			if (!s.isOwned())
			{
				return true;
			}
		}
		return false;
	}

	private static long minutes(long left, double perHour)
	{
		if (left <= 0)
		{
			return 0;
		}
		return perHour > 0 ? (long) Math.ceil(left * 60.0 / perHour) : -1;
	}

	private static long rounds(long left, double perRound)
	{
		if (left <= 0)
		{
			return 0;
		}
		return perRound > 0 ? (long) Math.ceil(left / perRound) : -1;
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

/**
 * Walking distances across the loaded scene, worked out from the game's own collision flags.
 * One flood from where the player stands gives the distance to every tile, so the nearest of
 * many targets (veins, hotspots) is the nearest on foot rather than as the crow flies, and a
 * target behind a wall loses to one around the corner.
 *
 * <p>Some tiles can be marked soft: blocked in the game, but passable here at a price. A rockfall
 * in the Motherlode Mine is one; a route through it means mining it first is the quicker way.
 */
public final class Route
{
	// The game's collision bits, as RuneLite's CollisionDataFlag names them.
	static final int NORTH_WEST = 0x1;
	static final int NORTH = 0x2;
	static final int NORTH_EAST = 0x4;
	static final int EAST = 0x8;
	static final int SOUTH_EAST = 0x10;
	static final int SOUTH = 0x20;
	static final int SOUTH_WEST = 0x40;
	static final int WEST = 0x80;
	static final int FULL = 0x100 | 0x40000 | 0x200000;

	private static final int[] DX = {0, 1, 0, -1, 1, 1, -1, -1};
	private static final int[] DY = {1, 0, -1, 0, 1, -1, -1, 1};
	private static final int UNREACHED = Integer.MAX_VALUE;

	private final int width;
	private final int height;
	private final int[] dist;
	private final int[] from;

	private Route(int width, int height)
	{
		this.width = width;
		this.height = height;
		this.dist = new int[width * height];
		this.from = new int[width * height];
		Arrays.fill(dist, UNREACHED);
		Arrays.fill(from, -1);
	}

	/**
	 * Floods out from a tile.
	 *
	 * @param flags the collision flags, indexed [x][y]
	 * @param soft extra cost of stepping onto each tile that is otherwise blocked, or null; zero means blocked
	 */
	public static Route flood(int[][] flags, int startX, int startY, int[][] soft)
	{
		int w = flags.length;
		int h = w == 0 ? 0 : flags[0].length;
		Route r = new Route(w, h);
		if (!r.inside(startX, startY))
		{
			return r;
		}
		PriorityQueue<long[]> open = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
		int start = startX * h + startY;
		r.dist[start] = 0;
		open.add(new long[]{0, start});
		while (!open.isEmpty())
		{
			long[] head = open.poll();
			int at = (int) head[1];
			if (head[0] > r.dist[at])
			{
				continue;
			}
			int x = at / h;
			int y = at % h;
			for (int d = 0; d < 8; d++)
			{
				int nx = x + DX[d];
				int ny = y + DY[d];
				if (!r.inside(nx, ny))
				{
					continue;
				}
				int cost = stepCost(flags, soft, x, y, DX[d], DY[d]);
				if (cost <= 0)
				{
					continue;
				}
				int next = nx * h + ny;
				int nd = r.dist[at] + cost;
				if (nd < r.dist[next])
				{
					r.dist[next] = nd;
					r.from[next] = at;
					open.add(new long[]{nd, next});
				}
			}
		}
		return r;
	}

	/** The cost of one step, or zero when it cannot be taken. Diagonal steps cost the same tick as straight ones. */
	static int stepCost(int[][] flags, int[][] soft, int x, int y, int dx, int dy)
	{
		int nx = x + dx;
		int ny = y + dy;
		if (dx != 0 && dy != 0)
		{
			// A diagonal needs both straight steps open and the corner free.
			if (stepCost(flags, null, x, y, dx, 0) <= 0 || stepCost(flags, null, x, y, 0, dy) <= 0)
			{
				return 0;
			}
			int corner = dx > 0 ? (dy > 0 ? SOUTH_WEST : NORTH_WEST) : (dy > 0 ? SOUTH_EAST : NORTH_EAST);
			int side = (dx > 0 ? WEST : EAST) | (dy > 0 ? SOUTH : NORTH);
			if ((flags[nx][ny] & (FULL | corner | side)) != 0)
			{
				return softCost(flags, soft, nx, ny, corner | side);
			}
			return 1;
		}
		int wall = dx > 0 ? WEST : dx < 0 ? EAST : dy > 0 ? SOUTH : NORTH;
		if ((flags[nx][ny] & (FULL | wall)) != 0)
		{
			return softCost(flags, soft, nx, ny, wall);
		}
		return 1;
	}

	/** A blocked tile that is marked soft can still be crossed, unless a wall is in the way too. */
	private static int softCost(int[][] flags, int[][] soft, int x, int y, int walls)
	{
		if (soft == null || soft[x][y] <= 0 || (flags[x][y] & walls) != 0)
		{
			return 0;
		}
		return 1 + soft[x][y];
	}

	private boolean inside(int x, int y)
	{
		return x >= 0 && y >= 0 && x < width && y < height;
	}

	/** Steps to reach a tile, or -1 when it cannot be reached. */
	public int distance(int x, int y)
	{
		if (!inside(x, y))
		{
			return -1;
		}
		int d = dist[x * height + y];
		return d == UNREACHED ? -1 : d;
	}

	public boolean reaches(int x, int y)
	{
		return distance(x, y) >= 0;
	}

	/** The tiles walked from the start (not included) to a tile, or an empty list when unreachable. */
	public List<int[]> pathTo(int x, int y)
	{
		if (!reaches(x, y))
		{
			return Collections.emptyList();
		}
		List<int[]> path = new ArrayList<>();
		int at = x * height + y;
		while (from[at] >= 0)
		{
			path.add(new int[]{at / height, at % height});
			at = from[at];
		}
		Collections.reverse(path);
		return path;
	}

	/**
	 * Where to stand to use an object: the reachable tile beside its footprint that is fewest
	 * steps away, never a corner and never across a wall from it.
	 *
	 * @param flags the same flags the route was flooded over
	 * @return {x, y, steps}, or null when nothing beside it can be reached
	 */
	public int[] approach(int[][] flags, int ox, int oy, int sizeX, int sizeY)
	{
		int[] best = null;
		for (int x = ox - 1; x <= ox + sizeX; x++)
		{
			for (int y = oy - 1; y <= oy + sizeY; y++)
			{
				boolean insideX = x >= ox && x < ox + sizeX;
				boolean insideY = y >= oy && y < oy + sizeY;
				if (insideX == insideY)
				{
					// Either on the footprint itself or on one of its corners.
					continue;
				}
				int d = distance(x, y);
				if (d < 0 || (best != null && d >= best[2]))
				{
					continue;
				}
				int toward = x < ox ? EAST : x >= ox + sizeX ? WEST : y < oy ? NORTH : SOUTH;
				if ((flags[x][y] & toward) != 0)
				{
					continue;
				}
				best = new int[]{x, y, d};
			}
		}
		return best;
	}

	/** Whether standing on a tile already counts as being beside an object. */
	public static boolean beside(int px, int py, int ox, int oy, int sizeX, int sizeY)
	{
		boolean insideX = px >= ox && px < ox + sizeX;
		boolean insideY = py >= oy && py < oy + sizeY;
		if (insideX && insideY)
		{
			return false;
		}
		return (insideX && (py == oy - 1 || py == oy + sizeY)) || (insideY && (px == ox - 1 || px == ox + sizeX));
	}
}

package com.codex.minigamepilot.core;

import java.util.Objects;

/**
 * The one thing to do next: a short verb for the game view, a sentence for the panel, a line of
 * why, and what in the world to light up. Planners hand these out; the plugin finds the target.
 */
public final class Step
{
	/** What in the world the step is about. The plugin turns this into an object, a character or an item. */
	public enum Target
	{
		NONE,
		// Motherlode Mine
		VEIN,
		HOPPER,
		SACK,
		BANK,
		STRUT,
		ROCKFALL,
		LADDER,
		// Blast Furnace
		BELT,
		DISPENSER,
		COFFER,
		/** An item in the inventory, worn, or in the open bank. */
		ITEM,
		// Mahogany Homes
		CONTRACTOR,
		CLIENT,
		HOTSPOT,
		HOME
	}

	private final String verb;
	private final String title;
	private final String detail;
	private final Target target;
	private final int[] items;
	private final boolean waiting;

	private Step(String verb, String title, String detail, Target target, int[] items, boolean waiting)
	{
		this.verb = verb;
		this.title = title;
		this.detail = detail;
		this.target = target;
		this.items = items == null ? new int[0] : items;
		this.waiting = waiting;
	}

	public static Step of(String verb, String title, String detail, Target target)
	{
		return new Step(verb, title, detail, target, null, false);
	}

	/** A step about items: withdraw them, equip them, use them. */
	public static Step items(String verb, String title, String detail, int... items)
	{
		return new Step(verb, title, detail, Target.ITEM, items, false);
	}

	/** Nothing to click: the game is doing the work. The target is where to wait. */
	public static Step waiting(String title, String detail, Target target)
	{
		return new Step("Wait", title, detail, target, null, true);
	}

	/** The same step with a different line of why. */
	public Step withDetail(String newDetail)
	{
		return new Step(verb, title, newDetail, target, items, waiting);
	}

	/** The same step with items to light up too, such as the teleport to use on the way. */
	public Step withItems(int... newItems)
	{
		return new Step(verb, title, detail, target, newItems, waiting);
	}

	/** A short word for the label over the target, such as "Deposit". */
	public String getVerb()
	{
		return verb;
	}

	/** The sentence the panel and plaque lead with. */
	public String getTitle()
	{
		return title;
	}

	/** Why, or how much: a quieter line under the title. May be empty. */
	public String getDetail()
	{
		return detail == null ? "" : detail;
	}

	public Target getTarget()
	{
		return target;
	}

	public int[] getItems()
	{
		return items.clone();
	}

	public boolean hasItem(int id)
	{
		for (int i : items)
		{
			if (i == id)
			{
				return true;
			}
		}
		return false;
	}

	public boolean isWaiting()
	{
		return waiting;
	}

	/** Two steps are the same instruction when they ask for the same action on the same thing. */
	public boolean sameAs(Step other)
	{
		return other != null && target == other.target && Objects.equals(title, other.title);
	}

	@Override
	public String toString()
	{
		return verb + ": " + title + (detail == null || detail.isEmpty() ? "" : " (" + detail + ")");
	}
}

package com.codex.minigamepilot.core;

/**
 * How far the supplies in your bank go: at the Blast Furnace, how many bars your ore and coal make
 * together and which runs out first; at Mahogany Homes, how many contracts your planks and steel
 * bars cover at what your own contracts have taken. Both turn into time at your own pace once it
 * is known.
 */
public final class Supplies
{
	private Supplies()
	{
	}

	/** What a stock of ore and coal makes at the furnace. */
	public static final class Furnace
	{
		private final Bar bar;
		private final long bars;
		private final boolean coalShort;
		private final long coalToUseAllOre;
		private final double trips;
		private final double seconds;

		Furnace(Bar bar, long bars, boolean coalShort, long coalToUseAllOre, double trips, double seconds)
		{
			this.bar = bar;
			this.bars = bars;
			this.coalShort = coalShort;
			this.coalToUseAllOre = coalToUseAllOre;
			this.trips = trips;
			this.seconds = seconds;
		}

		public long getBars()
		{
			return bars;
		}

		/** True when coal runs out before the ore does. */
		public boolean isCoalShort()
		{
			return coalShort;
		}

		/** More coal it would take to smelt every ore, 0 when the coal is enough. */
		public long getCoalToUseAllOre()
		{
			return coalToUseAllOre;
		}

		/** Trips to the furnace, coal trips included. */
		public double getTrips()
		{
			return trips;
		}

		/** Seconds all of it takes at your trip time, 0 when that is not known. */
		public double getSeconds()
		{
			return seconds;
		}

		/** "378 runite bars, about 1h 50m" or "No runite ore in the bank". */
		public String headline()
		{
			if (bars <= 0)
			{
				return "Not enough " + bar.oreName() + (bar.getCoal() > 0 ? " and coal" : "") + " for a bar";
			}
			String s = Goal.group(bars) + " " + bar.barName(bars == 1 ? 1 : 2) + ", " + Math.max(1, Math.round(trips)) + (Math.round(trips) == 1 ? " trip" : " trips");
			return seconds > 0 ? s + ", about " + Goal.duration(Math.round(seconds / 60)) : s;
		}

		/** What runs out first, or null when the ore and coal come out even. */
		public String limit()
		{
			if (bars <= 0)
			{
				return null;
			}
			if (coalShort)
			{
				return "Coal runs out first: " + Goal.group(coalToUseAllOre) + " more would smelt all the ore";
			}
			return bar.getCoal() > 0 ? "The ore runs out first" : null;
		}
	}

	/**
	 * @param ore the bar's ore in the bank and carried
	 * @param coal coal in the bank and carried
	 * @param slots ore one trip carries
	 * @param bag coal the coal bag brings along, 0 without one
	 * @param tripSeconds your usual trip, bank to bank, or 0 when not known
	 */
	public static Furnace furnace(Bar bar, long ore, long coal, int slots, int bag, double tripSeconds)
	{
		int perBar = bar.getCoal();
		long bars = perBar == 0 ? Math.max(0, ore) : Math.max(0, Math.min(ore, coal / perBar));
		boolean coalShort = perBar > 0 && bars < ore;
		long needed = coalShort ? ore * perBar - coal : 0;
		int load = Math.max(1, slots);
		double trips = bars / (double) load * (1 + BarPick.coalTrips(perBar, load, Math.max(0, bag)));
		return new Furnace(bar, bars, coalShort, Math.max(0, needed), trips, tripSeconds > 0 ? trips * tripSeconds : 0);
	}

	/** What a stock of planks and steel covers at Mahogany Homes. */
	public static final class Homes
	{
		private final Contract.Tier tier;
		private final long planks;
		private final long contracts;
		private final boolean steelShort;
		private final double seconds;

		Homes(Contract.Tier tier, long planks, long contracts, boolean steelShort, double seconds)
		{
			this.tier = tier;
			this.planks = planks;
			this.contracts = contracts;
			this.steelShort = steelShort;
			this.seconds = seconds;
		}

		/** Contracts the planks cover, or -1 when a contract's needs are not learned yet. */
		public long getContracts()
		{
			return contracts;
		}

		public boolean isSteelShort()
		{
			return steelShort;
		}

		/** "Teak planks for about 11 contracts, 1h 10m" or "212 teak planks". */
		public String headline()
		{
			String name = tier.planks(2).substring(2);
			if (contracts < 0)
			{
				return planks <= 0 ? "No " + name + " in the bank" : capital(tier.planks((int) Math.min(Integer.MAX_VALUE, planks)));
			}
			if (contracts == 0)
			{
				return "Not enough " + name + " for a contract";
			}
			String s = capital(name) + " for about " + contracts + (contracts == 1 ? " contract" : " contracts");
			return seconds > 0 ? s + ", " + Goal.duration(Math.round(seconds / 60)) : s;
		}
	}

	/**
	 * @param planks the tier's planks in the bank, carried and in the plank sack
	 * @param steel steel bars in the bank and carried
	 * @param tally what your contracts of this tier have taken, or null when none is recorded
	 */
	public static Homes homes(Contract.Tier tier, long planks, long steel, ContractBook.Tally tally)
	{
		if (tally == null || tally.getContracts() == 0 || tally.planksEach() <= 0)
		{
			return new Homes(tier, planks, -1, false, 0);
		}
		long byPlanks = (long) Math.floor(planks / tally.planksEach());
		long bySteel = tally.steelEach() > 0 ? (long) Math.floor(steel / tally.steelEach()) : Long.MAX_VALUE;
		long contracts = Math.max(0, Math.min(byPlanks, bySteel));
		return new Homes(tier, planks, contracts, bySteel < byPlanks, contracts * tally.secondsEach());
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.codex.minigamepilot.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What a session at a minigame came to, kept when you leave it: how long it ran and its counts
 * ("318 pay-dirt", "21,400 Mining xp"), said in the chat as you go and shown on the panel's card
 * for that minigame until the next visit. Saved per account as {@code endedAt|minutes|part;part}.
 */
public final class Visit
{
	/** A session shorter than this, or with nothing done, is not worth a summary. */
	public static final long MIN_MS = 5 * 60_000L;

	private final long endedAt;
	private final long minutes;
	private final List<String> parts;

	public Visit(long endedAt, long minutes, List<String> parts)
	{
		this.endedAt = endedAt;
		this.minutes = Math.max(0, minutes);
		List<String> clean = new ArrayList<>();
		for (String p : parts == null ? Collections.<String>emptyList() : parts)
		{
			if (p != null && !p.trim().isEmpty())
			{
				// The saved form splits on these.
				clean.add(p.replace('|', ' ').replace(';', ',').trim());
			}
		}
		this.parts = Collections.unmodifiableList(clean);
	}

	/**
	 * A summary of a session, or null when it was too short or did nothing worth saying.
	 *
	 * @param elapsedMs how long the session ran
	 * @param parts its counts, those with nothing to show already left out
	 */
	public static Visit of(long endedAt, long elapsedMs, List<String> parts)
	{
		Visit v = new Visit(endedAt, elapsedMs / 60_000L, parts);
		return elapsedMs < MIN_MS || v.parts.isEmpty() ? null : v;
	}

	public long getEndedAt()
	{
		return endedAt;
	}

	public List<String> getParts()
	{
		return parts;
	}

	/** "52m" or "1h 12m". */
	public String duration()
	{
		return minutes < 60 ? minutes + "m" : (minutes / 60) + "h " + (minutes % 60) + "m";
	}

	/** "1h 12m: 318 pay-dirt, 21,400 Mining xp and ore worth 48k." */
	public String line()
	{
		return duration() + ": " + counts() + ".";
	}

	/** "Last visit 3 hours ago: 1h 12m for 318 pay-dirt, ..." for the card, against the time now. */
	public String status(long now)
	{
		return "Last visit " + ago(endedAt, now) + ": " + duration() + " for " + counts() + ".";
	}

	/** "318 pay-dirt, 21,400 Mining xp and ore worth 48k" */
	private String counts()
	{
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < parts.size(); i++)
		{
			if (i > 0)
			{
				b.append(i == parts.size() - 1 ? " and " : ", ");
			}
			b.append(parts.get(i));
		}
		return b.toString();
	}

	/** "just now", "12 minutes ago", "3 hours ago", "2 days ago". */
	static String ago(long then, long now)
	{
		long m = Math.max(0, now - then) / 60_000L;
		if (m < 1)
		{
			return "just now";
		}
		if (m < 60)
		{
			return m + (m == 1 ? " minute ago" : " minutes ago");
		}
		long h = m / 60;
		if (h < 48)
		{
			return h + (h == 1 ? " hour ago" : " hours ago");
		}
		return (h / 24) + " days ago";
	}

	/** Whether this came to the same counts as another, however long each ran. */
	public boolean sameCounts(Visit other)
	{
		return other != null && parts.equals(other.parts);
	}

	public String encode()
	{
		return endedAt + "|" + minutes + "|" + String.join(";", parts);
	}

	private static final java.util.regex.Pattern DAMAGED = java.util.regex.Pattern.compile("NaN|Infinity|(^|\\s)-\\d");

	/** True when no count in a summary is below zero or not a number, as no visit writes one. */
	private static boolean plain(List<String> parts)
	{
		for (String p : parts)
		{
			if (DAMAGED.matcher(p).find())
			{
				return false;
			}
		}
		return true;
	}

	/** A saved summary, or null when there is none, it cannot be read or it is damaged. */
	public static Visit decode(String saved)
	{
		if (saved == null || saved.isEmpty())
		{
			return null;
		}
		String[] f = saved.split("\\|", 3);
		if (f.length < 3)
		{
			return null;
		}
		try
		{
			long ended = Long.parseLong(f[0].trim());
			long minutes = Long.parseLong(f[1].trim());
			List<String> parts = new ArrayList<>();
			Collections.addAll(parts, f[2].split(";"));
			Visit v = new Visit(ended, minutes, parts);
			return ended <= 0 || v.parts.isEmpty() || !plain(v.parts) ? null : v;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

