/**
 * Keeps the goals planner's books: the nuggets and reward pieces in your bank (seen whenever it
 * is open, remembered per account), your Mahogany Homes points (read from the message after each
 * contract), and how fast you earn nuggets, points and experience in each minigame. From those
 * it adds a goal card to the panel. When Codex Navigator is installed, a level goal follows the
 * level your pinned goals need. It only reads the game, and stays out of the guidance and the
 * field notes.
 */
public final class GoalWatch
{
	static final String BANK_KEY = "goal.bank";
	/** The last points total read, as a plain number, as older versions saved it. */
	static final String POINTS_KEY = "goal.points";
	/** The points book: total, contracts, what the total means and points spent since. */
	static final String POINTS_BOOK_KEY = "goal.pointsBook";
	/** The rewards you have been seen to own, so one put away in the costume room still counts. */
	static final String OWNED_KEY = "goal.owned";
	private static final Pattern POINTS = Pattern.compile("You have completed ([\\d,]+) contracts? with a total of ([\\d,]+) points?");
	/** Time in a minigame before an hourly rate is trusted. */
	private static final int RATE_TICKS = 300;
	private static final double TICK_HOURS = 0.6 / 3600;
	/** Ticks after the reward shop closes in which a reward turning up still counts as bought. */
	static final int SHOP_GRACE = 3;

	/** The settings that decide what each minigame works toward. */
	public static final class Choices
	{
		final Goals.Choice motherlode;
		final Goals.Choice homes;
		/** The Smithing level to reach, 0 for the next one, or -1 for no goal. */
		final int furnaceLevel;
		/** Whether the minigame you are in shows its whole shop as a road. */
		final boolean road;

		/** @param furnaceLevel the Smithing level to reach, 0 for the next one, -1 for none */
		public Choices(Goals.Choice motherlode, Goals.Choice homes, int furnaceLevel)
		{
			this(motherlode, homes, furnaceLevel, true);
		}

		public Choices(Goals.Choice motherlode, Goals.Choice homes, int furnaceLevel, boolean road)
		{
			this.motherlode = motherlode;
			this.homes = homes;
			this.furnaceLevel = furnaceLevel;
			this.road = road;
		}
	}

	/** Earnings in one minigame this session. */
	static final class Rate
	{
		int ticks;
		long xp;
		long currency;

		double perHour(long gained, int minimum)
		{
			return ticks >= RATE_TICKS && gained >= minimum ? gained / (ticks * TICK_HOURS) : 0;
		}
	}

	private static final int[] TRACKED = tracked();

	private final Function<String, String> load;
	private final BiConsumer<String, String> save;
	private final Map<Integer, Integer> bank = new HashMap<>();
	private final Map<View.Activity, Rate> rates = new EnumMap<>(View.Activity.class);
	private final Supplier<NavigatorGoals.Board> navigator;
	private Points points = new Points();
	/** Points rewards carried or worn on the last tick, or null when not seen yet. */
	private EnumSet<Goal.Reward> carried;
	/** What the points rewards you own cost, as of the last tick. */
	private long ownedCost;
	private boolean storageWasOpen;
	private Owned owned = new Owned();
	/** Every reward carried or worn on the last tick, or null when not seen yet. */
	private EnumSet<Goal.Reward> heldBefore;
	private boolean groupWasOpen;
	/** The game tick the contract reward shop was last seen open, or -1. */
	private int shopTick = -1;
	/** The game tick the books were last kept on, or -1. */
	private int lastTick = -1;
	private View.Activity last = View.Activity.NONE;
	private long lastXp = -1;
	private int lastNuggets = -1;

	/**
	 * @param load reads a key of this account's saved settings
	 * @param save writes one
	 * @param navigator Codex Navigator's goal board, or null when it is not installed
	 */
	public GoalWatch(Function<String, String> load, BiConsumer<String, String> save, Supplier<NavigatorGoals.Board> navigator)
	{
		this.load = load;
		this.save = save;
		this.navigator = navigator;
	}

	private static int[] tracked()
	{
		List<Integer> ids = new ArrayList<>();
		ids.add(ItemIds.GOLDEN_NUGGET);
		for (Goal.Reward r : Goal.Reward.values())
		{
			for (int id : r.getItems())
			{
				ids.add(id);
			}
		}
		int[] out = new int[ids.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = ids.get(i);
		}
		return out;
	}

	/** After logging in or switching account: that account's bank and points, and a fresh session. */
	public void reload()
	{
		bank.clear();
		bank.putAll(decode(load.apply(BANK_KEY)));
		points = Points.decode(load.apply(POINTS_BOOK_KEY));
		if (!points.known())
		{
			// Saved by an older version: just the total, nothing known about what it means.
			points = Points.decode(load.apply(POINTS_KEY));
		}
		carried = null;
		ownedCost = 0;
		storageWasOpen = false;
		shopTick = -1;
		owned = Owned.decode(load.apply(OWNED_KEY));
		heldBefore = null;
		groupWasOpen = false;
		lastTick = -1;
		rates.clear();
		last = View.Activity.NONE;
		lastXp = -1;
		lastNuggets = -1;
	}

	/**
	 * Logging in or hopping: experience and the inventory arrive over the first ticks, so what
	 * was seen before is no base for what is gained next.
	 */
	public void relog()
	{
		last = View.Activity.NONE;
		lastXp = -1;
		lastNuggets = -1;
		carried = null;
		heldBefore = null;
		lastTick = -1;
	}

	/** A skill's experience, or -1 while the skills have not arrived (no Hitpoints experience yet). */
	static long known(long xp, long hitpointsXp)
	{
		return hitpointsXp > 0 ? xp : -1;
	}

	/** Experience gained since the last tick, 0 when either reading is not known. */
	static long xpGained(long before, long now)
	{
		return before >= 0 && now > before ? now - before : 0;
	}

	/** The bank changed while open: remember what it holds of the goal items. */
	public void bank(ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		Map<Integer, Integer> now = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (isTracked(item.getId()))
			{
				now.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		if (!now.equals(bank))
		{
			bank.clear();
			bank.putAll(now);
			save.accept(BANK_KEY, encode(bank));
		}
	}

	/**
	 * Nuggets earned between two ticks, from what you hold carried and banked together. Taking
	 * nuggets out of the bank leaves that total as it was, even when the bank is closed on the
	 * same tick, so it never counts as earning. While the bank is open nothing counts, so the
	 * first look at a bank that changed since it was last seen is not taken for a haul.
	 *
	 * @param before carried plus banked nuggets on the last tick, or -1 when not known
	 */
	static int nuggetsEarned(int before, int now, boolean bankOpen)
	{
		return before >= 0 && now > before && !bankOpen ? now - before : 0;
	}

	/** A game message: the line after a finished contract gives your points. */
	public void chat(String message)
	{
		long[] read = readPoints(message);
		if (read == null)
		{
			return;
		}
		long earned = points.message(read[0], read[1], ownedCost);
		if (earned > 0)
		{
			rate(View.Activity.HOMES).currency += earned;
		}
		savePoints();
	}

	private void savePoints()
	{
		save.accept(POINTS_BOOK_KEY, points.encode());
		save.accept(POINTS_KEY, String.valueOf(points.getTotal()));
	}

	/**
	 * The contracts and points from the message after a contract, or null when the message is not
	 * that one.
	 */
	static long[] readPoints(String message)
	{
		Matcher m = message == null ? null : POINTS.matcher(message);
		if (m == null || !m.find())
		{
			return null;
		}
		long count = parse(m.group(1).replace(",", ""));
		long total = parse(m.group(2).replace(",", ""));
		return count < 0 || total < 0 ? null : new long[]{count, total};
	}

	/**
	 * The points rewards that turned up carried since the last tick, at the reward shop, from
	 * nowhere you had them: not carried or worn a tick ago and not in the bank as last seen.
	 * Those were just bought. Anything that turns up away from the shop, or while a bank, group
	 * storage or your house's costume room is open, was only taken out of storage, even when the
	 * Pilot never saw it go in.
	 *
	 * @param before points rewards carried or worn on the last tick, or null when not seen yet
	 * @param storageOpen a bank, group storage or costume room open on this tick or the last
	 * @param atShop the contract reward shop open on this tick or one of the last few
	 */
	static List<Goal.Reward> bought(EnumSet<Goal.Reward> before, EnumSet<Goal.Reward> now, EnumSet<Goal.Reward> inInventory,
		Map<Integer, Integer> bank, boolean storageOpen, boolean atShop)
	{
		List<Goal.Reward> out = new ArrayList<>();
		if (before == null || storageOpen || !atShop)
		{
			return out;
		}
		for (Goal.Reward r : inInventory)
		{
			if (!before.contains(r) && now.contains(r) && !r.ownedBy(id -> bank.getOrDefault(id, 0) > 0))
			{
				out.add(r);
			}
		}
		return out;
	}

	/**
	 * Whether the reward shop was open on this tick or one of the last few. A shop tick from
	 * before the tick count started over (logging in again) is not recent.
	 */
	static boolean atShop(int shopTick, int tickCount)
	{
		return shopTick >= 0 && tickCount >= shopTick && tickCount - shopTick <= SHOP_GRACE;
	}

	/** Whether an interface component is open and showing. */
	private static boolean showing(Client client, int component)
	{
		Widget w = client.getWidget(component);
		return w != null && !w.isHidden();
	}

	/** A bank, group storage or the costume room in your house: places a reward can come out of. */
	static boolean storageOpen(Client client)
	{
		return com.codex.minigamepilot.pilot.FurnacePilot.bankOpen(client)
			|| showing(client, InterfaceID.SharedBank.ITEMS)
			|| showing(client, InterfaceID.PohCostumes.ITEMS);
	}

	/** The points rewards among what a container holds. */
	private static EnumSet<Goal.Reward> pointsRewards(ItemContainer c)
	{
		EnumSet<Goal.Reward> set = EnumSet.noneOf(Goal.Reward.class);
		if (c == null)
		{
			return set;
		}
		for (Goal.Reward r : Goal.Reward.values())
		{
			if (r.getCurrency() == Goal.Currency.POINTS && r.ownedBy(c::contains))
			{
				set.add(r);
			}
		}
		return set;
	}

	/** What the points rewards you have anywhere cost: all of them were bought with points. */
	static long ownedCost(Have have)
	{
		long cost = 0;
		for (Goal.Reward r : Goal.Reward.values())
		{
			if (r.getCurrency() == Goal.Currency.POINTS && r.ownedBy(have::has))
			{
				cost += r.getCost();
			}
		}
		return cost;
	}

	/**
	 * One tick: counts time, experience and nuggets earned in the minigame you are in, then adds
	 * goal cards to the view: the minigame's own when in one, every minigame's away from them.
	 */
	public void tick(Client client, View view, Choices choices, Contract contract)
	{
		View.Activity activity = view.getActivity();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		int nuggets = inv == null ? 0 : inv.count(ItemIds.GOLDEN_NUGGET);
		// Carried plus banked as last seen: moving nuggets between the two changes neither. With
		// no inventory yet (just logged in) nothing is known, so the next tick is no gain on it.
		int heldNuggets = inv == null ? -1 : nuggets + bank.getOrDefault(ItemIds.GOLDEN_NUGGET, 0);
		Skill skill = skillOf(activity);
		long xp = skill == null ? -1 : known(client.getSkillExperience(skill), client.getSkillExperience(Skill.HITPOINTS));
		if (activity != View.Activity.NONE)
		{
			Rate r = rate(activity);
			r.ticks++;
			if (activity == last)
			{
				r.xp += xpGained(lastXp, xp);
			}
			if (activity == View.Activity.MOTHERLODE && last == activity)
			{
				r.currency += nuggetsEarned(lastNuggets, heldNuggets, com.codex.minigamepilot.pilot.FurnacePilot.bankOpen(client));
			}
		}
		last = activity;
		lastXp = xp;
		lastNuggets = heldNuggets;

		int tickCount = client.getTickCount();
		if (tickCount != lastTick + 1)
		{
			// Ticks went by unwatched (goals hidden, say): what was carried then tells nothing now.
			carried = null;
			storageWasOpen = false;
			shopTick = -1;
			heldBefore = null;
			groupWasOpen = false;
		}
		lastTick = tickCount;
		if (inv != null)
		{
			EnumSet<Goal.Reward> inInventory = pointsRewards(inv);
			EnumSet<Goal.Reward> now = EnumSet.copyOf(inInventory);
			now.addAll(pointsRewards(worn));
			boolean storage = storageOpen(client);
			if (showing(client, InterfaceID.ConstructionContractShop.UNIVERSE))
			{
				shopTick = tickCount;
			}
			boolean atShop = atShop(shopTick, tickCount);
			// Taking a reward out and closing the storage on one tick shows it carried with the
			// storage shut, and the bank as last seen already without it: the open storage a tick
			// ago tells.
			List<Goal.Reward> bought = bought(carried, now, inInventory, bank, storage || storageWasOpen, atShop);
			// One you were already seen to own came from somewhere you keep it, not the shop.
			bought.removeIf(owned::has);
			storageWasOpen = storage;
			remember(inv, worn, client);
			for (Goal.Reward r : bought)
			{
				points.bought(r.getCost());
			}
			if (!bought.isEmpty() && points.known())
			{
				savePoints();
			}
			carried = now;
		}

		Have have = new Have(inv, worn, bank, owned);
		ownedCost = ownedCost(have);
		if (activity == View.Activity.NONE)
		{
			for (View.Activity a : new View.Activity[]{View.Activity.MOTHERLODE, View.Activity.FURNACE, View.Activity.HOMES})
			{
				addCard(client, view, a, choices, contract, have, nuggets);
			}
		}
		else
		{
			addCard(client, view, activity, choices, contract, have, nuggets);
		}
	}

	private void addCard(Client client, View view, View.Activity activity, Choices choices, Contract contract, Have have, int nuggets)
	{
		NavigatorGoals.Target target = navigatorTarget(client, activity, choices);
		Goal goal = plan(client, activity, choices, contract, have, nuggets, target);
		if (goal != null)
		{
			View.GoalCard card = card(activity, goal, balanceKnown(activity));
			if (target != null && goal.getPieces().isEmpty())
			{
				card.aside(aside(target, skillOf(activity)));
			}
			view.goal(card);
		}
		if (activity != View.Activity.NONE && choices.road)
		{
			view.road(road(client, activity, contract, have, nuggets));
		}
	}

	/**
	 * The whole shop of the minigame you are in as one road (at the Blast Furnace, which has no
	 * shop, the Smithing levels that open its bars), with the level your Navigator goals need in
	 * its skill when there is one.
	 */
	List<RewardRoad.Stop> road(Client client, View.Activity activity, Contract contract, Have have, int nuggets)
	{
		Goals.Input in = input(client, activity, contract, have, nuggets, null);
		List<RewardRoad.Stop> road;
		switch (activity)
		{
			case MOTHERLODE:
				road = RewardRoad.motherlode(in);
				break;
			case HOMES:
				road = RewardRoad.homes(in);
				break;
			case FURNACE:
				road = RewardRoad.furnace(in);
				break;
			default:
				road = new ArrayList<>();
		}
		Skill skill = skillOf(activity);
		NavigatorGoals.Target target = navigator == null || skill == null ? null
			: NavigatorGoals.target(navigator.get(), skill.getName(), Goals.levelFor(in.xp));
		if (target != null)
		{
			road = RewardRoad.withLevel(road, skill.getName(), target.getLevel(), target.getGoal(), in);
		}
		// A road of one level alone says no more than the goal card does.
		return road.size() > 1 ? road : new ArrayList<>();
	}

	/**
	 * The level Navigator's goals need in this minigame's skill, when the level goal is left to
	 * the Pilot to pick: the next level at the Blast Furnace, or next level or next reward
	 * elsewhere (which turns to a level once every reward is owned).
	 */
	private NavigatorGoals.Target navigatorTarget(Client client, View.Activity activity, Choices choices)
	{
		Skill skill = skillOf(activity);
		if (navigator == null || skill == null)
		{
			return null;
		}
		boolean pilotPicks;
		switch (activity)
		{
			case FURNACE:
				pilotPicks = choices.furnaceLevel == 0;
				break;
			case MOTHERLODE:
				pilotPicks = picksLevel(choices.motherlode);
				break;
			case HOMES:
				pilotPicks = picksLevel(choices.homes);
				break;
			default:
				pilotPicks = false;
		}
		if (!pilotPicks)
		{
			return null;
		}
		return NavigatorGoals.target(navigator.get(), skill.getName(), Goals.levelFor(client.getSkillExperience(skill)));
	}

	private static boolean picksLevel(Goals.Choice choice)
	{
		return choice == Goals.Choice.NEXT_LEVEL || choice == Goals.Choice.NEXT_REWARD;
	}

	/** "Dragon Slayer II needs Smithing 70", from your Navigator goals. */
	static String aside(NavigatorGoals.Target target, Skill skill)
	{
		return target.getGoal() + " needs " + (skill == null ? "level" : skill.getName()) + " " + target.getLevel();
	}

	private boolean balanceKnown(View.Activity activity)
	{
		return activity != View.Activity.HOMES || points.known();
	}

	Goal plan(Client client, View.Activity activity, Choices choices, Contract contract, Have have, int nuggets, NavigatorGoals.Target target)
	{
		Goals.Input in = input(client, activity, contract, have, nuggets, target);
		switch (activity)
		{
			case MOTHERLODE:
				return Goals.motherlode(choices.motherlode, in);
			case HOMES:
				return Goals.homes(choices.homes, in);
			case FURNACE:
				if (choices.furnaceLevel < 0)
				{
					return null;
				}
				if (choices.furnaceLevel > 0)
				{
					in.targetLevel = choices.furnaceLevel;
				}
				return Goals.furnace(in);
			default:
				return null;
		}
	}

	/** What a minigame's goal and reward road are worked out from: what you own and hold, and your pace. */
	private Goals.Input input(Client client, View.Activity activity, Contract contract, Have have, int nuggets, NavigatorGoals.Target target)
	{
		Skill skill = skillOf(activity);
		Goals.Input in = new Goals.Input();
		in.have = have::has;
		in.skill = skill == null ? null : skill.getName();
		in.xp = skill == null ? 0 : client.getSkillExperience(skill);
		Rate r = rate(activity);
		in.xpPerHour = r.perHour(r.xp, 1);
		if (target != null)
		{
			in.targetLevel = target.getLevel();
		}
		switch (activity)
		{
			case MOTHERLODE:
				if (client.getVarbitValue(VarbitID.MOTHERLODE_BIGGERSACK) > 0)
				{
					in.ownedOtherwise = EnumSet.of(Goal.Reward.BIGGER_SACK);
				}
				in.balance = nuggets + bank.getOrDefault(ItemIds.GOLDEN_NUGGET, 0);
				in.currencyPerHour = r.perHour(r.currency, 2);
				break;
			case HOMES:
				in.balance = points.balance(ownedCost);
				in.currencyPerHour = r.perHour(r.currency, 2);
				Contract.Tier tier = contract != null && contract.getTier() != null ? contract.getTier()
					: Contract.Tier.forLevel(client.getRealSkillLevel(Skill.CONSTRUCTION));
				in.currencyPerRound = tier.points();
				in.roundName = tier.getName().toLowerCase() + " contract";
				break;
			default:
				break;
		}
		return in;
	}

	private View.GoalCard card(View.Activity activity, Goal goal, boolean balanceKnown)
	{
		List<View.Line> lines = new ArrayList<>();
		long left = goal.getHave();
		for (Goal.Piece p : goal.getPieces())
		{
			Goal.Reward reward = p.getReward();
			if (p.isOwned())
			{
				lines.add(new View.Line(reward.getName(), "owned", View.Line.Mark.DONE));
				continue;
			}
			// Lit when what you hold already pays for it, taking the pieces above first.
			boolean affordable = balanceKnown && left >= reward.getCost();
			if (affordable)
			{
				left -= reward.getCost();
			}
			lines.add(new View.Line(reward.getName(), com.codex.minigamepilot.core.Figures.count(reward.getCost()),
				affordable ? View.Line.Mark.NEXT : View.Line.Mark.TODO));
		}
		String note = balanceKnown ? goal.describe()
			: "Finish a contract and the Pilot reads your points from the message. " + com.codex.minigamepilot.core.Figures.count(goal.getNeed()) + " points for all of it";
		if (activity == View.Activity.HOMES && balanceKnown && !goal.getPieces().isEmpty() && points.getMeaning() == Points.Meaning.UNKNOWN && ownedCost > 0)
		{
			// Until the Pilot knows whether the message's total is a balance or every point ever
			// earned, it takes the lower reading, so a reward is never lit before you can buy it.
			note += ". Rewards you own are taken off until a purchase shows whether the total is a balance";
		}
		return new View.GoalCard(activity, goal.getTitle(), balanceKnown ? goal.getHave() : 0, goal.getNeed(), goal.getUnit(), note, lines,
			balanceKnown && goal.done());
	}

	private Rate rate(View.Activity activity)
	{
		return rates.computeIfAbsent(activity, a -> new Rate());
	}

	static Skill skillOf(View.Activity activity)
	{
		switch (activity)
		{
			case MOTHERLODE:
				return Skill.MINING;
			case FURNACE:
				return Skill.SMITHING;
			case HOMES:
				return Skill.CONSTRUCTION;
			default:
				return null;
		}
	}

	static boolean isTracked(int id)
	{
		for (int t : TRACKED)
		{
			if (t == id)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Remembers the rewards seen carried, worn or in the bank, so one put away in the costume
	 * room still counts as owned; one that came out of group storage is not remembered.
	 */
	private void remember(ItemContainer inv, ItemContainer worn, Client client)
	{
		EnumSet<Goal.Reward> inPack = itemRewards(inv);
		EnumSet<Goal.Reward> held = EnumSet.copyOf(inPack);
		held.addAll(itemRewards(worn));
		EnumSet<Goal.Reward> appeared = EnumSet.noneOf(Goal.Reward.class);
		if (heldBefore != null)
		{
			appeared.addAll(inPack);
			appeared.removeAll(heldBefore);
		}
		EnumSet<Goal.Reward> seen = EnumSet.copyOf(held);
		for (Goal.Reward r : Goal.Reward.values())
		{
			if (r.ownedBy(id -> bank.getOrDefault(id, 0) > 0))
			{
				seen.add(r);
			}
		}
		boolean group = showing(client, InterfaceID.SharedBank.ITEMS);
		if (owned.see(seen, appeared, group || groupWasOpen))
		{
			save.accept(OWNED_KEY, owned.encode());
		}
		groupWasOpen = group;
		heldBefore = held;
	}

	/** Every reward with an item among what a container holds. */
	private static EnumSet<Goal.Reward> itemRewards(ItemContainer c)
	{
		EnumSet<Goal.Reward> set = EnumSet.noneOf(Goal.Reward.class);
		if (c == null)
		{
			return set;
		}
		for (Goal.Reward r : Goal.Reward.values())
		{
			if (r.ownedBy(c::contains))
			{
				set.add(r);
			}
		}
		return set;
	}

	/** Whether an item is carried, worn, in the bank as last seen, or a reward you were seen to own. */
	static final class Have
	{
		private final ItemContainer inv;
		private final ItemContainer worn;
		private final Map<Integer, Integer> bank;
		private final Owned owned;

		Have(ItemContainer inv, ItemContainer worn, Map<Integer, Integer> bank, Owned owned)
		{
			this.inv = inv;
			this.worn = worn;
			this.bank = bank;
			this.owned = owned;
		}

		boolean has(int id)
		{
			return inv != null && inv.contains(id) || worn != null && worn.contains(id) || bank.getOrDefault(id, 0) > 0
				|| owned != null && owned.hasItem(id);
		}
	}

	static String encode(Map<Integer, Integer> counts)
	{
		StringBuilder b = new StringBuilder();
		counts.keySet().stream().sorted().forEach(id ->
		{
			if (b.length() > 0)
			{
				b.append(';');
			}
			b.append(id).append('=').append(counts.get(id));
		});
		return b.toString();
	}

	static Map<Integer, Integer> decode(String saved)
	{
		Map<Integer, Integer> map = new HashMap<>();
		if (saved == null || saved.isEmpty())
		{
			return map;
		}
		for (String part : saved.split(";"))
		{
			int eq = part.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(part.substring(0, eq));
				int n = Integer.parseInt(part.substring(eq + 1));
				if (n > 0 && isTracked(id))
				{
					map.put(id, n);
				}
			}
			catch (NumberFormatException ignored)
			{
				// A damaged entry is dropped; the rest still count.
			}
		}
		return map;
	}

	private static long parse(String s)
	{
		if (s == null || s.isEmpty())
		{
			return -1;
		}
		try
		{
			return Long.parseLong(s.trim());
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.codex.minigamepilot.overlay;

import com.codex.minigamepilot.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Color;

/**
 * The colours and strokes the overlays draw with, made once. The overlays draw every frame, so
 * a pulse or a fading trail picks its colour from a table here rather than making a new one.
 */
final class Ink
{
	/** Steps a pulse or a fade is cut into; more than the eye can tell apart at these sizes. */
	static final int STEPS = 16;

	static final BasicStroke THIN = new BasicStroke(1f);
	static final BasicStroke MEDIUM = new BasicStroke(1.5f);
	static final BasicStroke THICK = new BasicStroke(2f);

	static final Color OTHER_RIM = Theme.alpha(Theme.GOLD, 90);
	static final Color END_FILL = Theme.alpha(Theme.TEAL, 40);
	static final Color END_RIM = Theme.alpha(Theme.TEAL, 200);
	static final Color MINIMAP_BEAD = Theme.alpha(Theme.TEAL, 200);
	static final Color MINIMAP_SHADOW = Theme.alpha(Color.BLACK, 140);
	static final Color PLATE_FILL = Theme.alpha(Theme.INK_DEEP, 215);
	static final Color RING_RIM = Theme.alpha(Theme.GOLD_BRIGHT, 230);
	static final Color HULL_RIM = Theme.alpha(Theme.GOLD_BRIGHT, 220);

	/** The target's fill as it pulses, from 30 to 70 alpha, for gold and for teal. */
	static final Color[] GOLD_PULSE = pulse(Theme.GOLD, 30, 40);
	static final Color[] TEAL_PULSE = pulse(Theme.TEAL, 30, 40);
	/** A character's hull pulses a little softer. */
	static final Color[] HULL_PULSE = pulse(Theme.GOLD, 25, 35);
	static final Color GOLD_HOVER = Theme.alpha(Theme.GOLD, 90);
	static final Color TEAL_HOVER = Theme.alpha(Theme.TEAL, 90);
	static final Color GOLD_RIM = Theme.alpha(Theme.mix(Theme.GOLD, Color.WHITE, 0.15), 230);
	static final Color GOLD_RIM_HOVER = Theme.alpha(Theme.mix(Theme.GOLD, Color.WHITE, 0.4), 230);
	static final Color TEAL_RIM = Theme.alpha(Theme.mix(Theme.TEAL, Color.WHITE, 0.15), 230);
	static final Color TEAL_RIM_HOVER = Theme.alpha(Theme.mix(Theme.TEAL, Color.WHITE, 0.4), 230);

	/** The ground trail's beads, brightening toward the end, and their shadows; and the dimmer trail while waiting. */
	static final Color[] BEAD = new Color[STEPS + 1];
	static final Color[] BEAD_SHADOW = new Color[STEPS + 1];
	static final Color WAIT_BEAD = Theme.alpha(Theme.TEAL, 60);
	static final Color WAIT_SHADOW = Theme.alpha(Color.BLACK, 30);

	static
	{
		for (int i = 0; i <= STEPS; i++)
		{
			double t = i / (double) STEPS;
			int alpha = (int) Math.round(110 + 120 * t);
			BEAD[i] = Theme.alpha(Theme.mix(Theme.TEAL, Theme.TEXT, 0.25 * t), alpha);
			BEAD_SHADOW[i] = Theme.alpha(Color.BLACK, alpha / 2);
		}
	}

	private Ink()
	{
	}

	private static Color[] pulse(Color c, int from, int span)
	{
		Color[] out = new Color[STEPS + 1];
		for (int i = 0; i <= STEPS; i++)
		{
			out[i] = Theme.alpha(c, (int) Math.round(from + span * i / (double) STEPS));
		}
		return out;
	}

	/** The table entry for a value from 0 to 1. */
	static Color at(Color[] table, double t)
	{
		int i = (int) Math.round(Math.max(0, Math.min(1, t)) * STEPS);
		return table[i];
	}
}

package com.codex.minigamepilot.overlay;

import com.codex.minigamepilot.pilot.Flight;
import com.codex.minigamepilot.ui.Theme;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.RoundRectangle2D;
import java.util.function.Supplier;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Rings the items a step names, in the inventory, the worn equipment and the open bank: the
 * coal to withdraw, the gloves to put on, the teleport to take.
 */
public class ItemGuide extends WidgetItemOverlay
{
	private static final int PULSE_MS = 1600;

	private final Supplier<Flight> flight;
	/** Reused for every ringed item, so a frame allocates nothing. */
	private final RoundRectangle2D.Float ring = new RoundRectangle2D.Float();

	public ItemGuide(Supplier<Flight> flight)
	{
		this.flight = flight;
		showOnInventory();
		showOnBank();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem item)
	{
		Flight f = flight.get();
		if (f == null || f.step == null || !f.step.hasItem(itemId))
		{
			return;
		}
		Rectangle b = item.getCanvasBounds();
		if (b == null)
		{
			return;
		}
		Theme.smooth(g);
		double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() % PULSE_MS / (double) PULSE_MS * Math.PI * 2);
		ring.setRoundRect(b.x - 1.5f, b.y - 1.5f, b.width + 3, b.height + 3, 8, 8);
		g.setColor(Ink.at(Ink.GOLD_PULSE, pulse));
		g.fill(ring);
		g.setStroke(Ink.THICK);
		g.setColor(Ink.RING_RIM);
		g.draw(ring);
	}
}

package com.codex.minigamepilot.overlay;

import com.codex.minigamepilot.pilot.Flight;
import com.codex.minigamepilot.ui.Theme;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** The same path on the minimap, ending in a gold ring where the step is. */
public class MinimapGuide extends Overlay
{
	private final Client client;
	private final Supplier<Flight> flight;
	private final Supplier<Boolean> enabled;
	/** Reused for every dot, so a frame allocates nothing. */
	private final Ellipse2D.Float dot = new Ellipse2D.Float();

	public MinimapGuide(Client client, Supplier<Flight> flight, Supplier<Boolean> enabled)
	{
		this.client = client;
		this.flight = flight;
		this.enabled = enabled;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Flight f = flight.get();
		if (f == null || f.step == null || !enabled.get())
		{
			return null;
		}
		Theme.smooth(g);
		List<WorldPoint> route = f.route;
		Point end = null;
		for (int i = 0; i < route.size(); i++)
		{
			Point p = minimap(route.get(i));
			if (p == null)
			{
				continue;
			}
			end = p;
			if (i % 2 == 1 && i != route.size() - 1)
			{
				continue;
			}
			g.setColor(Ink.MINIMAP_BEAD);
			dot.setFrame(p.getX() - 1.5f, p.getY() - 1.5f, 3, 3);
			g.fill(dot);
		}
		Point target = null;
		if (f.object != null)
		{
			target = minimap(f.object.getWorldLocation());
		}
		else if (f.npc != null)
		{
			target = minimap(f.npc.getWorldLocation());
		}
		if (target == null)
		{
			target = end;
		}
		if (target != null)
		{
			g.setStroke(Ink.THICK);
			g.setColor(Ink.MINIMAP_SHADOW);
			dot.setFrame(target.getX() - 3.5f, target.getY() - 3.5f, 9, 9);
			g.draw(dot);
			g.setColor(Theme.GOLD_BRIGHT);
			dot.setFrame(target.getX() - 4.5f, target.getY() - 4.5f, 9, 9);
			g.draw(dot);
		}
		return null;
	}

	private Point minimap(WorldPoint wp)
	{
		LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), wp);
		return lp == null ? null : Perspective.localToMinimap(client, lp);
	}
}

package com.codex.minigamepilot.overlay;

import com.codex.minigamepilot.pilot.Flight;
import com.codex.minigamepilot.ui.Theme;
import com.codex.minigamepilot.ui.Ui;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the step in the world: the thing to click lit in gold with a small plate naming the
 * action, the path to it as a trail of teal beads that brighten toward the end, and anything
 * else still to do marked quietly. It only draws; it never clicks or changes menus.
 */
public class SceneGuide extends Overlay
{
	/** Beads drawn at most, so a long walk does not paint the whole screen. */
	private static final int MAX_BEADS = 40;
	private static final Color PLATE_RIM_GOLD = Theme.alpha(Theme.GOLD, 200);
	private static final Color PLATE_RIM_TEAL = Theme.alpha(Theme.TEAL, 200);
	private static final Color PLATE_TEXT_GOLD = Theme.mix(Theme.GOLD, Color.WHITE, 0.3);
	private static final Color PLATE_TEXT_TEAL = Theme.mix(Theme.TEAL, Color.WHITE, 0.3);
	private static final int PULSE_MS = 1600;

	private final Client client;
	private final Supplier<Flight> flight;
	private final Supplier<Settings> settings;
	/** Reused for every bead, so the trail allocates nothing per frame. */
	private final Ellipse2D.Float bead = new Ellipse2D.Float();

	/** What to draw, from the plugin's config. */
	public static final class Settings
	{
		public final boolean route;
		public final boolean labels;
		public final boolean others;

		public Settings(boolean route, boolean labels, boolean others)
		{
			this.route = route;
			this.labels = labels;
			this.others = others;
		}
	}

	public SceneGuide(Client client, Supplier<Flight> flight, Supplier<Settings> settings)
	{
		this.client = client;
		this.flight = flight;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Flight f = flight.get();
		if (f == null || f.step == null)
		{
			return null;
		}
		Settings set = settings.get();
		Theme.smooth(g);
		double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() % PULSE_MS / (double) PULSE_MS * Math.PI * 2);

		if (set.others)
		{
			for (TileObject o : f.others)
			{
				Shape box = o.getClickbox();
				if (box != null)
				{
					g.setStroke(Ink.THIN);
					g.setColor(Ink.OTHER_RIM);
					g.draw(box);
				}
			}
		}
		if (set.route)
		{
			drawRoute(g, f.route, f.step.isWaiting());
		}
		if (f.object != null)
		{
			drawObject(g, f.object, f, pulse, set.labels);
		}
		if (f.npc != null)
		{
			drawNpc(g, f.npc, f, pulse, set.labels);
		}
		return null;
	}

	private void drawRoute(Graphics2D g, List<WorldPoint> route, boolean waiting)
	{
		int n = Math.min(route.size(), MAX_BEADS);
		for (int i = 0; i < n; i++)
		{
			LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), route.get(i));
			if (lp == null)
			{
				continue;
			}
			Point p = Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				continue;
			}
			boolean last = i == route.size() - 1;
			if (last)
			{
				Polygon tile = Perspective.getCanvasTilePoly(client, lp);
				if (tile != null)
				{
					g.setColor(Ink.END_FILL);
					g.fill(tile);
					g.setStroke(Ink.MEDIUM);
					g.setColor(Ink.END_RIM);
					g.draw(tile);
				}
				continue;
			}
			double t = n <= 1 ? 1 : i / (double) (n - 1);
			float r = (float) (2.2 + 1.4 * t);
			g.setColor(waiting ? Ink.WAIT_SHADOW : Ink.at(Ink.BEAD_SHADOW, t));
			bead.setFrame(p.getX() - r + 1, p.getY() - r + 1, r * 2, r * 2);
			g.fill(bead);
			g.setColor(waiting ? Ink.WAIT_BEAD : Ink.at(Ink.BEAD, t));
			bead.setFrame(p.getX() - r, p.getY() - r, r * 2, r * 2);
			g.fill(bead);
		}
	}

	private void drawObject(Graphics2D g, TileObject o, Flight f, double pulse, boolean label)
	{
		Shape box = o.getClickbox();
		boolean teal = f.step.isWaiting();
		Color tone = teal ? Theme.TEAL : Theme.GOLD;
		if (box != null)
		{
			Point mouse = client.getMouseCanvasPosition();
			boolean hover = mouse != null && box.contains(mouse.getX(), mouse.getY());
			g.setColor(hover ? (teal ? Ink.TEAL_HOVER : Ink.GOLD_HOVER) : Ink.at(teal ? Ink.TEAL_PULSE : Ink.GOLD_PULSE, pulse));
			g.fill(box);
			g.setStroke(Ink.THICK);
			g.setColor(teal ? (hover ? Ink.TEAL_RIM_HOVER : Ink.TEAL_RIM) : (hover ? Ink.GOLD_RIM_HOVER : Ink.GOLD_RIM));
			g.draw(box);
		}
		if (label)
		{
			Point at = o.getCanvasTextLocation(g, f.step.getVerb(), 160);
			if (at != null)
			{
				plate(g, f.step.getVerb(), at.getX(), at.getY(), tone);
			}
		}
	}

	private void drawNpc(Graphics2D g, NPC npc, Flight f, double pulse, boolean label)
	{
		Shape hull = npc.getConvexHull();
		if (hull != null)
		{
			g.setColor(Ink.at(Ink.HULL_PULSE, pulse));
			g.fill(hull);
			g.setStroke(Ink.THICK);
			g.setColor(Ink.HULL_RIM);
			g.draw(hull);
		}
		if (label)
		{
			Point at = npc.getCanvasTextLocation(g, f.step.getVerb(), npc.getLogicalHeight() + 40);
			if (at != null)
			{
				plate(g, f.step.getVerb(), at.getX(), at.getY(), Theme.GOLD);
			}
		}
	}

	/** A small ink plate with a gilt rim and the action on it, centred over a point. */
	private static void plate(Graphics2D g, String text, int x, int y, Color tone)
	{
		g.setFont(Theme.title());
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(text) + 14;
		int h = fm.getAscent() + 8;
		int left = x + fm.stringWidth(text) / 2 - w / 2;
		int top = y - fm.getAscent() - 4;
		g.setColor(Ink.PLATE_FILL);
		g.fillRoundRect(left, top, w, h, 8, 8);
		g.setStroke(Ink.THIN);
		boolean teal = tone == Theme.TEAL;
		g.setColor(teal ? PLATE_RIM_TEAL : PLATE_RIM_GOLD);
		g.drawRoundRect(left, top, w, h, 8, 8);
		Ui.shadowed(g, text, left + 7, top + fm.getAscent() + 3, teal ? PLATE_TEXT_TEAL : PLATE_TEXT_GOLD);
	}
}

package com.codex.minigamepilot.overlay;

import com.codex.minigamepilot.core.Step;
import com.codex.minigamepilot.ui.Sigil;
import com.codex.minigamepilot.ui.Theme;
import com.codex.minigamepilot.ui.Ui;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A slim gilt plaque in the game view with the next step: the action in gold, the instruction,
 * and its line of why underneath. It draws what the plugin hands it.
 */
public class StepPlaque extends Overlay
{
	private static final int PAD = 7;
	private static final int MAX_WIDTH = 300;

	private static final java.awt.image.BufferedImage MARK = Sigil.icon(16);
	private static final Color GOLD_RIM = Theme.alpha(Theme.GOLD, 170);
	private static final Color GOLD_BAR = Theme.alpha(Theme.GOLD, 200);
	private static final Color TEAL_RIM = Theme.alpha(Theme.TEAL, 170);
	private static final Color TEAL_BAR = Theme.alpha(Theme.TEAL, 200);

	private volatile Step step;
	/** The step's capitalised verb, worked out once per step rather than every frame. */
	private Step verbOf;
	private String verb;
	/** The backdrop, made again only when the plaque's height changes. */
	private GradientPaint backdrop;
	private int backdropHeight;

	public StepPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** @param step the step to show, or null to hide the plaque */
	public void show(Step step)
	{
		this.step = step;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Step s = step;
		if (s == null)
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();

		int icon = 16;
		if (s != verbOf)
		{
			verbOf = s;
			verb = s.getVerb().toUpperCase();
		}
		String verb = this.verb;
		int textX = PAD + icon + 7;
		int line1 = bold.stringWidth(verb) + 8 + small.stringWidth(s.getTitle());
		int line2 = s.getDetail().isEmpty() ? 0 : small.stringWidth(s.getDetail());
		int width = Math.min(MAX_WIDTH, textX + Math.max(line1, line2) + PAD + 2);
		int height = PAD * 2 + bold.getAscent() + (line2 > 0 ? small.getHeight() : 0) + 1;

		boolean teal = s.isWaiting();
		Color tone = teal ? Theme.TEAL : Theme.GOLD;
		if (backdrop == null || backdropHeight != height)
		{
			backdrop = new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 235), 0, height, Theme.alpha(Theme.INK_DEEP, 235));
			backdropHeight = height;
		}
		g.setPaint(backdrop);
		g.fillRoundRect(0, 0, width - 1, height - 1, 10, 10);
		g.setColor(teal ? TEAL_RIM : GOLD_RIM);
		g.drawRoundRect(0, 0, width - 1, height - 1, 10, 10);
		g.setColor(teal ? TEAL_BAR : GOLD_BAR);
		g.fillRect(1, 6, 2, height - 12);

		g.drawImage(MARK, PAD, PAD, null);
		int base = PAD + bold.getAscent();
		g.setFont(Theme.title());
		Ui.shadowed(g, verb, textX, base, tone);
		int x = textX + bold.stringWidth(verb) + 8;
		g.setFont(Theme.small());
		Ui.shadowed(g, Ui.clip(s.getTitle(), small, width - x - PAD), x, base, Theme.TEXT);
		if (line2 > 0)
		{
			Ui.shadowed(g, Ui.clip(s.getDetail(), small, width - textX - PAD), textX, base + small.getHeight(), Theme.TEXT_MUTED);
		}
		return new Dimension(width, height);
	}
}

package com.codex.minigamepilot.pilot;

import com.codex.minigamepilot.core.Pace;
import com.codex.minigamepilot.core.Step;
import com.codex.minigamepilot.ui.View;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;

/**
 * Watches you play, a tick at a time, and hands the pace coach what it needs: whether you stood
 * still with something to do, how far you moved, how far the step was. Then it writes the
 * coach's verdict into the panel.
 */
final class Coach
{
	/**
	 * Interfaces that mean you are busy even though you are not moving: the bank, dialogue, the
	 * make-how-many box and the furniture menu.
	 */
	private static final int[] BUSY = {12, 193, 217, 219, 229, 231, 270, 397, 458};

	private final Map<View.Activity, Pace> paces = new EnumMap<>(View.Activity.class);
	private final Function<View.Activity, String> load;
	private final BiConsumer<View.Activity, String> save;
	private WorldPoint lastAt;
	private View.Activity lastActivity = View.Activity.NONE;

	Coach(Function<View.Activity, String> load, BiConsumer<View.Activity, String> save)
	{
		this.load = load;
		this.save = save;
	}

	/** After a profile change: the bests of the account now logged in. */
	void reload()
	{
		for (Map.Entry<View.Activity, Pace> e : paces.entrySet())
		{
			e.getValue().loadBests(load.apply(e.getKey()));
		}
	}

	Pace pace(View.Activity activity)
	{
		return paces.computeIfAbsent(activity, a ->
		{
			Pace p = new Pace();
			p.loadBests(load.apply(a));
			return p;
		});
	}

	/** One tick in a minigame. Returns the round that just finished, or null. */
	Pace.Round tick(Client client, Flight flight, int units, String kindHint)
	{
		Player me = client.getLocalPlayer();
		if (me == null || flight.step == null || flight.activity == View.Activity.NONE)
		{
			left();
			return null;
		}
		if (flight.activity != lastActivity)
		{
			left();
			lastActivity = flight.activity;
		}
		WorldPoint at = me.getWorldLocation();
		int moved = 0;
		if (lastAt != null && at.getPlane() == lastAt.getPlane())
		{
			int d = Math.max(Math.abs(at.getX() - lastAt.getX()), Math.abs(at.getY() - lastAt.getY()));
			// More than a running stride is a ladder or a teleport, not walking.
			moved = d <= 2 ? d : 0;
		}
		lastAt = at;
		boolean still = moved == 0 && me.getAnimation() == -1 && !busy(client);

		Step step = flight.step;
		WorldPoint where = flight.object != null ? flight.object.getWorldLocation()
			: flight.npc != null ? flight.npc.getWorldLocation() : flight.destination;
		String leg = step.getVerb() + "|" + step.getTarget() + "|" + where;
		int route = flight.route == null || flight.route.isEmpty() ? -1 : flight.route.size();
		Pace pace = pace(flight.activity);
		Pace.Round done = pace.tick(flight.view.loopAt(), leg, place(step), still, step.isWaiting(), moved, route, units, kindHint);
		// Every fair round can set a stage best even when the round as a whole was slower.
		if (done != null && !done.hadBreak)
		{
			save.accept(flight.activity, pace.saveBests());
		}
		return done;
	}

	/** Out of the minigames: any round in progress is dropped. */
	void left()
	{
		if (lastActivity != View.Activity.NONE)
		{
			Pace p = paces.get(lastActivity);
			if (p != null)
			{
				p.reset();
			}
		}
		lastActivity = View.Activity.NONE;
		lastAt = null;
	}

	/** Adds the coach's card to the panel, once a round has been timed. */
	void decorate(View view, View.Activity activity)
	{
		Pace p = paces.get(activity);
		Pace.Round last = p == null ? null : p.last();
		if (last == null)
		{
			return;
		}
		int best = p.best(last.kind);
		int typical = p.typical(last.kind);
		int rounds = p.rounds().size();
		String tail = rounds + (rounds == 1 ? " round" : " rounds")
			+ (typical > 0 && rounds > 2 ? " · usually " + Pace.clock(typical) : "")
			+ (p.idleTotal() > 0 ? " · " + Pace.clock(p.idleTotal()) + " idle" : "");
		View.PaceCard card = new View.PaceCard(last.ticks, best, last.isBest(),
			last.bestBefore > 0 && !last.hadBreak ? last.ticks - last.bestBefore : 0,
			last.advice(), last.costly(), tail);
		String[] names = view.loopNames();
		if (names != null && !last.hadBreak)
		{
			card.splits(splits(last, names), splitNote(last, names));
		}
		view.pace(card);
	}

	/** The round's stages in loop order, those it spent time in. */
	static java.util.List<View.Split> splits(Pace.Round round, String[] names)
	{
		java.util.List<View.Split> list = new java.util.ArrayList<>();
		int slow = round.slowestStage();
		for (int s = 0; s < names.length; s++)
		{
			if (round.stageTicks(s) > 0)
			{
				list.add(new View.Split(names[s], round.stageTicks(s), round.stageBest(s), s == slow));
			}
		}
		return list;
	}

	/** "Bank took 0:14, 0:05 over your best", or null when no stage lost much. */
	static String splitNote(Pace.Round round, String[] names)
	{
		int slow = round.slowestStage();
		if (slow < 0 || slow >= names.length)
		{
			return null;
		}
		int ticks = round.stageTicks(slow);
		int over = ticks - round.stageBest(slow);
		return names[slow] + " took " + Pace.clock(ticks) + ", " + Pace.clock(over) + " over your best for it";
	}

	private static boolean busy(Client client)
	{
		for (int group : BUSY)
		{
			Widget w = client.getWidget(group, 0);
			if (w != null && !w.isHidden())
			{
				return true;
			}
		}
		return false;
	}

	/** Where a step is, as the coach says it: "Stood still 4 ticks at the bank". */
	static String place(Step step)
	{
		switch (step.getTarget())
		{
			case VEIN:
				return "a vein";
			case HOPPER:
				return "the hopper";
			case SACK:
				return "the sack";
			case BANK:
				return "the bank";
			case STRUT:
				return "the strut";
			case ROCKFALL:
				return "the rockfall";
			case LADDER:
				return "the ladder";
			case BELT:
				return "the belt";
			case DISPENSER:
				return "the dispenser";
			case COFFER:
				return "the coffer";
			case CONTRACTOR:
				return "the contractor";
			case CLIENT:
				return "the client";
			case HOTSPOT:
				return "the furniture";
			case HOME:
				return "the house";
			default:
				return null;
		}
	}
}

package com.codex.minigamepilot.pilot;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * How much coal is in the coal bag. The game only says when the bag is checked, so this follows
 * the bag's Fill and Empty options and watches the coal in the inventory move.
 */
final class CoalBag
{
	private static final Pattern CONTAINS = Pattern.compile("The coal bag (?:still )?contains (\\d+|one) pieces? of coal\\.");
	private static final Pattern EMPTY = Pattern.compile("The coal bag is (?:now )?empty\\.");

	/** What was last asked of the bag, waiting for the inventory to show it. */
	private enum Pending
	{
		NONE,
		FILL,
		EMPTY
	}

	private int coal = -1;
	private int capacity = 27;
	private Pending pending = Pending.NONE;
	private int coalBefore;
	private int wait;

	/** Coal in the bag, or -1 when unknown. */
	int coal()
	{
		return coal;
	}

	int capacity()
	{
		return capacity;
	}

	/** A smithing cape lets the bag hold 36. */
	void setCapacity(int capacity)
	{
		this.capacity = capacity;
		if (coal > capacity)
		{
			coal = capacity;
		}
	}

	void chat(String message)
	{
		Matcher m = CONTAINS.matcher(message);
		if (m.matches())
		{
			coal = "one".equals(m.group(1)) ? 1 : Integer.parseInt(m.group(1));
		}
		else if (EMPTY.matcher(message).matches())
		{
			coal = 0;
		}
	}

	/**
	 * The player chose an option on the bag.
	 *
	 * @param bankCoal coal in the open bank, or -1 when the bank is closed
	 */
	void option(String option, int inventoryCoal, int bankCoal)
	{
		if ("Fill".equalsIgnoreCase(option))
		{
			if (bankCoal >= 0)
			{
				// Filled from the bank: the inventory does not change, so count it now.
				int room = capacity - Math.max(0, coal);
				coal = Math.max(0, coal) + Math.min(room, bankCoal);
				return;
			}
			pending = Pending.FILL;
		}
		else if ("Empty".equalsIgnoreCase(option))
		{
			pending = Pending.EMPTY;
		}
		else
		{
			return;
		}
		coalBefore = inventoryCoal;
		wait = 3;
	}

	/** Once a tick, with the coal carried now. */
	void tick(int inventoryCoal)
	{
		if (pending == Pending.NONE)
		{
			return;
		}
		int moved = inventoryCoal - coalBefore;
		if (pending == Pending.EMPTY && moved > 0)
		{
			coal = Math.max(0, Math.max(0, coal) - moved);
			pending = Pending.NONE;
		}
		else if (pending == Pending.FILL && moved < 0)
		{
			coal = Math.min(capacity, Math.max(0, coal) - moved);
			pending = Pending.NONE;
		}
		else if (--wait <= 0)
		{
			pending = Pending.NONE;
		}
	}
}

package com.codex.minigamepilot.pilot;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Field notes: an optional, local record of what the Pilot saw and decided, one JSON object a
 * line, written to the plugin's own data folder (.runelite/plugin-data/codex-minigame-pilot)
 * through RuneLite's Filepath, which keeps every write inside that folder. It exists so the guidance can be checked
 * against a real session: which objects and varbits the game showed, which step was chosen,
 * where a target could not be found, and how each round went. Nothing is sent anywhere.
 */
public final class FieldNotes
{
	private static final Logger log = LoggerFactory.getLogger(FieldNotes.class);
	/** A notes file stops growing past this, so a forgotten setting cannot fill a disk. */
	private static final long LIMIT = 25L * 1024 * 1024;

	/** The plugin's data folder, looked up only when notes are first opened. */
	private final Callable<Filepath> dir;
	private final Gson gson;
	private final ExecutorService writer = Executors.newSingleThreadExecutor(r ->
	{
		Thread t = new Thread(r, "codex-minigame-pilot-notes");
		t.setDaemon(true);
		return t;
	});
	private BufferedWriter out;
	private Filepath file;
	private long written;
	private volatile boolean active;

	public FieldNotes(Callable<Filepath> dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	/** Opens a new notes file. Safe to call when already open. */
	public synchronized void open(String version)
	{
		if (active)
		{
			return;
		}
		active = true;
		String name = "field-notes-" + new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date()) + ".jsonl";
		writer.execute(() ->
		{
			try
			{
				Filepath folder = dir.call();
				folder.createDirectories();
				Filepath target = folder.joinSegment(name);
				BufferedWriter w = target.openBufferedWriter(StandardOpenOption.CREATE, StandardOpenOption.APPEND);
				synchronized (this)
				{
					out = w;
					file = target;
					written = 0;
				}
			}
			catch (Exception e)
			{
				log.warn("Could not open field notes {}", name, e);
			}
		});
		JsonObject start = new JsonObject();
		start.addProperty("plugin", "codex-minigame-pilot");
		start.addProperty("version", version);
		start.addProperty("java", System.getProperty("java.version"));
		note("start", start);
	}

	public boolean isOpen()
	{
		return active;
	}

	/** The file being written, once it is open, or null. */
	public synchronized Filepath file()
	{
		return file;
	}

	/** Adds a line. The time and the kind of note lead every line. */
	public void note(String kind, JsonObject body)
	{
		if (!active)
		{
			return;
		}
		JsonObject line = new JsonObject();
		line.addProperty("ms", System.currentTimeMillis());
		line.addProperty("k", kind);
		for (String key : body.keySet())
		{
			line.add(key, body.get(key));
		}
		String text = gson.toJson(line);
		writer.execute(() -> write(text));
	}

	/** Turns an object with plain fields, such as a planner's snapshot, into a note body. */
	public JsonObject tree(Object o)
	{
		return o == null ? new JsonObject() : gson.toJsonTree(o).getAsJsonObject();
	}

	/** Finishes the file. Safe to call when already closed. */
	public void close()
	{
		active = false;
		writer.execute(() ->
		{
			synchronized (this)
			{
				if (out == null)
				{
					return;
				}
				try
				{
					out.close();
				}
				catch (IOException e)
				{
					log.warn("Could not close field notes", e);
				}
				out = null;
				file = null;
			}
		});
	}

	public void shutdown()
	{
		close();
		writer.shutdown();
	}

	private synchronized void write(String text)
	{
		if (out == null || written > LIMIT)
		{
			return;
		}
		try
		{
			out.write(text);
			out.newLine();
			out.flush();
			written += text.length() + 1;
		}
		catch (IOException e)
		{
			log.warn("Could not write field notes", e);
		}
	}
}

package com.codex.minigamepilot.pilot;

import com.codex.minigamepilot.core.Step;
import com.codex.minigamepilot.ui.View;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.NPC;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

/**
 * One tick's guidance: the step, the thing in the world to light up, the tiles to walk, and what
 * the panel shows. Overlays draw it; nothing in it is ever acted on by the plugin.
 */
public final class Flight
{
	public final View.Activity activity;
	public final Step step;
	public final View view;
	/** The object the step is about, or null. */
	public TileObject object;
	/** The character the step is about, or null. */
	public NPC npc;
	/** Tiles to walk to reach it, nearest first. */
	public List<WorldPoint> route = Collections.emptyList();
	/** A place beyond the loaded scene to head for, or null. */
	public WorldPoint destination;
	/** Other objects worth a quieter mark, such as the rest of the furniture still to fix. */
	public final List<TileObject> others = new ArrayList<>();

	public Flight(View.Activity activity, Step step, View view)
	{
		this.activity = activity;
		this.step = step;
		this.view = view;
	}

	public static Flight idle(View view)
	{
		return new Flight(View.Activity.NONE, null, view);
	}

	Flight to(Ground.Way<?> way)
	{
		if (way != null)
		{
			if (way.thing instanceof TileObject)
			{
				object = (TileObject) way.thing;
			}
			else if (way.thing instanceof NPC)
			{
				npc = (NPC) way.thing;
			}
			route = way.path;
		}
		return this;
	}
}

