/**
 * Flies Mahogany Homes: getting a contract, fetching the right planks, the way to the client's
 * house and the teleport to take, then each piece of furniture in walking order, floor by floor.
 */
public final class HomesPilot
{
	private static final Pattern ASSIGNED = Pattern.compile("(\\w+) Contract: Go see (\\w+)");
	private static final Pattern GO_SEE = Pattern.compile("[Gg]o see (\\w+)");
	private static final Pattern ON_TIER = Pattern.compile("on an? (\\w+) [Cc]ontract");
	private static final Pattern ASKED = Pattern.compile("Could I have an? (\\w+) contract");
	private static final Pattern FINISHED = Pattern.compile("You have completed [\\d,]+ contracts? with a total of [\\d,]+ points?\\.");
	/** Tiles from a client's house within which an open contract takes over the panel. */
	private static final int NEAR = 150;
	private static final String[] LOOP = {"Job", "Planks", "Go", "Fix", "Report"};
	private static final int[] PLANK_SACK_VARBITS = {
		VarbitID.PLANK_SACK_PLAIN, VarbitID.PLANK_SACK_OAK, VarbitID.PLANK_SACK_TEAK, VarbitID.PLANK_SACK_MAHOGANY
	};

	/** Teleports that land near each city's houses, by the start of the item's name. */
	private static final Map<Home.City, String[]> TELEPORTS = new HashMap<>();

	static
	{
		TELEPORTS.put(Home.City.FALADOR, new String[]{"Falador teleport", "Ring of wealth", "Skills necklace"});
		TELEPORTS.put(Home.City.VARROCK, new String[]{"Varrock teleport"});
		TELEPORTS.put(Home.City.ARDOUGNE, new String[]{"Ardougne teleport", "Ardougne cloak", "Achievement diary cape"});
		TELEPORTS.put(Home.City.HOSIDIUS, new String[]{"Hosidius teleport", "Xeric's talisman", "Kharedst's memoirs", "Book of the dead"});
	}

	private final Session session = new Session(Skill.CONSTRUCTION);

	/** Another account logged in: the session and its counts start over on its first tick. */
	void newAccount()
	{
		session.startOver();
	}
	private final Consumer<Contract> save;
	private final Map<Integer, String> objectNames = new HashMap<>();
	private Contract contract;
	private Contract.Tier asked;
	private String lastDialog;
	private int contracts;
	/** Contracts and points from before this session began, left out of its counts. */
	private int contractsBefore;
	private int pointsBefore;
	/** The last snapshot planned from, for the field notes. */
	Object lastState;
	/** The contract tier's planks carried, plank sack included, as of the last tick flown. */
	private int lastPlanks;
	private int points;
	private long assignedAt;

	/** Where the contract book is saved for this account. */
	static final String BOOK_KEY = "homes.book";
	/** Ticks after the hand-in message before its experience is read, so the reward has landed. */
	static final int SETTLE_TICKS = 3;
	private final Function<String, String> load;
	private final BiConsumer<String, String> saveKey;
	private ContractBook book = new ContractBook();
	/** The contract being measured: its house, the experience when work began, and what it takes. */
	private Home meterHome;
	/** Experience when the job was first seen untouched, -1 before that, -2 when first seen part done. */
	private long meterXp = -1;
	private int meterPlanks;
	private int meterSteel;
	private Contract.Tier meterTier;
	/** A handed-in contract waiting for its experience to settle: ticks left, or -1. */
	private int settleIn = -1;
	private long settleXp;
	private int settlePlanks;
	private int settleSteel;
	private Contract.Tier settleTier;
	private long settleSeconds;
	/** When the last contract was handed in, for the time a whole loop takes. */
	private long lastHandIn;

	HomesPilot(Contract saved, Consumer<Contract> save, Function<String, String> load, BiConsumer<String, String> saveKey)
	{
		this.contract = saved;
		this.save = save;
		this.load = load;
		this.saveKey = saveKey;
		reloadBook();
	}

	/** This account's contract book, after logging in or switching account. */
	void reloadBook()
	{
		book = ContractBook.decode(load == null ? null : load.apply(BOOK_KEY));
		meterHome = null;
		meterXp = -1;
		settleIn = -1;
		lastHandIn = 0;
	}

	ContractBook getBook()
	{
		return book;
	}

	/**
	 * Measures the contract open now: the first time its furniture is seen with every piece still
	 * to do, the experience and the planks and steel the job takes are noted. A job first seen part
	 * done is not measured, since what was done before would be missing.
	 */
	void meter(Contract open, int[] values, long xp)
	{
		if (open == null || open.getTier() == null)
		{
			return;
		}
		if (open.getHome() != meterHome)
		{
			meterHome = open.getHome();
			meterXp = -1;
		}
		// No experience at all means the skills have not arrived yet (just logged in): wait for them.
		if (meterXp != -1 || xp <= 0 || !Contract.known(values))
		{
			return;
		}
		int used = 0;
		for (int v : values)
		{
			if (v != 0)
			{
				used++;
			}
		}
		int left = open.remaining(values).size();
		if (left == 0)
		{
			// Every piece done: the end of a job (this one or the last), which says nothing yet.
			return;
		}
		if (left == used)
		{
			meterXp = xp;
			meterPlanks = open.planksNeeded(values);
			meterSteel = open.steelNeeded(values);
			meterTier = open.getTier();
		}
		else
		{
			meterXp = -2;
		}
	}

	/** The hand-in message: a measured contract waits a few ticks for its experience to land. */
	private void handedIn(long now)
	{
		if (contract != null && contract.getHome() == meterHome && meterXp >= 0)
		{
			settleIn = SETTLE_TICKS;
			settleXp = meterXp;
			settlePlanks = meterPlanks;
			settleSteel = meterSteel;
			settleTier = meterTier;
			settleSeconds = lastHandIn > 0 ? (now - lastHandIn) / 1000 : 0;
		}
		lastHandIn = now;
		meterHome = null;
		meterXp = -1;
	}

	/** Every tick, wherever you are: files a handed-in contract once its experience has landed. */
	void settle(long xp)
	{
		if (settleIn < 0 || --settleIn > 0)
		{
			return;
		}
		settleIn = -1;
		if (xp > 0 && book.record(settleTier, xp - settleXp, settlePlanks, settleSteel, settleSeconds) && saveKey != null)
		{
			saveKey.accept(BOOK_KEY, book.encode());
		}
	}

	Contract getContract()
	{
		return contract;
	}

	/** After a profile change, the saved contract of the account now logged in. */
	void load(Contract saved)
	{
		contract = saved;
	}

	/** A running count of what rounds produce, for the pace coach. */
	int units()
	{
		return contracts;
	}

	/** Contracts are only compared with the same house and tier. */
	String kindHint()
	{
		return contract == null ? null : contract.getHome().getName() + (contract.getTier() == null ? "" : " " + contract.getTier().getName());
	}

	static boolean isWatched(int id)
	{
		for (Home h : Home.values())
		{
			if (h.indexOf(id) >= 0 || h.isLadder(id))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether this pilot has something to say: a contractor in sight, or a contract open and the
	 * player plainly working on it (near the house, carrying its planks, or just given it). An open
	 * contract alone does not take over the panel while the player is off doing something else.
	 */
	boolean active(Client client, long now)
	{
		if (contractorNear(client) != null)
		{
			return true;
		}
		if (contract == null)
		{
			return false;
		}
		if (now - assignedAt < 15 * 60_000L)
		{
			return true;
		}
		WorldPoint at = client.getLocalPlayer().getWorldLocation();
		if (contract.getHome().distanceTo(at.getX(), at.getY()) <= NEAR)
		{
			return true;
		}
		Contract.Tier tier = contract.getTier();
		return tier != null && Pack.read(client).carries(tier.getPlank());
	}

	View.Brief brief(BankStock stock, int constructionLevel)
	{
		String status = contract == null ? "No contract open"
			: (contract.getTier() == null ? "A" : contract.getTier().getName()) + " contract for " + contract.getHome().getName()
			+ " in " + contract.getHome().getCity().getName();
		Contract.Tier tier = contract != null && contract.getTier() != null ? contract.getTier() : Contract.Tier.forLevel(constructionLevel);
		if (stock != null && tier != null)
		{
			Supplies.Homes h = Supplies.homes(tier, stock.count(tier.getPlank()), stock.count(Contract.STEEL_BAR), book.tally(tier));
			if (h.getContracts() >= 0)
			{
				status += ". In the bank: " + Character.toLowerCase(h.headline().charAt(0)) + h.headline().substring(1);
			}
		}
		return new View.Brief(View.Activity.HOMES, status,
			"Contracts from Amy in Falador, Marlo in Varrock, Ellie in East Ardougne or Angelo in Hosidius.");
	}

	void chat(String message)
	{
		String text = Text.removeTags(message);
		Matcher m = ASSIGNED.matcher(text);
		if (m.find())
		{
			assign(m.group(2), Contract.Tier.byName(m.group(1)));
		}
		if (FINISHED.matcher(text).find())
		{
			handedIn(System.currentTimeMillis());
			if (contract != null)
			{
				contracts++;
				points += contract.getTier() == null ? 0 : contract.getTier().points();
			}
			contract = null;
			save.accept(null);
		}
	}

	/** Reads the dialogue box, where contracts are handed out and reminded of. */
	private void dialog(Client client)
	{
		Widget npc = client.getWidget(InterfaceID.ChatLeft.TEXT);
		Widget me = client.getWidget(InterfaceID.ChatRight.TEXT);
		String text = npc != null && !npc.isHidden() ? npc.getText() : me != null && !me.isHidden() ? me.getText() : null;
		if (text == null || text.equals(lastDialog))
		{
			return;
		}
		lastDialog = text;
		String plain = Text.sanitizeMultilineText(text);
		Matcher ask = ASKED.matcher(plain);
		if (ask.find())
		{
			asked = Contract.Tier.byName(ask.group(1));
			return;
		}
		Matcher go = GO_SEE.matcher(plain);
		if (go.find() && plain.contains("another job"))
		{
			Matcher tier = ON_TIER.matcher(plain);
			assign(go.group(1), tier.find() ? Contract.Tier.byName(tier.group(1)) : asked);
		}
	}

	private void assign(String name, Contract.Tier tier)
	{
		Home home = Home.byName(name);
		if (home == null)
		{
			return;
		}
		if (tier == null && contract != null && contract.getHome() == home)
		{
			tier = contract.getTier();
		}
		Contract next = new Contract(home, tier);
		if (contract == null || contract.getHome() != home || contract.getTier() != tier)
		{
			if (contract == null || contract.getHome() != home)
			{
				assignedAt = System.currentTimeMillis();
			}
			contract = next;
			save.accept(next);
		}
	}

	Flight fly(Client client, SceneIndex scene, Collection<NPC> npcs, long now)
	{
		dialog(client);
		Player me = client.getLocalPlayer();
		WorldPoint at = me.getWorldLocation();
		Pack pack = Pack.read(client);

		Contract.Snapshot s = new Contract.Snapshot();
		lastState = s;
		for (int i = 0; i < Home.HOTSPOTS; i++)
		{
			s.values[i] = client.getVarbitValue(Home.HOTSPOT_VARBIT + i);
		}
		s.constructionLevel = client.getRealSkillLevel(Skill.CONSTRUCTION);
		if (contract != null && contract.getTier() == null)
		{
			Contract.Tier seen = Contract.tierFromValues(s.values);
			if (seen != null)
			{
				contract = new Contract(contract.getHome(), seen);
				save.accept(contract);
			}
		}
		Contract.Tier tier = contract == null ? null : contract.getTier();
		if (tier != null)
		{
			s.planks = pack.count(tier.getPlank());
			if (pack.carries(ItemIds.PLANK_SACK))
			{
				s.planks += client.getVarbitValue(PLANK_SACK_VARBITS[tier.ordinal()]);
			}
		}
		s.steelBars = pack.count(Contract.STEEL_BAR);
		meter(contract, s.values, client.getSkillExperience(Skill.CONSTRUCTION));
		lastPlanks = s.planks;
		Home home = contract == null ? null : contract.getHome();
		s.atHome = home != null && home.contains(at.getX(), at.getY());
		if (contract != null && session.tick(client, now))
		{
			// A new session after a break: contracts from the last one would inflate its hourly rate.
			contractsBefore = contracts;
			pointsBefore = points;
		}

		Step step = Contract.next(contract, s);
		Ground ground = Ground.read(client, null, 0);
		Flight flight;
		int stage;
		switch (step.getTarget())
		{
			case CONTRACTOR:
			{
				stage = 0;
				NPC who = contractorNear(client);
				flight = new Flight(View.Activity.HOMES, step, null);
				if (who != null && ground != null)
				{
					flight.to(ground.to(who));
					flight.npc = who;
				}
				break;
			}
			case CLIENT:
			{
				stage = 4;
				NPC who = clientNear(npcs, home);
				Ground.Way<NPC> way = ground == null ? null : ground.to(who);
				if (who != null && way == null && ground != null)
				{
					Step climb = climb(home, ground, scene, home.getName() + " is on the other floor");
					if (climb != null)
					{
						step = climb;
					}
				}
				flight = new Flight(View.Activity.HOMES, step, null);
				if (step.getTarget() == Step.Target.LADDER)
				{
					flight.to(ground.nearest(ladders(scene, home), null));
				}
				else
				{
					flight.to(way);
					flight.npc = who;
				}
				if (who == null && !s.atHome)
				{
					flight.destination = new WorldPoint(home.getDoorX(), home.getDoorY(), 0);
				}
				break;
			}
			case ITEM:
				stage = 1;
				flight = new Flight(View.Activity.HOMES, step, null);
				break;
			case HOME:
			{
				stage = 2;
				int teleport = teleport(client, home.getCity());
				if (teleport > 0 && home.distanceTo(at.getX(), at.getY()) > 60)
				{
					step = step.withItems(teleport).withDetail(step.getDetail() + ". Your " + client.getItemDefinition(teleport).getName() + " is the quickest way");
				}
				flight = new Flight(View.Activity.HOMES, step, null);
				WorldPoint door = new WorldPoint(home.getDoorX(), home.getDoorY(), 0);
				flight.destination = door;
				if (ground != null && at.getPlane() == 0)
				{
					flight.route = ground.toTile(door);
				}
				break;
			}
			default:
			{
				stage = 3;
				List<TileObject> todo = new ArrayList<>();
				for (TileObject o : scene.get(hotspotIds(home)))
				{
					int i = home.indexOf(o.getId());
					if (i >= 0 && Contract.needsWork(s.values[i]))
					{
						todo.add(o);
					}
				}
				Ground.Way<TileObject> way = ground == null ? null : ground.nearest(todo, null);
				if (way != null)
				{
					int value = s.values[home.indexOf(way.thing.getId())];
					String name = name(client, way.thing);
					step = Step.of(Contract.verb(value), Contract.verb(value) + " the " + name, step.getDetail(), Step.Target.HOTSPOT);
				}
				else if (!todo.isEmpty() && ground != null)
				{
					Step climb = climb(home, ground, scene, "The rest of the work is on the other floor");
					if (climb != null)
					{
						step = climb;
						way = ground.nearest(ladders(scene, home), null);
					}
				}
				flight = new Flight(View.Activity.HOMES, step, null).to(way);
				for (TileObject o : todo)
				{
					if (o != flight.object)
					{
						flight.others.add(o);
					}
				}
				break;
			}
		}

		String place = home == null ? null : home.getName() + ", " + home.getCity().getName();
		View view = new View(true, View.Activity.HOMES, step, place, LOOP, stage);
		if (contract != null && Contract.known(s.values) && tier != null)
		{
			int planks = contract.planksNeeded(s.values);
			int steel = contract.steelNeeded(s.values);
			view.gauge(new View.Gauge(tier.getName() + " planks", Math.min(s.planks, Math.max(planks, s.planks)), 0, Math.max(planks, s.planks),
				s.planks >= planks ? "Enough for the rest of the job" : (planks - s.planks) + " short", s.planks >= planks ? Theme.GREEN : Theme.EMBER));
			if (steel > 0 || s.steelBars > 0)
			{
				view.gauge(new View.Gauge("Steel bars", s.steelBars, 0, Math.max(steel, s.steelBars),
					s.steelBars >= steel ? "Enough" : (steel - s.steelBars) + " short", s.steelBars >= steel ? Theme.GREEN : Theme.EMBER));
			}
		}
		if (contract != null && Contract.known(s.values))
		{
			view.lines("Furniture", (contract.remaining(s.values).size()) + " left", furniture(client, scene, home, s.values, flight.object));
		}
		if (session.begun())
		{
			view.stat(new View.Stat(String.valueOf(contracts - contractsBefore), "Contracts", session.perHour(contracts - contractsBefore, now), Theme.GOLD));
			view.stat(new View.Stat(String.valueOf(points - pointsBefore), "Points", "From contracts", Theme.TEAL));
			int xp = session.xp(client);
			view.stat(new View.Stat(Session.format(xp), "Con xp", session.perHour(xp, now), Theme.GREEN));
			view.stat(new View.Stat(session.elapsed(now), "Time", "On contracts", Theme.TEXT_MUTED));
		}
		Flight out = new Flight(View.Activity.HOMES, step, view);
		out.object = flight.object;
		out.npc = flight.npc;
		out.route = flight.route;
		out.destination = flight.destination;
		out.others.addAll(flight.others);
		return out;
	}

	/**
	 * What each tier costs you per experience point at today's prices, from your own finished
	 * contracts; null until one is finished or while prices are loading.
	 */
	View.PickCard costs(IntUnaryOperator price, int constructionLevel)
	{
		if (book.isEmpty() || price == null)
		{
			return null;
		}
		List<ContractBook.Row> rows = book.rank(price, constructionLevel);
		if (rows.isEmpty())
		{
			return null;
		}
		Contract.Tier current = contract != null && contract.getTier() != null ? contract.getTier() : Contract.Tier.forLevel(constructionLevel);
		return costCard(rows, current);
	}

	/** The ranking as the panel shows it. */
	static View.PickCard costCard(List<ContractBook.Row> rows, Contract.Tier current)
	{
		double cheapest = 0;
		for (ContractBook.Row r : rows)
		{
			if (r.isKnown() && r.getPerXp() > 0 && (cheapest == 0 || r.getPerXp() < cheapest))
			{
				cheapest = r.getPerXp();
			}
		}
		List<View.Pick> picks = new ArrayList<>();
		for (ContractBook.Row r : rows)
		{
			Contract.Tier t = r.getTier();
			if (!r.isKnown())
			{
				picks.add(new View.Pick(t.getName(), "", r.isUnlocked() ? "Finish one to learn what it costs" : "Needs Construction " + t.getLevel(),
					false, t == current, 0, false));
				continue;
			}
			ContractBook.Tally tally = r.getTally();
			String detail = Session.format(Math.round(tally.xpEach())) + " xp · " + compact(Math.round(r.getCoinsEach())) + " gp"
				+ (r.getXpPerHour() > 0 ? " · " + compact(Math.round(r.getXpPerHour())) + " xp/h" : "");
			double share = r.getPerXp() <= 0 ? 1 : cheapest / r.getPerXp();
			picks.add(new View.Pick(t.getName(), perXp(r.getPerXp()), detail, true, t == current, share, false));
		}
		String note = "A contract's planks and steel at today's prices, against the experience your own contracts gave."
			+ " Rates count the whole loop, contract to contract.";
		return new View.PickCard("What it costs", "coins an xp", note, picks);
	}

	/**
	 * How far the planks and steel bars you have go: in the bank (as last seen by the Pilot or Bank
	 * Steward), carried and in the plank sack. Null when no bank has been seen yet.
	 */
	View.Supply supply(BankStock stock, int constructionLevel, long now)
	{
		if (stock == null)
		{
			return null;
		}
		Contract.Tier tier = contract != null && contract.getTier() != null ? contract.getTier() : Contract.Tier.forLevel(constructionLevel);
		boolean sameTier = contract != null && contract.getTier() == tier;
		long planks = stock.count(tier.getPlank()) + (sameTier ? lastPlanks : 0);
		long steel = stock.count(Contract.STEEL_BAR);
		Supplies.Homes h = Supplies.homes(tier, planks, steel, book.tally(tier));
		List<View.Line> lines = new ArrayList<>();
		String plankName = tier.planks(2).substring(2);
		lines.add(new View.Line(Character.toUpperCase(plankName.charAt(0)) + plankName.substring(1), Session.format(planks),
			planks > 0 ? View.Line.Mark.TODO : View.Line.Mark.IDLE));
		lines.add(new View.Line("Steel bars", Session.format(steel), steel > 0 ? View.Line.Mark.TODO : View.Line.Mark.IDLE));
		String detail = h.getContracts() < 0 ? "Finish a contract and this counts the jobs they cover"
			: h.isSteelShort() ? "Steel bars run out first" : null;
		return new View.Supply(tier.getName(), lines, h.headline(), detail, h.isSteelShort() || h.getContracts() == 0, seenNote(stock, now));
	}

	/** Where and when the bank was seen: "Your bank as the Pilot saw it 12 minutes ago". */
	static String seenNote(BankStock stock, long now)
	{
		String who = stock.getSource() == BankStock.Source.BANK_STEWARD ? "as Codex Bank Steward saw it" : "as last seen";
		long minutes = stock.getSavedAt() <= 0 ? -1 : Math.max(0, (now - stock.getSavedAt()) / 60_000L);
		String when = minutes < 0 ? "" : minutes < 1 ? ", just now" : ", " + com.codex.minigamepilot.core.Goal.duration(minutes) + " ago";
		return "Your bank " + who + when + ", with what you carry.";
	}

	private static String perXp(double coins)
	{
		return String.format(Locale.ENGLISH, coins < 10 ? "%.2f gp" : "%.1f gp", coins);
	}

	private static String compact(long n)
	{
		return com.codex.minigamepilot.core.Figures.brief(n);
	}

	private Step climb(Home home, Ground ground, SceneIndex scene, String why)
	{
		if (ground.nearest(ladders(scene, home), null) == null)
		{
			return null;
		}
		return Step.of("Climb", "Take the ladder", why, Step.Target.LADDER);
	}

	private static List<TileObject> ladders(SceneIndex scene, Home home)
	{
		List<TileObject> out = new ArrayList<>();
		for (TileObject o : scene.get(home.getLadders()))
		{
			if (home.distanceTo(o.getWorldLocation().getX(), o.getWorldLocation().getY()) <= 2)
			{
				out.add(o);
			}
		}
		return out;
	}

	private static int[] hotspotIds(Home home)
	{
		int[] ids = new int[home.hotspotCount()];
		for (int i = 0; i < ids.length; i++)
		{
			ids[i] = home.hotspot(i).getObjectId();
		}
		return ids;
	}

	private List<View.Line> furniture(Client client, SceneIndex scene, Home home, int[] values, TileObject next)
	{
		Map<Integer, TileObject> seen = new HashMap<>();
		for (TileObject o : scene.get(hotspotIds(home)))
		{
			seen.put(o.getId(), o);
		}
		List<View.Line> lines = new ArrayList<>();
		for (int i = 0; i < home.hotspotCount(); i++)
		{
			Home.Hotspot h = home.hotspot(i);
			int v = values[i];
			if (v == 0)
			{
				continue;
			}
			TileObject o = seen.get(h.getObjectId());
			String name = o != null ? capital(name(client, o)) : objectNames.getOrDefault(h.getObjectId(), "Piece " + (i + 1));
			String cost = h.getKind().isSteel() ? "steel bar" : h.getKind().getAmount() + (h.getKind().getAmount() == 1 ? " plank" : " planks");
			View.Line.Mark mark = !Contract.needsWork(v) ? View.Line.Mark.DONE : o != null && o == next ? View.Line.Mark.NEXT : View.Line.Mark.TODO;
			String trailing = Contract.needsWork(v) ? Contract.verb(v) + ", " + cost : "Done";
			lines.add(new View.Line(name, trailing, mark));
		}
		return lines;
	}

	/** The furniture's own name, such as "wardrobe", remembered so the checklist keeps it out of sight. */
	private String name(Client client, TileObject o)
	{
		ObjectComposition def = client.getObjectDefinition(o.getId());
		if (def != null && def.getImpostorIds() != null && def.getImpostor() != null)
		{
			def = def.getImpostor();
		}
		String name = def == null ? null : def.getName();
		if (name == null || name.isEmpty() || "null".equals(name))
		{
			return objectNames.getOrDefault(o.getId(), "furniture");
		}
		objectNames.put(o.getId(), capital(name));
		return name.toLowerCase(Locale.ENGLISH);
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/** The best teleport carried or worn for a city, or -1. */
	private static int teleport(Client client, Home.City city)
	{
		String[] names = TELEPORTS.get(city);
		for (String want : names)
		{
			for (int container : new int[]{InventoryID.INV, InventoryID.WORN})
			{
				net.runelite.api.ItemContainer c = client.getItemContainer(container);
				if (c == null)
				{
					continue;
				}
				for (net.runelite.api.Item item : c.getItems())
				{
					if (item.getId() <= 0)
					{
						continue;
					}
					ItemComposition def = client.getItemDefinition(item.getId());
					if (def != null && def.getName() != null && def.getName().startsWith(want))
					{
						return item.getId();
					}
				}
			}
		}
		return -1;
	}

	private static NPC clientNear(Collection<NPC> npcs, Home home)
	{
		for (NPC n : npcs)
		{
			if (n != null && n.getName() != null && n.getName().equalsIgnoreCase(home.getName())
				&& home.distanceTo(n.getWorldLocation().getX(), n.getWorldLocation().getY()) <= 3)
			{
				return n;
			}
		}
		return null;
	}

	private static NPC contractorNear(Client client)
	{
		for (NPC n : client.getTopLevelWorldView().npcs())
		{
			if (n != null && n.getName() != null && Home.City.isContractor(n.getName()) && hasContractOption(n))
			{
				return n;
			}
		}
		return null;
	}

	private static boolean hasContractOption(NPC n)
	{
		if (n.getComposition() == null || n.getComposition().getActions() == null)
		{
			return false;
		}
		for (String a : n.getComposition().getActions())
		{
			if ("Contract".equalsIgnoreCase(a))
			{
				return true;
			}
		}
		return false;
	}
}

package com.codex.minigamepilot.pilot;

/**
 * The first ticks after logging in or hopping, while the inventory, skills and varbits arrive
 * from the game. The minigames are not read for a couple of ticks, and a little longer while the
 * inventory has not shown up, but never for good: an inventory that never arrives (an empty
 * pack, say) must not keep the Pilot, and its field notes, quiet for the rest of the login.
 */
public final class LoginSettle
{
	/** Ticks always waited after logging in; RuneLite's own XP tracker waits the same. */
	static final int GRACE = 2;
	/** The most ticks waited for the inventory before going on without it. */
	static final int MAX_WAIT = 10;

	/** Ticks since logging in, or -1 once settled. */
	private int ticks = -1;

	/** Logging in, or hopping: settle in again. */
	public void relog()
	{
		ticks = 0;
	}

	/**
	 * One tick logged in.
	 *
	 * @param inventoryArrived whether the game has sent the inventory yet
	 * @return true while still settling in, so this tick is not read
	 */
	public boolean tick(boolean inventoryArrived)
	{
		if (ticks < 0)
		{
			return false;
		}
		ticks++;
		if (ticks <= GRACE || !inventoryArrived && ticks < MAX_WAIT)
		{
			return true;
		}
		ticks = -1;
		return false;
	}
}

package com.codex.minigamepilot.pilot;

import com.codex.minigamepilot.core.ItemIds;
import com.codex.minigamepilot.core.MotherlodeCycle;
import com.codex.minigamepilot.core.Step;
import com.codex.minigamepilot.ui.Theme;
import com.codex.minigamepilot.ui.View;
import java.util.Collection;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

/** Flies the Motherlode Mine: which vein, when to deposit, when to empty the sack, and the way there. */
public final class MotherlodePilot
{
	private static final Set<Integer> REGIONS = Set.of(14679, 14680, 14681, 14935, 14936, 14937, 15191, 15192, 15193);
	static final int[] VEINS = {ObjectID.MOTHERLODE_ORE_SINGLE, ObjectID.MOTHERLODE_ORE_LEFT, ObjectID.MOTHERLODE_ORE_MIDDLE, ObjectID.MOTHERLODE_ORE_RIGHT};
	static final int[] SACKS = {ObjectID.MOTHERLODE_SACK, ObjectID.MOTHERLODE_SACK_EMPTY, ObjectID.MOTHERLODE_SACK_FULL};
	static final int[] ROCKFALLS = {ObjectID.MOTHERLODE_ROCKFALL_1, ObjectID.MOTHERLODE_ROCKFALL_2};
	static final int[] LADDERS = {
		ObjectID.MOTHERLODE_LADDER_BOTTOM, ObjectID.MOTHERLODE_LADDER_TOP, ObjectID.MOTHERLODE_LADDER_BOTTOM_ACTIVE,
		ObjectID.MOTHERLODE_LADDER_BOTTOM_INACTIVE, ObjectID.MOTHERLODE_LADDER_TOP_ACTIVE, ObjectID.MOTHERLODE_LADDER_TOP_INACTIVE
	};
	/** Steps a rockfall is worth: walking around it is better unless that is a long way. */
	private static final int ROCKFALL_COST = 8;
	/** Steps charged for a vein someone else is standing at. */
	private static final int CROWDED = 12;
	private static final String[] LOOP = {"Mine", "Hopper", "Sack", "Bank"};

	private final MotherlodeCycle cycle = new MotherlodeCycle();
	private final Session session = new Session(Skill.MINING);
	private int lastSack = -1;
	private int collected;
	private int sacks;
	/** Pay-dirt deposited before this session began, left out of its count. */
	private int depositedBefore;
	private final com.codex.minigamepilot.core.OreHaul haul = new com.codex.minigamepilot.core.OreHaul();
	/** Grand Exchange prices, or null when not set. */
	private java.util.function.IntUnaryOperator price;
	private boolean wasEmptying;
	/** This session's experience and ore worth as last shown, for its summary when you leave. */
	private int xpSeen;
	private long worthSeen;
	/** The last snapshot planned from, for the field notes. */
	Object lastState;

	/** A running count of what rounds produce, for the pace coach. */
	int units()
	{
		return cycle.getDeposited();
	}

	static boolean isWatched(int id)
	{
		return contains(VEINS, id) || contains(SACKS, id) || contains(ROCKFALLS, id) || contains(LADDERS, id)
			|| id == ObjectID.MOTHERLODE_HOPPER || id == ObjectID.MOTHERLODE_WHEEL_STRUT_BROKEN;
	}

	static boolean contains(int[] ids, int id)
	{
		for (int i : ids)
		{
			if (i == id)
			{
				return true;
			}
		}
		return false;
	}

	public static boolean inMine(Client client)
	{
		Player me = client.getLocalPlayer();
		return me != null && REGIONS.contains(me.getWorldLocation().getRegionID());
	}

	/** Called when leaving the mine, so pay-dirt in flight is not carried over into a later visit. */
	void left()
	{
		cycle.reset();
		lastSack = -1;
		haul.forget();
	}

	/** Another account logged in: the session and its counts start over on its first tick. */
	void newAccount()
	{
		session.startOver();
	}

	/** Logged in again or hopped: readings start afresh, pay-dirt in flight stays in flight. */
	void relogged()
	{
		cycle.relog();
		lastSack = -1;
		haul.forget();
	}

	/** Pay-dirt deposited this session. */
	private int deposited()
	{
		return Math.max(0, cycle.getDeposited() - depositedBefore);
	}

	void setPrice(java.util.function.IntUnaryOperator price)
	{
		this.price = price;
	}

	/** What this session came to, for when you leave the mine, or null when it was too short or idle. */
	com.codex.minigamepilot.core.Visit visit(long now)
	{
		if (!session.begun())
		{
			return null;
		}
		java.util.List<String> parts = new java.util.ArrayList<>();
		if (deposited() > 0)
		{
			parts.add(Session.format(deposited()) + " pay-dirt");
		}
		if (collected > 0)
		{
			parts.add(Session.format(collected) + " ore");
		}
		if (xpSeen > 0)
		{
			parts.add(Session.format(xpSeen) + " Mining xp");
		}
		if (worthSeen > 0)
		{
			parts.add("ore worth " + Session.format(worthSeen));
		}
		return com.codex.minigamepilot.core.Visit.of(now, session.activeMs(), parts);
	}

	/** This session's pace so far, as a reading for your best visit, or null while it is too short. */
	com.codex.minigamepilot.core.BestVisit pace(long now)
	{
		return com.codex.minigamepilot.core.BestVisit.of(session.startedAt(), now, session.activeMs(), deposited(), xpSeen);
	}

	/**
	 * Brief for the panel when the player is elsewhere.
	 *
	 * @param lastVisit the summary saved when you last left the mine, or null
	 * @param best your fastest visit, or null
	 */
	View.Brief brief(com.codex.minigamepilot.core.Visit lastVisit, com.codex.minigamepilot.core.BestVisit best, long now)
	{
		String status = lastVisit != null ? lastVisit.status(now)
			: session.begun() ? Session.format(deposited()) + " pay-dirt deposited this session" : null;
		return new View.Brief(View.Activity.MOTHERLODE, status,
			"Under Falador, through the Dwarven Mine or the Falador mining guild. Bring a pickaxe; a hammer helps.")
			.best(best == null ? null : best.status(UNIT, "Mining", lastVisit, now));
	}

	/** What the mine's pace is counted in. */
	static final String UNIT = "pay-dirt";

	Flight fly(Client client, SceneIndex scene, long now)
	{
		if (session.tick(client, now))
		{
			// A new session after a break: counts from the last one would inflate its hourly rates.
			collected = 0;
			sacks = 0;
			depositedBefore = cycle.getDeposited();
			haul.clear();
		}
		Pack pack = Pack.read(client);
		Collection<TileObject> rockfalls = scene.get(ROCKFALLS);
		Ground ground = Ground.read(client, rockfalls, ROCKFALL_COST);

		MotherlodeCycle.Snapshot s = new MotherlodeCycle.Snapshot();
		lastState = s;
		s.payDirt = pack.count(ItemIds.PAYDIRT);
		s.free = pack.free();
		s.loot = pack.count(ItemIds.MOTHERLODE_LOOT);
		s.sack = client.getVarbitValue(VarbitID.MOTHERLODE_SACK_TRANSMIT);
		s.capacity = client.getVarbitValue(VarbitID.MOTHERLODE_BIGGERSACK) == 1 ? 189 : 108;
		Collection<TileObject> struts = scene.get(ObjectID.MOTHERLODE_WHEEL_STRUT_BROKEN);
		s.brokenStruts = struts.size();
		s.hammer = pack.carries(ItemIds.HAMMER, ItemIds.IMCANDO_HAMMER) || pack.wears(ItemIds.IMCANDO_HAMMER_OFFHAND, ItemIds.IMCANDO_HAMMER);

		TileObject hopper = first(scene.get(ObjectID.MOTHERLODE_HOPPER));
		boolean nearHopper = hopper != null && client.getLocalPlayer().getWorldLocation().distanceTo(hopper.getWorldLocation()) <= 2;
		cycle.observe(s.payDirt, s.sack, nearHopper, s.brokenStruts >= 2);
		boolean paidOut = lastSack >= 0 && s.sack < lastSack;
		int drop = paidOut ? lastSack - s.sack : 0;
		collected += drop;
		lastSack = s.sack;
		int[] ores = new int[com.codex.minigamepilot.core.OreHaul.ORES.length];
		for (int i = 0; i < ores.length; i++)
		{
			ores[i] = pack.count(com.codex.minigamepilot.core.OreHaul.ORES[i]);
		}
		haul.observe(ores, pack.count(ItemIds.GOLDEN_NUGGET), drop, pack.carries(ItemIds.COAL_BAG_OPEN));

		Step step = cycle.next(s);
		if (wasEmptying && !cycle.isEmptying())
		{
			sacks++;
		}
		wasEmptying = cycle.isEmptying();

		Ground.Way<TileObject> way = null;
		if (ground != null)
		{
			switch (step.getTarget())
			{
				case VEIN:
					way = ground.nearest(scene.get(VEINS), v -> crowded(client, v) ? CROWDED : 0);
					break;
				case HOPPER:
					way = ground.to(hopper);
					break;
				case SACK:
					way = ground.nearest(scene.get(SACKS), null);
					break;
				case BANK:
					way = ground.nearest(scene.banks(), null);
					break;
				case STRUT:
					way = ground.nearest(struts, null);
					break;
				default:
					break;
			}
			if (way != null)
			{
				// A route through a rockfall means mining it is quicker than walking around.
				TileObject rock = Ground.crossed(way.scenePath, rockfalls);
				if (rock != null)
				{
					step = Step.of("Clear", "Mine the rockfall", "It blocks the quickest way to " + what(step.getTarget()), Step.Target.ROCKFALL);
					way = ground.to(rock);
				}
			}
			else if (step.getTarget() != Step.Target.NONE && !step.isWaiting())
			{
				Ground.Way<TileObject> ladder = ground.nearest(scene.get(LADDERS), null);
				if (ladder != null)
				{
					step = Step.of("Climb", "Climb the ladder", "The " + what(step.getTarget()) + " is on the other level", Step.Target.LADDER);
					way = ladder;
				}
			}
		}

		View view = new View(true, View.Activity.MOTHERLODE, step, level(client), LOOP, stage(step, cycle.isEmptying()));
		int room = cycle.room(s);
		view.gauge(new View.Gauge("Sack", s.sack, cycle.getInFlight(), s.capacity,
			room == 0 ? "Full: empty it into the bank" : "Room for " + room + " more", s.sack + cycle.getInFlight() >= s.capacity ? Theme.EMBER : Theme.GOLD));
		if (!cycle.isEmptying())
		{
			int load = cycle.loadSize(s);
			view.gauge(new View.Gauge("This load", s.payDirt, 0, Math.max(load, s.payDirt), load < s.free + s.payDirt ? "Sized to fill the sack" : "A full inventory", Theme.TEAL));
		}
		if (s.brokenStruts > 0)
		{
			view.gauge(new View.Gauge("Struts working", 2 - Math.min(2, s.brokenStruts), 0, 2,
				s.brokenStruts >= 2 ? "The wheel has stopped" : "One broken: the wheel still turns", s.brokenStruts >= 2 ? Theme.BLOOD : Theme.EMBER));
		}
		view.stat(new View.Stat(Session.format(deposited()), "Pay-dirt", session.perHour(deposited(), now), Theme.GOLD));
		view.stat(new View.Stat(Session.format(collected), "Ore", sacks + (sacks == 1 ? " sack emptied" : " sacks emptied"), Theme.TEAL));
		int xp = session.xp(client);
		xpSeen = xp;
		view.stat(new View.Stat(Session.format(xp), "Mining xp", session.perHour(xp, now), Theme.GREEN));
		view.stat(new View.Stat(session.elapsed(now), "Time", "In the mine", Theme.TEXT_MUTED));
		long worth = price == null ? 0 : haul.worth(price);
		worthSeen = worth;
		if (worth > 0)
		{
			String rate = session.perHour(worth, now);
			view.stat(new View.Stat(Session.format(worth), "Ore worth", rate.isEmpty() ? "At GE prices" : rate, Theme.GOLD_BRIGHT));
		}

		Flight flight = new Flight(View.Activity.MOTHERLODE, step, view).to(way);
		if (step.getTarget() == Step.Target.VEIN && way != null)
		{
			// The next vein along, quietly, so the eye already knows where to go after this one.
			Ground.Way<TileObject> next = ground.nearest(scene.get(VEINS), v -> v == flight.object ? 1000 : crowded(client, v) ? CROWDED : 0);
			if (next != null && next.thing != flight.object)
			{
				flight.others.add(next.thing);
			}
		}
		return flight;
	}

	private static String what(Step.Target t)
	{
		switch (t)
		{
			case VEIN:
				return "the next vein";
			case HOPPER:
				return "hopper";
			case SACK:
				return "sack";
			case BANK:
				return "bank";
			case STRUT:
				return "broken strut";
			default:
				return "next stop";
		}
	}

	private static int stage(Step step, boolean emptying)
	{
		switch (step.getTarget())
		{
			case VEIN:
			case ROCKFALL:
				return 0;
			case HOPPER:
			case STRUT:
				return emptying ? 2 : 1;
			case SACK:
				return 2;
			case BANK:
				return 3;
			default:
				return emptying ? 2 : 0;
		}
	}

	private static String level(Client client)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		// The upper level sits on the same floor as the lower, only higher; the core plugin tells them apart by tile height.
		int height = net.runelite.api.Perspective.getTileHeight(client, me.getLocalLocation(), 0);
		return height < -490 ? "Upper level" : "Lower level";
	}

	private static boolean crowded(Client client, TileObject vein)
	{
		WorldPoint at = vein.getWorldLocation();
		for (Player p : client.getTopLevelWorldView().players())
		{
			if (p != null && p != client.getLocalPlayer() && p.getWorldLocation().distanceTo(at) <= 1)
			{
				return true;
			}
		}
		return false;
	}

	private static TileObject first(Collection<TileObject> objects)
	{
		return objects.isEmpty() ? null : objects.iterator().next();
	}
}

package com.codex.minigamepilot.pilot;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/** What the player carries and wears, read once a tick. */
final class Pack
{
	private final Item[] inventory;
	private final Item[] worn;
	private final Item[] bank;

	private Pack(Item[] inventory, Item[] worn, Item[] bank)
	{
		this.inventory = inventory;
		this.worn = worn;
		this.bank = bank;
	}

	static Pack read(Client client)
	{
		return new Pack(items(client.getItemContainer(InventoryID.INV)), items(client.getItemContainer(InventoryID.WORN)),
			items(client.getItemContainer(InventoryID.BANK)));
	}

	private static Item[] items(ItemContainer c)
	{
		return c == null ? null : c.getItems();
	}

	/** How many of these items are carried, stacks counted in full. */
	int count(int... ids)
	{
		return count(inventory, ids);
	}

	boolean carries(int... ids)
	{
		return count(ids) > 0;
	}

	boolean wears(int... ids)
	{
		return count(worn, ids) > 0;
	}

	/** How many the bank held when last open, or -1 when it has not been seen this session. */
	int banked(int... ids)
	{
		return bank == null ? -1 : count(bank, ids);
	}

	/** Empty inventory slots. */
	int free()
	{
		if (inventory == null)
		{
			return 28;
		}
		int used = 0;
		for (Item i : inventory)
		{
			if (i.getId() > 0 && i.getQuantity() > 0)
			{
				used++;
			}
		}
		return Math.max(0, 28 - used);
	}

	/** Inventory slots holding these items. */
	int slots(int... ids)
	{
		if (inventory == null)
		{
			return 0;
		}
		int n = 0;
		for (Item i : inventory)
		{
			for (int id : ids)
			{
				if (i.getId() == id && i.getQuantity() > 0)
				{
					n++;
					break;
				}
			}
		}
		return n;
	}

	private static int count(Item[] items, int... ids)
	{
		if (items == null)
		{
			return 0;
		}
		int n = 0;
		for (Item i : items)
		{
			for (int id : ids)
			{
				if (i.getId() == id)
				{
					n += i.getQuantity();
					break;
				}
			}
		}
		return n;
	}
}

package com.codex.minigamepilot.pilot;

import com.codex.minigamepilot.core.BankStock;
import com.codex.minigamepilot.core.Bar;
import com.codex.minigamepilot.core.BestVisit;
import com.codex.minigamepilot.core.Contract;
import com.codex.minigamepilot.core.Pace;
import com.codex.minigamepilot.core.Visit;
import com.codex.minigamepilot.ui.View;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Scene;
import net.runelite.api.Tile;

/** The three pilots, the scene they share, and which one is flying this tick. */
public final class Pilots
{
	private final Client client;
	private final SceneIndex scene;
	private final MotherlodePilot motherlode = new MotherlodePilot();
	private final FurnacePilot furnace = new FurnacePilot();
	private final HomesPilot homes;
	private final Coach coach;
	private final Recorder recorder;
	private final IntUnaryOperator price;
	private final Supplier<BankStock> stock;
	private View.Activity last = View.Activity.NONE;
	private final Function<String, String> load;
	private final BiConsumer<String, String> saveKey;
	/** A summary of the visit just ended, for the chat, or null. */
	private String note;
	/** The visit last said in the chat for each minigame, so stepping out again says nothing new. */
	private final java.util.Map<View.Activity, Visit> said = new java.util.EnumMap<>(View.Activity.class);
	/** Where the summary of each minigame's last visit is kept: this and the minigame's name. */
	static final String VISIT_KEY = "visit.";

	/**
	 * @param loadBests the pace coach's saved bests for a minigame
	 * @param saveBests saves them again when a round beats one
	 * @param load reads a key of this account's saved settings
	 * @param saveKey writes one
	 * @param stock the supplies in your bank as last seen, or null when no bank has been seen
	 */
	public Pilots(Client client, Contract saved, Consumer<Contract> save, FieldNotes notes,
		Function<View.Activity, String> loadBests, BiConsumer<View.Activity, String> saveBests, IntUnaryOperator price,
		Function<String, String> load, BiConsumer<String, String> saveKey, Supplier<BankStock> stock)
	{
		this.client = client;
		this.load = load;
		this.saveKey = saveKey;
		this.price = price;
		this.stock = stock;
		motherlode.setPrice(price);
		this.coach = new Coach(loadBests, saveBests);
		this.recorder = new Recorder(notes);
		this.scene = new SceneIndex(client, id -> MotherlodePilot.isWatched(id) || FurnacePilot.isWatched(id) || HomesPilot.isWatched(id));
		this.homes = new HomesPilot(saved, save, load, saveKey);
	}

	public SceneIndex scene()
	{
		return scene;
	}

	public void clearScene()
	{
		scene.clear();
	}

	/** The last account that was logged in, so logging out and back in is not a new one. */
	private String account;

	/**
	 * The save profile changed. It changes to none on every logout and back on login, so only a
	 * login to a different account than the last starts every session over: back on the same
	 * account soon, the session goes on as it always has.
	 *
	 * @param profile the profile now, or null while logged out
	 */
	public void profile(String profile)
	{
		if (switched(account, profile))
		{
			motherlode.newAccount();
			furnace.newAccount();
			homes.newAccount();
			said.clear();
			unsaid.clear();
		}
		if (profile != null)
		{
			account = profile;
		}
	}

	/** Whether a login to {@code profile} is another account than {@code last}, the last one logged in. */
	static boolean switched(String last, String profile)
	{
		return profile != null && last != null && !profile.equals(last);
	}

	public void loadContract(Contract saved)
	{
		homes.load(saved);
		homes.reloadBook();
		coach.reload();
	}

	public void chat(String type, String message)
	{
		recorder.chat(type, message);
		furnace.coalBag.chat(message);
		homes.chat(message);
	}

	/** @param bankCoal coal in the open bank, or -1 when the bank is closed */
	public void coalBagOption(String option, int inventoryCoal, int bankCoal)
	{
		furnace.coalBag.option(option, inventoryCoal, bankCoal);
	}

	public void varbit(int id, int value)
	{
		recorder.varbit(id, value);
	}

	public void click(String option, String target, int id, String action, int itemId)
	{
		recorder.click(option, target, id, action, itemId);
	}

	public void inventory(Map<Integer, Integer> changes)
	{
		recorder.inventory(changes);
	}

	/** Indexes what is already loaded, for when the plugin starts while logged in. */
	public void rescan()
	{
		scene.clear();
		Scene s = client.getTopLevelWorldView().getScene();
		Tile[][][] tiles = s.getTiles();
		for (Tile[][] plane : tiles)
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null)
					{
						continue;
					}
					for (GameObject o : tile.getGameObjects())
					{
						scene.add(o);
					}
					scene.add(tile.getWallObject());
					scene.add(tile.getDecorativeObject());
				}
			}
		}
	}

	/** Works out this tick's guidance. Only ever reads the game. */
	public Flight fly(boolean useMotherlode, boolean useFurnace, boolean useHomes, Bar bar, int cofferLow, long now)
	{
		View.Activity activity;
		Flight flight;
		Object state = null;
		int units = 0;
		String kind = null;
		if (useMotherlode && MotherlodePilot.inMine(client))
		{
			activity = View.Activity.MOTHERLODE;
			flight = motherlode.fly(client, scene, now);
			state = motherlode.lastState;
			units = motherlode.units();
		}
		else if (useFurnace && FurnacePilot.atFurnace(client))
		{
			activity = View.Activity.FURNACE;
			flight = furnace.fly(client, scene, bar, cofferLow, now);
			state = furnace.lastState;
			units = furnace.units();
		}
		else if (useHomes && homes.active(client, now))
		{
			activity = View.Activity.HOMES;
			List<NPC> npcs = new ArrayList<>();
			for (NPC n : client.getTopLevelWorldView().npcs())
			{
				npcs.add(n);
			}
			flight = homes.fly(client, scene, npcs, now);
			state = homes.lastState;
			units = homes.units();
			kind = homes.kindHint();
		}
		else
		{
			activity = View.Activity.NONE;
			flight = Flight.idle(idleView());
		}
		if (activity != last)
		{
			if (last == View.Activity.MOTHERLODE)
			{
				keep(last, motherlode.visit(now), motherlode.pace(now), true);
				motherlode.left();
			}
			else if (last == View.Activity.FURNACE)
			{
				keep(last, furnace.visit(now), furnace.pace(now), true);
				furnace.left();
			}
			last = activity;
		}
		homes.settle(client.getSkillExperience(net.runelite.api.Skill.CONSTRUCTION));
		Pace.Round round = coach.tick(client, flight, units, kind);
		coach.decorate(flight.view, activity);
		BankStock banked = stock == null ? null : stock.get();
		if (activity == View.Activity.FURNACE)
		{
			double tripSeconds = typicalTicks(coach.pace(View.Activity.FURNACE)) * 0.6;
			if (price != null)
			{
				flight.view.pick(furnace.pick(client, price, tripSeconds));
			}
			flight.view.supply(furnace.supply(banked, tripSeconds, now));
		}
		else if (activity == View.Activity.HOMES)
		{
			int level = client.getRealSkillLevel(net.runelite.api.Skill.CONSTRUCTION);
			flight.view.pick(homes.costs(price, level));
			flight.view.supply(homes.supply(banked, level, now));
		}
		recorder.tick(client, scene, flight, state, round);
		return flight;
	}

	/**
	 * Logged out or hopping. What you carry, your experience and the minigames' varbits arrive
	 * again over the first ticks after, so nothing seen before is a base for change: a full
	 * pack read as empty for a tick, then full, is no haul. The visit under way is summed up
	 * quietly; its session goes on if you are back soon.
	 */
	public void relogged(long now)
	{
		if (last == View.Activity.MOTHERLODE)
		{
			keep(last, motherlode.visit(now), motherlode.pace(now), false);
		}
		else if (last == View.Activity.FURNACE)
		{
			keep(last, furnace.visit(now), furnace.pace(now), false);
		}
		motherlode.relogged();
		furnace.relogged();
		coach.left();
		last = View.Activity.NONE;
	}

	/**
	 * Saves a visit's summary and weighs its pace against your best visit, and holds both for
	 * the chat when it was walked out of. Package-private for tests.
	 */
	void keep(View.Activity activity, Visit visit, BestVisit pace, boolean say)
	{
		if (visit == null)
		{
			return;
		}
		if (saveKey != null)
		{
			saveKey.accept(VISIT_KEY + activity.name(), visit.encode());
		}
		String beat = null;
		String unit = activity == View.Activity.FURNACE ? FurnacePilot.UNIT : MotherlodePilot.UNIT;
		BestVisit held = best(activity);
		BestVisit.Outcome outcome = BestVisit.judge(held, pace);
		if (outcome != BestVisit.Outcome.KEPT && saveKey != null)
		{
			saveKey.accept(BEST_KEY + activity.name(), pace.encode());
			if (outcome == BestVisit.Outcome.BEATEN)
			{
				if (say)
				{
					beat = pace.beat(held, unit);
				}
				else
				{
					// Beaten at a hop or logout, where nothing is said: once the session goes on,
					// its later readings only weigh against its own, so keep what it beat.
					unsaid.put(activity, held);
				}
			}
		}
		if (say)
		{
			BestVisit from = unsaid.remove(activity);
			BestVisit record = beat == null && from != null ? best(activity) : null;
			if (record != null && record.sameSession(pace))
			{
				beat = record.beat(from, unit);
			}
		}
		// A session carries on when you step out and back in, so leaving again with nothing more
		// done would say the same counts twice.
		if (say && !visit.sameCounts(said.get(activity)))
		{
			note = activity.getTitle() + ", " + visit.line() + (beat == null ? "" : " " + beat);
			said.put(activity, visit);
		}
	}

	/** The other session's record a visit beat while nothing could be said, to say as it is walked out of. */
	private final java.util.Map<View.Activity, BestVisit> unsaid = new java.util.EnumMap<>(View.Activity.class);

	/** Where each minigame's fastest visit is kept: this and the minigame's name. */
	static final String BEST_KEY = "best.";

	/** Your fastest visit to a minigame, or null. */
	private BestVisit best(View.Activity activity)
	{
		return load == null ? null : BestVisit.decode(load.apply(BEST_KEY + activity.name()));
	}

	/** The summary of a visit just walked out of, once, or null. */
	public String takeNote()
	{
		String n = note;
		note = null;
		return n;
	}

	/** The summary saved when a minigame was last left, or null. */
	private Visit lastVisit(View.Activity activity)
	{
		return load == null ? null : Visit.decode(load.apply(VISIT_KEY + activity.name()));
	}

	/** The median of this session's timed rounds, of any kind, or 0 before there are three. */
	static int typicalTicks(Pace pace)
	{
		List<Integer> t = new ArrayList<>();
		for (Pace.Round r : pace.rounds())
		{
			if (!r.hadBreak)
			{
				t.add(r.ticks);
			}
		}
		if (t.size() < 3)
		{
			return 0;
		}
		java.util.Collections.sort(t);
		return t.get(t.size() / 2);
	}

	/** The panel away from the minigames: each one, and what is waiting there. */
	public View idleView()
	{
		View v = new View(true, View.Activity.NONE, null, null, null, -1);
		v.brief(homes.brief(stock == null ? null : stock.get(), client.getRealSkillLevel(net.runelite.api.Skill.CONSTRUCTION)));
		long now = System.currentTimeMillis();
		v.brief(motherlode.brief(lastVisit(View.Activity.MOTHERLODE), best(View.Activity.MOTHERLODE), now));
		v.brief(furnace.brief(lastVisit(View.Activity.FURNACE), best(View.Activity.FURNACE), now));
		return v;
	}
}

package com.codex.minigamepilot.pilot;

import com.codex.minigamepilot.core.Pace;
import com.codex.minigamepilot.core.Step;
import com.codex.minigamepilot.ui.View;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

/**
 * Decides what goes in the field notes. Only changes are written: a new step, a target that could
 * not be found, a planner snapshot that differs from the last, a varbit or message while in a
 * minigame, a click, a finished round, and every so often the objects and characters around you
 * that the Pilot has not noted yet, each marked with whether the Pilot was tracking it. Away from
 * the minigames, only where you are, once a minute.
 */
final class Recorder
{
	/** Ticks between looks around, about a minute. */
	private static final int SURVEY_EVERY = 100;
	/** How far around you a look reaches, in tiles. */
	private static final int SURVEY_RANGE = 16;
	private static final int SURVEY_CAP = 300;

	private final FieldNotes notes;
	private View.Activity activity = View.Activity.NONE;
	private String lastStep;
	private String lastMiss;
	private String lastState;
	private int sinceSurvey = SURVEY_EVERY;
	private final Set<String> surveyed = new HashSet<>();

	Recorder(FieldNotes notes)
	{
		this.notes = notes;
	}

	boolean on()
	{
		return notes.isOpen();
	}

	View.Activity activity()
	{
		return activity;
	}

	void tick(Client client, SceneIndex scene, Flight flight, Object state, Pace.Round round)
	{
		if (!on())
		{
			return;
		}
		Player me = client.getLocalPlayer();
		WorldPoint at = me == null ? null : me.getWorldLocation();
		if (flight.activity != activity)
		{
			JsonObject b = new JsonObject();
			b.addProperty("from", activity.name());
			b.addProperty("to", flight.activity.name());
			b.add("at", point(at));
			if (at != null)
			{
				b.addProperty("region", at.getRegionID());
			}
			notes.note("activity", b);
			activity = flight.activity;
			lastStep = null;
			lastMiss = null;
			lastState = null;
			surveyed.clear();
			sinceSurvey = SURVEY_EVERY;
		}
		if (activity == View.Activity.NONE)
		{
			// Away from the minigames, a line a minute saying where you are, so a minigame the
			// Pilot failed to recognise still shows up in the notes.
			if (++sinceSurvey >= SURVEY_EVERY && at != null)
			{
				sinceSurvey = 0;
				JsonObject b = new JsonObject();
				b.add("at", point(at));
				b.addProperty("region", at.getRegionID());
				notes.note("where", b);
			}
			return;
		}

		Step step = flight.step;
		if (step != null)
		{
			String key = step.getVerb() + "|" + step.getTitle() + "|" + step.getTarget() + "|" + flight.view.loopAt()
				+ "|" + (flight.object == null ? "" : flight.object.getWorldLocation())
				+ "|" + (flight.npc == null ? "" : flight.npc.getIndex());
			if (!key.equals(lastStep))
			{
				lastStep = key;
				JsonObject b = new JsonObject();
				b.addProperty("verb", step.getVerb());
				b.addProperty("title", step.getTitle());
				b.addProperty("detail", step.getDetail());
				b.addProperty("target", step.getTarget().name());
				b.addProperty("waiting", step.isWaiting());
				b.addProperty("stage", flight.view.loopAt());
				b.add("at", point(at));
				if (flight.object != null)
				{
					JsonObject o = new JsonObject();
					o.addProperty("id", flight.object.getId());
					o.add("at", point(flight.object.getWorldLocation()));
					b.add("object", o);
				}
				if (flight.npc != null)
				{
					JsonObject n = new JsonObject();
					n.addProperty("id", flight.npc.getId());
					n.addProperty("name", flight.npc.getName());
					n.add("at", point(flight.npc.getWorldLocation()));
					b.add("npc", n);
				}
				b.addProperty("route", flight.route == null ? 0 : flight.route.size());
				if (flight.destination != null)
				{
					b.add("destination", point(flight.destination));
				}
				JsonArray items = new JsonArray();
				for (int id : step.getItems())
				{
					items.add(id);
				}
				if (items.size() > 0)
				{
					b.add("items", items);
				}
				notes.note("step", b);
			}

			// A step about something in the world that the Pilot could not find to light up.
			boolean worldTarget = step.getTarget() != Step.Target.NONE && step.getTarget() != Step.Target.ITEM;
			String miss = worldTarget && flight.object == null && flight.npc == null && flight.destination == null
				? step.getTarget() + "|" + step.getTitle() : null;
			if (!Objects.equals(miss, lastMiss))
			{
				lastMiss = miss;
				if (miss != null)
				{
					JsonObject b = new JsonObject();
					b.addProperty("target", step.getTarget().name());
					b.addProperty("title", step.getTitle());
					b.add("at", point(at));
					notes.note("miss", b);
				}
			}
		}

		if (state != null)
		{
			JsonObject tree = notes.tree(state);
			String text = tree.toString();
			if (!text.equals(lastState))
			{
				lastState = text;
				tree.addProperty("of", state.getClass().getName().replaceAll(".*\\.", ""));
				notes.note("state", tree);
			}
		}

		if (round != null)
		{
			notes.note("round", notes.tree(round));
		}

		if (++sinceSurvey >= SURVEY_EVERY && at != null)
		{
			sinceSurvey = 0;
			survey(client, scene, at);
		}
	}

	void varbit(int id, int value)
	{
		if (on() && activity != View.Activity.NONE && id >= 0)
		{
			JsonObject b = new JsonObject();
			b.addProperty("id", id);
			b.addProperty("v", value);
			notes.note("varbit", b);
		}
	}

	void chat(String type, String message)
	{
		if (on() && activity != View.Activity.NONE)
		{
			JsonObject b = new JsonObject();
			b.addProperty("type", type);
			b.addProperty("text", message);
			notes.note("chat", b);
		}
	}

	void click(String option, String target, int id, String action, int itemId)
	{
		if (on() && activity != View.Activity.NONE)
		{
			JsonObject b = new JsonObject();
			b.addProperty("option", option);
			b.addProperty("target", target);
			b.addProperty("id", id);
			b.addProperty("action", action);
			if (itemId > 0)
			{
				b.addProperty("item", itemId);
			}
			notes.note("click", b);
		}
	}

	void inventory(Map<Integer, Integer> changes)
	{
		if (on() && activity != View.Activity.NONE && !changes.isEmpty())
		{
			JsonObject b = new JsonObject();
			JsonObject c = new JsonObject();
			changes.forEach((id, n) -> c.addProperty(String.valueOf(id), n));
			b.add("changes", c);
			notes.note("inventory", b);
		}
	}

	/** Notes objects and characters nearby that have not been noted yet this visit. */
	private void survey(Client client, SceneIndex scene, WorldPoint at)
	{
		JsonArray objects = new JsonArray();
		Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
		int plane = client.getTopLevelWorldView().getPlane();
		if (plane >= 0 && plane < tiles.length)
		{
			for (Tile[] row : tiles[plane])
			{
				for (Tile tile : row)
				{
					if (tile == null || objects.size() >= SURVEY_CAP)
					{
						continue;
					}
					if (tile.getWorldLocation().distanceTo(at) > SURVEY_RANGE)
					{
						continue;
					}
					for (GameObject o : tile.getGameObjects())
					{
						object(client, scene, o, objects);
					}
					object(client, scene, tile.getWallObject(), objects);
					object(client, scene, tile.getDecorativeObject(), objects);
					object(client, scene, tile.getGroundObject(), objects);
				}
			}
		}
		JsonArray npcs = new JsonArray();
		for (NPC n : client.getTopLevelWorldView().npcs())
		{
			if (n == null || n.getName() == null || n.getWorldLocation().distanceTo(at) > SURVEY_RANGE)
			{
				continue;
			}
			String key = "n" + n.getId() + "@" + n.getIndex();
			if (surveyed.add(key))
			{
				JsonObject j = new JsonObject();
				j.addProperty("id", n.getId());
				j.addProperty("name", n.getName());
				j.add("at", point(n.getWorldLocation()));
				npcs.add(j);
			}
		}
		if (objects.size() == 0 && npcs.size() == 0)
		{
			return;
		}
		JsonObject b = new JsonObject();
		b.add("at", point(at));
		b.add("objects", objects);
		b.add("npcs", npcs);
		notes.note("survey", b);
	}

	private void object(Client client, SceneIndex scene, TileObject o, JsonArray into)
	{
		if (o == null || into.size() >= SURVEY_CAP)
		{
			return;
		}
		WorldPoint where = o.getWorldLocation();
		String key = o.getId() + "@" + where;
		if (surveyed.contains(key))
		{
			return;
		}
		ObjectComposition def = client.getObjectDefinition(o.getId());
		if (def == null)
		{
			return;
		}
		int shown = o.getId();
		if (def.getImpostorIds() != null)
		{
			ObjectComposition now = def.getImpostor();
			if (now != null)
			{
				def = now;
				shown = now.getId();
			}
		}
		String name = def.getName();
		String[] actions = def.getActions();
		boolean any = false;
		if (actions != null)
		{
			for (String a : actions)
			{
				any |= a != null;
			}
		}
		if (name == null || "null".equals(name) || !any)
		{
			return;
		}
		surveyed.add(key);
		JsonObject j = new JsonObject();
		j.addProperty("id", o.getId());
		if (shown != o.getId())
		{
			j.addProperty("shows", shown);
		}
		j.addProperty("name", name);
		JsonArray acts = new JsonArray();
		for (String a : actions)
		{
			if (a != null)
			{
				acts.add(a);
			}
		}
		j.add("actions", acts);
		j.add("at", point(where));
		j.addProperty("tracked", scene.knows(o));
		into.add(j);
	}

	private static JsonArray point(WorldPoint p)
	{
		JsonArray a = new JsonArray();
		if (p != null)
		{
			a.add(p.getX());
			a.add(p.getY());
			a.add(p.getPlane());
		}
		return a;
	}
}

package com.codex.minigamepilot.pilot;

import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;
import net.runelite.api.Client;
import net.runelite.api.ObjectComposition;
import net.runelite.api.TileObject;

/**
 * The objects in the loaded scene that a pilot cares about, kept up to date from the game's
 * spawn and despawn events so nothing has to sweep the scene every tick. Banks are found by
 * name, since every bank in the game has its own object id.
 */
public final class SceneIndex
{
	private static final Set<String> BANK_NAMES = new HashSet<>(Arrays.asList(
		"bank chest", "bank booth", "bank deposit box"));

	private final Client client;
	private final IntPredicate watched;
	private final Map<Integer, Set<TileObject>> byId = new HashMap<>();
	private final Set<TileObject> banks = new LinkedHashSet<>();
	/** Whether each object id is a bank, worked out once: a region load spawns thousands of objects. */
	private final Map<Integer, Boolean> bankIds = new HashMap<>();

	public SceneIndex(Client client, IntPredicate watched)
	{
		this.client = client;
		this.watched = watched;
	}

	/** Call from the client thread when an object appears. */
	public void add(TileObject o)
	{
		if (o == null)
		{
			return;
		}
		int id = o.getId();
		if (watched.test(id))
		{
			byId.computeIfAbsent(id, k -> new LinkedHashSet<>()).add(o);
		}
		if (isBank(id))
		{
			banks.add(o);
		}
	}

	public void remove(TileObject o)
	{
		if (o == null)
		{
			return;
		}
		Set<TileObject> set = byId.get(o.getId());
		if (set != null)
		{
			set.remove(o);
		}
		banks.remove(o);
	}

	public void clear()
	{
		byId.clear();
		banks.clear();
	}

	public Collection<TileObject> get(int id)
	{
		Set<TileObject> set = byId.get(id);
		return set == null ? Collections.emptySet() : set;
	}

	public Set<TileObject> get(int... ids)
	{
		Set<TileObject> out = new LinkedHashSet<>();
		for (int id : ids)
		{
			out.addAll(get(id));
		}
		return out;
	}

	/** Whether this very object is indexed, so the field notes can show what the Pilot missed. */
	public boolean knows(TileObject o)
	{
		Set<TileObject> set = byId.get(o.getId());
		return set != null && set.contains(o) || banks.contains(o);
	}

	public Set<TileObject> banks()
	{
		return banks;
	}

	private boolean isBank(int id)
	{
		return bankIds.computeIfAbsent(id, this::lookUpBank);
	}

	private boolean lookUpBank(int id)
	{
		ObjectComposition def = client.getObjectDefinition(id);
		if (def == null)
		{
			return false;
		}
		if (def.getImpostorIds() != null)
		{
			ObjectComposition now = def.getImpostor();
			if (now != null)
			{
				def = now;
			}
		}
		String name = def.getName();
		return name != null && BANK_NAMES.contains(name.toLowerCase());
	}
}

package com.codex.minigamepilot.pilot;

import net.runelite.api.Client;
import net.runelite.api.Skill;

/** A minigame session: when it began, experience in its skill, and per-hour pace. */
final class Session
{
	private final Skill skill;
	private long started;
	private int startXp = -1;
	private long last;
	/** Set when another account logs in: its first tick starts the session over. */
	private boolean startOver;

	Session(Skill skill)
	{
		this.skill = skill;
	}

	/** A break longer than this starts a new session. */
	static final long BREAK_MS = 30 * 60_000L;

	/**
	 * Starts the clock on the first tick in the minigame, and again after a long break.
	 *
	 * @return true when a session already under way was started over after a break, so the
	 *     counts kept alongside it should start over too
	 */
	boolean tick(Client client, long now)
	{
		// Every account has some Hitpoints experience: none at all means the skills have not
		// arrived yet (just logged in), and a start taken then would count your whole total.
		return tick(client.getSkillExperience(skill), client.getSkillExperience(Skill.HITPOINTS) > 0, now);
	}

	/**
	 * @param xp experience in the session's skill now
	 * @param loaded whether the skills have arrived from the game yet
	 */
	boolean tick(int xp, boolean loaded, long now)
	{
		boolean restart = restarts(started, last, now) || startOver && started != 0;
		startOver = false;
		if (started == 0 || restart)
		{
			started = now;
			startXp = -1;
		}
		if (startXp < 0 && loaded)
		{
			startXp = xp;
		}
		last = now;
		return restart;
	}

	/** Whether a session begun at {@code started}, last seen at {@code last}, starts over now. */
	static boolean restarts(long started, long last, long now)
	{
		return started != 0 && now - last > BREAK_MS;
	}

	/** Whether a session is under way; not once another account has logged in, until its first tick. */
	boolean begun()
	{
		return started > 0 && !startOver;
	}

	/**
	 * Another account has logged in. A session otherwise carries on through a short logout, and
	 * would give the new account the last one's counts, hourly pace and best visit.
	 */
	void startOver()
	{
		startOver = true;
	}

	/** When this session began, or 0 before it has; a new one after a break begins again. */
	long startedAt()
	{
		return startOver ? 0 : started;
	}

	/** How long the session has run, to its last tick. */
	long activeMs()
	{
		return started == 0 ? 0 : Math.max(0, last - started);
	}

	int xp(Client client)
	{
		return xp(client.getSkillExperience(skill));
	}

	/** Experience gained this session, from the skill's experience now; 0 while it is not loaded. */
	int xp(int now)
	{
		return startXp < 0 || now <= 0 ? 0 : Math.max(0, now - startXp);
	}

	/** A count as an hourly pace, once there has been enough time to make it mean something. */
	String perHour(long count, long now)
	{
		long ms = now - started;
		if (started == 0 || ms < 60_000L)
		{
			return "";
		}
		return format(Math.round(count * 3_600_000d / ms)) + " an hour";
	}

	String elapsed(long now)
	{
		long minutes = started == 0 ? 0 : (now - started) / 60_000L;
		return minutes < 60 ? minutes + "m" : (minutes / 60) + "h " + (minutes % 60) + "m";
	}

	/** A count written as every card writes it: "68,040", "142k", "1.2M". */
	static String format(long n)
	{
		return com.codex.minigamepilot.core.Figures.count(n);
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.minigamepilot.ui;

import com.codex.minigamepilot.core.Figures;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * A label, a figure and an engraved bar. The solid part is what is there now; a hatched part
 * after it is what is on its way, such as pay-dirt still washing through the wheel.
 */
class GaugeBar extends JComponent
{
	private final View.Gauge gauge;

	GaugeBar(View.Gauge gauge)
	{
		this.gauge = gauge;
		setOpaque(false);
		setPreferredSize(new Dimension(10, gauge.note == null || gauge.note.isEmpty() ? 30 : 42));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		String figure = gauge.max > 0 ? Figures.pair(gauge.value, gauge.max) : Figures.brief(gauge.value);
		if (gauge.coming > 0)
		{
			figure = "+" + gauge.coming + "  " + figure;
		}
		Ui.shadowed(g, gauge.label.toUpperCase(), 0, 11, Theme.TEXT_MUTED);
		Ui.shadowed(g, figure, w - fm.stringWidth(figure), 11, gauge.tone);

		int by = 16;
		int bh = 9;
		RoundRectangle2D track = new RoundRectangle2D.Float(0.5f, by + 0.5f, w - 1, bh, bh, bh);
		g.setPaint(new GradientPaint(0, by, Theme.INK_DEEP, 0, by + bh, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(track);

		double max = Math.max(1, gauge.max > 0 ? gauge.max : gauge.value + gauge.coming);
		int fill = (int) Math.round((w - 2) * Math.min(1, gauge.value / max));
		int coming = (int) Math.round((w - 2) * Math.min(1, (gauge.value + gauge.coming) / max)) - fill;
		Shape old = g.getClip();
		g.clip(track);
		if (fill > 0)
		{
			g.setPaint(new GradientPaint(0, by, Theme.mix(gauge.tone, Theme.TEXT, 0.3), 0, by + bh, Theme.mix(gauge.tone, Theme.INK_DEEP, 0.25)));
			g.fillRect(1, by, fill, bh + 1);
		}
		if (coming > 0)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 70));
			g.fillRect(1 + fill, by, coming, bh + 1);
			Shape bar = g.getClip();
			g.clipRect(1 + fill, by, coming, bh + 1);
			g.setStroke(new BasicStroke(1.5f));
			g.setColor(Theme.alpha(Theme.TEAL, 170));
			for (int x = 1 + fill - bh; x < 1 + fill + coming; x += 4)
			{
				g.drawLine(x, by + bh + 1, x + bh, by);
			}
			g.setClip(bar);
		}
		g.setClip(old);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(track);

		if (gauge.note != null && !gauge.note.isEmpty())
		{
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(gauge.note, fm, w), 0, by + bh + 13);
		}
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import com.codex.minigamepilot.core.Step;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.Timer;

/**
 * The top of the panel: the Pilot's medallion, where you are, the next action as one large gilt
 * word, and the full instruction under it. When the step changes the medallion's ring flares
 * once, so a glance at the panel shows that something new is asked.
 */
public class Helm extends JComponent
{
	private static final int MEDAL = 54;

	private String heading = "MINIGAME PILOT";
	private String place;
	private Step step;
	private String idleTitle = "Log in to begin";
	private float flare;
	private final Timer flareTimer;

	public Helm()
	{
		setOpaque(false);
		flareTimer = new Timer(30, e ->
		{
			flare = Math.max(0, flare - 0.04f);
			if (flare <= 0)
			{
				((Timer) e.getSource()).stop();
			}
			repaint();
		});
		setPreferredSize(new Dimension(10, 128));
	}

	public void update(String heading, String place, Step step, String idleTitle)
	{
		boolean changed = step != null && (this.step == null || !step.sameAs(this.step));
		this.heading = heading.toUpperCase();
		this.place = place;
		this.step = step;
		this.idleTitle = idleTitle;
		if (changed && isShowing())
		{
			flare = 1;
			flareTimer.restart();
		}
		revalidate();
		repaint();
	}

	@Override
	public Dimension getPreferredSize()
	{
		int w = Math.max(200, getWidth() > 0 ? getWidth() : PilotPanel.WIDTH + 25);
		FontMetrics bold = getFontMetrics(Theme.title());
		FontMetrics small = getFontMetrics(Theme.small());
		int text = w - 16;
		int h = 82;
		String title = step == null ? idleTitle : step.getTitle();
		h += wrap(title, bold, text, 3).size() * (bold.getHeight() - 2);
		if (step != null && !step.getDetail().isEmpty())
		{
			h += 2 + wrap(step.getDetail(), small, text, 3).size() * small.getHeight();
		}
		return new Dimension(w, h + 12);
	}

	static List<String> wrap(String text, FontMetrics fm, int width, int maxLines)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			return lines;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(next) > width && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		lines.add(line.toString());
		if (lines.size() > maxLines)
		{
			List<String> cut = new ArrayList<>(lines.subList(0, maxLines));
			cut.set(maxLines - 1, Ui.clip(cut.get(maxLines - 1) + " " + lines.get(maxLines), fm, width));
			return cut;
		}
		return lines;
	}

	/** Large letters made by doubling every pixel of the game's bold font, the way the game draws big numbers. */
	static int paintLarge(Graphics2D g, String text, int x, int top, Color tint)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, 3, Theme.mix(tint, Color.WHITE, 0.35), 0, base, tint));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, top, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion, lit from above, with a ring that flares when the step changes.
		int mx = 10;
		int my = 12;
		g.setPaint(new RadialGradientPaint(mx + MEDAL / 2f, my + MEDAL / 3f, MEDAL * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, MEDAL, MEDAL));
		if (flare > 0)
		{
			float r = MEDAL / 2f + 3 + (1 - flare) * 8;
			g.setStroke(new BasicStroke(2f));
			g.setColor(Theme.alpha(Theme.GOLD_BRIGHT, Math.round(200 * flare)));
			g.draw(new Ellipse2D.Float(mx + MEDAL / 2f - r, my + MEDAL / 2f - r, r * 2, r * 2));
		}
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + MEDAL, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, MEDAL - 2, MEDAL - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, MEDAL - 10, MEDAL - 10));
		Sigil.paint(g, mx + 11, my + 11, MEDAL - 22);

		int tx = mx + MEDAL + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);
		if (place != null)
		{
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(place, small, room), tx, 70);
		}
		String verb = step == null ? "Ready" : step.getVerb();
		Color tint = step == null ? Theme.GOLD_DIM : step.isWaiting() ? Theme.TEAL : Theme.GOLD;
		paintLarge(g, verb, tx, 26, tint);

		// The instruction in full, then the line of why.
		int y = 82;
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		String title = step == null ? idleTitle : step.getTitle();
		for (String line : wrap(title, bold, w - 16, 3))
		{
			y += bold.getHeight() - 2;
			Ui.shadowed(g, line, 8, y, step == null ? Theme.TEXT_MUTED : Theme.TEXT);
		}
		if (step != null && !step.getDetail().isEmpty())
		{
			g.setFont(Theme.small());
			y += 2;
			for (String line : wrap(step.getDetail(), small, w - 16, 3))
			{
				y += small.getHeight();
				Ui.shadowed(g, line, 8, y, step.isWaiting() ? Theme.mix(Theme.TEAL, Theme.TEXT_MUTED, 0.4) : Theme.TEXT_MUTED);
			}
		}

		// The gilt rule under the helm, with a diamond at its middle.
		int ry = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, ry, w, ry);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, ry - 3);
		diamond.lineTo(w / 2f + 3, ry);
		diamond.lineTo(w / 2f, ry + 3);
		diamond.lineTo(w / 2f - 3, ry);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** One line of a checklist: a diamond that is hollow to do, lit for next and ticked when done. */
class LineRow extends JComponent
{
	/** The width a row has in a card on the side panel, its first guess before it is laid out. */
	static final int ROOM = PilotPanel.WIDTH - 22;

	private final View.Line line;
	/**
	 * True when the text and its trailing note do not fit side by side at the row's width: the
	 * note then drops to a second line of its own, so a name never pushes the cost out.
	 */
	private boolean twoLines;

	LineRow(View.Line line)
	{
		this.line = line;
		setOpaque(false);
		twoLines = !fits(getFontMetrics(Theme.small()), line, ROOM);
		setPreferredSize(new Dimension(10, height(twoLines)));
	}

	private static int height(boolean twoLines)
	{
		return twoLines ? 31 : 18;
	}

	/** Whether a line's text and trailing note fit side by side in a row this wide. */
	static boolean fits(FontMetrics fm, View.Line line, int width)
	{
		int trailing = line.trailing == null || line.trailing.isEmpty() ? 0 : fm.stringWidth(line.trailing) + 10;
		return 16 + fm.stringWidth(line.text) + trailing + 4 <= width;
	}

	/**
	 * The row's real width is only known once it is laid out, and a card can be narrower than the
	 * first guess (a scroll bar, a nested card) or wider. When the guess was wrong the row takes
	 * the height it needs and asks for a fresh layout; the width does not depend on the height,
	 * so this settles at once.
	 */
	@Override
	public void setBounds(int x, int y, int width, int height)
	{
		super.setBounds(x, y, width, height);
		if (width <= 0)
		{
			return;
		}
		boolean two = !fits(getFontMetrics(Theme.small()), line, width);
		if (two != twoLines)
		{
			twoLines = two;
			setPreferredSize(new Dimension(10, height(two)));
			revalidate();
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int mid = 9;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(5, mid - 5);
		diamond.lineTo(10, mid);
		diamond.lineTo(5, mid + 5);
		diamond.lineTo(0, mid);
		diamond.closePath();

		Color text;
		switch (line.mark)
		{
			case NEXT:
				g.setColor(Theme.alpha(Theme.GOLD, 50));
				g.fillRoundRect(-2, 0, w + 2, getHeight(), 8, 8);
				g.setColor(Theme.GOLD_BRIGHT);
				g.fill(diamond);
				text = Theme.GOLD_BRIGHT;
				break;
			case DONE:
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.setColor(Theme.GREEN);
				g.drawLine(1, mid, 4, mid + 3);
				g.drawLine(4, mid + 3, 10, mid - 4);
				text = Theme.TEXT_FAINT;
				break;
			case IDLE:
				g.setColor(Theme.STROKE);
				g.draw(diamond);
				text = Theme.TEXT_FAINT;
				break;
			default:
				g.setStroke(new BasicStroke(1.2f));
				g.setColor(Theme.GOLD);
				g.draw(diamond);
				text = Theme.TEXT;
				break;
		}

		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int right = w - 4;
		if (line.trailing != null && !line.trailing.isEmpty())
		{
			// A long name keeps its line; the note then sits under it, right-aligned.
			// On its own line the note has the row to itself; only a row too narrow for even
			// that (never at the side panel's width) cuts it.
			String trailing = twoLines ? Ui.clip(line.trailing, fm, w - 4) : line.trailing;
			int tw = fm.stringWidth(trailing);
			Ui.shadowed(g, trailing, w - tw - 4, twoLines ? mid + 18 : mid + 5, line.mark == View.Line.Mark.NEXT ? Theme.GOLD : Theme.TEXT_MUTED);
			right = twoLines ? w - 4 : w - tw - 10;
		}
		Ui.shadowed(g, Ui.clip(line.text, fm, right - 16), 16, mid + 5, text);
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/**
 * The minigame's loop as a row of waypoints joined by a gilt line that curls back to the start,
 * with the stage you are on lit. It says where this step sits in the round, and how far is left
 * before it begins again.
 */
class LoopStrip extends JComponent
{
	private static final int HEIGHT = 52;

	private final String[] stages;
	private final int at;

	LoopStrip(String[] stages, int at)
	{
		this.stages = stages;
		this.at = at;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int n = stages.length;
		if (n == 0)
		{
			g.dispose();
			return;
		}
		int pad = 18;
		float span = n == 1 ? 0 : (w - pad * 2) / (float) (n - 1);
		int cy = 18;

		// The return path: a faint arc under the row from the last stage back to the first.
		Path2D back = new Path2D.Float();
		back.moveTo(pad + span * (n - 1), cy + 6);
		back.curveTo(pad + span * (n - 1), cy + 16, pad, cy + 16, pad, cy + 6);
		g.setStroke(new BasicStroke(1f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{2f, 3f}, 0f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.draw(back);
		Path2D tip = new Path2D.Float();
		tip.moveTo(pad - 3, cy + 10);
		tip.lineTo(pad, cy + 6);
		tip.lineTo(pad + 3, cy + 10);
		g.setStroke(new BasicStroke(1f));
		g.draw(tip);

		// The way forward between the waypoints, gilt up to where you are.
		for (int i = 0; i < n - 1; i++)
		{
			float x0 = pad + span * i;
			float x1 = pad + span * (i + 1);
			g.setStroke(new BasicStroke(2f));
			g.setColor(i < at ? Theme.alpha(Theme.GOLD, 200) : Theme.STROKE);
			g.drawLine(Math.round(x0 + 6), cy, Math.round(x1 - 6), cy);
		}

		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		// When the names would run into each other, only the current one is written.
		boolean crowded = false;
		for (int i = 0; i < n - 1; i++)
		{
			int a = fm.stringWidth(stages[i].toUpperCase());
			int b = fm.stringWidth(stages[i + 1].toUpperCase());
			if ((a + b) / 2f + 4 > span)
			{
				crowded = true;
			}
		}
		for (int i = 0; i < n; i++)
		{
			float x = pad + span * i;
			boolean now = i == at;
			boolean past = i < at;
			if (now)
			{
				g.setColor(Theme.alpha(Theme.GOLD, 50));
				g.fill(new Ellipse2D.Float(x - 10, cy - 10, 20, 20));
			}
			float r = now ? 6 : 4.5f;
			Ellipse2D dot = new Ellipse2D.Float(x - r, cy - r, r * 2, r * 2);
			if (now)
			{
				g.setPaint(new GradientPaint(x, cy - r, Theme.GOLD_BRIGHT, x, cy + r, Theme.GOLD));
			}
			else
			{
				g.setColor(past ? Theme.GOLD_DIM : Theme.INK_DEEP);
			}
			g.fill(dot);
			g.setStroke(new BasicStroke(1.2f));
			g.setColor(now ? Theme.GOLD_BRIGHT : past ? Theme.GOLD : Theme.STROKE);
			g.draw(dot);

			if (crowded && !now)
			{
				continue;
			}
			String label = stages[i].toUpperCase();
			int lw = fm.stringWidth(label);
			int lx = Math.round(x - lw / 2f);
			lx = Math.max(0, Math.min(w - lw, lx));
			Ui.shadowed(g, label, lx, HEIGHT - 6, now ? Theme.GOLD_BRIGHT : past ? Theme.TEXT_MUTED : Theme.TEXT_FAINT);
		}
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import com.codex.minigamepilot.core.Pace;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * The last round against your best: the round's time in gilt, a chip saying how it compares,
 * and a bar with a notch where your best sits, so a slow round reads at a glance.
 */
class PaceDial extends JComponent
{
	private static final int HEIGHT = 50;

	private final View.PaceCard pace;

	PaceDial(View.PaceCard pace)
	{
		this.pace = pace;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Ui.shadowed(g, "LAST ROUND", 0, small.getAscent(), Theme.TEXT_MUTED);

		// The chip: a new best, or how far over or under the old one.
		String chip;
		Color tone;
		if (pace.isBest)
		{
			chip = "NEW BEST";
			tone = Theme.GOLD_BRIGHT;
		}
		else if (pace.againstBest > 0)
		{
			chip = "+" + seconds(pace.againstBest);
			tone = pace.againstBest <= 3 ? Theme.GOLD : Theme.EMBER;
		}
		else if (pace.againstBest < 0)
		{
			chip = "-" + seconds(-pace.againstBest);
			tone = Theme.GREEN;
		}
		else
		{
			chip = null;
			tone = Theme.TEXT_MUTED;
		}
		if (chip != null)
		{
			int cw = small.stringWidth(chip) + 10;
			int ch = small.getHeight() + 2;
			RoundRectangle2D pill = new RoundRectangle2D.Float(w - cw - 0.5f, 0.5f, cw, ch, ch, ch);
			g.setColor(Theme.alpha(tone, 40));
			g.fill(pill);
			g.setColor(Theme.alpha(tone, 170));
			g.draw(pill);
			Ui.shadowed(g, chip, w - cw + 4, 1 + small.getAscent(), tone);
		}

		g.setFont(Theme.title());
		FontMetrics big = g.getFontMetrics();
		int timeY = small.getHeight() + 4 + big.getAscent();
		String time = Pace.clock(pace.lastTicks);
		Ui.shadowed(g, time, 0, timeY, pace.isBest ? Theme.GOLD_BRIGHT : Theme.GOLD);
		if (pace.bestTicks > 0 && !pace.isBest)
		{
			g.setFont(Theme.small());
			Ui.shadowed(g, "best " + Pace.clock(pace.bestTicks), big.stringWidth(time) + 8, timeY, Theme.TEXT_FAINT);
		}

		// The bar: this round's length, with a notch where your best sits.
		int by = HEIGHT - 9;
		int bh = 6;
		int max = Math.max(pace.lastTicks, pace.bestTicks);
		double scale = (w - 2) / (max * 1.08);
		RoundRectangle2D track = new RoundRectangle2D.Float(0.5f, by + 0.5f, w - 1, bh, bh, bh);
		g.setPaint(new GradientPaint(0, by, Theme.INK_DEEP, 0, by + bh, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(track);
		int fill = (int) Math.round(pace.lastTicks * scale);
		Color barTone = pace.isBest ? Theme.GOLD_BRIGHT : pace.costly ? Theme.EMBER : Theme.GOLD;
		g.setPaint(new GradientPaint(0, by, Theme.mix(barTone, Theme.TEXT, 0.25), 0, by + bh, Theme.mix(barTone, Theme.INK_DEEP, 0.3)));
		g.fill(new RoundRectangle2D.Float(1, by + 1, Math.max(bh, fill), bh - 1, bh - 1, bh - 1));
		g.setColor(Theme.STROKE_SOFT);
		g.draw(track);
		if (pace.bestTicks > 0)
		{
			float x = (float) (1 + pace.bestTicks * scale);
			g.setStroke(new BasicStroke(1.4f));
			g.setColor(Theme.GOLD_BRIGHT);
			g.drawLine(Math.round(x), by - 2, Math.round(x), by + bh + 1);
			Path2D notch = new Path2D.Float();
			notch.moveTo(x - 3, by - 5);
			notch.lineTo(x + 3, by - 5);
			notch.lineTo(x, by - 1);
			notch.closePath();
			g.fill(notch);
		}
		g.dispose();
	}

	/** Ticks as seconds, rounded to the nearest. */
	private static String seconds(int ticks)
	{
		return Math.round(ticks * 0.6) + "s";
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * One bar in the ranking of what pays: its name and what it makes on the first line, the coins a
 * bar and the coal trips it needs on the second, and a thin gilt rule as long as its share of the
 * best bar's earnings. The bar being made is lit; bars your level does not reach are dimmed.
 */
class PickRow extends JComponent
{
	private final View.Pick pick;

	PickRow(View.Pick pick)
	{
		this.pick = pick;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 32));
		setToolTipText(pick.name + ": " + pick.detail);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		if (pick.current)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 34));
			g.fill(new RoundRectangle2D.Float(-2, 0, w + 4, h - 1, 8, 8));
		}
		Color name = !pick.unlocked ? Theme.TEXT_FAINT : pick.current ? Theme.GOLD_BRIGHT : Theme.TEXT;
		Color figure = !pick.unlocked ? Theme.TEXT_FAINT : pick.loss ? Theme.BLOOD : pick.current ? Theme.GOLD_BRIGHT : Theme.GOLD;

		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		int fw = body.stringWidth(pick.figure);
		Ui.shadowed(g, pick.figure, w - fw - 2, 13, figure);
		Ui.shadowed(g, Ui.clip(pick.name, body, w - fw - 10), 2, 13, name);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(pick.unlocked ? Theme.TEXT_MUTED : Theme.TEXT_FAINT);
		g.drawString(Ui.clip(pick.detail, small, w - 4), 2, 25);

		if (pick.unlocked && pick.share > 0)
		{
			int len = Math.max(3, (int) Math.round((w - 4) * Math.min(1, pick.share)));
			g.setPaint(new GradientPaint(2, 0, Theme.alpha(pick.current ? Theme.GOLD_BRIGHT : Theme.GOLD, 200), 2 + len, 0, Theme.alpha(Theme.GOLD_DIM, 120)));
			g.fill(new RoundRectangle2D.Float(2, h - 4, len, 2, 2, 2));
		}
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import net.runelite.client.ui.PluginPanel;

/**
 * The Pilot side panel. The helm at the top always holds the one next action. Under it, the
 * loop with your place in it, the minigame's gauges, a checklist where there is one, the pace
 * coach's verdict on the last round, and the session so far. Away from the minigames it lists the three it flies and what is waiting at each.
 */
public class PilotPanel extends PluginPanel
{
	static final int WIDTH = 200;

	private final Helm helm = new Helm();
	private final StackPanel body = new StackPanel(8, 8);
	private View view = View.loggedOut();
	/** An item's picture by its id, for the reward road; null draws bare medallions. */
	private java.util.function.IntFunction<java.awt.image.BufferedImage> icons;
	/** Whether the panel is open in the sidebar; the plugin skips rebuilding it while it is not. */
	private volatile boolean open;
	private Runnable onOpen;

	public PilotPanel()
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(Theme.INK);
		add(helm, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(body);
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		add(scroll, BorderLayout.CENTER);
		rebuild();
	}

	/** Where the reward road gets each item's picture. */
	public void icons(java.util.function.IntFunction<java.awt.image.BufferedImage> source)
	{
		java.util.Map<Integer, java.awt.image.BufferedImage> kept = new java.util.HashMap<>();
		// Each picture is asked for once and kept, and the panel repaints once as it arrives,
		// however often the road is rebuilt.
		icons = source == null ? null : id -> kept.computeIfAbsent(id, k ->
		{
			java.awt.image.BufferedImage img = source.apply(k);
			if (img instanceof net.runelite.client.util.AsyncBufferedImage)
			{
				((net.runelite.client.util.AsyncBufferedImage) img).onLoaded(() -> javax.swing.SwingUtilities.invokeLater(this::repaint));
			}
			return img;
		});
	}

	/** Called when the panel is opened, so the plugin can bring it up to date. */
	public void onOpen(Runnable action)
	{
		onOpen = action;
	}

	/** True while the panel is open in the sidebar. Safe to read from any thread. */
	public boolean isOpen()
	{
		return open || isShowing();
	}

	@Override
	public void onActivate()
	{
		open = true;
		Runnable r = onOpen;
		if (r != null)
		{
			r.run();
		}
	}

	@Override
	public void onDeactivate()
	{
		open = false;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void update(View view)
	{
		this.view = view;
		rebuild();
	}

	private void rebuild()
	{
		View v = view;
		String idle = !v.loggedIn ? "Log in to begin" : "Head to a minigame and the Pilot takes over";
		helm.update(v.activity.getTitle(), v.place, v.step, idle);
		body.removeAll();

		if (v.loop != null && v.loop.length > 0)
		{
			Card loop = new Card(new BorderLayout());
			loop.setBorder(new javax.swing.border.EmptyBorder(6, 4, 4, 4));
			loop.add(new LoopStrip(v.loop, v.loopAt), BorderLayout.CENTER);
			body.add(loop);
		}

		if (!v.gauges.isEmpty())
		{
			body.add(new SectionHeader(v.activity == View.Activity.FURNACE ? "The furnace" : v.activity == View.Activity.HOMES ? "Materials" : "The sack"));
			Card card = new Card(new BorderLayout());
			StackPanel gauges = new StackPanel(6, 0);
			for (View.Gauge gauge : v.gauges)
			{
				gauges.add(new GaugeBar(gauge));
			}
			card.add(gauges, BorderLayout.CENTER);
			body.add(card);
		}

		if (!v.lines.isEmpty())
		{
			body.add(new SectionHeader(v.linesTitle == null ? "To do" : v.linesTitle, v.linesNote));
			Card card = new Card(new BorderLayout());
			StackPanel lines = new StackPanel(2, 0);
			for (View.Line line : v.lines)
			{
				lines.add(new LineRow(line));
			}
			card.add(lines, BorderLayout.CENTER);
			body.add(card);
		}

		if (!v.goals.isEmpty())
		{
			body.add(new SectionHeader(v.goals.size() == 1 ? "Goal" : "Goals", v.goals.size() == 1 ? v.goals.get(0).unit : null));
			for (View.GoalCard goal : v.goals)
			{
				body.add(goalCard(goal, v.goals.size() > 1));
			}
		}

		if (!v.road.isEmpty())
		{
			int owned = 0;
			for (com.codex.minigamepilot.core.RewardRoad.Stop s : v.road)
			{
				owned += s.isOwned() ? 1 : 0;
			}
			body.add(new SectionHeader(v.activity == View.Activity.FURNACE ? "Smithing road" : "Reward road", owned + " of " + v.road.size() + " done"));
			Card card = new Card(new BorderLayout());
			card.setBorder(new javax.swing.border.EmptyBorder(4, 8, 4, 8));
			card.add(new RoadView(v.road, icons), BorderLayout.CENTER);
			String why = RoadView.footnote(v.road);
			if (why != null)
			{
				card.add(Ui.wrapped(why, Theme.small(), Theme.TEAL, WIDTH - 30), BorderLayout.SOUTH);
			}
			body.add(card);
		}

		if (v.pick != null && !v.pick.picks.isEmpty())
		{
			body.add(new SectionHeader(v.pick.title, v.pick.trailing));
			Card card = new Card(new BorderLayout(0, 4));
			StackPanel rows = new StackPanel(2, 0);
			for (View.Pick p : v.pick.picks)
			{
				rows.add(new PickRow(p));
			}
			card.add(rows, BorderLayout.CENTER);
			card.add(Ui.wrapped(v.pick.note, Theme.small(), Theme.TEXT_FAINT, WIDTH - 30), BorderLayout.SOUTH);
			body.add(card);
		}

		if (v.supply != null && !v.supply.lines.isEmpty())
		{
			body.add(new SectionHeader("In the bank", v.supply.trailing));
			Card card = new Card(new BorderLayout());
			card.accent(v.supply.warn ? Theme.EMBER : Theme.TEAL);
			StackPanel stack = new StackPanel(4, 0);
			StackPanel lines = new StackPanel(1, 0);
			for (View.Line line : v.supply.lines)
			{
				lines.add(new LineRow(line));
			}
			stack.add(lines);
			if (v.supply.headline != null)
			{
				stack.add(Ui.wrapped(v.supply.headline, Theme.small(), Theme.TEXT, WIDTH - 30));
			}
			if (v.supply.detail != null)
			{
				stack.add(Ui.wrapped(v.supply.detail, Theme.small(), v.supply.warn ? Theme.EMBER : Theme.TEXT_MUTED, WIDTH - 30));
			}
			if (v.supply.note != null)
			{
				stack.add(Ui.wrapped(v.supply.note, Theme.small(), Theme.TEXT_FAINT, WIDTH - 30));
			}
			card.add(stack, BorderLayout.CENTER);
			body.add(card);
		}

		if (v.pace != null)
		{
			body.add(new SectionHeader("Pace"));
			Card card = new Card(new BorderLayout());
			card.accent(v.pace.isBest ? Theme.GOLD_BRIGHT : v.pace.costly ? Theme.EMBER : Theme.GREEN);
			StackPanel stack = new StackPanel(4, 0);
			stack.add(new PaceDial(v.pace));
			stack.add(Ui.wrapped(v.pace.advice, Theme.small(), v.pace.costly ? Theme.EMBER : Theme.GREEN, WIDTH - 30));
			if (v.pace.splits.size() > 1)
			{
				stack.add(new StageStrip(v.pace.splits));
				if (v.pace.splitNote != null)
				{
					stack.add(Ui.wrapped(v.pace.splitNote, Theme.small(), Theme.mix(Theme.TEXT_MUTED, Theme.EMBER, 0.5), WIDTH - 30));
				}
			}
			stack.add(Ui.wrapped(v.pace.tail, Theme.small(), Theme.TEXT_FAINT, WIDTH - 30));
			card.add(stack, BorderLayout.CENTER);
			body.add(card);
		}

		if (!v.stats.isEmpty())
		{
			body.add(new SectionHeader("This session"));
			JPanel grid = new JPanel(new GridLayout(0, 2, 6, 6));
			grid.setOpaque(false);
			for (View.Stat s : v.stats)
			{
				grid.add(new StatTile(s.value, s.label, s.note, s.tone));
			}
			body.add(grid);
		}

		if (!v.briefs.isEmpty())
		{
			body.add(new SectionHeader("Minigames"));
			for (View.Brief b : v.briefs)
			{
				Card card = new Card(new BorderLayout(0, 2));
				card.accent(Theme.GOLD_DIM);
				card.add(Ui.label(b.activity.getTitle(), Theme.title(), Theme.GOLD), BorderLayout.NORTH);
				StackPanel text = new StackPanel(2, 0);
				if (b.status != null)
				{
					text.add(Ui.wrapped(b.status, Theme.small(), Theme.TEXT, WIDTH - 30));
				}
				if (b.best != null)
				{
					text.add(Ui.wrapped(b.best, Theme.small(), Theme.GOLD, WIDTH - 30));
				}
				if (b.how != null)
				{
					text.add(Ui.wrapped(b.how, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30));
				}
				card.add(text, BorderLayout.CENTER);
				body.add(card);
			}
		}

		body.revalidate();
		body.repaint();
		revalidate();
		repaint();
	}

	/**
	 * A goal: how far along it is, how far off in rounds and time, and its pieces ticked off.
	 * A goal of one piece is all in its gauge ("Coal bag 64 / 100"), so a list of that one piece
	 * would only say its cost twice.
	 */
	private static Card goalCard(View.GoalCard goal, boolean named)
	{
		Card card = new Card(new BorderLayout());
		card.accent(goal.done ? Theme.GREEN : Theme.GOLD);
		StackPanel stack = new StackPanel(4, 0);
		if (named)
		{
			stack.add(Ui.label(goal.activity.getTitle(), Theme.small(), Theme.GOLD_DIM));
		}
		int have = (int) Math.min(Integer.MAX_VALUE, goal.have);
		int need = (int) Math.min(Integer.MAX_VALUE, goal.need);
		stack.add(new GaugeBar(new View.Gauge(goal.title, have, 0, need, null, goal.done ? Theme.GREEN : Theme.progressColor(need == 0 ? 1 : have / (double) need))));
		stack.add(Ui.wrapped(goal.note, Theme.small(), goal.done ? Theme.GREEN : Theme.TEXT_MUTED, WIDTH - 30));
		if (goal.aside != null)
		{
			stack.add(Ui.wrapped(goal.aside, Theme.small(), Theme.TEAL, WIDTH - 30));
		}
		if (goal.pieces.size() > 1)
		{
			StackPanel lines = new StackPanel(1, 0);
			for (View.Line line : goal.pieces)
			{
				lines.add(new LineRow(line));
			}
			stack.add(lines);
		}
		card.add(stack, BorderLayout.CENTER);
		return card;
	}
}

package com.codex.minigamepilot.ui;

import com.codex.minigamepilot.core.Goal;
import com.codex.minigamepilot.core.RewardRoad;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.Shape;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Locale;
import java.util.function.IntFunction;
import javax.swing.JComponent;

/**
 * The reward road: a minigame's whole shop as a column of medallions joined by a gilt thread,
 * each holding the reward's own item. Owned ones are rimmed in gold and ticked, the next is
 * ringed by how much of it you already hold, and the line beside each says what it takes, lit
 * gold when you can buy it now. The thread is solid as far as you own and dotted beyond.
 */
class RoadView extends JComponent
{
	static final int ROW = 42;
	private static final int D = 32;
	private static final BasicStroke THREAD = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final BasicStroke THREAD_AHEAD = new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1, new float[]{2, 4}, 0);
	private static final BasicStroke RIM = new BasicStroke(1.4f);
	private static final BasicStroke ARC = new BasicStroke(2.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final BasicStroke TICK = new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	private final List<RewardRoad.Stop> stops;
	private final BufferedImage[] icons;

	/** @param icons an item's picture by its id (the panel keeps them, and repaints as they load), or null to draw the medallions bare */
	RoadView(List<RewardRoad.Stop> stops, IntFunction<BufferedImage> icons)
	{
		this.stops = stops;
		this.icons = new BufferedImage[stops.size()];
		for (int i = 0; i < stops.size(); i++)
		{
			int id = stops.get(i).getIcon();
			this.icons[i] = icons == null || id <= 0 ? null : icons.apply(id);
		}
		setOpaque(false);
		setPreferredSize(new Dimension(10, stops.size() * ROW));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int i = e.getY() / ROW;
				setToolTipText(i >= 0 && i < stops.size() ? tip(stops.get(i)) : null);
			}
		};
		addMouseMotionListener(mouse);
	}

	/** The first stop not yet owned, or -1 when the road is done. */
	static int next(List<RewardRoad.Stop> stops)
	{
		for (int i = 0; i < stops.size(); i++)
		{
			if (!stops.get(i).isOwned())
			{
				return i;
			}
		}
		return -1;
	}

	static String count(long n)
	{
		return com.codex.minigamepilot.core.Figures.count(n);
	}

	/** "1,250 nuggets", "320 points", "412K xp". */
	static String amount(RewardRoad.Stop s, long n)
	{
		Goal.Currency c = s.getCurrency();
		if (c == null)
		{
			return com.codex.minigamepilot.core.Figures.brief(n) + " xp";
		}
		return count(n) + " " + c.of(n);
	}

	/**
	 * The line under a stop's name: owned, yours now, or what it takes and when. The next stop
	 * says what is still to earn ("36 to go, 1h 43m"); later ones what they cost and when, at
	 * your pace, they are yours once the stops above are ("100 nuggets, in 6h 29m").
	 */
	static String status(RewardRoad.Stop s, boolean next)
	{
		return status(s, next, false);
	}

	/** @param compact the shorter form for a narrow row: when it comes, or what is left, alone */
	static String status(RewardRoad.Stop s, boolean next, boolean compact)
	{
		if (s.isOwned())
		{
			return s.getLevel() > 0 ? "Reached" : "Owned";
		}
		if (s.isAffordable())
		{
			return compact ? "Yours to buy now" : "Yours to buy now, " + amount(s, s.getCost());
		}
		if (!s.isKnown())
		{
			return amount(s, s.getCost());
		}
		String when = s.getMinutesAway() > 0 ? Goal.duration(s.getMinutesAway())
			: s.getRoundsAway() > 0 && s.getCurrency() != null ? count(s.getRoundsAway()) + (s.getRoundsAway() == 1 ? " contract" : " contracts")
			: null;
		if (next)
		{
			String left = (s.getCurrency() == null ? amount(s, s.getLeft()) : count(s.getLeft())) + " to go";
			return when == null || compact ? left : left + ", " + when;
		}
		if (compact && when != null)
		{
			return "In " + when;
		}
		return amount(s, s.getCost()) + (when == null ? "" : ", in " + when);
	}

	/** "Mining 72 is for Dragon Slayer II, a Codex Navigator goal.", when the road ends in one. */
	static String footnote(java.util.List<RewardRoad.Stop> stops)
	{
		for (RewardRoad.Stop s : stops)
		{
			if (s.getReason() != null && !s.isOwned())
			{
				// A level that lands on a stop of another name says which stop it is.
				String level = s.getLevelName().equals(s.getName()) ? s.getName() : s.getLevelName() + " (" + s.getName() + ")";
				return level + " is for " + s.getReason() + ", a Codex Navigator goal.";
			}
		}
		return null;
	}

	static String tip(RewardRoad.Stop s)
	{
		String tip = s.getName() + ": " + status(s, false);
		if (s.getReason() != null)
		{
			tip += ". " + s.getReason() + " needs " + (s.getLevelName().equals(s.getName()) ? "it" : s.getLevelName());
		}
		else if (!s.isOwned() && !s.isAffordable() && s.getCost() != s.getLeft())
		{
			tip += ", counting the stops above it first";
		}
		return tip;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int next = next(stops);
		float cx = D / 2f + 1;

		// The thread first, under the medallions: solid as far as the last owned stop, dotted after.
		for (int i = 0; i + 1 < stops.size(); i++)
		{
			float y0 = i * ROW + ROW / 2f + D / 2f;
			float y1 = (i + 1) * ROW + ROW / 2f - D / 2f;
			boolean walked = stops.get(i + 1).isOwned();
			g.setStroke(walked ? THREAD : THREAD_AHEAD);
			g.setColor(walked ? Theme.GOLD : Theme.alpha(Theme.GOLD_DIM, 170));
			g.draw(new Line2D.Float(cx, y0, cx, y1));
		}

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		for (int i = 0; i < stops.size(); i++)
		{
			RewardRoad.Stop s = stops.get(i);
			int top = i * ROW + (ROW - D) / 2;
			boolean isNext = i == next;
			Shape disc = new Ellipse2D.Float(1, top, D, D);
			Color glow = s.isOwned() ? Theme.GOLD : isNext ? (s.isAffordable() ? Theme.GOLD_BRIGHT : Theme.TEAL) : Theme.STROKE;
			g.setPaint(new RadialGradientPaint(cx, top + D * 0.65f, D * 0.7f, new float[]{0, 1},
				new Color[]{Theme.mix(Theme.CARD_TOP, glow, s.isOwned() || isNext ? 0.22 : 0.06), Theme.INK_DEEP}));
			g.fill(disc);

			BufferedImage icon = icons[i];
			if (icon != null && icon.getWidth() > 1)
			{
				Graphics2D ig = (Graphics2D) g.create();
				ig.clip(disc);
				if (!s.isOwned() && !isNext)
				{
					ig.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.55f));
				}
				ig.drawImage(icon, Math.round(cx - icon.getWidth() / 2f), top + (D - icon.getHeight()) / 2, null);
				ig.dispose();
			}
			else
			{
				// No item to show: a level, or the bigger sack. Its figure, or the Pilot's mark.
				String mark = s.getLevel() > 0 ? String.valueOf(s.getLevel()) : null;
				if (mark != null)
				{
					g.setFont(Theme.title());
					FontMetrics bold = g.getFontMetrics();
					Ui.shadowed(g, mark, Math.round(cx - bold.stringWidth(mark) / 2f), top + (D + bold.getAscent()) / 2 - 1,
						isNext ? Theme.TEAL : Theme.GOLD_DIM);
					g.setFont(Theme.small());
				}
				else
				{
					Sigil.paint(g, cx - 9, top + D / 2f - 9, 18);
				}
			}

			g.setStroke(RIM);
			g.setColor(s.isOwned() ? Theme.GOLD : isNext ? Theme.alpha(glow, 200) : Theme.alpha(Theme.STROKE, 220));
			g.draw(disc);
			if (isNext && s.getCost() > 0 && !s.isAffordable())
			{
				// How much of the next stop you already hold, as an arc round its rim.
				double held = Math.max(0, Math.min(1, (s.getCost() - s.getLeft()) / (double) s.getCost()));
				if (held > 0)
				{
					g.setStroke(ARC);
					g.setColor(Theme.GOLD_BRIGHT);
					g.draw(new Arc2D.Double(1, top, D, D, 90, -360 * held, Arc2D.OPEN));
				}
			}
			if (s.isOwned())
			{
				// A small green tick on a dark seal at the medallion's foot.
				float tx = cx + D / 2f - 9;
				float ty = top + D - 9;
				g.setColor(Theme.INK_DEEP);
				g.fill(new Ellipse2D.Float(tx - 1, ty - 1, 12, 12));
				g.setStroke(TICK);
				g.setColor(Theme.GREEN);
				g.draw(new Line2D.Float(tx + 2, ty + 5, tx + 4.5f, ty + 7.5f));
				g.draw(new Line2D.Float(tx + 4.5f, ty + 7.5f, tx + 9, ty + 2.5f));
			}

			int tx = D + 10;
			int room = w - tx - 2;
			int mid = i * ROW + ROW / 2;
			g.setFont(isNext ? Theme.title() : Theme.small());
			FontMetrics nameFm = g.getFontMetrics();
			Color nameColor = s.isOwned() ? Theme.TEXT_MUTED : isNext ? Theme.GOLD_BRIGHT : Theme.TEXT;
			Ui.shadowed(g, Ui.clip(s.getName(), nameFm, room), tx, mid - 2, nameColor);
			g.setFont(Theme.small());
			Color statusColor = s.isOwned() ? Theme.GREEN : s.isAffordable() ? Theme.GOLD : isNext ? Theme.TEXT_MUTED : Theme.TEXT_FAINT;
			g.setColor(statusColor);
			String line = status(s, isNext);
			if (small.stringWidth(line) > room)
			{
				line = status(s, isNext, true);
			}
			g.drawString(Ui.clip(line, small, room), tx, mid + small.getAscent() + 1);
		}
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.minigamepilot.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** The Pilot's mark: a gilt compass ring with a teal needle pointing the way. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float cx = x + 8 * s;
		float cy = y + 8 * s;
		float stroke = Math.max(1f, 1.3f * s);

		// The ring, with its four cardinal ticks.
		g.setStroke(new BasicStroke(stroke));
		g.setPaint(new GradientPaint(x, y, Theme.GOLD_BRIGHT, x, y + size, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(x + 1.4f * s, y + 1.4f * s, 13.2f * s, 13.2f * s));
		g.setStroke(new BasicStroke(Math.max(0.8f, 0.9f * s)));
		for (int i = 0; i < 4; i++)
		{
			double a = Math.PI / 2 * i;
			float ox = (float) Math.cos(a);
			float oy = (float) Math.sin(a);
			g.drawLine(Math.round(cx + ox * 5.2f * s), Math.round(cy + oy * 5.2f * s),
				Math.round(cx + ox * 6.6f * s), Math.round(cy + oy * 6.6f * s));
		}

		// The needle: a teal point to the north-east and a dark tail behind it.
		double angle = -Math.PI / 4;
		float len = 5.4f * s;
		float wid = 1.7f * s;
		float tx = (float) Math.cos(angle);
		float ty = (float) Math.sin(angle);
		float nx = -ty;
		float ny = tx;
		Path2D head = new Path2D.Float();
		head.moveTo(cx + tx * len, cy + ty * len);
		head.lineTo(cx + nx * wid, cy + ny * wid);
		head.lineTo(cx - nx * wid, cy - ny * wid);
		head.closePath();
		Path2D tail = new Path2D.Float();
		tail.moveTo(cx - tx * len * 0.8f, cy - ty * len * 0.8f);
		tail.lineTo(cx + nx * wid, cy + ny * wid);
		tail.lineTo(cx - nx * wid, cy - ny * wid);
		tail.closePath();
		g.setColor(Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.3));
		g.fill(tail);
		g.setPaint(new GradientPaint(cx, cy, Theme.TEAL, cx + tx * len, cy + ty * len, Theme.mix(Theme.TEAL, Theme.TEXT, 0.5)));
		g.fill(head);
		g.setColor(Theme.GOLD_BRIGHT);
		float hub = Math.max(1.6f, 1.6f * s);
		g.fill(new Ellipse2D.Float(cx - hub / 2, cy - hub / 2, hub, hub));
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.minigamepilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.util.List;

/**
 * The last round cut into its stages: one engraved bar split in proportion to the time each
 * stage took, the slowest against its best lit in ember, and under each segment its name. A
 * fine tick inside a segment marks where your best for that stage would have ended it.
 */
class StageStrip extends javax.swing.JComponent
{
	private static final Color[] TONES = {Theme.GOLD, Theme.TEAL, Theme.GREEN, Theme.GOLD_DIM, Theme.TEXT_MUTED};

	private final List<View.Split> splits;

	StageStrip(List<View.Split> splits)
	{
		this.splits = splits;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 34));
		StringBuilder tip = new StringBuilder("<html>");
		for (View.Split s : splits)
		{
			tip.append(s.name).append(": ").append(com.codex.minigamepilot.core.Pace.clock(s.ticks));
			if (s.best > 0)
			{
				tip.append(" (best ").append(com.codex.minigamepilot.core.Pace.clock(s.best)).append(')');
			}
			tip.append("<br>");
		}
		setToolTipText(tip.append("</html>").toString());
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int total = 0;
		for (View.Split s : splits)
		{
			total += s.ticks;
		}
		if (total == 0)
		{
			g.dispose();
			return;
		}
		int by = 2;
		int bh = 10;
		RoundRectangle2D track = new RoundRectangle2D.Float(0.5f, by + 0.5f, w - 1, bh, bh, bh);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		Shape old = g.getClip();
		g.clip(track);
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		double x = 1;
		double span = w - 2;
		int i = 0;
		double[] starts = new double[splits.size()];
		double[] widths = new double[splits.size()];
		for (View.Split s : splits)
		{
			double sw = span * s.ticks / total;
			starts[i] = x;
			widths[i] = sw;
			Color tone = s.slowest ? Theme.EMBER : TONES[i % TONES.length];
			g.setPaint(new GradientPaint(0, by, Theme.mix(tone, Theme.TEXT, 0.25), 0, by + bh, Theme.mix(tone, Theme.INK_DEEP, 0.3)));
			g.fillRect((int) Math.round(x), by, (int) Math.max(1, Math.round(sw) - 1), bh + 1);
			if (s.best > 0 && s.best < s.ticks)
			{
				// Where your best for this stage would have ended it.
				int bx = (int) Math.round(x + sw * s.best / (double) s.ticks);
				g.setStroke(new BasicStroke(1.2f));
				g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
				g.drawLine(bx, by, bx, by + bh);
			}
			x += sw;
			i++;
		}
		g.setClip(old);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(track);
		// Names under the segments that have room for them.
		for (int k = 0; k < splits.size(); k++)
		{
			View.Split s = splits.get(k);
			String label = s.name;
			if (fm.stringWidth(label) > widths[k] - 2)
			{
				label = s.name.substring(0, 1);
				if (fm.stringWidth(label) > widths[k])
				{
					continue;
				}
			}
			int lx = (int) Math.round(starts[k] + (widths[k] - fm.stringWidth(label)) / 2);
			Ui.shadowed(g, label, lx, by + bh + 4 + fm.getAscent(), s.slowest ? Theme.EMBER : Theme.TEXT_MUTED);
		}
		g.dispose();
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Pilot keeps gold for the one thing to do next, teal for the path that leads there
 * and ember for anything that is holding the loop up.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.minigamepilot.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.minigamepilot.ui;

import com.codex.minigamepilot.core.RewardRoad;
import com.codex.minigamepilot.core.Step;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Everything the panel shows, worked out on the client thread and handed over whole. */
public final class View
{
	/** Which minigame the Pilot is flying. */
	public enum Activity
	{
		NONE("Minigame Pilot"),
		MOTHERLODE("Motherlode Mine"),
		FURNACE("Blast Furnace"),
		HOMES("Mahogany Homes");

		private final String title;

		Activity(String title)
		{
			this.title = title;
		}

		public String getTitle()
		{
			return title;
		}
	}

	/** A filled bar: how much of something there is against its limit, with a lighter part still on its way. */
	public static final class Gauge
	{
		final String label;
		final int value;
		final int coming;
		final int max;
		final String note;
		final Color tone;

		public Gauge(String label, int value, int coming, int max, String note, Color tone)
		{
			this.label = label;
			this.value = value;
			this.coming = coming;
			this.max = max;
			this.note = note;
			this.tone = tone;
		}
	}

	/** A number for the session tiles. */
	public static final class Stat
	{
		final String value;
		final String label;
		final String note;
		final Color tone;

		public Stat(String value, String label, String note, Color tone)
		{
			this.value = value;
			this.label = label;
			this.note = note;
			this.tone = tone;
		}
	}

	/** One line of a checklist, such as a piece of furniture. */
	public static final class Line
	{
		/** How a line is marked. */
		public enum Mark
		{
			TODO,
			NEXT,
			DONE,
			IDLE
		}

		final String text;
		final String trailing;
		final Mark mark;

		public Line(String text, String trailing, Mark mark)
		{
			this.text = text;
			this.trailing = trailing;
			this.mark = mark;
		}
	}

	/** A minigame the Pilot knows, for when the player is in none of them. */
	public static final class Brief
	{
		final Activity activity;
		final String status;
		final String how;

		/** Your fastest visit, in gold under the status, or null. */
		String best;

		public Brief best(String line)
		{
			best = line;
			return this;
		}

		public Brief(Activity activity, String status, String how)
		{
			this.activity = activity;
			this.status = status;
			this.how = how;
		}
	}

	/** One stage of the last round against your best for it. */
	public static final class Split
	{
		final String name;
		final int ticks;
		final int best;
		final boolean slowest;

		public Split(String name, int ticks, int best, boolean slowest)
		{
			this.name = name;
			this.ticks = ticks;
			this.best = best;
			this.slowest = slowest;
		}
	}

	/** The pace coach's verdict on the last round. */
	public static final class PaceCard
	{
		final int lastTicks;
		/** Your best for this kind of round, this one included; 0 when there is none. */
		final int bestTicks;
		final boolean isBest;
		/** Ticks over (positive) or under your best before this round; 0 when there was none. */
		final int againstBest;
		final String advice;
		final boolean costly;
		final String tail;
		/** Each stage of the loop this round: its name, ticks, and your best for it (0 for none). */
		final List<Split> splits = new ArrayList<>();
		/** The stage that cost the most against its best, in a sentence, or null. */
		String splitNote;

		public PaceCard(int lastTicks, int bestTicks, boolean isBest, int againstBest, String advice, boolean costly, String tail)
		{
			this.lastTicks = lastTicks;
			this.bestTicks = bestTicks;
			this.isBest = isBest;
			this.againstBest = againstBest;
			this.advice = advice;
			this.costly = costly;
			this.tail = tail;
		}

		/** Adds the round's stages and the line on the slowest one. */
		public PaceCard splits(List<Split> list, String note)
		{
			splits.addAll(list);
			splitNote = note;
			return this;
		}
	}

	/** A goal being worked toward in a minigame: a reward from its shop, or a level. */
	public static final class GoalCard
	{
		final Activity activity;
		final String title;
		final long have;
		final long need;
		final String unit;
		final String note;
		final List<Line> pieces;
		final boolean done;
		/** A line on what Codex Navigator's goals need from this minigame's skill, or null. */
		String aside;

		/**
		 * @param have how much of the goal you hold, against need
		 * @param note how far off it is, in a sentence
		 * @param pieces the rewards it covers, ticked when owned, or empty for a level
		 */
		public GoalCard(Activity activity, String title, long have, long need, String unit, String note, List<Line> pieces, boolean done)
		{
			this.activity = activity;
			this.title = title;
			this.have = have;
			this.need = need;
			this.unit = unit;
			this.note = note;
			this.pieces = pieces == null ? Collections.emptyList() : pieces;
			this.done = done;
		}

		/** Adds a line on what your Navigator goals need. */
		public GoalCard aside(String text)
		{
			aside = text;
			return this;
		}
	}

	/** One bar in the ranking of what pays at the Blast Furnace. */
	public static final class Pick
	{
		final String name;
		/** The big figure on the right: coins an hour, or a bar when the trip time is not known. */
		final String figure;
		/** A quieter line: coins a bar, coal trips, experience, or the level it needs. */
		final String detail;
		final boolean unlocked;
		final boolean current;
		/** How it compares with the best bar you can make, 0 to 1, for the bar under it. */
		final double share;
		final boolean loss;

		public Pick(String name, String figure, String detail, boolean unlocked, boolean current, double share, boolean loss)
		{
			this.name = name;
			this.figure = figure;
			this.detail = detail;
			this.unlocked = unlocked;
			this.current = current;
			this.share = share;
			this.loss = loss;
		}
	}

	/** A ranking at today's prices, best first: what each bar pays, or what each contract tier costs. */
	public static final class PickCard
	{
		final String title;
		final String trailing;
		final String note;
		final List<Pick> picks;

		public PickCard(String trailing, String note, List<Pick> picks)
		{
			this("What pays", trailing, note, picks);
		}

		public PickCard(String title, String trailing, String note, List<Pick> picks)
		{
			this.title = title;
			this.trailing = trailing;
			this.note = note;
			this.picks = picks == null ? Collections.emptyList() : picks;
		}
	}

	/**
	 * How far the supplies in your bank go: each supply and how many you have, what they come to
	 * in a sentence, what runs out first, and where and when the bank was seen.
	 */
	public static final class Supply
	{
		final String trailing;
		final List<Line> lines;
		final String headline;
		final String detail;
		/** True when the detail is a shortfall, drawn in ember. */
		final boolean warn;
		final String note;

		public Supply(String trailing, List<Line> lines, String headline, String detail, boolean warn, String note)
		{
			this.trailing = trailing;
			this.lines = lines == null ? Collections.emptyList() : lines;
			this.headline = headline;
			this.detail = detail;
			this.warn = warn;
			this.note = note;
		}
	}

	final boolean loggedIn;
	final Activity activity;
	final Step step;
	final String place;
	final String[] loop;
	final int loopAt;
	final List<Gauge> gauges = new ArrayList<>();
	final List<Stat> stats = new ArrayList<>();
	final List<Line> lines = new ArrayList<>();
	String linesTitle;
	String linesNote;
	final List<Brief> briefs = new ArrayList<>();
	PaceCard pace;
	final List<GoalCard> goals = new ArrayList<>();
	/** The minigame's whole shop as a road, or empty. */
	final List<RewardRoad.Stop> road = new ArrayList<>();
	PickCard pick;
	Supply supply;

	/**
	 * @param place where, such as "Falador" or "Lower level", or null
	 * @param loop the names of the loop's stages, or null
	 * @param loopAt which stage the step belongs to
	 */
	public View(boolean loggedIn, Activity activity, Step step, String place, String[] loop, int loopAt)
	{
		this.loggedIn = loggedIn;
		this.activity = activity;
		this.step = step;
		this.place = place;
		this.loop = loop;
		this.loopAt = loopAt;
	}

	/** Logged out: what the Pilot does at each minigame, for a first look before logging in. */
	public static View loggedOut()
	{
		View v = new View(false, Activity.NONE, null, null, null, -1);
		v.brief(new Brief(Activity.MOTHERLODE, null,
			"Each load sized to fill the sack, the nearest free vein on foot, and rockfalls and struts dealt with on the way."));
		v.brief(new Brief(Activity.FURNACE, null,
			"Coal trips worked out ahead, the whole round in order, the coffer watched, and what each bar pays."));
		v.brief(new Brief(Activity.HOMES, null,
			"The planks to bring, the way to the client, each piece of furniture in walking order, and what a contract costs you."));
		return v;
	}

	public int loopAt()
	{
		return loopAt;
	}

	/** The names of the loop's stages, or null. */
	public String[] loopNames()
	{
		return loop == null ? null : loop.clone();
	}

	public View pick(PickCard p)
	{
		pick = p;
		return this;
	}

	public View supply(Supply s)
	{
		supply = s;
		return this;
	}

	public View goal(GoalCard g)
	{
		goals.add(g);
		return this;
	}

	/** Sets the reward road for the minigame you are in. */
	public View road(List<RewardRoad.Stop> stops)
	{
		road.clear();
		if (stops != null)
		{
			road.addAll(stops);
		}
		return this;
	}

	public Activity getActivity()
	{
		return activity;
	}

	public View pace(PaceCard p)
	{
		pace = p;
		return this;
	}

	public View gauge(Gauge g)
	{
		gauges.add(g);
		return this;
	}

	public View stat(Stat s)
	{
		stats.add(s);
		return this;
	}

	public View lines(String title, String note, List<Line> list)
	{
		linesTitle = title;
		linesNote = note;
		lines.addAll(list == null ? Collections.emptyList() : list);
		return this;
	}

	/** A summary of everything shown, so the panel is only rebuilt when something on it changes. */
	public String signature()
	{
		StringBuilder b = new StringBuilder();
		b.append(loggedIn).append(activity).append(step).append(place).append(loopAt).append(linesNote);
		for (Gauge g : gauges)
		{
			b.append('|').append(g.label).append(g.value).append('/').append(g.coming).append('/').append(g.max).append(g.note);
		}
		for (Stat s : stats)
		{
			b.append('|').append(s.value).append(s.label).append(s.note);
		}
		for (Line l : lines)
		{
			b.append('|').append(l.text).append(l.trailing).append(l.mark);
		}
		if (pace != null)
		{
			b.append("|pace").append(pace.lastTicks).append(pace.bestTicks).append(pace.advice).append(pace.tail).append(pace.splitNote);
		}
		for (GoalCard g : goals)
		{
			b.append("|goal").append(g.activity).append(g.title).append(g.have).append('/').append(g.need).append(g.note).append(g.aside);
			for (Line l : g.pieces)
			{
				b.append(l.mark);
			}
		}
		for (RewardRoad.Stop r : road)
		{
			// Time to a stop moves in steps of five minutes, so the road does not redraw every tick.
			b.append("|road").append(r.getName()).append(r.isOwned()).append(r.isAffordable()).append(r.getLeft())
				.append('/').append(r.getMinutesAway() < 0 ? -1 : r.getMinutesAway() / 5).append('/').append(r.getRoundsAway());
		}
		for (Brief r : briefs)
		{
			b.append('|').append(r.activity).append(r.status).append(r.best);
		}
		if (pick != null)
		{
			b.append("|pick").append(pick.title).append(pick.trailing).append(pick.note);
			for (Pick p : pick.picks)
			{
				b.append(p.name).append(p.figure).append(p.detail).append(p.current);
			}
		}
		if (supply != null)
		{
			b.append("|supply").append(supply.trailing).append(supply.headline).append(supply.detail).append(supply.note);
			for (Line l : supply.lines)
			{
				b.append(l.text).append(l.trailing).append(l.mark);
			}
		}
		return b.toString();
	}

	public View brief(Brief b)
	{
		briefs.add(b);
		return this;
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class BankStockTest
{
	private static final Gson GSON = new Gson();
	/**
	 * Codex Bank Steward's {@code bankV1} exactly as its own BankSnapshotTest proves its writer
	 * produces it (bank-steward-bankV1.json), with a teak plank and coal entry added in the same shape.
	 */
	private static final String STEWARD = "{\"version\":1,\"savedAt\":1760000000000,\"items\":{\"385\":240,\"453\":1200,"
		+ "\"995\":1234567,\"2434\":30,\"8780\":212,\"8839\":1,\"11666\":1,\"26950\":1},\"truncated\":false}";

	@Test
	public void groupAndKeyMatchBankSteward()
	{
		// CodexBankStewardConfig.GROUP and BankSnapshot.KEY.
		assertEquals("codexbanksteward", BankStock.STEWARD_GROUP);
		assertEquals("bankV1", BankStock.STEWARD_KEY);
	}

	@Test
	public void readsBankStewardsSnapshotKeepingOnlySupplies()
	{
		BankStock s = BankStock.steward(GSON, STEWARD);
		assertSame(BankStock.Source.BANK_STEWARD, s.getSource());
		assertEquals(1_760_000_000_000L, s.getSavedAt());
		assertEquals(212, s.count(8780));
		assertEquals(1200, s.count(Bar.COAL));
		assertEquals("coins are not a supply", 0, s.count(995));
		assertNull(BankStock.steward(GSON, null));
		assertNull(BankStock.steward(GSON, "not json {"));
		assertNull(BankStock.steward(GSON, "{\"version\":1}"));
		BankStock odd = BankStock.steward(GSON, "{\"items\":{\"x\":1,\"453\":\"many\",\"451\":-2,\"8782\":3}}");
		assertEquals(3, odd.count(8782));
		assertEquals(0, odd.getSavedAt());
	}

	@Test
	public void theNewerLookWins()
	{
		Map<Integer, Long> seen = new HashMap<>();
		seen.put(8780, 40L);
		seen.put(995, 10L);
		BankStock own = BankStock.seen(seen, 1_760_000_000_000L);
		BankStock steward = BankStock.steward(GSON, STEWARD);
		assertSame("a tie goes to the Pilot", own, BankStock.newest(own, steward));
		BankStock older = BankStock.seen(seen, 1_759_000_000_000L);
		assertSame(steward, BankStock.newest(older, steward));
		assertSame(own, BankStock.newest(own, null));
		assertSame(steward, BankStock.newest(null, steward));
		assertNull(BankStock.newest(null, null));
	}

	@Test
	public void savesItsOwnLookAndReadsItBack()
	{
		Map<Integer, Long> seen = new HashMap<>();
		seen.put(8780, 40L);
		seen.put(Bar.COAL, 900L);
		seen.put(995, 10L);
		BankStock own = BankStock.seen(seen, 123L);
		assertEquals("123|453=900;8780=40", own.encode());
		BankStock read = BankStock.decode(own.encode());
		assertTrue(read.sameItems(own));
		assertEquals(123L, read.getSavedAt());
		assertEquals(0, BankStock.decode("5|").count(Bar.COAL));
		assertNull(BankStock.decode("garbage"));
		assertNull(BankStock.decode(null));
		BankStock damaged = BankStock.decode("9|453=x;8780=4;995=7");
		assertEquals(4, damaged.count(8780));
		assertFalse(damaged.sameItems(own));
	}

	@Test
	public void readsBankStewardsOwnFixtureUnchanged()
	{
		// osrs-codex-bank-steward src/test/resources/com/codex/steward/core/bank-steward-bankV1.json,
		// byte for byte: a bank with no minigame supplies in it reads as an empty stock, not as none.
		String fixture = "{\"version\":1,\"savedAt\":1760000000000,\"items\":{\"385\":240,\"995\":1234567,\"2434\":30,"
			+ "\"8839\":1,\"11666\":1,\"26950\":1},\"truncated\":false}";
		BankStock s = BankStock.steward(GSON, fixture);
		assertSame(BankStock.Source.BANK_STEWARD, s.getSource());
		assertEquals(1_760_000_000_000L, s.getSavedAt());
		assertEquals(0, s.count(Bar.COAL));
		assertEquals(0, s.count(Contract.STEEL_BAR));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

public class BarPickTest
{
	private static IntUnaryOperator prices()
	{
		Map<Integer, Integer> p = new HashMap<>();
		p.put(Bar.COAL, 150);
		put(p, Bar.IRON, 100, 300);
		put(p, Bar.STEEL, 100, 600);
		put(p, Bar.MITHRIL, 150, 600);
		put(p, Bar.ADAMANTITE, 1000, 2100);
		put(p, Bar.RUNITE, 11000, 12500);
		put(p, Bar.GOLD, 150, 120);
		put(p, Bar.SILVER, 60, 150);
		return id -> p.getOrDefault(id, 0);
	}

	private static void put(Map<Integer, Integer> p, Bar bar, int ore, int made)
	{
		p.put(bar.getOre(), ore);
		p.put(bar.getBar(), made);
	}

	@Test
	public void coalTripsFollowTheCoalBag()
	{
		assertEquals(0, BarPick.coalTrips(0, 27, 27), 1e-9);
		assertEquals(0, BarPick.coalTrips(1, 27, 27), 1e-9);
		assertEquals(0.5, BarPick.coalTrips(2, 27, 27), 1e-9);
		assertEquals(1.5, BarPick.coalTrips(4, 27, 27), 1e-9);
		// No bag: steel needs a full coal trip for each ore trip.
		assertEquals(1, BarPick.coalTrips(1, 27, 0), 1e-9);
	}

	@Test
	public void ranksUnlockedBarsByCoinsATrip()
	{
		BarPick.Setup s = new BarPick.Setup();
		s.level = 72;
		s.coalBag = true;
		s.oreSlots = 26;
		s.tripSeconds = 60;
		List<BarPick.Row> rows = BarPick.rank(prices(), s);
		assertEquals(7, rows.size());
		// Steel: 600 - 100 - 150 = 350 a bar, no coal trips with the bag.
		BarPick.Row first = rows.get(0);
		assertEquals(Bar.STEEL, first.getBar());
		assertEquals(350, first.getPerBar());
		assertEquals(26 * 350, first.getPerTrip(), 1e-6);
		assertEquals(26 * 60, first.getBarsPerHour(), 1e-6);
		// Over 60 Smithing, only the coffer comes off.
		assertEquals(26 * 60 * 350 - BarPick.COFFER_PER_HOUR, first.getPerHour());
		assertEquals(26 * 60 * 17.5, first.getXpPerHour(), 1e-6);
		// Runite is out of reach at 72 and goes last whatever it pays.
		BarPick.Row last = rows.get(rows.size() - 1);
		assertEquals(Bar.RUNITE, last.getBar());
		assertFalse(last.isUnlocked());
		for (int i = 1; i < rows.size() - 1; i++)
		{
			assertTrue(rows.get(i - 1).getPerTrip() >= rows.get(i).getPerTrip());
		}
	}

	@Test
	public void theForemanAndGauntletsCountBelowSixtyAndOnGold()
	{
		BarPick.Setup s = new BarPick.Setup();
		s.level = 45;
		s.goldsmith = true;
		s.tripSeconds = 36;
		for (BarPick.Row r : BarPick.rank(prices(), s))
		{
			if (r.getBar() == Bar.GOLD)
			{
				assertEquals(27 * 100 * 56.2, r.getXpPerHour(), 1e-6);
				assertEquals(Math.round(2700.0 * -30) - BarPick.COFFER_PER_HOUR - BarPick.FOREMAN_PER_HOUR, r.getPerHour());
			}
		}
	}

	@Test
	public void missingPricesAndTripTimesAreLeftOut()
	{
		BarPick.Setup s = new BarPick.Setup();
		assertTrue(BarPick.rank(id -> 0, s).isEmpty());
		// Coal not priced: only the bars that burn none are ranked.
		IntUnaryOperator known = prices();
		List<BarPick.Row> rows = BarPick.rank(id -> id == Bar.COAL ? 0 : known.applyAsInt(id), s);
		assertEquals(3, rows.size());
		assertEquals(Long.MIN_VALUE, rows.get(0).getPerHour());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.Collections;
import org.junit.Test;

public class BestVisitTest
{
	private static final long T = 1_760_000_000_000L;
	private static final long MIN = 60_000L;

	@Test
	public void aVisitIsMeasuredInUnitsAndExperienceAnHour()
	{
		BestVisit b = BestVisit.of(T, T + 72 * MIN, 72 * MIN, 1_944, 97_200);
		assertEquals(1_620, b.getPerHour());
		assertEquals(81_000, b.getXpPerHour());
		assertEquals("1,620 pay-dirt an hour", b.pace("pay-dirt"));
	}

	@Test
	public void aShortOrIdleVisitIsNoRecord()
	{
		assertNull(BestVisit.of(T, T, BestVisit.MIN_MS - 1, 400, 20_000));
		assertNull(BestVisit.of(T, T, 60 * MIN, 0, 20_000));
		assertNull(BestVisit.of(0, T, 60 * MIN, 400, 20_000));
	}

	@Test
	public void onlyBeatingAnotherSessionIsNews()
	{
		BestVisit held = BestVisit.of(T, T + 60 * MIN, 60 * MIN, 1_500, 0);
		BestVisit slower = BestVisit.of(T + 1, T + 60 * MIN, 60 * MIN, 1_400, 0);
		BestVisit faster = BestVisit.of(T + 1, T + 60 * MIN, 60 * MIN, 1_600, 0);
		BestVisit sameSessionFaster = BestVisit.of(T, T + 90 * MIN, 60 * MIN, 1_600, 0);
		assertEquals(BestVisit.Outcome.QUIET, BestVisit.judge(null, held));
		assertEquals(BestVisit.Outcome.KEPT, BestVisit.judge(held, null));
		assertEquals(BestVisit.Outcome.KEPT, BestVisit.judge(held, slower));
		assertEquals(BestVisit.Outcome.KEPT, BestVisit.judge(held, held));
		assertEquals(BestVisit.Outcome.BEATEN, BestVisit.judge(held, faster));
		// Stepping out of the same session a second time, faster, updates the record quietly.
		assertEquals(BestVisit.Outcome.QUIET, BestVisit.judge(held, sameSessionFaster));
		assertEquals("A new best: 1,600 pay-dirt an hour, up from 1,500.", faster.beat(held, "pay-dirt"));
	}

	@Test
	public void theCardSaysWhenAndHowLongUnlessItWasTheLastVisit()
	{
		long end = T + 72 * MIN;
		BestVisit b = BestVisit.of(T, end, 72 * MIN, 1_944, 97_200);
		assertEquals("Best visit 3 days ago: 1,620 pay-dirt and 81k Mining xp an hour over 1h 12m.",
			b.status("pay-dirt", "Mining", null, end + 72 * 3_600_000L));
		Visit last = Visit.of(end, 72 * MIN, Collections.singletonList("1,944 pay-dirt"));
		assertEquals("Your best visit yet, at 1,620 pay-dirt and 81k Mining xp an hour.",
			b.status("pay-dirt", "Mining", last, end + MIN));
		BestVisit noXp = BestVisit.of(T, end, 20 * MIN, 300, 0);
		assertEquals("Best visit 3 days ago: 900 bars an hour over 20m.", noXp.status("bars", "Smithing", null, end + 72 * 3_600_000L));
	}

	@Test
	public void survivesBeingSavedAndADamagedSave()
	{
		BestVisit b = BestVisit.of(T, T + 72 * MIN, 72 * MIN, 1_944, 97_200);
		BestVisit back = BestVisit.decode(b.encode());
		assertEquals(b.encode(), back.encode());
		assertEquals(BestVisit.Outcome.KEPT, BestVisit.judge(back, b));
		assertNull(BestVisit.decode(null));
		assertNull(BestVisit.decode(""));
		assertNull(BestVisit.decode("1|2|3|4"));
		assertNull(BestVisit.decode("a|b|c|d|e"));
		assertNull(BestVisit.decode(T + "|" + (T - 1) + "|20|300|0"));
		assertNull(BestVisit.decode(T + "|" + T + "|3|300|0"));
		assertNull(BestVisit.decode(T + "|" + T + "|20|0|0"));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

public class ContractBookTest
{
	/** Plank 300, oak 600, teak 1,500, mahogany 2,400, steel bar 500. */
	private static final IntUnaryOperator PRICES = id ->
	{
		switch (id)
		{
			case 960:
				return 300;
			case 8778:
				return 600;
			case 8780:
				return 1500;
			case 8782:
				return 2400;
			case Contract.STEEL_BAR:
				return 500;
			default:
				return 0;
		}
	};

	@Test
	public void ranksTheTiersYouHaveDoneByCoinsAnExperiencePoint()
	{
		ContractBook book = new ContractBook();
		// Adept: 10 teak and a steel bar for 1,000 xp, a loop of 4 minutes.
		book.record(Contract.Tier.ADEPT, 1000, 10, 1, 240);
		// Expert: 10 mahogany for 2,000 xp, untimed.
		book.record(Contract.Tier.EXPERT, 2000, 10, 0, 0);
		List<ContractBook.Row> rows = book.rank(PRICES, 75);
		assertEquals(4, rows.size());
		ContractBook.Row first = rows.get(0);
		assertSame(Contract.Tier.EXPERT, first.getTier());
		assertEquals(24_000, first.getCoinsEach(), 0.01);
		assertEquals(12.0, first.getPerXp(), 0.001);
		assertEquals("untimed: no rate", 0, first.getXpPerHour(), 0);
		ContractBook.Row second = rows.get(1);
		assertSame(Contract.Tier.ADEPT, second.getTier());
		assertEquals(15.5, second.getPerXp(), 0.001);
		assertEquals(15_000, second.getXpPerHour(), 0.01);
		// Tiers not done yet follow, highest first, all within reach at 75.
		assertSame(Contract.Tier.NOVICE, rows.get(2).getTier());
		assertFalse(rows.get(2).isKnown());
		assertTrue(rows.get(3).isUnlocked());
	}

	@Test
	public void tiersOutOfReachComeLast()
	{
		ContractBook book = new ContractBook();
		book.record(Contract.Tier.NOVICE, 500, 8, 0, 300);
		List<ContractBook.Row> rows = book.rank(PRICES, 30);
		assertSame(Contract.Tier.NOVICE, rows.get(0).getTier());
		assertSame(Contract.Tier.BEGINNER, rows.get(1).getTier());
		assertFalse(rows.get(2).isUnlocked());
		assertFalse(rows.get(3).isUnlocked());
	}

	@Test
	public void anUnpricedPlankRanksNothingRatherThanCallingItFree()
	{
		ContractBook book = new ContractBook();
		book.record(Contract.Tier.EXPERT, 2000, 10, 0, 0);
		assertTrue(book.rank(id -> id == 8782 ? 0 : 500, 80).isEmpty());
	}

	@Test
	public void leavesOutWhatNoContractGivesAndTimesOnlyRealLoops()
	{
		ContractBook book = new ContractBook();
		assertFalse("no experience", book.record(Contract.Tier.ADEPT, 0, 10, 0, 100));
		assertFalse("POH training mixed in", book.record(Contract.Tier.ADEPT, 50_000, 10, 0, 100));
		assertFalse(book.record(null, 900, 10, 0, 100));
		assertTrue(book.isEmpty());
		assertTrue(book.record(Contract.Tier.ADEPT, 900, 10, 0, ContractBook.MAX_LOOP_SECONDS + 1));
		assertEquals("a long break is not a loop", 0, book.tally(Contract.Tier.ADEPT).secondsEach(), 0);
	}

	@Test
	public void savesAndReadsBackAndDropsDamage()
	{
		ContractBook book = new ContractBook();
		book.record(Contract.Tier.ADEPT, 1000, 10, 1, 240);
		book.record(Contract.Tier.ADEPT, 1200, 12, 0, 0);
		String saved = book.encode();
		assertEquals("ADEPT=2,2200,22,1,1,240", saved);
		ContractBook read = ContractBook.decode(saved + ";EXPERT=x,1,2,3,4,5;NOPE=1,1,1,1,1,1;BEGINNER=1,100,5,0,3,9");
		assertEquals(2, read.tally(Contract.Tier.ADEPT).getContracts());
		assertEquals(11, read.tally(Contract.Tier.ADEPT).planksEach(), 0.001);
		assertNull(read.tally(Contract.Tier.EXPERT));
		assertNull("more timed than done is damage", read.tally(Contract.Tier.BEGINNER));
		assertTrue(ContractBook.decode(null).isEmpty());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class ContractTest
{
	@Test
	public void everyHouseHasAtMostEightHotspotsWithUniqueObjects()
	{
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		for (Home h : Home.values())
		{
			assertTrue(h.name(), h.hotspotCount() <= Home.HOTSPOTS);
			for (int i = 0; i < h.hotspotCount(); i++)
			{
				assertTrue("duplicate " + h.hotspot(i).getObjectId(), seen.add(h.hotspot(i).getObjectId()));
				assertEquals(i, h.indexOf(h.hotspot(i).getObjectId()));
			}
		}
	}

	@Test
	public void tiersByLevel()
	{
		assertEquals(Contract.Tier.BEGINNER, Contract.Tier.forLevel(1));
		assertEquals(Contract.Tier.NOVICE, Contract.Tier.forLevel(49));
		assertEquals(Contract.Tier.ADEPT, Contract.Tier.forLevel(50));
		assertEquals(Contract.Tier.EXPERT, Contract.Tier.forLevel(99));
		assertEquals(5, Contract.Tier.EXPERT.points());
	}

	@Test
	public void noContractSendsToAContractor()
	{
		Contract.Snapshot s = new Contract.Snapshot();
		s.constructionLevel = 72;
		Step step = Contract.next(null, s);
		assertEquals(Step.Target.CONTRACTOR, step.getTarget());
		assertTrue(step.getDetail().contains("an expert contract"));
	}

	@Test
	public void countsPlanksAndSteelFromTheHotspots()
	{
		Contract c = new Contract(Home.LARRY, Contract.Tier.ADEPT);
		// Larry: SB, B2, B2, B3, RP, B3, RP.
		int[] v = {1, 3, 2, 4, 1, 6, 0, 0};
		assertEquals(2 + 3 + 1, c.planksNeeded(v));
		assertEquals(1, c.steelNeeded(v));
		assertEquals(4, c.remaining(v).size());
	}

	@Test
	public void asksForMissingMaterialsBeforeTravelling()
	{
		Contract c = new Contract(Home.LARRY, Contract.Tier.ADEPT);
		Contract.Snapshot s = new Contract.Snapshot();
		s.values = new int[]{1, 3, 2, 4, 1, 6, 0, 0};
		s.planks = 2;
		Step step = Contract.next(c, s);
		assertEquals("Fetch", step.getVerb());
		assertTrue(step.getTitle(), step.getTitle().contains("4 teak planks and 1 steel bar"));
		assertTrue(step.hasItem(8780));
		s.planks = 6;
		s.steelBars = 1;
		assertEquals(Step.Target.HOME, Contract.next(c, s).getTarget());
		s.atHome = true;
		assertEquals(Step.Target.HOTSPOT, Contract.next(c, s).getTarget());
	}

	@Test
	public void reportsWhenEverythingIsDone()
	{
		Contract c = new Contract(Home.NORMAN, Contract.Tier.EXPERT);
		Contract.Snapshot s = new Contract.Snapshot();
		s.values = new int[]{2, 2, 8, 8, 8, 8, 8, 0};
		Step step = Contract.next(c, s);
		assertEquals(Step.Target.CLIENT, step.getTarget());
		assertTrue(step.getDetail().contains("upstairs"));
		assertEquals(Contract.Tier.EXPERT, Contract.tierFromValues(s.values));
		assertNull(Contract.tierFromValues(new int[8]));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class FiguresTest
{
	@Test
	public void countsAreExactUntilTenThousand()
	{
		assertEquals("0", Figures.count(0));
		assertEquals("9,999", Figures.count(9_999));
		assertEquals("68k", Figures.count(68_040));
		assertEquals("142k", Figures.count(142_400));
	}

	@Test
	public void millionsAreRoundedNotCutAndNeverWrittenAsThousands()
	{
		// The old panel wrote 1,234,567 xp as "1234k" and 12,900,000 as "12M".
		assertEquals("1.2M", Figures.count(1_234_567));
		assertEquals("12.9M", Figures.count(12_900_000));
		assertEquals("1.0M", Figures.count(999_960));
		assertEquals("999k", Figures.count(999_400));
		assertEquals("1.00B", Figures.count(999_960_000));
		assertEquals("2.15B", Figures.count(2_147_483_647L));
	}

	@Test
	public void briefFiguresShortenFromTenThousand()
	{
		assertEquals("9,870", Figures.brief(9_870));
		assertEquals("41k", Figures.brief(41_400));
		assertEquals("-104k", Figures.brief(-104_276));
		assertEquals("+9,870", Figures.signed(9_870));
		assertEquals("-104k", Figures.signed(-104_276));
		assertEquals("+0", Figures.signed(0));
	}

	@Test
	public void aPairSharesTheLargerOnesUnit()
	{
		assertEquals("612 / 1,800", Figures.pair(612, 1_800));
		assertEquals("41k / 993k", Figures.pair(41_000, 993_000));
		// Not "9,870 / 41k" nor "0k / 41k".
		assertEquals("10k / 41k", Figures.pair(9_870, 41_000));
		assertEquals("300 / 41k", Figures.pair(300, 41_000));
		assertEquals("1.2M / 13.0M", Figures.pair(1_234_567, 13_034_431));
		assertEquals("12k / 13.0M", Figures.pair(12_000, 13_034_431));
		assertEquals("0 / 26", Figures.pair(0, 26));
	}

	@Test
	public void aPairShortOfItsGoalNeverReadsFull()
	{
		// 9,600 nuggets of 10,000 read "10k / 10k", and 12,980,000 xp of 99 read "13.0M / 13.0M".
		assertEquals("9k / 10k", Figures.pair(9_600, 10_000));
		assertEquals("12.9M / 13.0M", Figures.pair(12_980_000, 13_034_431));
		assertEquals("13.0M / 13.0M", Figures.pair(13_034_431, 13_034_431));
		assertEquals("10k / 10k", Figures.pair(10_400, 10_000));
		assertEquals("0.9M / 1.0M", Figures.pair(999_600, 1_000_000));
		assertEquals("1.99B / 2.00B", Figures.pair(1_999_999_999L, 2_000_000_000L));
		for (long need : new long[]{10_000, 41_000, 999_000, 1_000_000, 13_034_431, 2_000_000_000L})
		{
			for (long have = Math.max(0, need - 60_000); have < need; have += Math.max(1, need / 997))
			{
				String[] two = Figures.pair(have, need).split(" / ");
				org.junit.Assert.assertNotEquals(have + " of " + need, two[1], two[0]);
			}
			String[] two = Figures.pair(need - 1, need).split(" / ");
			org.junit.Assert.assertNotEquals((need - 1) + " of " + need, two[1], two[0]);
		}
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/** The suite's one number format, as every Codex plugin with coin or xp figures pins it. */
public class FormatTest
{
	@Test
	public void amountsFollowTheSuiteRule()
	{
		// In full below 10,000; whole k below a million; M to one decimal; B to two.
		assertEquals("8,240", Figures.count(8_240));
		assertEquals("10k", Figures.count(10_000));
		assertEquals("41k", Figures.count(41_200));
		assertEquals("96k", Figures.count(95_700));
		assertEquals("412k", Figures.count(412_000));
		assertEquals("1.2M", Figures.count(1_240_000));
		assertEquals("26.0M", Figures.count(26_000_000));
		assertEquals("812.4M", Figures.count(812_400_000));
		assertEquals("2.10B", Figures.count(2_100_000_000L));
		// Rounding that reaches the next unit is written in it.
		assertEquals("100k", Figures.count(99_960));
		assertEquals("1.0M", Figures.count(999_600));
		assertEquals("999k", Figures.count(999_499));
		assertEquals("1.00B", Figures.count(999_960_000));
		assertEquals("-45k", Figures.brief(-45_200));
		assertEquals("+880k", Figures.signed(880_000));
		// Tiles, lines and gauges all write a count the same way.
		assertEquals(Figures.brief(68_040), Figures.count(68_040));
		assertEquals("41k / 993k", Figures.pair(41_000, 993_000));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class FurnaceCycleTest
{
	private static FurnaceCycle.Snapshot snap(Bar bar)
	{
		FurnaceCycle.Snapshot s = new FurnaceCycle.Snapshot();
		s.bar = bar;
		s.coffer = 50_000;
		s.free = 26;
		s.fixed = 2;
		s.iceGlovesWorn = true;
		return s;
	}

	@Test
	public void steelWithACoalBagNeverNeedsACoalTrip()
	{
		FurnaceCycle.Snapshot s = snap(Bar.STEEL);
		s.coalBag = true;
		s.furnaceCoal = 0;
		assertFalse(FurnaceCycle.coalRunNext(s));
	}

	@Test
	public void runiteAlternatesCoalTrips()
	{
		FurnaceCycle.Snapshot s = snap(Bar.RUNITE);
		s.coalBag = true;
		s.furnaceCoal = 0;
		assertTrue(FurnaceCycle.coalRunNext(s));
		// 26 ore burns 104 coal; with a full bag of 27, 77 must already be waiting.
		s.furnaceCoal = 77;
		assertFalse(FurnaceCycle.coalRunNext(s));
		s.furnaceCoal = 76;
		assertTrue(FurnaceCycle.coalRunNext(s));
	}

	/**
	 * Plays runite out trip by trip as the pilot calls them: coal trips bring a pack and a bag,
	 * ore trips burn a load less what the bag brings. About one and a half coal trips go to each
	 * ore trip, the same as the "what pays" ranking counts, not three.
	 */
	@Test
	public void runiteTakesAboutOneAndAHalfCoalTripsAnOreTrip()
	{
		FurnaceCycle.Snapshot s = snap(Bar.RUNITE);
		s.coalBag = true;
		s.bagCapacity = 27;
		s.furnaceCoal = 0;
		int coalTrips = 0;
		int oreTrips = 0;
		while (oreTrips < 1000)
		{
			if (FurnaceCycle.coalRunNext(s))
			{
				s.furnaceCoal += FurnaceCycle.coalTrip(s);
				coalTrips++;
			}
			else
			{
				s.furnaceCoal -= Bar.RUNITE.getCoal() * FurnaceCycle.load(s) - s.bagCapacity;
				oreTrips++;
			}
		}
		double perOre = coalTrips / (double) oreTrips;
		assertEquals(1.45, perOre, 0.01);
		assertEquals(BarPick.coalTrips(Bar.RUNITE.getCoal(), FurnaceCycle.load(s), 27), perOre, 0.01);
	}

	@Test
	public void atTheBankFillsTheBagThenWithdraws()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.MITHRIL);
		s.bankOpen = true;
		s.coalBag = true;
		s.bagCoal = 0;
		s.furnaceCoal = 100;
		Step step = c.next(s);
		assertEquals("Fill", step.getVerb());
		s.bagCoal = 27;
		step = c.next(s);
		assertEquals("Withdraw", step.getVerb());
		assertTrue(step.hasItem(Bar.MITHRIL.getOre()));
		s.ore = 26;
		s.free = 0;
		assertEquals(Step.Target.BELT, c.next(s).getTarget());
	}

	@Test
	public void depositsBarsBeforeAnythingElseAtTheBank()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.STEEL);
		s.bankOpen = true;
		s.bars = 26;
		s.free = 0;
		Step step = c.next(s);
		assertEquals("Deposit", step.getVerb());
		assertTrue(step.hasItem(Bar.STEEL.getBar()));
	}

	@Test
	public void loadsThenEmptiesTheBagThenWaitsForBars()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.STEEL);
		s.coalBag = true;
		s.ore = 26;
		s.free = 0;
		s.bagCoal = 27;
		assertEquals(Step.Target.BELT, c.next(s).getTarget());
		s.ore = 0;
		s.free = 26;
		Step empty = c.next(s);
		assertEquals("Empty", empty.getVerb());
		s.bagCoal = 0;
		s.furnaceOre = 26;
		s.furnaceCoal = 27;
		Step wait = c.next(s);
		assertTrue(wait.isWaiting());
		assertEquals(Step.Target.DISPENSER, wait.getTarget());
	}

	@Test
	public void takesBarsWhenReadyAndAsksForIceGlovesWhenHot()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.GOLD);
		s.dispenserBars = 26;
		s.dispenserState = 2;
		s.iceGlovesWorn = false;
		s.iceGlovesCarried = true;
		Step equip = c.next(s);
		assertEquals("Equip", equip.getVerb());
		assertTrue(equip.hasItem(ItemIds.ICE_GLOVES));
		s.iceGlovesWorn = true;
		assertEquals("Take", c.next(s).getVerb());
		s.dispenserState = 3;
		s.iceGlovesWorn = false;
		assertEquals("Take", c.next(s).getVerb());
	}

	@Test
	public void goldAsksForGauntletsBeforeLoading()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.GOLD);
		s.ore = 26;
		s.free = 0;
		s.goldsmithCarried = true;
		Step step = c.next(s);
		assertTrue(step.hasItem(ItemIds.GOLDSMITH_GAUNTLETS));
		s.goldsmithWorn = true;
		s.goldsmithCarried = false;
		assertEquals(Step.Target.BELT, c.next(s).getTarget());
	}

	@Test
	public void lowCofferComesFirst()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.STEEL);
		s.coffer = 0;
		s.ore = 26;
		Step step = c.next(s);
		assertEquals(Step.Target.COFFER, step.getTarget());
		assertTrue(step.getDetail().contains("stops"));
	}

	@Test
	public void beltFlightIsFollowed()
	{
		FurnaceCycle c = new FurnaceCycle();
		c.observe(52, 0, true);
		c.observe(0, 0, true);
		assertEquals(52, c.getOnBelt());
		c.observe(0, 52, true);
		assertEquals(0, c.getOnBelt());
	}

	@Test
	public void emptyHandedGoesToTheBank()
	{
		FurnaceCycle c = new FurnaceCycle();
		FurnaceCycle.Snapshot s = snap(Bar.ADAMANTITE);
		Step step = c.next(s);
		assertEquals(Step.Target.BANK, step.getTarget());
		assertTrue(step.getDetail().contains("coal"));
	}

	@Test
	public void aHopKeepsOreOnTheBeltButReadsAfresh()
	{
		FurnaceCycle c = new FurnaceCycle();
		c.observe(52, 0, true);
		c.observe(0, 0, true);
		c.relog();
		// Back in after the login grace with a fresh load carried: only a base, no new load.
		c.observe(27, 0, true);
		c.observe(27, 0, true);
		assertEquals(52, c.getOnBelt());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class GoalTest
{
	private static Goals.Input owning(Integer... ids)
	{
		Set<Integer> set = new HashSet<>(Arrays.asList(ids));
		Goals.Input in = new Goals.Input();
		in.have = set::contains;
		in.skill = "Mining";
		return in;
	}

	@Test
	public void experienceTableMatchesTheGame()
	{
		assertEquals(0, Goals.xpFor(1));
		assertEquals(83, Goals.xpFor(2));
		assertEquals(13_034_431, Goals.xpFor(99));
		assertEquals(737_627, Goals.xpFor(70));
		for (int level = 1; level <= 99; level++)
		{
			assertEquals(net.runelite.api.Experience.getXpForLevel(level), Goals.xpFor(level));
		}
		assertEquals(69, Goals.levelFor(Goals.xpFor(69)));
		assertEquals(68, Goals.levelFor(Goals.xpFor(69) - 1));
		assertEquals(99, Goals.levelFor(200_000_000));
	}

	@Test
	public void nextRewardSkipsTheKitOnceItIsAllOwned()
	{
		Goals.Input in = owning(12013, 12014, 12015, 25555);
		in.balance = 30;
		Goal g = Goals.motherlode(Goals.Choice.NEXT_REWARD, in);
		assertEquals("Coal bag", g.getTitle());
		assertEquals(100, g.getNeed());
		assertEquals(70, g.toGo());
	}

	@Test
	public void kitCountsOnlyThePiecesStillMissing()
	{
		// The helmet is in the bank; the gilded boots count as boots.
		Goals.Input in = owning(12013, 25555);
		in.balance = 64;
		in.currencyPerHour = 12;
		Goal g = Goals.motherlode(Goals.Choice.NEXT_REWARD, in);
		assertEquals("Prospector kit", g.getTitle());
		assertEquals(110, g.getNeed());
		assertEquals(64, g.getHave());
		assertEquals(46, g.toGo());
		assertEquals(4, g.getPieces().size());
		assertTrue(g.getPieces().get(0).isOwned());
		assertFalse(g.getPieces().get(1).isOwned());
		assertEquals(230, g.minutesLeft());
		assertEquals("46 nuggets to go · about 3h 50m", g.describe());
	}

	@Test
	public void everythingOwnedBecomesTheNextLevel()
	{
		Goals.Input in = owning(12013, 12014, 12015, 12016, 12019, 24481);
		in.ownedOtherwise = EnumSet.of(Goal.Reward.BIGGER_SACK);
		in.xp = Goals.xpFor(80) + 1000;
		Goal g = Goals.motherlode(Goals.Choice.NEXT_REWARD, in);
		assertEquals("Mining level 81", g.getTitle());
		assertEquals(Goals.xpFor(81) - Goals.xpFor(80), g.getNeed());
		assertEquals(1000, g.getHave());
	}

	@Test
	public void homesGoalCountsContractsAtYourTier()
	{
		Goals.Input in = owning();
		in.balance = 100;
		in.currencyPerRound = 5;
		in.roundName = "expert contract";
		Goal g = Goals.homes(Goals.Choice.CARPENTERS_OUTFIT, in);
		assertEquals("Carpenter's outfit", g.getTitle());
		assertEquals(2000, g.getNeed());
		assertEquals(380, g.roundsLeft());
		assertEquals("1,900 points to go · 380 expert contracts", g.describe());
	}

	@Test
	public void enoughInHandIsDone()
	{
		Goals.Input in = owning();
		in.balance = 400;
		Goal g = Goals.homes(Goals.Choice.PLANK_SACK, in);
		assertTrue(g.done());
		assertEquals(350, g.getHave());
		assertEquals("You have enough: off to the shop", g.describe());
	}

	@Test
	public void otherShopsGoalFallsBackAndOffIsNothing()
	{
		Goals.Input in = owning();
		assertEquals("Plank sack", Goals.homes(Goals.Choice.COAL_BAG, in).getTitle());
		assertNull(Goals.homes(Goals.Choice.OFF, in));
		assertNull(Goals.homes(null, in));
	}

	@Test
	public void levelTargetsAndTheTop()
	{
		Goals.Input in = owning();
		in.skill = "Smithing";
		in.xp = Goals.xpFor(60);
		in.targetLevel = 70;
		in.xpPerHour = 100_000;
		Goal g = Goals.furnace(in);
		assertEquals("Smithing level 70", g.getTitle());
		assertEquals(Goals.xpFor(70) - Goals.xpFor(60), g.toGo());
		assertEquals((long) Math.ceil((Goals.xpFor(70) - Goals.xpFor(60)) * 60 / 100_000.0), g.minutesLeft());
		in.xp = Goals.xpFor(99);
		in.targetLevel = 0;
		assertNull(Goals.furnace(in));
	}

	@Test
	public void durations()
	{
		assertEquals("1m", Goal.duration(0));
		assertEquals("45m", Goal.duration(45));
		assertEquals("2h", Goal.duration(120));
		assertEquals("2h 10m", Goal.duration(130));
		assertEquals("120h", Goal.duration(7200));
	}

	@Test
	public void aChosenRewardYouOwnSaysSo()
	{
		Goals.Input in = owning(12019);
		in.balance = 500;
		Goal g = Goals.motherlode(Goals.Choice.COAL_BAG, in);
		assertTrue(g.done());
		assertEquals("All owned. Pick another goal in the settings", g.describe());
	}

	@Test
	public void theOffHandSawStillCountsAsAmysSaw()
	{
		// ItemID.WEARABLE_SAW_OFFHAND: the saw after it is made into an off-hand.
		org.junit.Assert.assertTrue(Goal.Reward.AMYS_SAW.ownedBy(id -> id == 29774));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class MotherlodeCycleTest
{
	private static MotherlodeCycle.Snapshot snap(int payDirt, int free, int loot, int sack)
	{
		MotherlodeCycle.Snapshot s = new MotherlodeCycle.Snapshot();
		s.payDirt = payDirt;
		s.free = free;
		s.loot = loot;
		s.sack = sack;
		return s;
	}

	@Test
	public void minesUntilTheInventoryIsFull()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		Step s = c.next(snap(10, 17, 0, 0));
		assertEquals(Step.Target.VEIN, s.getTarget());
		assertTrue(s.getDetail().startsWith("17 more"));
		assertEquals(Step.Target.HOPPER, c.next(snap(27, 0, 0, 0)).getTarget());
	}

	@Test
	public void sizesTheLastLoadToFillTheSackExactly()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		// 89 in the sack leaves room for 19: deposit at 19, not 27.
		Step s = c.next(snap(5, 22, 0, 89));
		assertEquals(Step.Target.VEIN, s.getTarget());
		assertTrue(s.getDetail(), s.getDetail().contains("14 more"));
		assertTrue(s.getDetail().contains("fills the sack"));
		assertEquals(Step.Target.HOPPER, c.next(snap(19, 8, 0, 89)).getTarget());
	}

	@Test
	public void countsPayDirtInFlightAgainstTheSack()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		c.observe(27, 54, true, false);
		c.observe(0, 54, true, false);
		assertEquals(27, c.getInFlight());
		assertEquals(27, c.room(snap(0, 27, 0, 54)));
		c.observe(0, 70, true, false);
		assertEquals(11, c.getInFlight());
		assertEquals(27, c.getDeposited());
	}

	@Test
	public void forgetsFlightThatNeverLands()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		c.observe(27, 0, true, false);
		c.observe(0, 0, true, false);
		for (int i = 0; i <= MotherlodeCycle.FLIGHT_TIMEOUT; i++)
		{
			c.observe(0, 0, false, false);
		}
		assertEquals(0, c.getInFlight());
	}

	@Test
	public void holdsFlightWhileTheWheelIsStopped()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		c.observe(27, 0, true, true);
		c.observe(0, 0, true, true);
		for (int i = 0; i < 200; i++)
		{
			c.observe(0, 0, false, true);
		}
		assertEquals(27, c.getInFlight());
		MotherlodeCycle.Snapshot s = snap(0, 27, 0, 0);
		s.brokenStruts = 2;
		assertEquals(Step.Target.STRUT, c.next(s).getTarget());
	}

	@Test
	public void emptiesTheSackOnceFullThenGoesBackToMining()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		assertEquals(Step.Target.SACK, c.next(snap(0, 27, 0, 108)).getTarget());
		assertTrue(c.isEmptying());
		// Collected 27: inventory full of ore, bank it.
		assertEquals(Step.Target.BANK, c.next(snap(0, 0, 27, 81)).getTarget());
		// After banking, back to the sack, not to the veins, though there is room.
		assertEquals(Step.Target.SACK, c.next(snap(0, 27, 0, 81)).getTarget());
		assertEquals(Step.Target.BANK, c.next(snap(0, 0, 27, 0)).getTarget());
		Step s = c.next(snap(0, 27, 0, 0));
		assertEquals(Step.Target.VEIN, s.getTarget());
		assertFalse(c.isEmptying());
	}

	@Test
	public void bankedEarlyWhenOverfull()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		// The sack is full yet 27 pay-dirt is carried: it cannot go in, so bank it.
		assertEquals(Step.Target.BANK, c.next(snap(27, 0, 0, 108)).getTarget());
	}

	@Test
	public void biggerSackTakesMore()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		MotherlodeCycle.Snapshot s = snap(0, 27, 0, 108);
		s.capacity = 189;
		assertEquals(Step.Target.VEIN, c.next(s).getTarget());
	}

	@Test
	public void aHopKeepsPayDirtInFlightButReadsAfresh()
	{
		MotherlodeCycle c = new MotherlodeCycle();
		c.observe(27, 54, true, false);
		c.observe(0, 54, true, false);
		c.relog();
		// Back in after the login grace: the first readings are only a base.
		c.observe(0, 54, true, false);
		c.observe(0, 54, true, false);
		assertEquals("still on its way, and no deposit counted twice", 27, c.getInFlight());
		assertEquals(27, c.getDeposited());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Test;

public class NavigatorGoalsTest
{
	/** A board as Codex Navigator writes it (GoalBoard, version 1), extra fields and all. */
	private static final String BOARD = "{\"version\":1,\"focus\":\"quest:Dragon Slayer II\",\"goals\":["
		+ "{\"key\":\"diary:Varrock Hard\",\"type\":\"diary\",\"title\":\"Varrock Hard\",\"complete\":false,\"progress\":0.4,"
		+ "\"next\":\"Train Smithing to 60\",\"hoursLeft\":6.5,\"skills\":{\"Smithing\":60,\"Agility\":51},\"quests\":[]},"
		+ "{\"key\":\"quest:Dragon Slayer II\",\"type\":\"quest\",\"title\":\"Dragon Slayer II\",\"complete\":false,\"progress\":0.2,"
		+ "\"next\":\"Train Smithing to 70\",\"hoursLeft\":30.0,\"skills\":{\"Smithing\":70,\"Mining\":68,\"Construction\":50},"
		+ "\"quests\":[\"Bone Voyage\",\"Dragon Slayer II\"]},"
		+ "{\"key\":\"quest:Done Deal\",\"type\":\"quest\",\"title\":\"Done Deal\",\"complete\":true,\"progress\":1.0,"
		+ "\"hoursLeft\":0.0,\"skills\":{},\"quests\":[],\"somethingNew\":[1,2]}]}";

	private static NavigatorGoals.Board board()
	{
		return new Gson().fromJson(BOARD, NavigatorGoals.Board.class);
	}

	@Test
	public void readsNavigatorsBoardAsItIsWritten()
	{
		NavigatorGoals.Board b = board();
		assertEquals(1, b.version);
		assertEquals(3, b.goals.size());
		assertEquals(Integer.valueOf(70), b.goals.get(1).skills.get("Smithing"));
		assertTrue(b.goals.get(2).complete);
	}

	@Test
	public void theFocusGoalComesFirst()
	{
		NavigatorGoals.Target t = NavigatorGoals.target(board(), "Smithing", 45);
		assertEquals(70, t.getLevel());
		assertEquals("Dragon Slayer II", t.getGoal());
		assertTrue(t.isFocus());
	}

	@Test
	public void otherwiseTheNearestLevelAboveYours()
	{
		NavigatorGoals.Board b = board();
		b.focus = null;
		NavigatorGoals.Target t = NavigatorGoals.target(b, "smithing", 45);
		assertEquals(60, t.getLevel());
		assertEquals("Varrock Hard", t.getGoal());
		assertFalse(t.isFocus());
		// Past 60 the next goal up is the focus-free 70.
		assertEquals(70, NavigatorGoals.target(b, "Smithing", 60).getLevel());
	}

	/**
	 * Contract: the board exactly as Codex Navigator's GoalBoard.of wrote it (Dragon Slayer II in
	 * focus and the Varrock Hard diary pinned, on an account with Smithing 45), unedited.
	 */
	private static final String WRITTEN = "{\"version\":1,\"focus\":\"quest:Dragon Slayer II\",\"goals\":[{\"key\":\"quest:Dragon Slayer II\",\"type\":\"quest\",\"title\":\"Dragon Slayer II\",\"complete\":false,\"progress\":0.0,\"next\":\"Start Shield of Arrav\",\"hoursLeft\":109.5,\"skills\":{\"Slayer\":18,\"Ranged\":30,\"Construction\":50,\"Firemaking\":49,\"Herblore\":45,\"Defence\":40,\"Prayer\":42,\"Cooking\":53,\"Strength\":50,\"Thieving\":60,\"Crafting\":62,\"Fishing\":53,\"Woodcutting\":55,\"Agility\":60,\"Hitpoints\":50,\"Smithing\":70,\"Mining\":68,\"Magic\":75},\"quests\":[\"Family Crest\",\"Shield of Arrav\",\"Lost City\",\"Merlin\\u0027s Crystal\",\"Dragon Slayer I\",\"Heroes\\u0027 Quest\",\"Druidic Ritual\",\"Jungle Potion\",\"Shilo Village\",\"Plague City\",\"Biohazard\",\"Underground Pass\",\"Waterfall Quest\",\"Legends\\u0027 Quest\",\"The Fremennik Trials\",\"Rune Mysteries\",\"Lunar Diplomacy\",\"Death Plateau\",\"Troll Stronghold\",\"Eadgar\\u0027s Ruse\",\"Dream Mentor\",\"Gertrude\\u0027s Cat\",\"Icthlarin\\u0027s Little Helper\",\"A Tail of Two Cats\",\"The Restless Ghost\",\"Ernest the Chicken\",\"Priest in Peril\",\"Animal Magnetism\",\"Ghosts Ahoy\",\"The Dig Site\",\"Bone Voyage\",\"X Marks the Spot\",\"Client of Kourend\",\"Dragon Slayer II\"]},{\"key\":\"diary:Varrock Hard\",\"type\":\"diary\",\"title\":\"Varrock Hard Diary\",\"complete\":false,\"progress\":0.05,\"next\":\"Start Death Plateau\",\"hoursLeft\":46.5,\"skills\":{\"Fletching\":10,\"Herblore\":10,\"Slayer\":10,\"Construction\":50,\"Ranged\":40,\"Thieving\":53,\"Firemaking\":60,\"Magic\":54,\"Prayer\":52,\"Agility\":51,\"Hunter\":66,\"Woodcutting\":60,\"Farming\":68},\"quests\":[\"The Dig Site\",\"Temple of Ikov\",\"The Tourist Trap\",\"Death Plateau\",\"Troll Stronghold\",\"Priest in Peril\",\"Waterfall Quest\",\"Desert Treasure I\"]}]}";

	@Test
	public void readsTheBoardNavigatorActuallyWrites()
	{
		NavigatorGoals.Board b = new Gson().fromJson(WRITTEN, NavigatorGoals.Board.class);
		assertEquals(1, b.version);
		assertEquals("quest:Dragon Slayer II", b.focus);
		NavigatorGoals.Target t = NavigatorGoals.target(b, net.runelite.api.Skill.SMITHING.getName(), 45);
		assertEquals(70, t.getLevel());
		assertEquals("Dragon Slayer II", t.getGoal());
		assertTrue(t.isFocus());
		// The diary needs no Smithing, so with the focus dropped nothing else asks for it.
		b.focus = null;
		assertEquals(70, NavigatorGoals.target(b, "Smithing", 45).getLevel());
		assertFalse(NavigatorGoals.target(b, "Smithing", 45).isFocus());
		assertEquals(66, NavigatorGoals.target(b, net.runelite.api.Skill.HUNTER.getName(), 1).getLevel());
	}

	@Test
	public void nothingWhenNoGoalNeedsTheSkill()
	{
		assertNull(NavigatorGoals.target(board(), "Smithing", 70));
		assertNull(NavigatorGoals.target(board(), "Fishing", 1));
		assertNull(NavigatorGoals.target(null, "Smithing", 1));
		assertNull(NavigatorGoals.target(new Gson().fromJson("{}", NavigatorGoals.Board.class), "Smithing", 1));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class OreHaulTest
{
	@Test
	public void countsOnlyWhatTheSackPaysOut()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{0, 0, 0, 0, 0}, false);
		// The sack pays out 14 coal, 3 gold and 2 mithril.
		h.observe(new int[]{14, 3, 2, 0, 0}, true);
		// Banked: counts fall, nothing earned.
		h.observe(new int[]{0, 0, 0, 0, 0}, false);
		h.observe(new int[]{0, 0, 0, 0, 0}, false);
		// Coal taken out of the bank is not a haul.
		h.observe(new int[]{20, 0, 0, 0, 0}, false);
		h.observe(new int[]{20, 0, 0, 0, 1}, true);
		assertEquals(20, h.count());
		// Coal 150, gold 160, mithril 120, runite 10,000.
		assertEquals(14 * 150 + 3 * 160 + 2 * 120 + 10_000, h.worth(id -> id == 453 ? 150 : id == 444 ? 160 : id == 447 ? 120 : id == 451 ? 10_000 : 0));
	}

	@Test
	public void orePackedATickAfterTheSackDropsStillCounts()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{0, 0, 0, 0, 0}, false);
		h.observe(new int[]{0, 0, 0, 0, 0}, true);
		h.observe(new int[]{10, 2, 0, 0, 0}, false);
		assertEquals(12, h.count());
		// Two ticks on, the window has shut.
		h.observe(new int[]{10, 2, 0, 0, 0}, false);
		h.observe(new int[]{30, 2, 0, 0, 0}, false);
		assertEquals(12, h.count());
	}

	@Test
	public void theFirstLookAndAReturnToTheMineCountNothing()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{27, 0, 0, 0, 0}, true);
		assertEquals(0, h.count());
		h.forget();
		h.observe(new int[]{28, 0, 0, 0, 0}, true);
		assertEquals(0, h.count());
		h.observe(new int[]{28, 1, 0, 0, 0}, true);
		assertEquals(1, h.count());
	}

	@Test
	public void aNewSessionStartsTheHaulAgain()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{0, 0, 0, 0, 0}, false);
		h.observe(new int[]{0, 0, 0, 0, 5}, true);
		h.clear();
		assertEquals(0, h.count());
		assertEquals(0, h.worth(id -> 10_000));
		// What is carried still stands as the base for the next payout.
		h.observe(new int[]{0, 0, 0, 0, 7}, true);
		assertEquals(2, h.count());
	}

	@Test
	public void coalThatGoesStraightIntoAnOpenCoalBagStillCounts()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{0, 0, 0, 0, 0}, 0, 0, true);
		// The sack gives 40: 27 coal fills the open bag, and 9 coal, 3 gold and 1 nugget land in the pack.
		h.observe(new int[]{9, 3, 0, 0, 0}, 1, 40, true);
		h.observe(new int[]{9, 3, 0, 0, 0}, 1, 0, true);
		assertEquals(39, h.count());
		assertEquals(36 * 150 + 3 * 160, h.worth(id -> id == 453 ? 150 : id == 444 ? 160 : 0));
	}

	@Test
	public void withoutAnOpenBagNothingIsGuessed()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{0, 0, 0, 0, 0}, 0, 0, false);
		// A closed bag takes nothing: the sack's 20 all land, or stay in the sack.
		h.observe(new int[]{12, 0, 0, 0, 0}, 0, 20, false);
		h.observe(new int[]{12, 0, 0, 0, 0}, 0, 0, false);
		assertEquals(12, h.count());
	}

	@Test
	public void aPayoutLandingOverTwoTicksIsNotCountedTwice()
	{
		OreHaul h = new OreHaul();
		h.observe(new int[]{0, 0, 0, 0, 0}, 0, 0, true);
		// The sack's count drops a tick before the pack fills.
		h.observe(new int[]{0, 0, 0, 0, 0}, 0, 30, true);
		h.observe(new int[]{3, 0, 0, 0, 0}, 0, 0, true);
		assertEquals("27 in the bag, 3 in the pack", 30, h.count());
		h.observe(new int[]{3, 0, 0, 0, 0}, 0, 0, true);
		assertEquals(30, h.count());
		// The first look in the mine is no base for a guess either.
		OreHaul fresh = new OreHaul();
		fresh.observe(new int[]{0, 0, 0, 0, 0}, 0, 30, true);
		fresh.observe(new int[]{0, 0, 0, 0, 0}, 0, 0, true);
		assertEquals(0, fresh.count());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import org.junit.Test;

public class OwnedTest
{
	private static final EnumSet<Goal.Reward> NONE = EnumSet.noneOf(Goal.Reward.class);

	@Test
	public void aRewardSeenOnceStaysOwnedOnceItIsInTheCostumeRoom()
	{
		Owned o = new Owned();
		EnumSet<Goal.Reward> shirt = EnumSet.of(Goal.Reward.CARPENTERS_SHIRT);
		assertTrue(o.see(shirt, NONE, false));
		assertFalse("already remembered", o.see(shirt, NONE, false));
		// Put away in the costume room: out of sight, still owned.
		o.see(NONE, NONE, false);
		assertTrue(o.has(Goal.Reward.CARPENTERS_SHIRT));
		assertTrue(o.hasItem(24874));
		assertFalse(o.hasItem(24872));
	}

	@Test
	public void aRewardOutOfGroupStorageMayBeAGroupMatesAndIsNotRemembered()
	{
		Owned o = new Owned();
		EnumSet<Goal.Reward> saw = EnumSet.of(Goal.Reward.AMYS_SAW);
		assertFalse(o.see(saw, saw, true));
		// Still carried after the storage shuts: not remembered this session.
		assertFalse(o.see(saw, NONE, false));
		assertFalse(o.has(Goal.Reward.AMYS_SAW));
		// Your own, already remembered, is not taken back by passing through group storage.
		Owned mine = Owned.decode("AMYS_SAW");
		mine.see(saw, saw, true);
		assertTrue(mine.has(Goal.Reward.AMYS_SAW));
	}

	@Test
	public void savesNamesAndKeepsTheUnknownForTheVersionThatWroteThem()
	{
		Owned o = new Owned();
		o.see(EnumSet.of(Goal.Reward.PLANK_SACK, Goal.Reward.PROSPECTOR_HELMET, Goal.Reward.BIGGER_SACK), NONE, false);
		assertEquals("the bigger sack is owned by a varbit, not an item", "PROSPECTOR_HELMET,PLANK_SACK", o.encode());
		Owned read = Owned.decode("PLANK_SACK,NOT_A_REWARD,,bigger_sack");
		assertTrue(read.has(Goal.Reward.PLANK_SACK));
		assertFalse(read.has(Goal.Reward.BIGGER_SACK));
		// A name this version does not know counts for nothing, but is saved again as it was.
		assertEquals("PLANK_SACK,NOT_A_REWARD", read.encode());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PaceTest
{
	/** Feeds n ticks of one stage and leg. */
	private static Pace.Round run(Pace p, int n, int stage, String leg, String place, boolean still, int moved, int route, int units)
	{
		Pace.Round r = null;
		for (int i = 0; i < n; i++)
		{
			Pace.Round got = p.tick(stage, leg, place, still, false, moved, route, units, null);
			if (got != null)
			{
				r = got;
			}
		}
		return r;
	}

	@Test
	public void roundsAreCutWhenTheLoopComesBackToTheStart()
	{
		Pace p = new Pace();
		assertNull(run(p, 10, 0, "mine", "a vein", false, 0, -1, 0));
		assertNull(run(p, 5, 1, "hopper", "the hopper", false, 1, 5, 0));
		Pace.Round r = run(p, 1, 0, "mine", "a vein", false, 0, -1, 27);
		assertNotNull(r);
		assertEquals(15, r.ticks);
		assertEquals("3/27", r.kind);
		assertTrue(r.isBest());
	}

	@Test
	public void thePartRoundBeforeTheFirstStartIsSkipped()
	{
		Pace p = new Pace();
		assertNull(run(p, 8, 2, "sack", "the sack", false, 0, -1, 0));
		assertNull(run(p, 3, 0, "mine", "a vein", false, 0, -1, 0));
		assertNull(run(p, 3, 1, "hopper", "the hopper", false, 0, -1, 0));
		Pace.Round r = run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		assertEquals(6, r.ticks);
	}

	@Test
	public void standingStillPastTheFirstTickIsCountedWhereItHappened()
	{
		Pace p = new Pace();
		run(p, 2, 0, "mine", "a vein", false, 0, -1, 0);
		run(p, 6, 1, "bank", "the bank", true, 0, -1, 0);
		Pace.Round r = run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		assertEquals(5, r.idle);
		assertEquals("the bank", r.idlePlace);
		assertEquals("Stood still 5 ticks at the bank", r.advice());
	}

	@Test
	public void waitingIsNotStandingStill()
	{
		Pace p = new Pace();
		run(p, 1, 0, "bank", "the bank", false, 0, -1, 0);
		for (int i = 0; i < 6; i++)
		{
			p.tick(1, "bars", "the dispenser", true, true, 0, -1, 0, null);
		}
		Pace.Round r = run(p, 1, 0, "bank", "the bank", false, 0, -1, 0);
		assertEquals(0, r.idle);
	}

	@Test
	public void detoursAreTilesWalkedBeyondTheShortestWay()
	{
		Pace p = new Pace();
		run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		// The hopper was 6 tiles away; 11 were walked.
		run(p, 11, 1, "hopper", "the hopper", false, 1, 6, 0);
		Pace.Round r = run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		assertEquals(5, r.extraTiles);
		assertEquals("Walked 5 tiles more than needed to the hopper", r.advice());
	}

	@Test
	public void aTileOrTwoOverIsForgiven()
	{
		Pace p = new Pace();
		run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		run(p, 8, 1, "hopper", "the hopper", false, 1, 6, 0);
		Pace.Round r = run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		assertEquals(0, r.extraTiles);
	}

	@Test
	public void roundsAreComparedOnlyWithTheirOwnKind()
	{
		Pace p = new Pace();
		run(p, 10, 0, "mine", "a vein", false, 0, -1, 0);
		run(p, 10, 1, "hopper", "the hopper", false, 0, -1, 0);
		Pace.Round load = run(p, 1, 0, "mine", "a vein", false, 0, -1, 27);
		run(p, 5, 1, "hopper", "the hopper", false, 0, -1, 27);
		run(p, 5, 2, "sack", "the sack", false, 0, -1, 27);
		Pace.Round empty = run(p, 1, 0, "mine", "a vein", false, 0, -1, 54);
		assertEquals("3/27", load.kind);
		assertEquals("7/27", empty.kind);
		assertEquals(0, empty.bestBefore);
		assertEquals(20, p.best("3/27"));
	}

	@Test
	public void aSlowerRoundKeepsTheBestAndAQuickerOneTakesIt()
	{
		Pace p = new Pace();
		run(p, 1, 0, "a", "x", false, 0, -1, 0);
		run(p, 9, 1, "b", "y", false, 0, -1, 0);
		run(p, 1, 0, "a", "x", false, 0, -1, 1);
		run(p, 11, 1, "b", "y", false, 0, -1, 1);
		Pace.Round slower = run(p, 1, 0, "a", "x", false, 0, -1, 2);
		assertFalse(slower.isBest());
		assertEquals(10, slower.bestBefore);
		run(p, 7, 1, "b", "y", false, 0, -1, 2);
		Pace.Round quicker = run(p, 1, 0, "a", "x", false, 0, -1, 3);
		assertTrue(quicker.isBest());
		assertEquals(8, p.best("3/1"));
	}

	@Test
	public void aRoundWithABreakIsLeftOut()
	{
		Pace p = new Pace();
		run(p, 1, 0, "a", "x", false, 0, -1, 0);
		run(p, 9, 1, "b", "y", false, 0, -1, 0);
		Pace.Round first = run(p, 1, 0, "a", "x", false, 0, -1, 1);
		run(p, 99, 1, "b", "y", false, 0, -1, 1);
		Pace.Round slow = run(p, 1, 0, "a", "x", false, 0, -1, 2);
		assertNotNull(first);
		assertTrue(slow.hadBreak);
		assertFalse(slow.isBest());
		assertEquals(10, p.typical("3/1"));
	}

	@Test
	public void theContractARoundWasForIsKept()
	{
		Pace p = new Pace();
		p.tick(0, "job", "the contractor", false, false, 0, -1, 0, null);
		p.tick(1, "go", "the house", false, false, 0, -1, 0, "Jess Adept");
		p.tick(3, "fix", "the furniture", false, false, 0, -1, 0, "Jess Adept");
		Pace.Round r = p.tick(0, "job", "the contractor", false, false, 0, -1, 1, null);
		assertEquals("11/1/Jess Adept", r.kind);
	}

	@Test
	public void bestsSurviveASaveAndLoad()
	{
		Pace p = new Pace();
		p.loadBests("3/27=40;7/27=120;bad;x=y");
		assertEquals(40, p.best("3/27"));
		assertEquals(120, p.best("7/27"));
		assertEquals("3/27=40;7/27=120", p.saveBests());
	}

	@Test
	public void clockReadsMinutesAndSeconds()
	{
		assertEquals("1:00", Pace.clock(100));
		assertEquals("0:06", Pace.clock(10));
	}

	@Test
	public void eachStageIsTimedAndTheSlowestAgainstItsBestIsNamed()
	{
		Pace p = new Pace();
		run(p, 1, 0, "mine", "a vein", false, 0, -1, 0);
		// A first round: 4 mining, 6 at the hopper.
		run(p, 3, 0, "mine", "a vein", false, 0, -1, 0);
		run(p, 6, 1, "hopper", "the hopper", false, 1, -1, 0);
		Pace.Round first = run(p, 1, 0, "mine", "a vein", false, 0, -1, 27);
		assertEquals(4, first.stageTicks(0));
		assertEquals(6, first.stageTicks(1));
		assertEquals(0, first.stageBest(1));
		assertEquals(-1, first.slowestStage());
		// A second round of the same kind loses 7 ticks at the hopper.
		run(p, 3, 0, "mine", "a vein", false, 0, -1, 27);
		run(p, 13, 1, "hopper", "the hopper", false, 1, -1, 27);
		Pace.Round second = run(p, 1, 0, "mine", "a vein", false, 0, -1, 54);
		assertEquals(first.kind, second.kind);
		assertEquals(6, second.stageBest(1));
		assertEquals(13, second.stageTicks(1));
		assertEquals(1, second.slowestStage());
		assertArrayEquals6(p.stageBests(first.kind));
	}

	private static void assertArrayEquals6(int[] bests)
	{
		assertEquals(4, bests[0]);
		assertEquals(6, bests[1]);
	}

	@Test
	public void stageBestsAreSavedAndReadBackBesideRoundBests()
	{
		Pace p = new Pace();
		p.loadBests("3/27=15;3/27#0=4;3/27#1=6;3/27#99=2;bad#x=3");
		assertEquals(15, p.best("3/27"));
		assertEquals(4, p.stageBests("3/27")[0]);
		assertEquals(6, p.stageBests("3/27")[1]);
		assertEquals(0, p.best("3/27#0"));
		assertEquals("3/27=15;3/27#0=4;3/27#1=6", p.saveBests());
	}

	@Test
	public void fieldNotesSeeTheRoundAsBefore()
	{
		Pace p = new Pace();
		run(p, 2, 0, "mine", "a vein", false, 0, -1, 0);
		run(p, 2, 1, "hopper", "the hopper", false, 0, -1, 0);
		Pace.Round r = run(p, 1, 0, "mine", "a vein", false, 0, -1, 27);
		String json = new com.google.gson.Gson().toJson(r);
		assertFalse(json, json.contains("stage"));
		assertTrue(json, json.contains("\"ticks\":4"));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PointsTest
{
	private static final long PLANK_SACK = 350;

	@Test
	public void aTotalThatDropsAfterAPurchaseIsABalance()
	{
		Points p = new Points();
		assertEquals(0, p.message(120, 470, 0));
		p.bought(PLANK_SACK);
		// Bought for 350, then one contract paid 4: a balance reads 124.
		assertEquals(4, p.message(121, 124, PLANK_SACK));
		assertEquals(Points.Meaning.BALANCE, p.getMeaning());
		assertEquals(124, p.balance(PLANK_SACK));
	}

	@Test
	public void aTotalThatKeepsClimbingAfterAPurchaseIsLifetime()
	{
		Points p = new Points();
		p.message(120, 470, 0);
		p.bought(PLANK_SACK);
		assertEquals(4, p.message(121, 474, PLANK_SACK));
		assertEquals(Points.Meaning.LIFETIME, p.getMeaning());
		// Every point ever earned less what the sack cost.
		assertEquals(124, p.balance(PLANK_SACK));
	}

	@Test
	public void untilItIsKnownTheLowerReadingIsTaken()
	{
		Points p = new Points();
		p.message(120, 470, PLANK_SACK);
		assertEquals(4, p.message(121, 474, PLANK_SACK));
		assertEquals(Points.Meaning.UNKNOWN, p.getMeaning());
		assertEquals(124, p.balance(PLANK_SACK));
		// Owning nothing, both readings agree.
		assertEquals(474, p.balance(0));
	}

	@Test
	public void aPurchaseBeforeTheNextContractCountsAtOnce()
	{
		Points p = new Points();
		p.message(120, 470, 0);
		p.bought(PLANK_SACK);
		// Unknown meaning: the sack is off both readings (spent from a balance, owned against a lifetime).
		assertEquals(120, p.balance(PLANK_SACK));
	}

	@Test
	public void aTotalBelowWhatYouOwnCanOnlyBeABalance()
	{
		Points p = new Points();
		p.message(10, 100, PLANK_SACK);
		assertEquals(Points.Meaning.BALANCE, p.getMeaning());
		assertEquals(100, p.balance(PLANK_SACK));
	}

	@Test
	public void aDropWithNoPurchaseSeenIsStillABalance()
	{
		Points p = new Points();
		p.message(120, 470, 0);
		// Bought somewhere the Pilot did not see (straight to the bank, say).
		p.message(121, 120, 0);
		assertEquals(Points.Meaning.BALANCE, p.getMeaning());
		assertEquals(120, p.balance(0));
	}

	@Test
	public void theSameLineTwiceIsNotEarningsTwice()
	{
		Points p = new Points();
		p.message(120, 470, 0);
		assertEquals(4, p.message(121, 474, 0));
		assertEquals(0, p.message(121, 474, 0));
		assertEquals(474, p.getTotal());
	}

	@Test
	public void severalContractsBetweenLinesAreCountedTogether()
	{
		Points p = new Points();
		p.message(120, 470, 0);
		p.bought(200);
		// Three contracts' lines missed, and boots bought for 200: a total of 482 climbed 12, which
		// fits three contracts' pay, while a balance would have had to climb 212.
		assertEquals(12, p.message(123, 482, 200));
		assertEquals(Points.Meaning.LIFETIME, p.getMeaning());
	}

	@Test
	public void savesAndReadsBackIncludingOlderBareTotals()
	{
		Points p = new Points();
		p.message(120, 470, 0);
		p.bought(PLANK_SACK);
		Points back = Points.decode(p.encode());
		assertEquals(p.encode(), back.encode());
		assertEquals(120, back.balance(PLANK_SACK));

		Points old = Points.decode("470");
		assertTrue(old.known());
		assertEquals(470, old.getTotal());
		assertEquals(Points.Meaning.UNKNOWN, old.getMeaning());
		// The first line after an upgrade sets the contract count without counting earnings.
		assertEquals(0, old.message(121, 474, 0));
		assertEquals(4, old.message(122, 478, 0));

		assertFalse(Points.decode(null).known());
		assertFalse(Points.decode("470:x:BALANCE:0").known());
		assertFalse(Points.decode("470:1:SIDEWAYS:0").known());
		assertEquals(-1, new Points().balance(0));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class RewardRoadTest
{
	private static Goals.Input owning(long balance, Integer... ids)
	{
		Set<Integer> set = new HashSet<>(Arrays.asList(ids));
		Goals.Input in = new Goals.Input();
		in.have = set::contains;
		in.balance = balance;
		return in;
	}

	@Test
	public void theMotherlodeRoadRunsInTheUsualOrderAndAddsUpAsItGoes()
	{
		// The whole kit owned, 64 nuggets held, 21 an hour.
		Goals.Input in = owning(64, 12013, 12014, 12015, 12016);
		in.currencyPerHour = 21;
		List<RewardRoad.Stop> road = RewardRoad.motherlode(in);
		assertEquals(4, road.size());
		assertEquals("Prospector kit", road.get(0).getName());
		assertTrue(road.get(0).isOwned());
		assertEquals(12013, road.get(0).getIcon());

		RewardRoad.Stop coal = road.get(1);
		assertEquals("Coal bag", coal.getName());
		assertEquals(100, coal.getCost());
		assertEquals(36, coal.getLeft());
		assertFalse(coal.isAffordable());
		assertEquals((long) Math.ceil(36 * 60.0 / 21), coal.getMinutesAway());

		// The gem bag comes after the coal bag: 200 in all, less the 64 held.
		assertEquals(136, road.get(2).getLeft());
		assertEquals(100, road.get(2).getCost());
		// The bigger sack has no item to show and is counted after both bags.
		assertEquals(0, road.get(3).getIcon());
		assertEquals(336, road.get(3).getLeft());
		assertTrue(RewardRoad.open(road));
	}

	@Test
