		assertFalse(RewardRoad.open(RewardRoad.homes(in)));
		assertTrue(RewardRoad.of(Goals.HOMES_ORDER, null).isEmpty());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

public class RouteTest
{
	private static int[][] open(int w, int h)
	{
		return new int[w][h];
	}

	@Test
	public void diagonalStepsCostTheSameAsStraightOnes()
	{
		Route r = Route.flood(open(10, 10), 0, 0, null);
		assertEquals(5, r.distance(5, 5));
		assertEquals(5, r.pathTo(5, 5).size());
	}

	@Test
	public void wallsAreWalkedAround()
	{
		int[][] f = open(10, 10);
		// A solid line at x = 3 from y = 0 to 7.
		for (int y = 0; y <= 7; y++)
		{
			f[3][y] = Route.FULL;
		}
		Route r = Route.flood(f, 0, 0, null);
		assertTrue(r.distance(5, 0) > 5);
		for (int[] t : r.pathTo(5, 0))
		{
			assertFalse("walked through the wall", t[0] == 3 && t[1] <= 7);
		}
	}

	@Test
	public void thinWallsBlockOneSideOnly()
	{
		int[][] f = open(4, 4);
		// A wall on the east edge of (1,1): stepping from (1,1) to (2,1) is blocked.
		f[1][1] |= Route.EAST;
		f[2][1] |= Route.WEST;
		assertEquals(0, Route.stepCost(f, null, 1, 1, 1, 0));
		assertEquals(1, Route.stepCost(f, null, 1, 1, 0, 1));
	}

	@Test
	public void softTilesCostExtraButCanBeCrossed()
	{
		int[][] f = open(10, 3);
		int[][] soft = new int[10][3];
		for (int y = 0; y < 3; y++)
		{
			f[5][y] = Route.FULL;
		}
		soft[5][1] = 8;
		Route blocked = Route.flood(f, 0, 1, null);
		assertFalse(blocked.reaches(9, 1));
		Route r = Route.flood(f, 0, 1, soft);
		assertEquals(9 + 8, r.distance(9, 1));
	}

	@Test
	public void approachPicksTheNearestSideAndNeverACorner()
	{
		int[][] f = open(10, 10);
		// A 2x2 object at (4,4).
		for (int x = 4; x < 6; x++)
		{
			for (int y = 4; y < 6; y++)
			{
				f[x][y] = Route.FULL;
			}
		}
		Route r = Route.flood(f, 0, 4, null);
		int[] stand = r.approach(f, 4, 4, 2, 2);
		assertNotNull(stand);
		assertEquals(3, stand[0]);
		assertTrue(stand[1] == 4 || stand[1] == 5);
		assertTrue(Route.beside(3, 4, 4, 4, 2, 2));
		assertFalse(Route.beside(3, 3, 4, 4, 2, 2));
	}

	@Test
	public void approachSkipsTilesAcrossAWall()
	{
		int[][] f = open(5, 5);
		f[2][2] = Route.FULL;
		// The west tile has a wall on its east edge, between it and the object.
		f[1][2] |= Route.EAST;
		Route r = Route.flood(f, 0, 2, null);
		int[] stand = r.approach(f, 2, 2, 1, 1);
		assertNotNull(stand);
		assertFalse(stand[0] == 1 && stand[1] == 2);
	}

	@Test
	public void unreachableGivesNothing()
	{
		int[][] f = open(5, 5);
		for (int y = 0; y < 5; y++)
		{
			f[2][y] = Route.FULL;
		}
		Route r = Route.flood(f, 0, 0, null);
		assertEquals(-1, r.distance(4, 4));
		List<int[]> path = r.pathTo(4, 4);
		assertTrue(path.isEmpty());
		assertNull(r.approach(f, 4, 4, 1, 1));
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/**
 * Every key the Pilot saves for itself, and the two it reads from other Codex plugins, damaged
 * every way a save can be: empty, cut short, garbage, wrong separators, huge, negative and
 * not-a-number figures, a newer version. None may throw, and nothing read back may print a
 * figure below zero, "NaN" or "Infinity".
 */
public class SavedKeysFuzzTest
{
	private static final Gson GSON = RuneLiteAPI.GSON;
	private static final long NOW = 1_760_000_000_000L;
	private static final String[] NUMBERS = {
		"", "x", "-1", "0", "-9223372036854775808", "9223372036854775807", "99999999999999999999", "2147483648", "1e30", "NaN", " 7 ",
	};
	private static final Pattern NUMBER = Pattern.compile("-?\\d+");

	/** A valid save and damaged copies of it: cut at every length, each figure replaced, separators doubled. */
	public static List<String> damaged(String good)
	{
		Set<String> out = new LinkedHashSet<>();
		out.add(null);
		out.add("");
		out.add(" ");
		out.add("garbage");
		out.add("\u0000");
		out.add("{\"version\":2}");
		out.add(good);
		for (int cut = 0; cut < good.length(); cut++)
		{
			out.add(good.substring(0, cut));
		}
		Matcher m = NUMBER.matcher(good);
		while (m.find())
		{
			for (String n : NUMBERS)
			{
				out.add(good.substring(0, m.start()) + n + good.substring(m.end()));
			}
		}
		for (String sep : new String[]{"|", ";", ":", ",", "="})
		{
			out.add(good.replace(sep, sep + sep));
			out.add(good.replace(sep, ""));
			out.add(sep + good + sep);
		}
		out.add(good + "|future|fields");
		out.add(good + ";" + good);
		return new ArrayList<>(out);
	}

	/** Runs the reader over every damaged copy, collecting what throws or prints a bad figure. */
	static void survive(String key, String good, Consumer<String> read)
	{
		List<String> failures = new ArrayList<>();
		for (String saved : damaged(good))
		{
			try
			{
				read.accept(saved);
			}
			catch (RuntimeException | AssertionError e)
			{
				failures.add(key + " = " + saved + ": " + e);
			}
		}
		assertTrue(failures.size() + " failures: " + failures, failures.isEmpty());
	}

	/** Text a card prints: no negative figure, no NaN or Infinity. */
	static void sane(String text)
	{
		if (text == null)
		{
			return;
		}
		assertFalse(text, text.contains("NaN") || text.contains("Infinity"));
		assertFalse(text, Pattern.compile("(^|[\\s(:])-\\d").matcher(text).find());
	}

	@Test
	public void visitSummary()
	{
		survive("visit.MOTHERLODE", "1760000000000|72|318 pay-dirt;21,400 Mining xp;ore worth 48k", s ->
		{
			Visit v = Visit.decode(s);
			if (v != null)
			{
				sane(v.line());
				sane(v.status(NOW));
				sane(v.duration());
			}
		});
	}

	@Test
	public void bestVisit()
	{
		survive("best.MOTHERLODE", "1759990000000|1760000000000|72|1620|81000", s ->
		{
			BestVisit b = BestVisit.decode(s);
			if (b != null)
			{
				sane(b.pace("pay-dirt"));
				sane(b.status("pay-dirt", "Mining", null, NOW));
				sane(b.status("pay-dirt", "Mining", Visit.decode("1760000000000|72|318 pay-dirt"), NOW));
			}
		});
	}

	@Test
	public void pointsBook()
	{
		Consumer<String> read = s ->
		{
			Points p = Points.decode(s);
			for (long owned : new long[]{0, 1_250, Long.MAX_VALUE / 2})
			{
				long balance = p.balance(owned);
				// -1 is "not read from a message yet".
				assertTrue(s + " balance " + balance, balance >= -1);
				assertTrue(s + " balance " + balance + " over total " + p.getTotal(), balance <= Math.max(0, p.getTotal()));
			}
			if (p.known())
			{
				sane(Figures.count(p.getTotal()));
			}
			Points.decode(p.encode());
		};
		survive("goal.pointsBook", "470:120:UNKNOWN:350", read);
		survive("goal.pointsBook", "470:120:BALANCE:0", read);
		survive("goal.points", "470", read);
	}

	@Test
	public void ownedRewards()
	{
		survive("goal.owned", "AMYS_SAW,PLANK_SACK,BIGGER_SACK", s ->
		{
			Owned o = Owned.decode(s);
			for (Goal.Reward r : Goal.Reward.values())
			{
				o.has(r);
			}
			Owned.decode(o.encode());
		});
	}

	@Test
	public void contractBook()
	{
		survive("homes.book", "EXPERT=12,24000,120,36,10,9000;ADEPT=4,4000,24,0,4,2400", s ->
		{
			ContractBook book = ContractBook.decode(s);
			for (ContractBook.Row row : book.rank(id -> 1_000, 70))
			{
				for (double v : new double[]{row.getCoinsEach(), row.getPerXp(), row.getXpPerHour()})
				{
					assertTrue(s + " " + v, Double.isFinite(v) && v >= 0);
				}
			}
			for (Contract.Tier tier : Contract.Tier.values())
			{
				ContractBook.Tally t = book.tally(tier);
				if (t != null)
				{
					Supplies.Homes h = Supplies.homes(tier, 1_000, 200, t);
					// -1 is "not learned yet".
					assertTrue(s, h.getContracts() >= -1);
					sane(h.headline());
				}
			}
			ContractBook.decode(book.encode());
		});
	}

	@Test
	public void ownBankStock()
	{
		survive("stock.bank", "1760000000000|453=5000;440=3000;2351=200;8780=400;8782=100", s ->
		{
			BankStock b = BankStock.decode(s);
			if (b != null)
			{
				for (int id : new int[]{453, 440, 2351, 8780, 8782})
				{
					assertTrue(s, b.count(id) >= 0 && b.count(id) <= Integer.MAX_VALUE);
				}
				assertTrue(s, b.getSavedAt() >= 0);
				BankStock.decode(b.encode());
				Supplies.Furnace f = Supplies.furnace(Bar.STEEL, b.count(440), b.count(453), 26, 27, 60);
				assertTrue(s, f.getBars() >= 0);
				sane(f.headline());
				sane(f.limit());
			}
		});
	}

	@Test
	public void bankStewardSnapshot()
	{
		Consumer<String> read = s ->
		{
			BankStock b = BankStock.steward(GSON, s);
			if (b != null)
			{
				for (int id : new int[]{453, 440, 8780})
				{
					assertTrue(s + " " + b.count(id), b.count(id) >= 0 && b.count(id) <= Integer.MAX_VALUE);
				}
				assertTrue(s, b.getSavedAt() >= 0);
			}
		};
		survive("codexbanksteward/bankV1", "{\"version\":1,\"savedAt\":1760000000000,\"items\":{\"453\":5000,\"440\":3000},\"truncated\":false}", read);
		for (String bad : new String[]{"\"x\"", "[]", "{}", "null", "true", "1e30", "-5", "NaN", "\"12\""})
		{
			read.accept("{\"version\":1,\"savedAt\":" + bad + ",\"items\":{\"453\":" + bad + "},\"truncated\":" + bad + "}");
			read.accept("{\"version\":" + bad + ",\"items\":" + bad + "}");
		}
	}

	@Test
	public void paceBests()
	{
		survive("pace.FURNACE", "3/27=15;3/27#0=4;3/27#1=6;7/27=120", s ->
		{
			Pace p = new Pace();
			p.loadBests(s);
			assertTrue(s, p.best("3/27") >= 0);
			p.loadBests(p.saveBests());
		});
	}

	@Test
	public void navigatorGoalBoard()
	{
		String board = "{\"version\":1,\"focus\":\"quest:Dragon Slayer II\",\"goals\":[{\"key\":\"quest:Dragon Slayer II\",\"type\":\"quest\","
			+ "\"title\":\"Dragon Slayer II\",\"complete\":false,\"progress\":0.4,\"next\":\"x\",\"hoursLeft\":12.5,"
			+ "\"skills\":{\"Smithing\":70,\"Mining\":68},\"quests\":[]}]}";
		Consumer<String> read = s ->
		{
			NavigatorGoals.Board b = NavigatorGoals.read(GSON, s);
			NavigatorGoals.Target t = NavigatorGoals.target(b, "Smithing", 50);
			if (t != null)
			{
				assertTrue(s, t.getLevel() > 50 && t.getLevel() <= 99);
			}
		};
		survive("codexnavigator/goalBoard", board, read);
		for (String bad : new String[]{"\"\"", "\"x\"", "[]", "{}", "null", "true", "1e400", "NaN", "-1", "99999999999", "[1,\"x\"]"})
		{
			for (String field : new String[]{"version", "focus", "goals", "key", "title", "complete", "hoursLeft", "skills", "quests"})
			{
				read.accept(board.replaceFirst("\"" + field + "\":(\\{[^}]*\\}|\\[[^\\]]*\\]|\"[^\"]*\"|[^,}]+)",
					"\"" + field + "\":" + Matcher.quoteReplacement(bad)));
			}
			read.accept(board.replace("\"Smithing\":70", "\"Smithing\":" + bad));
		}
	}

	@Test
	public void aSnapshotFromTheFutureDoesNotOutrankYourOwnLook()
	{
		// Bank Steward saved with a clock set years ahead: its snapshot must not win over the
		// Pilot's own look from a minute ago for ever more.
		BankStock own = BankStock.seen(java.util.Collections.singletonMap(453, 100L), NOW - 60_000L);
		BankStock ahead = BankStock.steward(GSON, "{\"version\":1,\"savedAt\":" + (NOW + 10 * 365 * 86_400_000L) + ",\"items\":{\"453\":9}}");
		org.junit.Assert.assertSame(own, BankStock.newest(own, ahead, NOW));
	}

	@Test
	public void aThousandItemBankReadsInAFewMilliseconds()
	{
		StringBuilder items = new StringBuilder("{");
		for (int id = 30_000; id < 31_500; id++)
		{
			items.append(id == 30_000 ? "" : ",").append('"').append(id).append("\":").append(id * 7);
		}
		items.append(",\"453\":5000}");
		String json = "{\"version\":1,\"savedAt\":1760000000000,\"items\":" + items + ",\"truncated\":false}";
		for (int i = 0; i < 50; i++)
		{
			BankStock.steward(GSON, json);
		}
		// The quickest of five batches: one batch on a busy machine (a shared CI runner, or this
		// test run beside others) read 3.6 ms and failed it.
		double ms = Double.MAX_VALUE;
		for (int batch = 0; batch < 5; batch++)
		{
			long t = System.nanoTime();
			for (int i = 0; i < 20; i++)
			{
				BankStock.steward(GSON, json);
			}
			ms = Math.min(ms, (System.nanoTime() - t) / 1e6 / 20);
		}
		assertTrue(ms + " ms", ms < 3);
		org.junit.Assert.assertEquals(5000, BankStock.steward(GSON, json).count(453));
	}

	@Test
	public void savedContract()
	{
		// ":" (a home name lost) split to nothing and threw on every login.
		for (String good : new String[]{"Jess:Expert", "Jess"})
		{
			survive("contract", good, s ->
			{
				Contract c = Contract.decode(s);
				if (c != null)
				{
					assertTrue(s, c.getHome() != null);
				}
			});
		}
		survive("contract", ":", Contract::decode);
	}

	@Test
	public void aRewardANewerVersionAddedIsNotForgottenOnTheNextSave()
	{
		// A newer version saved a reward this one does not know. Decoding dropped it, and the
		// next save (any new reward seen) wrote the list back without it: back on the newer
		// version, the goal card asked you to buy what you already owned.
		Owned o = Owned.decode("PLANK_SACK,GOLDEN_NUGGET_HAT");
		org.junit.Assert.assertTrue(o.has(Goal.Reward.PLANK_SACK));
		String again = o.encode();
		org.junit.Assert.assertTrue(again, again.contains("GOLDEN_NUGGET_HAT"));
		org.junit.Assert.assertTrue(again, again.contains("PLANK_SACK"));
		// Damage is still dropped, and cannot make the value grow.
		org.junit.Assert.assertEquals("PLANK_SACK", Owned.decode("PLANK_SACK,garbage,{},, ,\"x\"").encode());
		StringBuilder many = new StringBuilder();
		for (int i = 0; i < 500; i++)
		{
			many.append("NEW_").append(i).append(',');
		}
		org.junit.Assert.assertTrue(Owned.decode(many.toString()).encode().split(",").length <= 16);
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SuppliesTest
{
	@Test
	public void runiteRunsOnCoalAsMuchAsOre()
	{
		// 540 runite ore and 1,500 coal: four coal a bar makes only 375 bars.
		Supplies.Furnace f = Supplies.furnace(Bar.RUNITE, 540, 1500, 27, 27, 0);
		assertEquals(375, f.getBars());
		assertTrue(f.isCoalShort());
		assertEquals(540 * 4 - 1500, f.getCoalToUseAllOre());
		// 375 bars are 13.9 loads; each load needs one and a half coal trips more.
		assertEquals(375 / 27.0 * 2.5, f.getTrips(), 0.001);
		assertEquals("375 runite bars, 35 trips", f.headline());
		assertTrue(f.limit().startsWith("Coal runs out first: 660 more"));
	}

	@Test
	public void timeComesFromYourTrip()
	{
		// Steel with a coal bag: no coal trips, 27 a trip at 60 seconds.
		Supplies.Furnace f = Supplies.furnace(Bar.STEEL, 270, 5000, 27, 27, 60);
		assertEquals(270, f.getBars());
		assertFalse(f.isCoalShort());
		assertEquals(600, f.getSeconds(), 0.001);
		assertEquals("270 steel bars, 10 trips, about 10m", f.headline());
		assertEquals("The ore runs out first", f.limit());
	}

	@Test
	public void goldNeedsNoCoalAndNothingMakesNoBar()
	{
		Supplies.Furnace gold = Supplies.furnace(Bar.GOLD, 28, 0, 28, 0, 0);
		assertEquals(28, gold.getBars());
		assertNull(gold.limit());
		Supplies.Furnace none = Supplies.furnace(Bar.MITHRIL, 0, 900, 27, 27, 50);
		assertEquals(0, none.getBars());
		assertEquals("Not enough mithril ore and coal for a bar", none.headline());
		assertNull(none.limit());
	}

	@Test
	public void planksCountInContractsOnceOneIsLearned()
	{
		Supplies.Homes unknown = Supplies.homes(Contract.Tier.ADEPT, 212, 0, null);
		assertEquals(-1, unknown.getContracts());
		assertEquals("212 teak planks", unknown.headline());
		assertEquals("No teak planks in the bank", Supplies.homes(Contract.Tier.ADEPT, 0, 0, null).headline());

		ContractBook book = new ContractBook();
		book.record(Contract.Tier.ADEPT, 1000, 10, 1, 300);
		book.record(Contract.Tier.ADEPT, 1000, 12, 1, 300);
		ContractBook.Tally t = book.tally(Contract.Tier.ADEPT);
		Supplies.Homes h = Supplies.homes(Contract.Tier.ADEPT, 212, 50, t);
		assertEquals(19, h.getContracts());
		assertFalse(h.isSteelShort());
		assertEquals("Teak planks for about 19 contracts, 1h 35m", h.headline());
		// Five steel bars cover five contracts, before the planks run out.
		Supplies.Homes steel = Supplies.homes(Contract.Tier.ADEPT, 212, 5, t);
		assertEquals(5, steel.getContracts());
		assertTrue(steel.isSteelShort());
		assertEquals("Not enough teak planks for a contract", Supplies.homes(Contract.Tier.ADEPT, 4, 9, t).headline());
	}
}

package com.codex.minigamepilot.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class VisitTest
{
	private static final long NOW = 1_760_000_000_000L;

	@Test
	public void saysWhatASessionCameTo()
	{
		Visit v = Visit.of(NOW, 72 * 60_000L, Arrays.asList("318 pay-dirt", "21,400 Mining xp", "ore worth 48k"));
		assertEquals("1h 12m: 318 pay-dirt, 21,400 Mining xp and ore worth 48k.", v.line());
		assertEquals("Last visit 3 hours ago: 1h 12m for 318 pay-dirt, 21,400 Mining xp and ore worth 48k.",
			v.status(NOW + 3 * 3_600_000L));
		assertEquals("52m: 400 bars.", Visit.of(NOW, 52 * 60_000L, Collections.singletonList("400 bars")).line());
	}

	@Test
	public void aShortOrIdleSessionHasNoSummary()
	{
		assertNull(Visit.of(NOW, Visit.MIN_MS - 1, Collections.singletonList("3 pay-dirt")));
		assertNull(Visit.of(NOW, 60 * 60_000L, Collections.emptyList()));
		assertNull(Visit.of(NOW, 60 * 60_000L, Arrays.asList("", null, " ")));
	}

	@Test
	public void survivesBeingSavedAndADamagedSave()
	{
		Visit v = Visit.of(NOW, 30 * 60_000L, Arrays.asList("12 bars", "a|b;c"));
		Visit back = Visit.decode(v.encode());
		assertEquals(v.line(), back.line());
		assertEquals(NOW, back.getEndedAt());
		assertEquals("30m: 12 bars and a b,c.", back.line());
		assertNull(Visit.decode(null));
		assertNull(Visit.decode(""));
		assertNull(Visit.decode("x|3|bars"));
		assertNull(Visit.decode("100|3"));
		assertNull(Visit.decode("100|3|"));
	}

	@Test
	public void steppingOutAgainWithNothingMoreDoneIsTheSameVisit()
	{
		Visit first = Visit.of(NOW, 40 * 60_000L, Arrays.asList("318 pay-dirt", "ore worth 48k"));
		// Out for two minutes and back in: the session carries on, so leaving again reads the
		// same counts with a longer time, and the chat should not say it twice.
		Visit again = Visit.of(NOW + 180_000L, 43 * 60_000L, Arrays.asList("318 pay-dirt", "ore worth 48k"));
		Visit more = Visit.of(NOW + 900_000L, 55 * 60_000L, Arrays.asList("410 pay-dirt", "ore worth 61k"));
		org.junit.Assert.assertTrue(again.sameCounts(first));
		org.junit.Assert.assertFalse(more.sameCounts(first));
		org.junit.Assert.assertFalse(first.sameCounts(null));
	}
}

package com.codex.minigamepilot.goal;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.minigamepilot.core.Goal;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class GoalWatchTest
{
	@Test
	public void readsPointsFromTheContractMessage()
	{
		assertArrayEquals(new long[]{1310, 1234}, GoalWatch.readPoints("You have completed 1,310 contracts with a total of 1,234 points."));
		assertArrayEquals(new long[]{1, 2}, GoalWatch.readPoints("You have completed 1 contract with a total of 2 points."));
		assertNull(GoalWatch.readPoints("You have completed your contract."));
		assertNull(GoalWatch.readPoints(null));
	}

	@Test
	public void aRewardFromNowhereAtTheShopWasBought()
	{
		Map<Integer, Integer> bank = new HashMap<>();
		EnumSet<Goal.Reward> none = EnumSet.noneOf(Goal.Reward.class);
		EnumSet<Goal.Reward> sack = EnumSet.of(Goal.Reward.PLANK_SACK);
		assertEquals(Collections.singletonList(Goal.Reward.PLANK_SACK), GoalWatch.bought(none, sack, sack, bank, false, true));
		// Not on the first tick seen, nor with a storage open.
		assertTrue(GoalWatch.bought(null, sack, sack, bank, false, true).isEmpty());
		assertTrue(GoalWatch.bought(none, sack, sack, bank, true, true).isEmpty());
		// Carried or worn a tick ago (taking off the boots), or in the bank as last seen.
		assertTrue(GoalWatch.bought(sack, sack, sack, bank, false, true).isEmpty());
		bank.put(24882, 1);
		assertTrue(GoalWatch.bought(none, sack, sack, bank, false, true).isEmpty());
	}

	@Test
	public void aRewardTakenOutOfGroupStorageOrTheCostumeRoomIsNotBought()
	{
		// The outfit was never in the bank the Pilot saw: it sat in group storage or the costume
		// room. Away from the reward shop it was only taken out, whatever else is open.
		Map<Integer, Integer> bank = new HashMap<>();
		EnumSet<Goal.Reward> none = EnumSet.noneOf(Goal.Reward.class);
		EnumSet<Goal.Reward> shirt = EnumSet.of(Goal.Reward.CARPENTERS_SHIRT);
		assertTrue(GoalWatch.bought(none, shirt, shirt, bank, false, false).isEmpty());
		assertTrue(GoalWatch.bought(none, shirt, shirt, bank, true, false).isEmpty());
	}

	@Test
	public void theShopCountsForAFewTicksAfterItCloses()
	{
		assertTrue(GoalWatch.atShop(100, 100));
		assertTrue(GoalWatch.atShop(100, 100 + GoalWatch.SHOP_GRACE));
		assertFalse(GoalWatch.atShop(100, 101 + GoalWatch.SHOP_GRACE));
		assertFalse(GoalWatch.atShop(-1, 5));
		// Logged in again: the tick count started over below the old shop tick.
		assertFalse(GoalWatch.atShop(1000, 2));
	}

	@Test
	public void bankMemoryRoundTripsAndDropsJunk()
	{
		Map<Integer, Integer> counts = new HashMap<>();
		counts.put(12012, 87);
		counts.put(12013, 1);
		String saved = GoalWatch.encode(counts);
		assertEquals("12012=87;12013=1", saved);
		assertEquals(counts, GoalWatch.decode(saved));
		// Untracked items, damaged entries and empty counts are left out.
		Map<Integer, Integer> read = GoalWatch.decode("995=5000;12012=x;=4;12016=0;12019=1");
		assertEquals(1, read.size());
		assertTrue(read.containsKey(12019));
		assertTrue(GoalWatch.decode(null).isEmpty());
	}

	@Test
	public void nuggetsMovedOutOfTheBankAreNotEarned()
	{
		// 40 banked, none carried; withdraw all 40 and close the bank on the same tick.
		int before = 0 + 40;
		int after = 40 + 0;
		assertEquals(0, GoalWatch.nuggetsEarned(before, after, false));
		// A sack search adds 3 to the carried pile.
		assertEquals(3, GoalWatch.nuggetsEarned(after, after + 3, false));
		// Nothing counts while the bank is open, nor before the first tick.
		assertEquals(0, GoalWatch.nuggetsEarned(10, 50, true));
		assertEquals(0, GoalWatch.nuggetsEarned(-1, 50, false));
	}

	@Test
	public void experienceBeforeTheSkillsArriveIsNoBaseForAGain()
	{
		// Just logged in: no Hitpoints experience means nothing has loaded.
		assertEquals(-1, GoalWatch.known(0, 0));
		assertEquals(-1, GoalWatch.known(13_034_431, 0));
		assertEquals(13_034_431, GoalWatch.known(13_034_431, 1_154));
		// From not known to your whole total is no gain; a real tick's gain is.
		assertEquals(0, GoalWatch.xpGained(-1, 13_034_431));
		assertEquals(0, GoalWatch.xpGained(13_034_431, -1));
		assertEquals(35, GoalWatch.xpGained(13_034_431, 13_034_466));
	}

	@Test
	public void nuggetsAreNotEarnedFromAnInventoryNotYetLoaded()
	{
		assertEquals(0, GoalWatch.nuggetsEarned(-1, 40, false));
		assertEquals(0, GoalWatch.nuggetsEarned(40, -1, false));
		assertEquals(0, GoalWatch.nuggetsEarned(-1, -1, false));
		assertEquals(2, GoalWatch.nuggetsEarned(40, 42, false));
	}

	@Test
	public void aDamagedBankCopyKeepsWhatReads()
	{
		// goal.bank damaged every way the suite's fuzz test damages a save: no throw, no count below one.
		for (String saved : com.codex.minigamepilot.core.SavedKeysFuzzTest.damaged("12012=5000;12013=1;25549=1"))
		{
			for (Integer n : GoalWatch.decode(saved).values())
			{
				assertTrue(saved, n > 0);
			}
			GoalWatch.decode(GoalWatch.encode(GoalWatch.decode(saved)));
		}
	}
}

package com.codex.minigamepilot.pilot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.codex.minigamepilot.core.BestVisit;
import com.codex.minigamepilot.core.Visit;
import com.codex.minigamepilot.ui.View;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/** A visit that beats your best is said when you walk out, even if a hop summed it up first. */
public class BestNoteTest
{
	private static final long H = 3_600_000L;
	private static final long T = 1_760_000_000_000L;

	private final Map<String, String> saved = new HashMap<>();
	private final Pilots pilots = new Pilots(null, null, c -> { }, null, a -> null, (a, s) -> { }, id -> 0,
		saved::get, saved::put, () -> null);

	private void visit(long started, long ms, int payDirt, boolean walkedOut)
	{
		pilots.keep(View.Activity.MOTHERLODE, Visit.of(started + ms, ms, Collections.singletonList(Session.format(payDirt) + " pay-dirt")),
			BestVisit.of(started, started + ms, ms, payDirt, 0), walkedOut);
	}

	@Test
	public void aHopMidVisitStillLetsTheNewBestBeSaid()
	{
		// An old record: 1,000 pay-dirt an hour.
		visit(T, H, 1000, true);
		pilots.takeNote();
		// Days later, an hour at 1,500 an hour, then a hop: summed up quietly, the record taken.
		long s = T + 100 * H;
		visit(s, H, 1500, false);
		assertNull(pilots.takeNote());
		// Walked out an hour later, a little slower than at the hop but well past the old record.
		visit(s, 2 * H, 2900, true);
		assertEquals("Motherlode Mine, 2h 0m: 2,900 pay-dirt. A new best: 1,500 pay-dirt an hour, up from 1,000.",
			pilots.takeNote());
		// Walked out again later in the same session: nothing new to say about the record.
		visit(s, 3 * H, 4000, true);
		assertEquals("Motherlode Mine, 3h 0m: 4,000 pay-dirt.", pilots.takeNote());
	}

	@Test
	public void aRecordTakenByAnOlderSessionIsNotSaidByALaterOne()
	{
		visit(T, H, 1000, true);
		pilots.takeNote();
		// Beaten at a logout, and that session never walked out.
		visit(T + 100 * H, H, 1500, false);
		// A new session, slower than both: no word of a best.
		visit(T + 200 * H, H, 1200, true);
		assertEquals("Motherlode Mine, 1h 0m: 1,200 pay-dirt.", pilots.takeNote());
	}
}

package com.codex.minigamepilot.pilot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.minigamepilot.core.Contract;
import com.codex.minigamepilot.core.ContractBook;
import com.codex.minigamepilot.core.Home;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class ContractMeterTest
{
	private final Map<String, String> saved = new HashMap<>();

	private HomesPilot pilot()
	{
		return new HomesPilot(null, c -> { }, saved::get, saved::put);
	}

	private static void handIn(HomesPilot p)
	{
		p.chat("You have completed 12 contracts with a total of 40 points.");
	}

	@Test
	public void aJobSeenFromItsStartIsFiledOnceItsExperienceLands()
	{
		HomesPilot p = pilot();
		Contract c = new Contract(Home.LARRY, Contract.Tier.ADEPT);
		p.load(c);
		int[] fresh = {1, 3, 4, 4, 1, 3, 1, 0};
		p.meter(c, fresh, 10_000);
		// Halfway through the job: the start is kept.
		p.meter(c, new int[]{2, 3, 4, 4, 1, 3, 1, 0}, 10_400);
		handIn(p);
		p.settle(11_000);
		p.settle(11_100);
		assertNull("not before it settles", saved.get(HomesPilot.BOOK_KEY));
		p.settle(11_200);
		ContractBook.Tally t = p.getBook().tally(Contract.Tier.ADEPT);
		assertEquals(1, t.getContracts());
		assertEquals(1200, t.xpEach(), 0);
		assertEquals(c.planksNeeded(fresh), t.planksEach(), 0);
		assertEquals(1, t.steelEach(), 0);
		assertTrue(saved.get(HomesPilot.BOOK_KEY).startsWith("ADEPT=1,1200,"));
	}

	@Test
	public void aJobFirstSeenPartDoneIsNotFiled()
	{
		HomesPilot p = pilot();
		Contract c = new Contract(Home.LARRY, Contract.Tier.ADEPT);
		p.load(c);
		p.meter(c, new int[]{2, 3, 4, 4, 1, 6, 1, 0}, 10_000);
		handIn(p);
		for (int i = 0; i < 5; i++)
		{
			p.settle(12_000);
		}
		assertTrue(p.getBook().isEmpty());
	}

	@Test
	public void theLastJobsFinishedFurnitureDoesNotSpoilTheNext()
	{
		HomesPilot p = pilot();
		Contract c = new Contract(Home.LARRY, Contract.Tier.ADEPT);
		p.load(c);
		// The varbits still show a finished house when the new contract is read.
		p.meter(c, new int[]{2, 6, 6, 7, 2, 6, 2, 0}, 9_000);
		p.meter(c, new int[]{1, 3, 4, 4, 1, 3, 1, 0}, 9_500);
		handIn(p);
		for (int i = 0; i < 3; i++)
		{
			p.settle(10_500);
		}
		assertEquals(1000, p.getBook().tally(Contract.Tier.ADEPT).xpEach(), 0);
	}

	@Test
	public void theCostRankingLightsTheTierYouTakeAndScalesToTheCheapest()
	{
		ContractBook book = new ContractBook();
		book.record(Contract.Tier.ADEPT, 1000, 10, 1, 240);
		book.record(Contract.Tier.EXPERT, 2000, 10, 0, 300);
		java.util.List<ContractBook.Row> rows = book.rank(id -> id == 8780 ? 1500 : id == 8782 ? 2400 : 500, 80);
		com.codex.minigamepilot.ui.View.PickCard card = HomesPilot.costCard(rows, Contract.Tier.ADEPT);
		String sig = new com.codex.minigamepilot.ui.View(true, com.codex.minigamepilot.ui.View.Activity.HOMES, null, null, null, 0)
			.pick(card).signature();
		assertTrue(sig, sig.contains("What it costs"));
		assertTrue(sig, sig.contains("Expert12.0 gp2,000 xp · 24k gp · 24k xp/hfalse"));
		assertTrue(sig, sig.contains("Adept15.5 gp1,000 xp · 16k gp · 15k xp/htrue"));
		assertTrue(sig, sig.contains("NoviceFinish one to learn what it costs"));
	}

	@Test
	public void experienceNotLoadedYetIsNotTakenAsTheStart()
	{
		HomesPilot p = pilot();
		Contract c = new Contract(Home.LARRY, Contract.Tier.ADEPT);
		p.load(c);
		int[] fresh = {1, 3, 4, 4, 1, 3, 1, 0};
		// Just logged in: the furniture is read before the skills arrive.
		p.meter(c, fresh, 0);
		p.meter(c, fresh, 5_000);
		handIn(p);
		for (int i = 0; i < 3; i++)
		{
			p.settle(6_000);
		}
		assertEquals(1000, p.getBook().tally(Contract.Tier.ADEPT).xpEach(), 0);
	}
}

