package com.codex.minigamepilot.pilot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SessionTest
{
	@Test
	public void onlyALongBreakStartsASessionOver()
	{
		long t = 1_760_000_000_000L;
		assertFalse("the first tick starts a session, it does not restart one", Session.restarts(0, 0, t));
		assertFalse(Session.restarts(t, t + 60_000L, t + 120_000L));
		assertFalse(Session.restarts(t, t, t + Session.BREAK_MS));
		// Back after a long break: the counts kept beside the session must start over with it,
		// or two hours' haul is shown as earned in the first minute.
		assertTrue(Session.restarts(t, t, t + Session.BREAK_MS + 1));
	}

	@Test
	public void experienceIsOnlyTakenAsTheStartOnceTheSkillsHaveArrived()
	{
		long t = 1_760_000_000_000L;
		Session s = new Session(net.runelite.api.Skill.MINING);
		// Logged in inside the mine: the first tick reads no experience at all.
		s.tick(0, false, t);
		assertEquals(0, s.xp(0));
		s.tick(13_034_431, true, t + 600);
		assertEquals("not your whole total", 0, s.xp(13_034_431));
		s.tick(13_034_431, true, t + 1200);
		assertEquals(250, s.xp(13_034_681));
		// A tick where the skills read nothing again (logging out) shows nothing, not a loss.
		assertEquals(0, s.xp(0));
	}

	@Test
	public void anotherAccountStartsTheSessionOverEvenAfterAShortLogout()
	{
		long t = 1_760_000_000_000L;
		Session s = new Session(net.runelite.api.Skill.MINING);
		assertFalse(s.tick(1000, true, t));
		assertFalse(s.tick(2000, true, t + 600));
		// Logged out and into another account a minute later: without this the new account would
		// carry the last one's start, its counts and its hourly pace (and so its best visit).
		s.startOver();
		assertTrue(s.tick(50_000, true, t + 60_000L));
		assertEquals(t + 60_000L, s.startedAt());
		assertEquals(0, s.xp(50_000));
		assertFalse("only once", s.tick(50_100, true, t + 60_600L));
		// Before any session there is nothing to start over.
		Session fresh = new Session(net.runelite.api.Skill.MINING);
		fresh.startOver();
		assertFalse(fresh.tick(10, true, t));
	}

	@Test
	public void onlyALoginToAnotherAccountIsASwitch()
	{
		// The profile goes to none at every logout and back at login.
		assertFalse(Pilots.switched(null, "alpha"));
		assertFalse(Pilots.switched("alpha", null));
		assertFalse("back on the same account", Pilots.switched("alpha", "alpha"));
		assertTrue(Pilots.switched("alpha", "beta"));
	}

	@Test
	public void anotherAccountsSessionIsNotShownBeforeItsFirstTick()
	{
		// The card away from the mine reads the session's counts; between another account's login
		// and its first tick there it would have given the last account's pay-dirt as its own.
		Session s = new Session(net.runelite.api.Skill.MINING);
		s.tick(1000, true, 1_760_000_000_000L);
		assertTrue(s.begun());
		s.startOver();
		assertFalse(s.begun());
		assertEquals(0, s.startedAt());
	}
}

package com.codex.minigamepilot.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.codex.minigamepilot.core.Figures;
import com.codex.minigamepilot.core.Goal;
import com.codex.minigamepilot.core.Goals;
import com.codex.minigamepilot.core.RewardRoad;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * A brand-new account (no xp, nothing owned, no pace) and a maxed one (200M xp, every reward
 * owned, a vast balance) through every goal and road, timed: none may throw, read a figure below
 * zero or "NaN", or take more than a few milliseconds.
 */
public class ExtremeAccountTest
{
	private static Goals.Input input(String skill, long xp, long balance, boolean ownsAll, double perHour)
	{
		Goals.Input in = new Goals.Input();
		in.have = id -> ownsAll;
		in.skill = skill;
		in.xp = xp;
		in.balance = balance;
		in.xpPerHour = perHour;
		in.currencyPerHour = perHour;
		in.currencyPerRound = 5;
		in.roundName = "expert contract";
		return in;
	}

	private static List<String> texts(Goals.Input in, String skill)
	{
		List<String> out = new ArrayList<>();
		List<Goal> goals = new ArrayList<>();
		for (Goals.Choice c : Goals.Choice.values())
		{
			goals.add(Goals.motherlode(c, input(skill, in.xp, in.balance, true, in.xpPerHour)));
			goals.add(Goals.motherlode(c, in));
			goals.add(Goals.homes(c, in));
		}
		goals.add(Goals.furnace(in));
		for (Goal g : goals)
		{
			if (g != null)
			{
				out.add(g.getTitle());
				out.add(g.describe());
				out.add(Figures.pair(g.getHave(), g.getNeed()));
			}
		}
		List<RewardRoad.Stop> stops = new ArrayList<>(RewardRoad.motherlode(in));
		stops.addAll(RewardRoad.homes(in));
		stops.addAll(RewardRoad.furnace(in));
		stops.addAll(RewardRoad.withLevel(RewardRoad.motherlode(in), skill, 99, "Every skill", in));
		for (RewardRoad.Stop s : stops)
		{
			out.add(RoadView.status(s, false));
			out.add(RoadView.tip(s));
		}
		out.add(RoadView.footnote(stops));
		return out;
	}

	@Test
	public void brandNewAndMaxedAccountsReadCleanlyAndQuickly()
	{
		Object[][] accounts = {
			{0L, -1L, 0.0},
			{0L, 0L, 0.0},
			{Goals.xpFor(99), 1_000_000L, 90_000.0},
			{200_000_000L, Long.MAX_VALUE / 4, 1e9},
		};
		for (Object[] a : accounts)
		{
			for (String skill : new String[]{"Mining", "Smithing", "Construction"})
			{
				Goals.Input in = input(skill, (Long) a[0], (Long) a[1], false, (Double) a[2]);
				for (int i = 0; i < 20; i++)
				{
					texts(in, skill);
				}
				// The quickest of ten goes, so a busy machine's pause is not taken for the code's cost.
				List<String> out = null;
				double ms = Double.MAX_VALUE;
				for (int i = 0; i < 10; i++)
				{
					long t = System.nanoTime();
					out = texts(in, skill);
					ms = Math.min(ms, (System.nanoTime() - t) / 1e6);
				}
				assertTrue(skill + " " + a[0] + ": " + ms + " ms", ms < 5);
				for (String s : out)
				{
					if (s != null)
					{
						assertFalse(s, s.contains("NaN") || s.contains("Infinity"));
						assertFalse(s, s.matches("(?s).*(^|[\\s(:])-\\d.*"));
					}
				}
			}
		}
	}
}

package com.codex.minigamepilot.ui;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class LineRowTest
{
	private static int heightAt(View.Line line, int width)
	{
		LineRow row = new LineRow(line);
		row.setBounds(0, 0, width, row.getPreferredSize().height);
		return row.getPreferredSize().height;
	}

	@Test
	public void aRowNarrowerThanItsGuessGivesTheCostALineOfItsOwn()
	{
		// Guessed at the panel's width it fits on one line; in a narrower card the name used to
		// be cut to "Carpenter's trou..." and, narrower still, the cost ran over it.
		View.Line line = new View.Line("Carpenter's trousers", "600", View.Line.Mark.TODO);
		assertEquals(18, new LineRow(line).getPreferredSize().height);
		assertEquals(31, heightAt(line, 120));
	}

	@Test
	public void aRowWiderThanItsGuessKeepsOneLine()
	{
		View.Line line = new View.Line("Mahogany drawers", "Build, 2 planks", View.Line.Mark.TODO);
		assertEquals(31, new LineRow(line).getPreferredSize().height);
		assertEquals(18, heightAt(line, 400));
	}
}

package com.codex.minigamepilot.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.minigamepilot.core.Goals;
import com.codex.minigamepilot.core.RewardRoad;
import java.awt.Canvas;
import java.awt.FontMetrics;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class RoadViewTest
{
	private static List<RewardRoad.Stop> road(long balance, double perHour, Integer... owned)
	{
		Set<Integer> set = new HashSet<>(Arrays.asList(owned));
		Goals.Input in = new Goals.Input();
		in.have = set::contains;
		in.balance = balance;
		in.currencyPerHour = perHour;
		in.skill = "Mining";
		in.xp = Goals.xpFor(70);
		in.xpPerHour = 41_000;
		return RewardRoad.withLevel(RewardRoad.motherlode(in), "Mining", 72, "Dragon Slayer II", in);
	}

	@Test
	public void eachStopSaysWhereItStands()
	{
		List<RewardRoad.Stop> r = road(64, 21, 12013, 12014, 12015, 12016);
		assertEquals("Owned", RoadView.status(r.get(0), false));
		assertEquals(1, RoadView.next(r));
		assertEquals("36 to go, 1h 43m", RoadView.status(r.get(1), true));
		assertEquals("100 nuggets, in 6h 29m", RoadView.status(r.get(2), false));
		assertEquals("In 6h 29m", RoadView.status(r.get(2), false, true));
		assertEquals("162k xp, in 3h 57m", RoadView.status(r.get(4), false));
		assertEquals("Mining 72 is for Dragon Slayer II, a Codex Navigator goal.", RoadView.footnote(r));
		assertEquals("Mining 72: 162k xp, in 3h 57m. Dragon Slayer II needs it", RoadView.tip(r.get(4)));
		assertEquals("Gem bag: 100 nuggets, in 6h 29m, counting the stops above it first", RoadView.tip(r.get(2)));
		// A goal's level that is already a stop on the furnace road is named as the level.
		Goals.Input f = new Goals.Input();
		f.skill = "Smithing";
		f.xp = Goals.xpFor(52);
		List<RewardRoad.Stop> bars = RewardRoad.withLevel(RewardRoad.furnace(f), "Smithing", 70, "Monkey Madness II", f);
		// The stop it lands on is named too, or nothing on the road says which one Smithing 70 is.
		assertEquals("Smithing 70 (Adamantite bars) is for Monkey Madness II, a Codex Navigator goal.", RoadView.footnote(bars));
		assertTrue(RoadView.tip(bars.get(2)).startsWith("Adamantite bars: "));
		assertTrue(RoadView.tip(bars.get(2)).endsWith(". Monkey Madness II needs Smithing 70"));
	}

	@Test
	public void withNoPaceOrBalanceOnlyTheCostIsSaid()
	{
		List<RewardRoad.Stop> r = road(-1, 0);
		assertEquals("180 nuggets", RoadView.status(r.get(0), true));
		assertEquals("100 nuggets", RoadView.status(r.get(1), false));
		List<RewardRoad.Stop> rich = road(1_000, 0, 12013, 12014, 12015, 12016);
		assertEquals("Yours to buy now, 100 nuggets", RoadView.status(rich.get(1), true));
		assertEquals("Yours to buy now", RoadView.status(rich.get(1), true, true));
		assertEquals(-1, RoadView.next(Arrays.asList(rich.get(0))));
	}

	@Test
	public void bigExperienceReadsInMillions()
	{
		Goals.Input in = new Goals.Input();
		in.xp = 0;
		RewardRoad.Stop s = RewardRoad.withLevel(RewardRoad.motherlode(in), "Mining", 99, "x", in).get(4);
		assertEquals("13.0M xp to go", RoadView.status(s, true));
		assertNull(RoadView.footnote(RewardRoad.motherlode(in)));
	}

	@Test
	public void theRoadIsPartOfWhatTheViewSignsSoItRedraws()
	{
		View a = new View(true, View.Activity.MOTHERLODE, null, null, null, -1);
		View b = new View(true, View.Activity.MOTHERLODE, null, null, null, -1);
		assertEquals(a.signature(), b.signature());
		b.road(road(64, 21));
		assertNotEquals(a.signature(), b.signature());
	}

	@Test
	public void aLongChecklistLineDropsItsNoteToASecondLine()
	{
		FontMetrics fm = new Canvas().getFontMetrics(Theme.small());
		assertTrue(LineRow.fits(fm, new View.Line("Clock", "Done", View.Line.Mark.DONE), LineRow.ROOM));
		assertFalse(LineRow.fits(fm, new View.Line("Large oak bookshelf", "Remove, 3 planks", View.Line.Mark.TODO), LineRow.ROOM));
	}
}
